class _SubstrateHandle:
    """Generic substrate machinery shared by the learn-dir stores
    (corpus design §1.1): connection management, schema creation,
    corruption preservation, backup, checkpoint, dump_hash, write
    transactions. Each handle supplies only its policy via class
    attributes (filename, DDL list, table list, schema version)
    and hooks — _register_instance (per-handle registry),
    _corrupt_fallback (what corruption MEANS for this store —
    the enumerated divergence point between handles), _pre_write
    (StateDB's rolling backup; the corpus has none, §1.1 (a)),
    and _after_open (the corpus's capability probes, §1.5)."""

    _DB_NAME = None
    _DDL = ()
    _TABLES = ()
    _SCHEMA_VERSION = 1

    def __init__(self, path, conn):
        self.path = Path(path)
        self._conn = conn
        self._lock = threading.RLock()
        self.corrupt_at_open = False
        self._backup_done = False

    # -- construction ---------------------------------------------------
    @classmethod
    def _connect(cls, path):
        conn = sqlite3.connect(str(path), check_same_thread=False,
                               timeout=30)
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA synchronous=FULL")
        return conn

    @classmethod
    def _create_schema(cls, conn):
        with conn:
            for ddl in cls._DDL:
                conn.execute(ddl)
            conn.execute(f"PRAGMA user_version="
                         f"{cls._SCHEMA_VERSION}")

    @classmethod
    def create(cls, learn_dir, **init_kwargs):
        """Create the DB in learn_dir if absent (schema applied),
        else open the existing one."""
        d = Path(learn_dir)
        d.mkdir(parents=True, exist_ok=True)
        p = d / cls._DB_NAME
        if p.exists():
            return cls.open(learn_dir, **init_kwargs)
        conn = cls._connect(p)
        cls._create_schema(conn)
        db = cls(p, conn, **init_kwargs)
        db._after_open()
        cls._register_instance(db)
        return db

    @classmethod
    def open(cls, learn_dir, **init_kwargs):
        """Open the learn dir's DB, or None when there is none.
        A corrupt DB gets the F8 discipline through the handle's
        _corrupt_fallback: loud warning, original bytes (incl. WAL
        sidecars) preserved as .corrupt, NO automatic restore —
        what happens next is the handle's own consequence (§1.1)."""
        d = Path(learn_dir)
        p = d / cls._DB_NAME
        if not p.exists():
            return None
        conn = None
        try:
            conn = cls._connect(p)
            row = conn.execute("PRAGMA quick_check").fetchone()
            if not row or row[0] != "ok":
                raise sqlite3.DatabaseError(
                    f"quick_check: {row[0] if row else 'no result'}")
            ver = conn.execute("PRAGMA user_version").fetchone()[0]
            if ver != cls._SCHEMA_VERSION:
                # Unknown future/past schema: re-applying DDL is
                # additive-safe (IF NOT EXISTS) and user_version is
                # re-stamped; store payloads are versioned by the
                # stores themselves.
                cls._create_schema(conn)
            db = cls(p, conn, **init_kwargs)
            conn = None
        except Exception as e:
            if conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass
            db = cls._corrupt_fallback(p, e)
            if db is None:
                return None
        db._after_open()
        cls._register_instance(db)
        return db

    # -- per-handle policy hooks ----------------------------------------
    @classmethod
    def _register_instance(cls, db):
        pass

    @classmethod
    def _corrupt_fallback(cls, path, err):
        raise NotImplementedError

    def _after_open(self):
        pass

    def _pre_write(self):
        pass

    @staticmethod
    def _preserve_corrupt(path):
        """Rename a corrupt DB (and its WAL sidecars, which are
        part of the state) to .corrupt siblings — a rename, never
        a copy (A11: atomic on the same filesystem, cannot
        half-happen on a nearly-full disk). Never clobbers an
        existing backup."""
        path = Path(path)
        try:
            dest = path.with_name(path.name + ".corrupt")
            n = 1
            while dest.exists():
                dest = path.with_name(f"{path.name}.corrupt-{n}")
                n += 1
            for suffix in ("", "-wal", "-shm"):
                src = Path(str(path) + suffix)
                if src.exists():
                    os.replace(src, Path(str(dest) + suffix))
            print(f"  !! Preserved corrupt substrate as {dest}")
        except Exception as e:
            print(f"  !! WARNING: could not preserve corrupt substrate "
                  f"{path} ({e})")

    def close(self):
        with self._lock:
            try:
                self._conn.close()
            except Exception:
                pass

    # -- access -----------------------------------------------------------
    def query(self, sql, params=()):
        with self._lock:
            cur = self._conn.execute(sql, params)
            return cur.fetchall()

    def write_txn(self):
        """Context manager: one write transaction (the handle's
        _pre_write hook runs first, under the lock)."""
        return _SubstrateWriteTxn(self)

    def backup_to(self, dest_path):
        """Copy the whole DB to dest via SQLite's backup API (A2:
        consistent under WAL, includes the WAL tail)."""
        dest = Path(dest_path)
        with self._lock:
            out = sqlite3.connect(str(dest))
            try:
                self._conn.backup(out)
            finally:
                out.close()

    def checkpoint(self):
        """Fold the WAL back into the main file (a maintenance op:
        logical content unchanged). Replay seeding opens the live DB
        immutable (A2), which cannot recover a WAL — checkpointing
        through this handle first makes the seeded copy complete."""
        with self._lock:
            try:
                self._conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
            except Exception:
                pass

    def dump_hash(self):
        """Canonical hash of the DB's LOGICAL content (A2): every
        table's rows in a fixed order, serialized deterministically.
        Immune to WAL checkpointing and file-layout noise — two DBs
        with the same content hash identically."""
        with self._lock:
            return _dump_hash_conn(self._conn, self._TABLES)

    def size_info(self):
        try:
            total = self.path.stat().st_size
        except OSError:
            total = 0
        for suffix in ("-wal", "-shm"):
            try:
                total += Path(str(self.path) + suffix).stat().st_size
            except OSError:
                pass
        return {"bytes": total, "path": str(self.path)}


class StateDB(_SubstrateHandle):
    """The substrate handle for one learn dir's state.db.

    One connection per process per learn dir (registry below),
    check_same_thread=False, writes serialized by an RLock and
    executed as single transactions — the same discipline as the
    JSON stores' load-modify-save, with strictly less lost-update
    surface. Reads come from the same connection.

    Policy (corpus design §1.1): rolling backup on first write;
    corruption starts the state stores EMPTY under the F8 warning
    (state content exists nowhere else, and a restore could
    resurrect retracted state without a sound — recovery is a
    human act, §3.8); creation is migration/tests only — the
    running stores open only.
    """

    _DB_NAME = _STATE_DB_NAME
    _DDL = _SUBSTRATE_DDL
    _TABLES = _SUBSTRATE_TABLES
    _SCHEMA_VERSION = SUBSTRATE_SCHEMA_VERSION

    @classmethod
    def _register_instance(cls, db):
        _register_state_db(db)

    @classmethod
    def _corrupt_fallback(cls, path, err):
        print(f"  !! WARNING: state substrate {path} could not be "
              f"opened ({err}); starting the state stores EMPTY. "
              f"The original file will be preserved as a .corrupt "
              f"backup. State was NOT carried over — staging "
              f"sightings reset (promotions delayed), learning "
              f"resets, roster continuity resets for affected "
              f"works; no output is created by the loss.")
        cls._preserve_corrupt(path)
        conn = cls._connect(path)
        cls._create_schema(conn)
        db = cls(path, conn)
        db.corrupt_at_open = True
        return db

    def _pre_write(self):
        self._maybe_backup()

    def _maybe_backup(self):
        if self._backup_done:
            return
        self._backup_done = True
        try:
            if not self.path.exists():
                return
            n_rows = 0
            for t in ("learned_nicknames", "staging_works",
                      "roster_works", "meta"):
                n_rows += self.query(f"SELECT COUNT(*) FROM {t}")[0][0]
            if n_rows == 0:
                return  # nothing worth recovering yet
            bak = self.path.with_name(_STATE_DB_BAK_NAME)
            if bak.exists():
                try:
                    other = sqlite3.connect(str(bak))
                    try:
                        same = _dump_hash_conn(other) == self.dump_hash()
                    finally:
                        other.close()
                except Exception:
                    same = False
                if same:
                    return
            self.backup_to(bak)
        except Exception as e:
            print(f"  !! WARNING: state substrate backup failed ({e}); "
                  f"continuing without a fresh backup")


class _SubstrateWriteTxn:
    def __init__(self, db):
        self._db = db

    def __enter__(self):
        self._db._lock.acquire()
        self._db._pre_write()
        self._db._conn.execute("BEGIN IMMEDIATE")
        return self._db._conn

    def __exit__(self, exc_type, exc, tb):
        try:
            if exc_type is None:
                self._db._conn.execute("COMMIT")
            else:
                self._db._conn.execute("ROLLBACK")
        finally:
            self._db._lock.release()
        return False


_StateDBWriteTxn = _SubstrateWriteTxn


def _dump_hash_conn(conn, tables=None):
    import hashlib as _hl
    h = _hl.sha256()
    existing = {r[0] for r in conn.execute(
        "SELECT name FROM sqlite_master WHERE type='table'")}
    for t in (tables if tables is not None else _SUBSTRATE_TABLES):
        if t not in existing:
            h.update(f"{t}:absent;".encode())
            continue
        cols = [r[1] for r in conn.execute(f"PRAGMA table_info({t})")]
        rows = conn.execute(
            f"SELECT * FROM {t} ORDER BY {', '.join(cols[:2])}").fetchall()
        h.update(f"{t}:{len(rows)};".encode())
        for row in rows:
            h.update(repr(tuple(row)).encode("utf-8", "replace"))
            h.update(b"\n")
    return h.hexdigest()


_STATE_DBS = {}
_STATE_DBS_LOCK = threading.Lock()


def _register_state_db(db):
    with _STATE_DBS_LOCK:
        _STATE_DBS[str(db.path.parent.resolve())] = db


def _state_db_for(learn_dir):
    """The substrate for a learn dir, or None when the dir has no
    state.db (JSON mode). Positive hits are cached per process;
    opening applies the corruption discipline in StateDB.open."""
    if learn_dir is None:
        return None
    key = str(Path(learn_dir).resolve())
    with _STATE_DBS_LOCK:
        db = _STATE_DBS.get(key)
    if db is not None:
        return db
    if not (Path(learn_dir) / _STATE_DB_NAME).exists():
        return None
    return StateDB.open(learn_dir)


def _close_state_dbs():
    """Close every registered substrate (tests, process hygiene)."""
    with _STATE_DBS_LOCK:
        dbs = list(_STATE_DBS.values())
        _STATE_DBS.clear()
    for db in dbs:
        db.close()


def _substrate_active(learn_dir):
    return _state_db_for(learn_dir) is not None




# ---------------------------------------------------------------------------
# Corpus store (eval/corpus-design.md): corpus.db beside state.db,
# sharing the substrate machinery through _SubstrateHandle (§1.1).
# The corpus is retained source + recorded stage output; it decides
# nothing about any claim (design header doctrine). Divergences from
# StateDB, complete per §1.1: (a) NO rolling backup on corpus writes
# (the substrate is precious, the corpus is rebuildable, §5.3);
# (b) corruption consequence — a corrupt corpus opens as ABSENT and
# processing falls back to file parsing, where state starts empty;
# (c) creation posture — corpus.db is create-on-ingest (or explicit
# create in tests/maintenance), never created by a mere open.
# ---------------------------------------------------------------------------

CORPUS_SCHEMA_VERSION = 1
CORPUS_V = "1"
_CORPUS_DB_NAME = "corpus.db"
CORPUS_PARSER_VERSION = "1"
# The window builder's contract (§1.4): passage ids are content-
# derived over this format string; a window-shape change versions it.
_CORPUS_WINDOW_FORMAT = "win600-sent-v1"
# The vector encoding's format string (§1.4): float32 little-endian.
_CORPUS_VECTOR_FORMAT = "raw-f32-v1"
# A9: the corpus handle names its busy_timeout at open (§5.2).
_CORPUS_BUSY_TIMEOUT_MS = 30000

_CORPUS_DDL = [
    "CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT)",
    """CREATE TABLE IF NOT EXISTS corpus_works (
         fingerprint TEXT PRIMARY KEY, book_key TEXT, work_id TEXT,
         title TEXT, author TEXT, identifiers TEXT, series TEXT,
         series_index REAL, parser_version TEXT, chapter_count INTEGER,
         text_root_hash TEXT, source_hash TEXT, status TEXT,
         ingested_at TEXT, updated_at TEXT, payload TEXT)""",
    """CREATE TABLE IF NOT EXISTS corpus_chapters (
         fingerprint TEXT, chapter_index INTEGER, label TEXT,
         text TEXT, text_hash TEXT, char_count INTEGER,
         word_count INTEGER, is_frontmatter INTEGER,
         PRIMARY KEY (fingerprint, chapter_index))""",
    """CREATE TABLE IF NOT EXISTS corpus_passages (
         passage_id TEXT PRIMARY KEY, fingerprint TEXT,
         chapter_index INTEGER, start_offset INTEGER,
         end_offset INTEGER, text_hash TEXT)""",
    """CREATE INDEX IF NOT EXISTS corpus_passages_work_chapter
         ON corpus_passages (fingerprint, chapter_index)""",
    """CREATE TABLE IF NOT EXISTS passage_vectors (
         passage_id TEXT PRIMARY KEY, fingerprint TEXT, model TEXT,
         format TEXT, dim INTEGER, vector BLOB)""",
    """CREATE TABLE IF NOT EXISTS ingest_runs (
         id INTEGER PRIMARY KEY, fingerprint TEXT, started TEXT,
         finished TEXT, parser_version TEXT, embed_model TEXT,
         outcome TEXT, detail TEXT)""",
    """CREATE TABLE IF NOT EXISTS stage_runs (
         run_id TEXT PRIMARY KEY, fingerprint TEXT, stage TEXT,
         stage_version TEXT, model TEXT, input_hash TEXT,
         started TEXT, finished TEXT, status TEXT, payload TEXT)""",
    """CREATE TABLE IF NOT EXISTS stage_outputs (
         fingerprint TEXT, stage TEXT, output_key TEXT,
         input_hash TEXT, run_id TEXT, payload TEXT,
         PRIMARY KEY (fingerprint, stage, output_key))""",
    """CREATE TABLE IF NOT EXISTS quotes (
         quote_id TEXT PRIMARY KEY, fingerprint TEXT,
         chapter_index INTEGER, start_offset INTEGER,
         end_offset INTEGER, text TEXT, kind TEXT, status TEXT,
         payload TEXT)""",
    """CREATE TABLE IF NOT EXISTS work_envelope (
         fingerprint TEXT PRIMARY KEY, corpus_v TEXT,
         envelope TEXT, computed_at TEXT)""",
]

# FTS5 external-content index over corpus_chapters (§1.3, option A),
# maintained by triggers (A7) inside the same transaction as the text
# write — there is no application-level "remember to sync the index"
# step to forget, and rowids (unstable across generation replacement)
# stay honest through the rewrite. Applied only when the FTS5 probe
# passes (§1.5); a probe-less Python opens the corpus degraded.
_CORPUS_FTS_DDL = [
    """CREATE VIRTUAL TABLE IF NOT EXISTS corpus_fts USING fts5(
         text, content=corpus_chapters, content_rowid=rowid,
         tokenize='unicode61')""",
    """CREATE TRIGGER IF NOT EXISTS corpus_chapters_ai
         AFTER INSERT ON corpus_chapters BEGIN
           INSERT INTO corpus_fts(rowid, text)
             VALUES (new.rowid, new.text);
         END""",
    """CREATE TRIGGER IF NOT EXISTS corpus_chapters_ad
         AFTER DELETE ON corpus_chapters BEGIN
           INSERT INTO corpus_fts(corpus_fts, rowid, text)
             VALUES ('delete', old.rowid, old.text);
         END""",
    """CREATE TRIGGER IF NOT EXISTS corpus_chapters_au
         AFTER UPDATE ON corpus_chapters BEGIN
           INSERT INTO corpus_fts(corpus_fts, rowid, text)
             VALUES ('delete', old.rowid, old.text);
           INSERT INTO corpus_fts(rowid, text)
             VALUES (new.rowid, new.text);
         END""",
]

# Tables whose logical content the corpus dump hash covers. The FTS
# index is derived (a function of corpus_chapters) and is excluded —
# the hash attests canonical content, not its indexes.
_CORPUS_TABLES = [
    "meta", "corpus_works", "corpus_chapters", "corpus_passages",
    "passage_vectors", "ingest_runs", "stage_runs", "stage_outputs",
    "quotes", "work_envelope",
]

# §5.2's writer table, enforced by handle construction (mode), not
# convention: meta is written by CorpusDB open itself (probes,
# generation stamps); every other family names its writer modes.
_CORPUS_FAMILY_MODES = {
    "text": {"importer"},
    "vectors": {"importer", "processor"},
    "stages": {"processor"},
    "envelope": {"importer", "processor"},
}
CORPUS_MODES = ("importer", "processor", "report")


class CorpusWriteRefused(RuntimeError):
    """A corpus write attempted through a handle whose mode does not
    own that table family (§5.2 writer discipline)."""


def _corpus_probe_fts5(conn):
    """§1.5 probe: can this Python's SQLite build FTS5 tables?
    Probed at open, never presumed."""
    try:
        conn.execute(
            "CREATE VIRTUAL TABLE temp.__corpus_probe_fts USING fts5(x)")
        conn.execute("DROP TABLE temp.__corpus_probe_fts")
        return True
    except Exception:
        return False


def _corpus_probe_extensions(conn):
    """§1.5 probe: is extension loading callable on this connection
    (the §2.3 sqlite-vec path's precondition)?"""
    try:
        return callable(getattr(conn, "enable_load_extension", None))
    except Exception:
        return False


_FTS_NOTICE_PRINTED = False


class CorpusDB(_SubstrateHandle):
    """The corpus handle for one learn dir's corpus.db (§1.1).

    Constructed IN a mode (§5.2): a handle is built as importer,
    processor, or report, and its write_txn(family) refuses families
    the mode does not own — from the first day, because slices land
    their writers against guards that already exist (§11 slice 1).
    """

    _DB_NAME = _CORPUS_DB_NAME
    _DDL = _CORPUS_DDL
    _TABLES = _CORPUS_TABLES
    _SCHEMA_VERSION = CORPUS_SCHEMA_VERSION

    def __init__(self, path, conn, mode="processor", readonly=False):
        super().__init__(path, conn)
        if mode not in CORPUS_MODES:
            raise ValueError(f"unknown corpus mode: {mode!r}")
        self.mode = mode
        self._readonly = bool(readonly)
        self.fts_available = False
        self.extensions_available = False

    @classmethod
    def _connect(cls, path):
        conn = super()._connect(path)
        conn.execute(f"PRAGMA busy_timeout={_CORPUS_BUSY_TIMEOUT_MS}")
        return conn

    @classmethod
    def _create_schema(cls, conn):
        super()._create_schema(conn)
        if _corpus_probe_fts5(conn):
            with conn:
                for ddl in _CORPUS_FTS_DDL:
                    conn.execute(ddl)

    @classmethod
    def _register_instance(cls, db):
        _register_corpus_db(db)

    @classmethod
    def _corrupt_fallback(cls, path, err):
        # §1.1 divergence (b): corpus content is re-derivable, so a
        # corrupt corpus opens as ABSENT — processing falls back to
        # file parsing — instead of starting over an empty DB in
        # place (which would also violate create-on-ingest, (c)).
        print(f"  !! WARNING: corpus {path} could not be opened "
              f"({err}); the corpus is UNAVAILABLE for this process "
              f"and processing falls back to file parsing. The "
              f"original file will be preserved as a .corrupt backup "
              f"(rename-in-place, never a copy). No book data is "
              f"lost: the corpus is retained work, re-derivable by "
              f"--ingest from the books themselves.")
        cls._preserve_corrupt(path)
        return None

    def _after_open(self):
        # §1.5 probes, recorded in meta (writable handles only).
        probe_fts = _corpus_probe_fts5(self._conn)
        self.extensions_available = _corpus_probe_extensions(self._conn)
        have_fts = bool(self.query(
            "SELECT name FROM sqlite_master WHERE type='table' "
            "AND name='corpus_fts'"))
        if probe_fts and not have_fts and not self._readonly:
            # Self-heal across machines: the DB was created on a
            # Python whose SQLite lacked FTS5; this one has it, so
            # the derived index joins now (it rebuilds from the
            # canonical text via the triggers' backfill below).
            with self._lock:
                with self._conn:
                    for ddl in _CORPUS_FTS_DDL:
                        self._conn.execute(ddl)
                    self._conn.execute(
                        "INSERT INTO corpus_fts(corpus_fts) "
                        "VALUES ('rebuild')")
            have_fts = True
        self.fts_available = bool(probe_fts and have_fts)
        if self._readonly:
            return
        with self._lock:
            with self._conn:
                self._conn.execute(
                    "INSERT OR IGNORE INTO meta (k, v) VALUES "
                    "('corpus_v', ?), ('created_by', ?)",
                    (CORPUS_V, PORTABLE_VERSION))
                self._conn.execute(
                    "INSERT OR REPLACE INTO meta (k, v) VALUES "
                    "('probe_fts5', ?), ('probe_extensions', ?)",
                    ("1" if probe_fts else "0",
                     "1" if self.extensions_available else "0"))

    def meta_get(self, key, default=None):
        rows = self.query("SELECT v FROM meta WHERE k=?", (key,))
        return rows[0][0] if rows else default

    def meta_set(self, key, value):
        """Open-level bookkeeping writes (generation stamps, canary
        state): meta's writer is CorpusDB itself (§5.2)."""
        if self._readonly:
            raise CorpusWriteRefused("read-only corpus handle")
        with self._lock:
            with self._conn:
                self._conn.execute(
                    "INSERT OR REPLACE INTO meta (k, v) VALUES (?, ?)",
                    (key, value))

    def write_txn(self, family=None):
        """One write transaction for a table FAMILY (§5.2). The mode
        check happens at construction of the transaction — a refused
        family raises before any lock or BEGIN."""
        if family is not None:
            modes = _CORPUS_FAMILY_MODES.get(family)
            if modes is None:
                raise CorpusWriteRefused(
                    f"unknown corpus table family: {family!r}")
            if self.mode not in modes:
                raise CorpusWriteRefused(
                    f"corpus mode {self.mode!r} may not write the "
                    f"{family!r} family (writer modes: "
                    f"{', '.join(sorted(modes))})")
        if self._readonly:
            raise CorpusWriteRefused("read-only corpus handle")
        return _SubstrateWriteTxn(self)

    # -- consumers ------------------------------------------------------
    def fts_search_chapters(self, phrase):
        """Chapter-granular FTS search (§1.3): returns a list of
        (fingerprint, chapter_index) whose text matches the phrase,
        or None when FTS is unavailable on this Python (degraded
        open, §1.5 — the notice prints once per process)."""
        global _FTS_NOTICE_PRINTED
        if not self.fts_available:
            if not _FTS_NOTICE_PRINTED:
                _FTS_NOTICE_PRINTED = True
                print("  FTS unavailable on this Python's SQLite — "
                      "text search skipped (corpus text, passages, "
                      "and vectors are unaffected)")
            return None
        tokens = [t for t in str(phrase).split() if t]
        if not tokens:
            return []
        match = '"' + " ".join(
            t.replace('"', ' ') for t in tokens) + '"'
        rows = self.query(
            "SELECT c.fingerprint, c.chapter_index FROM corpus_fts f "
            "JOIN corpus_chapters c ON c.rowid = f.rowid "
            "WHERE corpus_fts MATCH ? "
            "ORDER BY c.fingerprint, c.chapter_index", (match,))
        return [(r[0], r[1]) for r in rows]


_CORPUS_DBS = {}
_CORPUS_DBS_LOCK = threading.Lock()


def _register_corpus_db(db):
    with _CORPUS_DBS_LOCK:
        _CORPUS_DBS[str(db.path.parent.resolve())] = db


def _corpus_db_for(learn_dir, mode="processor"):
    """The corpus handle for a learn dir, or None when the dir has
    no corpus.db (open NEVER creates one, §1.1 (c)). The mode
    applies when this call opens the handle; a handle's mode is
    its write authority, enforced by its own write_txn."""
    if learn_dir is None:
        return None
    key = str(Path(learn_dir).resolve())
    with _CORPUS_DBS_LOCK:
        db = _CORPUS_DBS.get(key)
    if db is not None:
        # One handle per process per learn dir: a registered handle
        # is returned as-is — its construction mode governs its own
        # writes (write_txn checks the handle's mode, not the
        # requester's), and a CLI process runs in one mode anyway.
        return db
    if not (Path(learn_dir) / _CORPUS_DB_NAME).exists():
        return None
    return CorpusDB.open(learn_dir, mode=mode)


def _close_corpus_dbs():
    """Close every registered corpus handle (tests, hygiene)."""
    with _CORPUS_DBS_LOCK:
        dbs = list(_CORPUS_DBS.values())
        _CORPUS_DBS.clear()
    for db in dbs:
        db.close()




# ---------------------------------------------------------------------------
# Corpus ingest — the importer mode (corpus-design §3). Acquisition is
# separated from analysis: --ingest parses a book ONCE, through the
# pipeline's own parse functions in the same order process_file_v2
# calls them (§3.1 — there is no second parser to drift), and stores
# chapter text, passage spans, and the FTS index in corpus.db.
# Ingest runs no model: the same file under the same parser version
# ingests to the same corpus, bit for bit, on any machine.
# ---------------------------------------------------------------------------

_CORPUS_BOOK_SUFFIXES = (".epub", ".mobi", ".azw3")


class CorpusIngestError(RuntimeError):
    """An ingest failed in a way the state machine records as
    outcome='failed' (losslessness self-check, no chapters)."""


def _corpus_sha256(data):
    import hashlib as _hl
    if isinstance(data, str):
        data = data.encode("utf-8")
    return _hl.sha256(data).hexdigest()


def _corpus_text_hash(text):
    return _corpus_sha256(text or "")


def _corpus_root_hash(chapter_hashes):
    """Root hash over the ORDERED chapter hashes (§3.2)."""
    return _corpus_sha256("\n".join(chapter_hashes))


def _corpus_passage_id(fingerprint, chapter_index, start, end):
    """Content-derived passage identity (§1.4): the same book under
    the same versions produces the same ids; a window-format change
    produces a new passage population, stated in the ids."""
    raw = "\x1f".join([str(fingerprint), str(chapter_index),
                       str(start), str(end), _CORPUS_WINDOW_FORMAT])
    return _corpus_sha256(raw)[:32]


def _corpus_now():
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).isoformat()


def _corpus_parse_book(fpath):
    """Parse a book exactly as process_file_v2's acquisition block
    does — same functions, same order, same diagnostics (§3.1).
    Returns a dict, or None when the format yields no text."""
    fpath = Path(fpath)
    if fpath.suffix.lower() == ".epub":
        _DIAG.chapter_detection_fallback = False  # reset per book
        units, title, author, identifiers = extract_epub_units(fpath)
        chapters = split_chapters(units)
        fallback = bool(getattr(_DIAG, "chapter_detection_fallback",
                                False))
        word_count = sum(len(u["text"].split()) for u in units)
    else:
        extracted = read_ebook(fpath)
        if extracted is None:
            return None
        text, title, author, identifiers = extracted
        _DIAG.chapter_detection_fallback = False  # reset per book
        chapters = _prose_chapters(text)
        fallback = bool(getattr(_DIAG, "chapter_detection_fallback",
                                False))
        word_count = len(text.split())
    chapters = sorted(chapters, key=lambda c: c.get("index", 0))
    return {"chapters": chapters, "title": title, "author": author,
            "identifiers": identifiers or {},
            "word_count": word_count,
            "chapter_detection_fallback": fallback,
            "source_name": fpath.name}


def _corpus_series_offline(fpath, identifiers):
    """Series as resolved at ingest, from OFFLINE sources only —
    _detect_series' flag/calibre/filename steps. The Open Library
    step is a network call, and §3.1 makes acquisition deterministic
    (same file + parser version -> same corpus on any machine); the
    run's own _detect_series remains the processing-time authority.
    Returns (name, index, source)."""
    flag_name = (CONFIG.get("series_override") or "").strip()
    if flag_name:
        return flag_name, CONFIG.get("series_position_override"), "flag"
    if identifiers:
        s = (identifiers.get("series") or "").strip()
        if s:
            return s, identifiers.get("series_index"), "epub"
    name, pos = _parse_series_from_filename(Path(fpath).name)
    if name:
        return name, pos, "filename"
    return None, None, "none"


def _corpus_fingerprint(parsed):
    return _checkpoint_fingerprint(
        parsed["identifiers"], parsed["title"], parsed["author"],
        _checkpoint_text_sample(parsed["chapters"]))


# -- consumer gates (§3.3: consumers gate on status, by family) ------

def corpus_work_record(db, fingerprint):
    rows = db.query(
        "SELECT fingerprint, book_key, work_id, title, author, "
        "identifiers, series, series_index, parser_version, "
        "chapter_count, text_root_hash, source_hash, status, "
        "ingested_at, updated_at, payload FROM corpus_works "
        "WHERE fingerprint=?", (fingerprint,))
    if not rows:
        return None
    cols = ("fingerprint", "book_key", "work_id", "title", "author",
            "identifiers", "series", "series_index", "parser_version",
            "chapter_count", "text_root_hash", "source_hash", "status",
            "ingested_at", "updated_at", "payload")
    return dict(zip(cols, rows[0]))


def corpus_work_state(db, fingerprint):
    """The composed state every consumer reads (§3.3): the stored
    status, with staleness composed in — a work stamped by an older
    parser generation is 'stale' whatever its stored status says."""
    rec = corpus_work_record(db, fingerprint)
    if rec is None:
        return "absent"
    if rec["status"] in ("ingesting", "failed"):
        return rec["status"]
    if rec["parser_version"] != CORPUS_PARSER_VERSION:
        return "stale"
    return rec["status"]


def corpus_chapters_for(db, fingerprint):
    """Chapter dicts for text consumers, or None. Text consumers
    need >= text_complete under the current parser generation
    (§3.3); a work in ingesting/failed/stale reads as absent."""
    if corpus_work_state(db, fingerprint) not in (
            "text_complete", "vectors_partial", "complete"):
        return None
    rows = db.query(
        "SELECT chapter_index, label, text, is_frontmatter FROM "
        "corpus_chapters WHERE fingerprint=? ORDER BY chapter_index",
        (fingerprint,))
    return [{"index": ci, "label": label, "text": text,
             "is_frontmatter": bool(fm)} for ci, label, text, fm in rows]


def corpus_retrieval_ready(db, fingerprint):
    """Retrieval's gate (§3.3): only a complete work under the
    current parser generation serves retrieval as a corpus; the
    gap-filling fallback for lesser states is §4.4's, at the vector
    layer, never a status shortcut here."""
    return corpus_work_state(db, fingerprint) == "complete"


# -- envelope (v1 sections; §6.4's refresh discipline) ---------------

def _corpus_refresh_envelope_in_txn(db, conn, fingerprint):
    """Refresh the corpus-sourced envelope sections (text, vectors)
    INSIDE the caller's transaction — the refresh rides the write
    that changes the facts (§6.4), so a payload can never pair a
    new text generation with sections computed against the old
    one. Other sections (written by later slices) are preserved."""
    now = _corpus_now()
    row = conn.execute(
        "SELECT envelope FROM work_envelope WHERE fingerprint=?",
        (fingerprint,)).fetchone()
    env = {}
    if row and row[0]:
        try:
            env = json.loads(row[0])
        except (TypeError, ValueError):
            env = {}
    sections = env.setdefault("sections", {})
    w = conn.execute(
        "SELECT status, chapter_count FROM corpus_works "
        "WHERE fingerprint=?", (fingerprint,)).fetchone()
    status = w[0] if w else None
    n_pass = conn.execute(
        "SELECT COUNT(*) FROM corpus_passages WHERE fingerprint=?",
        (fingerprint,)).fetchone()[0]
    text_state = ("present" if status in (
        "text_complete", "vectors_partial", "complete") else "unknown")
    sections["text"] = {
        "state": text_state, "stage": "ingest",
        "model": "deterministic", "stage_version": CORPUS_PARSER_VERSION,
        "updated_at": now, "scope": "edition",
        "value": {"chapters": w[1] if w else 0, "passages": n_pass,
                  "status": status}}
    # Vectors is the normative coverage statement (A5): composed
    # against the CURRENT (model, format) generation, never the
    # bare ingest-time status.
    gen = None
    cur = db.meta_get("generation_current")
    if cur:
        try:
            gen = json.loads(cur)
        except (TypeError, ValueError):
            gen = None
    coverage = None
    if gen is not None and n_pass:
        n_vec = conn.execute(
            "SELECT COUNT(*) FROM passage_vectors pv JOIN "
            "corpus_passages p ON p.passage_id = pv.passage_id "
            "WHERE p.fingerprint=? AND pv.model=? AND pv.format=?",
            (fingerprint, gen.get("model"), gen.get("format"))
            ).fetchone()[0]
        coverage = round(n_vec / n_pass, 4)
    sections["vectors"] = {
        "state": "present" if coverage is not None else "unknown",
        "stage": "embed", "model": (gen or {}).get("model"),
        "stage_version": _CORPUS_VECTOR_FORMAT,
        "updated_at": now, "scope": "edition",
        "coverage": coverage,
        "value": {"coverage": coverage,
                  "generation": ({"model": gen.get("model"),
                                  "format": gen.get("format")}
                                 if gen else None)}}
    conn.execute(
        "INSERT OR REPLACE INTO work_envelope (fingerprint, corpus_v,"
        " envelope, computed_at) VALUES (?, ?, ?, ?)",
        (fingerprint, CORPUS_V, json.dumps(env, ensure_ascii=False),
         now))


# -- ingest steps ------------------------------------------------------

def _corpus_ingest_bookkeeping(db, parsed, fingerprint, source_hash,
                               reason=""):
    """A9: the bookkeeping — the corpus_works row at 'ingesting'
    plus its ingest_runs row — commits in its OWN small transaction
    BEFORE phase 1 begins. A crash afterwards leaves the 'ingesting'
    row as observable evidence instead of silence, and the next
    ingest of the fingerprint re-enters idempotently (§3.3)."""
    now = _corpus_now()
    ids = parsed["identifiers"]
    prior = db.query(
        "SELECT status, parser_version FROM corpus_works "
        "WHERE fingerprint=?", (fingerprint,))
    detail = {"reason": reason or None, "source_name":
              parsed["source_name"], "source_hash": source_hash}
    if prior and prior[0][1] and prior[0][1] != CORPUS_PARSER_VERSION:
        detail["supersedes"] = {"parser_version": prior[0][1]}
    series, series_index, _src = _corpus_series_offline(
        parsed["source_name"], ids)
    book_key = staging_work_key(
        isbn=ids.get("isbn") or ids.get("asin"),
        title=parsed["title"] or "", author=parsed["author"] or "")
    with db.write_txn("text") as conn:
        cur = conn.execute(
            "INSERT INTO ingest_runs (fingerprint, started, finished,"
            " parser_version, embed_model, outcome, detail) VALUES "
            "(?, ?, NULL, ?, NULL, NULL, ?)",
            (fingerprint, now, CORPUS_PARSER_VERSION,
             json.dumps(detail, ensure_ascii=False)))
        run_id = cur.lastrowid
        conn.execute(
            "INSERT INTO corpus_works (fingerprint, book_key, title,"
            " author, identifiers, series, series_index, status,"
            " ingested_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?,"
            " 'ingesting', ?, ?) "
            "ON CONFLICT(fingerprint) DO UPDATE SET book_key="
            "excluded.book_key, title=excluded.title, author="
            "excluded.author, identifiers=excluded.identifiers, "
            "series=excluded.series, series_index="
            "excluded.series_index, status='ingesting', updated_at="
            "excluded.updated_at, ingested_at=COALESCE("
            "corpus_works.ingested_at, excluded.ingested_at)",
            (fingerprint, book_key, parsed["title"], parsed["author"],
             json.dumps(ids, ensure_ascii=False), series, series_index,
             now, now))
    return run_id, (prior[0][0] if prior else None)


def _corpus_fts_integrity_ok(conn):
    """A7's gate, as a seam: FTS5's own integrity-check over
    corpus_fts. A mismatch fails the ingest exactly as a hash
    mismatch does (§3.2 step 4)."""
    try:
        conn.execute(
            "INSERT INTO corpus_fts(corpus_fts) "
            "VALUES ('integrity-check')")
        return True
    except Exception:
        return False


def _corpus_selfcheck_in_txn(db, conn, fingerprint, chapters,
                             root_hash):
    """§3.2's losslessness self-check, inside the phase-1
    transaction, before the work may flip to text_complete:
    re-read + re-hash every chapter, recompute the root, re-slice
    EVERY passage span (100%, A2), and run FTS integrity-check."""
    rows = conn.execute(
        "SELECT chapter_index, text, text_hash FROM corpus_chapters "
        "WHERE fingerprint=? ORDER BY chapter_index",
        (fingerprint,)).fetchall()
    if len(rows) != len(chapters):
        raise CorpusIngestError(
            f"self-check: stored {len(rows)} chapters, parsed "
            f"{len(chapters)}")
    texts = {}
    stored_hashes = []
    for ci, text, th in rows:
        if _corpus_text_hash(text) != th:
            raise CorpusIngestError(
                f"self-check: chapter {ci} text hash mismatch")
        texts[ci] = text
        stored_hashes.append(th)
    if _corpus_root_hash(stored_hashes) != root_hash:
        raise CorpusIngestError("self-check: root hash mismatch")
    for ci, start, end, th in conn.execute(
            "SELECT chapter_index, start_offset, end_offset, "
            "text_hash FROM corpus_passages WHERE fingerprint=?",
            (fingerprint,)):
        span = texts[ci][start:end]
        if _corpus_text_hash(span) != th:
            raise CorpusIngestError(
                f"self-check: passage slice mismatch in chapter {ci}")
    if db.fts_available and not _corpus_fts_integrity_ok(conn):
        raise CorpusIngestError("self-check: FTS integrity-check "
                                "failed")


def _corpus_phase1_write(db, parsed, fingerprint, source_hash):
    """Phase 1 (one transaction, §3.3): chapters + passages against
    the pre-committed bookkeeping row; the previous generation's
    passages and their vectors are deleted in the same transaction
    (§3.4 — superseded generations do not accumulate); FTS rows
    follow via triggers (A7). The §3.2 self-check runs before the
    status flip; any failure rolls the whole book back."""
    chapters = parsed["chapters"]
    hashes = [_corpus_text_hash(ch["text"]) for ch in chapters]
    root = _corpus_root_hash(hashes)
    n_passages = 0
    with db.write_txn("text") as conn:
        conn.execute(
            "DELETE FROM passage_vectors WHERE passage_id IN "
            "(SELECT passage_id FROM corpus_passages "
            "WHERE fingerprint=?)", (fingerprint,))
        conn.execute("DELETE FROM corpus_passages WHERE fingerprint=?",
                     (fingerprint,))
        conn.execute("DELETE FROM corpus_chapters WHERE fingerprint=?",
                     (fingerprint,))
        for ch, th in zip(chapters, hashes):
            ci = ch.get("index")
            text = ch["text"]
            conn.execute(
                "INSERT INTO corpus_chapters (fingerprint, "
                "chapter_index, label, text, text_hash, char_count, "
                "word_count, is_frontmatter) VALUES (?, ?, ?, ?, ?, "
                "?, ?, ?)",
                (fingerprint, ci, ch.get("label"), text, th,
                 len(text), len(text.split()),
                 1 if ch.get("is_frontmatter") else 0))
            for w in _evidence_windows(text):
                start = w["offset"]
                end = start + len(w["text"])
                conn.execute(
                    "INSERT INTO corpus_passages (passage_id, "
                    "fingerprint, chapter_index, start_offset, "
                    "end_offset, text_hash) VALUES (?, ?, ?, ?, ?, ?)",
                    (_corpus_passage_id(fingerprint, ci, start, end),
                     fingerprint, ci, start, end,
                     _corpus_text_hash(w["text"])))
                n_passages += 1
        payload = {
            "chapter_detection_fallback":
                parsed["chapter_detection_fallback"],
            "word_count": parsed["word_count"],
            "source_name": parsed["source_name"],
            "series_source": _corpus_series_offline(
                parsed["source_name"], parsed["identifiers"])[2],
        }
        conn.execute(
            "UPDATE corpus_works SET chapter_count=?, "
            "text_root_hash=?, source_hash=?, parser_version=?, "
            "status='text_complete', payload=?, updated_at=? "
            "WHERE fingerprint=?",
            (len(chapters), root, source_hash, CORPUS_PARSER_VERSION,
             json.dumps(payload, ensure_ascii=False), _corpus_now(),
             fingerprint))
        _corpus_selfcheck_in_txn(db, conn, fingerprint, chapters, root)
        _corpus_refresh_envelope_in_txn(db, conn, fingerprint)
    return {"chapters": len(chapters), "passages": n_passages,
            "text_root_hash": root}


def _corpus_finalize_run(db, run_id, outcome, detail,
                         embed_model=None):
    """Close out an ingest_runs row, MERGING the outcome detail into
    the bookkeeping detail (reason, source, supersession record) —
    the run's forensic record keeps both halves (§3.4)."""
    with db.write_txn("text") as conn:
        row = conn.execute(
            "SELECT detail FROM ingest_runs WHERE id=?",
            (run_id,)).fetchone()
        merged = {}
        if row and row[0]:
            try:
                merged = json.loads(row[0])
            except (TypeError, ValueError):
                merged = {}
        merged.update(detail)
        conn.execute(
            "UPDATE ingest_runs SET finished=?, outcome=?, detail=?, "
            "embed_model=COALESCE(?, embed_model) WHERE id=?",
            (_corpus_now(), outcome,
             json.dumps(merged, ensure_ascii=False), embed_model,
             run_id))


def corpus_ingest_book(db, fpath, reason="", force=False,
                       embedder=None):
    """Ingest one book file into the corpus (§3). Returns a result
    dict {fingerprint, outcome, chapters, passages, detail,
    source_name}; outcome is noop | partial | complete | failed.
    With no embedder the ingest stops at text_complete (outcome
    'partial' — vectors pending); slice 3's command wiring passes
    the real embedder for phase 2."""
    fpath = Path(fpath)
    result = {"fingerprint": None, "outcome": "failed",
              "source_name": fpath.name, "chapters": 0, "passages": 0,
              "detail": None}
    try:
        parsed = _corpus_parse_book(fpath)
    except Exception as e:
        parsed = None
        result["detail"] = f"parse failed: {e}"
    if parsed is None or not parsed["chapters"]:
        if parsed is not None:
            result["detail"] = "no chapters extracted"
        try:
            with db.write_txn("text") as conn:
                conn.execute(
                    "INSERT INTO ingest_runs (fingerprint, started, "
                    "finished, parser_version, embed_model, outcome, "
                    "detail) VALUES (NULL, ?, ?, ?, NULL, 'failed', "
                    "?)",
                    (_corpus_now(), _corpus_now(),
                     CORPUS_PARSER_VERSION,
                     json.dumps({"source_name": fpath.name,
                                 "error": result["detail"]},
                                ensure_ascii=False)))
        except Exception:
            pass
        return result
    fingerprint = _corpus_fingerprint(parsed)
    result["fingerprint"] = fingerprint
    source_hash = _corpus_sha256(fpath.read_bytes())
    rec = corpus_work_record(db, fingerprint)
    if (not force and rec is not None
            and rec["source_hash"] == source_hash
            and rec["parser_version"] == CORPUS_PARSER_VERSION
            and rec["status"] in ("text_complete", "vectors_partial",
                                  "complete")):
        result.update({"outcome": "noop",
                       "chapters": rec["chapter_count"] or 0,
                       "passages": db.query(
                           "SELECT COUNT(*) FROM corpus_passages "
                           "WHERE fingerprint=?",
                           (fingerprint,))[0][0],
                       "detail": "already ingested, parser v"
                                 f"{rec['parser_version']}, "
                                 f"{rec['ingested_at']}"})
        return result
    run_id, prior_status = _corpus_ingest_bookkeeping(
        db, parsed, fingerprint, source_hash, reason=reason)
    try:
        stats = _corpus_phase1_write(db, parsed, fingerprint,
                                     source_hash)
    except Exception as e:
        # The phase-1 transaction rolled back: no partial book is
        # committed. Restore the pre-attempt status when a previous
        # generation survives intact; a first ingest reads 'failed'.
        with db.write_txn("text") as conn:
            conn.execute(
                "UPDATE corpus_works SET status=? WHERE fingerprint=?",
                (prior_status or "failed", fingerprint))
            row = conn.execute(
                "SELECT detail FROM ingest_runs WHERE id=?",
                (run_id,)).fetchone()
            merged = {}
            if row and row[0]:
                try:
                    merged = json.loads(row[0])
                except (TypeError, ValueError):
                    merged = {}
            merged.update({"error": str(e)})
            conn.execute(
                "UPDATE ingest_runs SET finished=?, outcome='failed'"
                ", detail=? WHERE id=?",
                (_corpus_now(),
                 json.dumps(merged, ensure_ascii=False), run_id))
        result["detail"] = str(e)
        return result
    result.update(stats)
    if embedder is not None:
        embed_fn, embed_model = embedder
        outcome = corpus_embed_work(db, fingerprint, embed_fn,
                                    embed_model, run_id=run_id)
        detail = {"source_name": parsed["source_name"],
                  "phases": [1, 2], "reason": reason or None,
                  "chapters": stats["chapters"],
                  "passages": stats["passages"]}
        if outcome == "suspect":
            detail["canary"] = (
                "drift — generation marked suspect; its vectors "
                "read as misses until re-embedded clean (§2.4)")
        _corpus_finalize_run(
            db, run_id,
            "complete" if outcome == "complete" else "partial",
            detail, embed_model=embed_model)
        result["outcome"] = outcome
    else:
        _corpus_finalize_run(db, run_id, "partial", {
            "source_name": parsed["source_name"], "phases": [1],
            "vectors": "pending", "reason": reason or None,
            "chapters": stats["chapters"],
            "passages": stats["passages"]})
        result["outcome"] = "partial"
    return result


def corpus_remove_work(db, fingerprint):
    """--corpus-remove (A10, §3.4): ONE transaction across every
    corpus table keyed by the fingerprint — works, chapters,
    passages, vectors, stage runs and outputs, quotes, envelope —
    with per-table counts. Partial removal is not offered: an
    orphaned stage output or quote would resurrect on re-ingest.
    Removal never cascades into state.db. ingest_runs rows stay:
    they are the forensic record of what was ingested when."""
    if db.mode == "report":
        raise CorpusWriteRefused(
            "a report-mode handle cannot remove a corpus work")
    counts = {}
    with db.write_txn() as conn:
        for table in ("passage_vectors", "corpus_passages",
                      "corpus_chapters", "stage_outputs",
                      "stage_runs", "quotes", "work_envelope",
                      "corpus_works"):
            cur = conn.execute(
                f"DELETE FROM {table} WHERE fingerprint=?",
                (fingerprint,))
            counts[table] = cur.rowcount
    return counts


def cmd_ingest(paths, learn_dir=None, reason="", force=False):
    """--ingest (file|dir): importer mode, then exit (§3.1). A
    directory ingests every supported book file in it (sorted,
    per-book outcome lines, failures isolated per book)."""
    d = (Path(learn_dir) if learn_dir
         else Path(os.path.expanduser("~")) / ".ebook-processor"
         / "learned")
    db = CorpusDB.create(d, mode="importer")
    files = []
    for p in paths:
        p = Path(p)
        if p.is_dir():
            files.extend(sorted(
                f for f in p.iterdir()
                if f.is_file()
                and f.suffix.lower() in _CORPUS_BOOK_SUFFIXES))
        elif p.is_file():
            files.append(p)
        else:
            print(f"  --ingest: no such file or directory: {p}")
    emb = _corpus_config_embedder()
    if emb is None:
        print("  (no embedder configured — text-only ingest; "
              "vectors stay pending. Set embed_url/embed_model in "
              "config.json, then run --corpus-reembed.)")
    results = []
    for f in files:
        r = corpus_ingest_book(db, f, reason=reason, force=force,
                               embedder=emb)
        fp8 = (r["fingerprint"] or "????????")[:8]
        line = (f"  {r['source_name']}: {r['outcome']} [{fp8}] "
                f"{r['chapters']} chapters, {r['passages']} passages")
        if r["outcome"] == "failed" and r["detail"]:
            line += f" — {r['detail']}"
        print(line)
        results.append(r)
    # §10.4(a): the deterministic opening line for each book whose
    # text landed. Quote records are stage-family writes (§5.2) —
    # the importer handle cannot make them — so generation runs
    # here, after the loop, through a processor-mode handle.
    fps = [r["fingerprint"] for r in results
           if r.get("fingerprint")
           and r["outcome"] in ("partial", "complete")]
    if fps:
        _close_corpus_dbs()
        pdb = CorpusDB.open(d, mode="processor")
        if pdb is not None:
            by_fp = {r["fingerprint"]: r for r in results}
            for fp in fps:
                # A failed opening-line stage must be VISIBLE, not
                # swallowed: the book's text is ingested, so no later
                # ingest of it re-runs this stage — a silent failure
                # here means the opening line never lands and nobody
                # can tell that apart from a book with no usable text.
                # Name the book and the error, record it on the book's
                # ingest result, and keep going: one bad book must
                # not abort the stage for the rest.
                try:
                    corpus_generate_opening_line(pdb, fp)
                except Exception as e:
                    detail = f"{type(e).__name__}: {e}"
                    print(f"  [{fp[:8]}] opening line FAILED — "
                          f"{detail}")
                    if fp in by_fp:
                        by_fp[fp]["opening_line_error"] = detail
    # A standalone ingest dispatch arms the run-history capture in
    # main(); watch-cycle ingests do not (their scan owns the run).
    if _HISTORY_INGEST_CAPTURE:
        _history_note_ingest(results, files, db)
    return results


def cmd_corpus_remove(fingerprint, learn_dir=None):
    """--corpus-remove <fingerprint>: the named, printed removal
    act (A10). Human-invoked only; never cascades into state.db."""
    d = (Path(learn_dir) if learn_dir
         else Path(os.path.expanduser("~")) / ".ebook-processor"
         / "learned")
    db = _corpus_db_for(d, mode="importer")
    if db is None:
        print(f"  No corpus in {d} — nothing to remove.")
        return
    if corpus_work_record(db, fingerprint) is None:
        print(f"  No corpus work with fingerprint {fingerprint}.")
        return
    counts = corpus_remove_work(db, fingerprint)
    parts = ", ".join(f"{t} {n}" for t, n in counts.items() if n)
    print(f"  Removed corpus work {fingerprint}: {parts}.")


# ---------------------------------------------------------------------------
# Corpus vectors (corpus-design §2): BLOB-canonical storage,
# content-keyed reads, in-process search, and the A1 drift canary.
# Storage and search are separate decisions (§2's preamble): the
# BLOBs are readable by anything, forever, with no loadable binary;
# search is an in-process scan — numpy when importable, a
# pure-Python fallback otherwise, top-k parity pinned (§2.5).
# ---------------------------------------------------------------------------

_CORPUS_EMBED_BATCH = 64
# Drift tolerance for the canary (§2.4): a sentinel's re-embedded
# vector must cosine-match its reference within this band, and the
# pairwise structure must hold within it too.
_CORPUS_CANARY_BAND = 0.05
_CORPUS_CANARY_TEXTS = [
    "The harbour bell rang once over the grey water.",
    "She folded the letter twice and hid it in the drawer.",
    "Quantum tunnelling lets particles cross barriers they cannot "
    "climb.",
    "Preheat the oven, then whisk the eggs with sugar and lemon "
    "zest.",
    "The committee postponed the vote until after the harvest "
    "festival.",
    "A red fox slipped through the hedge at the bottom of the "
    "garden.",
]
# (db path, model, format) generations whose canary this process has
# already verified — the check runs at generation birth, on every
# ingest/reembed entry, and on --corpus-status (§2.4), not per read.
_CANARY_CHECKED_THIS_PROCESS = set()


def _corpus_pack_vector(vec):
    import struct
    return struct.pack(f"<{len(vec)}f", *vec)


def _corpus_unpack_vector(blob, dim):
    import struct
    return list(struct.unpack(f"<{dim}f", blob))


def _corpus_cosine(a, b):
    import math
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0.0 or nb == 0.0:
        return 0.0
    return dot / (na * nb)


# -- generations + the drift canary (§2.4) ----------------------------

def _corpus_generation_key(model, fmt):
    return f"generation:{model}|{fmt}"


def _corpus_generation(db, model, fmt=_CORPUS_VECTOR_FORMAT):
    raw = db.meta_get(_corpus_generation_key(model, fmt))
    if not raw:
        return None
    try:
        return json.loads(raw)
    except (TypeError, ValueError):
        return None


def _corpus_store_generation(db, gen):
    db.meta_set(_corpus_generation_key(gen["model"], gen["format"]),
                json.dumps(gen, ensure_ascii=False))
    db.meta_set("generation_current",
                json.dumps({"model": gen["model"],
                            "format": gen["format"]},
                           ensure_ascii=False))


def _corpus_generation_birth(db, embed_fn, model,
                             fmt=_CORPUS_VECTOR_FORMAT):
    """A generation is born with its sentinel set (§2.4): pinned
    probe texts embedded NOW, their reference vectors and pairwise
    cosines recorded in meta. Later drift — the same model string
    served by different weights — is measured against this birth
    record, the only reference that exists."""
    vecs = embed_fn(list(_CORPUS_CANARY_TEXTS))
    if len(vecs) != len(_CORPUS_CANARY_TEXTS):
        raise CorpusIngestError(
            "canary: embedder returned a wrong vector count")
    dim = len(vecs[0])
    cosines = [[round(_corpus_cosine(a, b), 6) for b in vecs]
               for a in vecs]
    gen = {"model": model, "format": fmt, "dim": dim,
           "canary": "ok", "born": _corpus_now(),
           "checked": _corpus_now(),
           "sentinels": {"vectors": vecs, "cosines": cosines}}
    _corpus_store_generation(db, gen)
    _CANARY_CHECKED_THIS_PROCESS.add((str(db.path), model, fmt))
    return gen


def _corpus_canary_check(db, embed_fn, model,
                         fmt=_CORPUS_VECTOR_FORMAT):
    """Re-embed the sentinels and compare against the birth record
    (§2.4). Returns True (within band), False (DRIFT — the
    generation is marked suspect in meta and its rows read as
    misses until re-embedded clean), or None (the check itself
    could not run — an unreachable endpoint is an outage, not
    drift, and leaves the recorded state standing)."""
    gen = _corpus_generation(db, model, fmt)
    if gen is None:
        return True
    try:
        fresh = embed_fn(list(_CORPUS_CANARY_TEXTS))
    except Exception:
        return None
    if len(fresh) != len(_CORPUS_CANARY_TEXTS):
        return None
    ref = gen["sentinels"]["vectors"]
    drift = False
    for rv, nv in zip(ref, fresh):
        if _corpus_cosine(rv, nv) < 1.0 - _CORPUS_CANARY_BAND:
            drift = True
            break
    if not drift:
        ref_cos = gen["sentinels"]["cosines"]
        for i, a in enumerate(fresh):
            for j, b in enumerate(fresh):
                if abs(_corpus_cosine(a, b) - ref_cos[i][j]) \
                        > _CORPUS_CANARY_BAND:
                    drift = True
                    break
            if drift:
                break
    gen["canary"] = "suspect" if drift else "ok"
    gen["checked"] = _corpus_now()
    _corpus_store_generation(db, gen)
    _CANARY_CHECKED_THIS_PROCESS.add((str(db.path), model, fmt))
    return not drift


def _corpus_generation_suspect(db, model, fmt=_CORPUS_VECTOR_FORMAT):
    gen = _corpus_generation(db, model, fmt)
    return bool(gen and gen.get("canary") == "suspect")


# -- phase 2: embedding (§3.3) -----------------------------------------

def _corpus_note_embed_stop(db, run_id, fingerprint, reason):
    """Surface why a work's embedding stopped: one printed line for
    the operator watching the run, and the reason merged into the
    run row's detail (the "embed_error" key) for later inspection.
    The exception text is the only diagnostic a real endpoint
    offers — embed_vectors' carries the HTTP status and the
    server's own error body — and discarding it once turned a
    one-character model-name typo into a multi-round blind
    diagnosis. The record is written at stop time, not at finalize,
    because on the ingest path the caller finalizes this row
    afterwards and its merge preserves keys it does not own. The
    write is best-effort and never raises: bookkeeping must not
    change the outcome the phase returns."""
    print(f"  [{fingerprint[:8]}] embed stopped: {reason}")
    if run_id is None:
        return
    try:
        with db.write_txn("text") as conn:
            row = conn.execute(
                "SELECT detail FROM ingest_runs WHERE id=?",
                (run_id,)).fetchone()
            merged = {}
            if row and row[0]:
                try:
                    merged = json.loads(row[0])
                except (TypeError, ValueError):
                    merged = {}
            merged["embed_error"] = reason
            conn.execute(
                "UPDATE ingest_runs SET detail=? WHERE id=?",
                (json.dumps(merged, ensure_ascii=False), run_id))
    except Exception:
        pass


def corpus_embed_work(db, fingerprint, embed_fn, model,
                      fmt=_CORPUS_VECTOR_FORMAT, run_id=None):
    """Embed every passage of a work that lacks a current-stamp
    vector (§3.3 phase 2). The text embedded is RE-SLICED FROM THE
    STORED CHAPTER at write time (A2) — never carried from the
    parse — so no vector is ever computed over text the corpus
    does not hold. Batches commit as they land: a mid-phase failure
    leaves vectors_partial with the landed rows committed, and
    resume is gap-filling by content key. Returns 'complete' |
    'partial' | 'suspect' (canary drift: nothing is embedded into
    a suspect generation). Wherever embedding stops early, the
    reason is surfaced via _corpus_note_embed_stop — a failure
    whose reason is discarded cannot be diagnosed from outside."""
    own_run = run_id is None
    if own_run:
        with db.write_txn() as conn:
            cur = conn.execute(
                "INSERT INTO ingest_runs (fingerprint, started, "
                "finished, parser_version, embed_model, outcome, "
                "detail) VALUES (?, ?, NULL, ?, ?, NULL, ?)",
                (fingerprint, _corpus_now(), CORPUS_PARSER_VERSION,
                 model, json.dumps({"kind": "reembed"})))
            run_id = cur.lastrowid
    outcome = "partial"
    try:
        gen = _corpus_generation(db, model, fmt)
        if gen is None:
            try:
                gen = _corpus_generation_birth(db, embed_fn, model,
                                               fmt)
            except Exception as e:
                _corpus_note_embed_stop(
                    db, run_id, fingerprint,
                    f"canary birth failed: {e}")
                return "partial"
        elif gen.get("canary") == "suspect" or (
                (str(db.path), model, fmt)
                not in _CANARY_CHECKED_THIS_PROCESS):
            ok = _corpus_canary_check(db, embed_fn, model, fmt)
            if ok is False:
                return "suspect"
        chapters = {r[0]: r[1] for r in db.query(
            "SELECT chapter_index, text FROM corpus_chapters "
            "WHERE fingerprint=?", (fingerprint,))}
        missing = db.query(
            "SELECT p.passage_id, p.chapter_index, p.start_offset, "
            "p.end_offset FROM corpus_passages p LEFT JOIN "
            "passage_vectors pv ON pv.passage_id = p.passage_id "
            "AND pv.model=? AND pv.format=? WHERE p.fingerprint=? "
            "AND pv.passage_id IS NULL ORDER BY p.chapter_index, "
            "p.start_offset", (model, fmt, fingerprint))
        for i in range(0, len(missing), _CORPUS_EMBED_BATCH):
            batch = missing[i:i + _CORPUS_EMBED_BATCH]
            texts = [chapters[ci][s:e] for _pid, ci, s, e in batch]
            try:
                vecs = embed_fn(texts)
            except Exception as e:
                _corpus_note_embed_stop(
                    db, run_id, fingerprint, f"embedder failed: {e}")
                break  # landed batches stay committed (§3.3)
            if len(vecs) != len(texts) or not vecs:
                _corpus_note_embed_stop(
                    db, run_id, fingerprint,
                    f"embedder returned {len(vecs)} vectors for "
                    f"{len(texts)} passages")
                break
            dim = len(vecs[0])
            if any(len(v) != dim for v in vecs):
                _corpus_note_embed_stop(
                    db, run_id, fingerprint,
                    "embedder returned inconsistent vector "
                    "dimensions in one batch")
                break
            with db.write_txn("vectors") as conn:
                for (pid, _ci, _s, _e), vec in zip(batch, vecs):
                    conn.execute(
                        "INSERT OR REPLACE INTO passage_vectors "
                        "(passage_id, fingerprint, model, format, "
                        "dim, vector) VALUES (?, ?, ?, ?, ?, ?)",
                        (pid, fingerprint, model, fmt, dim,
                         _corpus_pack_vector(vec)))
        n_pass = db.query(
            "SELECT COUNT(*) FROM corpus_passages WHERE fingerprint=?",
            (fingerprint,))[0][0]
        n_vec = db.query(
            "SELECT COUNT(*) FROM passage_vectors WHERE fingerprint=? "
            "AND model=? AND format=?",
            (fingerprint, model, fmt))[0][0]
        if n_pass and n_vec >= n_pass:
            new_status, outcome = "complete", "complete"
        elif n_vec:
            new_status, outcome = "vectors_partial", "partial"
        else:
            new_status, outcome = None, "partial"
        with db.write_txn("vectors") as conn:
            if new_status is not None:
                conn.execute(
                    "UPDATE corpus_works SET status=?, updated_at=? "
                    "WHERE fingerprint=?",
                    (new_status, _corpus_now(), fingerprint))
            _corpus_refresh_envelope_in_txn(db, conn, fingerprint)
        return outcome
    finally:
        if own_run:
            with db.write_txn() as conn:
                conn.execute(
                    "UPDATE ingest_runs SET finished=?, outcome=? "
                    "WHERE id=?",
                    (_corpus_now(),
                     "complete" if outcome == "complete" else "partial",
                     run_id))


# -- reads + search (§2.2, §4.4's content key) --------------------------

def corpus_passage_vectors(db, fingerprint, model,
                           fmt=_CORPUS_VECTOR_FORMAT):
    """{passage_id: [floats]} for the work's rows stamped with the
    given (model, format). Stamp discipline is on the read path,
    per row (§2.4): foreign-stamp rows are absent, and a suspect
    generation's rows are ALL misses until re-embedded clean."""
    if _corpus_generation_suspect(db, model, fmt):
        return {}
    rows = db.query(
        "SELECT passage_id, dim, vector FROM passage_vectors "
        "WHERE fingerprint=? AND model=? AND format=?",
        (fingerprint, model, fmt))
    return {pid: _corpus_unpack_vector(blob, dim)
            for pid, dim, blob in rows}


def corpus_vector_by_text_hash(db, fingerprint, text_hash, model,
                               fmt=_CORPUS_VECTOR_FORMAT):
    """The §4.4 content key as a lookup: a vector is served only
    when the passage's text hash, the model, and the format all
    match the present corpus state — any mismatch is a miss."""
    if _corpus_generation_suspect(db, model, fmt):
        return None
    rows = db.query(
        "SELECT pv.dim, pv.vector FROM passage_vectors pv JOIN "
        "corpus_passages p ON p.passage_id = pv.passage_id WHERE "
        "p.fingerprint=? AND p.text_hash=? AND pv.model=? AND "
        "pv.format=? LIMIT 1", (fingerprint, text_hash, model, fmt))
    if not rows:
        return None
    return _corpus_unpack_vector(rows[0][1], rows[0][0])


_NUMPY_STATE = {"mod": None, "tried": False}


def _numpy():
    if not _NUMPY_STATE["tried"]:
        _NUMPY_STATE["tried"] = True
        try:
            import numpy as _np
            _NUMPY_STATE["mod"] = _np
        except Exception:
            _NUMPY_STATE["mod"] = None
    return _NUMPY_STATE["mod"]


def _corpus_default_engine():
    return "numpy" if _numpy() is not None else "pure"


def corpus_search_passages(db, fingerprint, query_vector, model,
                           fmt=_CORPUS_VECTOR_FORMAT, top_k=10,
                           engine=None):
    """Top-k cosine neighbours among the work's current-stamp
    passage vectors (§2.2: per-book scope is the v1 working set).
    engine='numpy' | 'pure' — the parity between them is pinned
    (§2.5), and the pure path is what a numpy-less Python runs."""
    vecs = corpus_passage_vectors(db, fingerprint, model, fmt)
    if not vecs or top_k <= 0:
        return []
    ids = sorted(vecs)
    if engine is None:
        engine = _corpus_default_engine()
    scores = None
    if engine == "numpy":
        np = _numpy()
        if np is not None:
            import math
            mat = np.array([vecs[i] for i in ids], dtype=np.float64)
            q = np.array(query_vector, dtype=np.float64)
            qn = float(np.linalg.norm(q))
            norms = np.linalg.norm(mat, axis=1)
            dots = mat @ q
            scores = [
                (float(dots[k] / (norms[k] * qn))
                 if norms[k] > 0 and qn > 0 else 0.0)
                for k in range(len(ids))]
    if scores is None:
        scores = [_corpus_cosine(query_vector, vecs[i]) for i in ids]
    order = sorted(range(len(ids)), key=lambda k: (-scores[k], ids[k]))
    return [(ids[k], float(scores[k])) for k in order[:top_k]]


def _corpus_config_embedder():
    """(embed_fn, model) from CONFIG, or None when no embedder is
    configured (embed_url/embed_model are config-only, no default
    model — the §0 discipline embed_vectors already lives by)."""
    url = CONFIG.get("embed_url") or ""
    model = CONFIG.get("embed_model") or ""
    if not url or not model:
        return None

    def embed(texts, _url=url, _model=model):
        return embed_vectors(_url, _model, texts)

    return (embed, model)


def cmd_corpus_reembed(learn_dir=None, work=None):
    """--corpus-reembed [--work <fingerprint>]: fill the current
    vector generation for works whose passages lack current-stamp
    vectors (§2.4/§3.4 — the cheap re-ingest: minutes of embedding,
    zero re-parsing)."""
    d = (Path(learn_dir) if learn_dir
         else Path(os.path.expanduser("~")) / ".ebook-processor"
         / "learned")
    emb = _corpus_config_embedder()
    if emb is None:
        print("  --corpus-reembed needs embed_url and embed_model "
              "in config.json; no embedder is configured.")
        return []
    db = _corpus_db_for(d, mode="importer")
    if db is None:
        print(f"  No corpus in {d} — nothing to re-embed.")
        return []
    if work:
        fps = [r[0] for r in db.query(
            "SELECT fingerprint FROM corpus_works WHERE fingerprint"
            "=?", (work,))]
        if not fps:
            print(f"  No corpus work with fingerprint {work}.")
            return []
    else:
        fps = [r[0] for r in db.query(
            "SELECT fingerprint FROM corpus_works WHERE status NOT "
            "IN ('failed', 'ingesting') ORDER BY title, fingerprint")]
    embed_fn, model = emb
    results = []
    failed = 0
    for fp in fps:
        # Per-work isolation: one work's DB-layer or corrupt-row
        # failure must not abort the batch and strand every later
        # work (embedder errors already come back as a "partial"
        # outcome from inside corpus_embed_work; what escapes is
        # the non-embedder class). Name the work and its error,
        # count it, and continue with the rest.
        try:
            outcome = corpus_embed_work(db, fp, embed_fn, model)
        except Exception as e:
            failed += 1
            print(f"  [{fp[:8]}] re-embed: FAILED — "
                  f"{type(e).__name__}: {e}")
            results.append({"fingerprint": fp, "outcome": "failed",
                            "detail": f"{type(e).__name__}: {e}"})
            continue
        print(f"  [{fp[:8]}] re-embed: {outcome} (model {model})")
        results.append({"fingerprint": fp, "outcome": outcome})
    if failed:
        print(f"  Re-embed summary: {len(results) - failed} done, "
              f"{failed} failed (of {len(results)} works)")
    return results


# ---------------------------------------------------------------------------
# Corpus stage contract (corpus-design §4): stage outputs are
# stamped (input_hash, stage, model, stage_version), keyed by
# (fingerprint, stage, output_key), and a re-run of a stage replaces
# its own outputs — the whole (fingerprint, stage) key space, in one
# transaction (A4). An output is current iff its input_hash equals
# the hash recomputed from the corpus's present state; reuse over
# inputs nobody hashed is the staleness class the contract exists
# to exclude, so every adopter enumerates its hashed inputs (§4.2).
# ---------------------------------------------------------------------------

# The retrieve stage's own contract version (§4.1): bumped when the
# judge prompt or the retrieval code path changes — it is named in
# every retrieve input hash (A6), so a bump re-derives yesterday's
# verdicts instead of serving them under a judge that no longer
# exists. The query-shape version versions evidence_query_text /
# evidence_query_terms (§4.2's enumerated hash input).
RETRIEVE_STAGE_VERSION = "1"
_EVIDENCE_QUERY_SHAPE_VERSION = "1"

# Stage -> envelope section (§6.4): the sections a stage write
# refreshes in its own transaction.
_STAGE_SECTION = {"retrieve": "retrieval"}
# The quotes stages are deliberately NOT in _STAGE_SECTION: the
# envelope's quotes section is a materialization of the quotes
# TABLE (the §10.3 record), refreshed by the record's writer in
# the same transaction as the record write
# (_corpus_refresh_quotes_section_in_txn) — a tally over stage
# outputs would go stale the moment selection flips a row's
# status without re-deriving anything.


def _corpus_stage_input_hash(material):
    """sha256 over the canonical serialization of a stage's hashed
    inputs (§4.1): sorted JSON, so the same material hashes equal
    on any machine, in any dict order."""
    blob = json.dumps(material, sort_keys=True, ensure_ascii=False,
                      separators=(",", ":"))
    return _corpus_sha256(blob)


def corpus_scoped_dump_hash(db, fingerprint, stage=None):
    """Scoped dump hash over one (fingerprint[, stage]) stage-output
    key space (§11 slice 4 — the substrate's _dump_hash_conn is
    whole-DB; §4.5's pins and §13 signal 8 need the scoped variant):
    hashes keys, input hashes, run ids, and payloads in key order."""
    import hashlib as _hl
    if stage is None:
        rows = db.query(
            "SELECT stage, output_key, input_hash, run_id, payload "
            "FROM stage_outputs WHERE fingerprint=? "
            "ORDER BY stage, output_key", (fingerprint,))
    else:
        rows = db.query(
            "SELECT stage, output_key, input_hash, run_id, payload "
            "FROM stage_outputs WHERE fingerprint=? AND stage=? "
            "ORDER BY output_key", (fingerprint, stage))
    h = _hl.sha256()
    for row in rows:
        h.update(repr(row).encode("utf-8"))
        h.update(b"\n")
    return h.hexdigest()


def corpus_stage_outputs(db, fingerprint, stage):
    """{output_key: {"input_hash", "run_id", "payload"}} for one
    (fingerprint, stage) key space — the read side of the contract."""
    out = {}
    for key, ih, rid, payload in db.query(
            "SELECT output_key, input_hash, run_id, payload FROM "
            "stage_outputs WHERE fingerprint=? AND stage=?",
            (fingerprint, stage)):
        try:
            payload = json.loads(payload) if payload else {}
        except (TypeError, ValueError):
            payload = {}
        out[key] = {"input_hash": ih, "run_id": rid, "payload": payload}
    return out


def _corpus_envelope_load(conn, fingerprint):
    row = conn.execute(
        "SELECT envelope FROM work_envelope WHERE fingerprint=?",
        (fingerprint,)).fetchone()
    if row and row[0]:
        try:
            env = json.loads(row[0])
            if isinstance(env, dict):
                return env
        except (TypeError, ValueError):
            pass
    return {}


def _corpus_envelope_store(conn, fingerprint, env):
    conn.execute(
        "INSERT OR REPLACE INTO work_envelope (fingerprint, corpus_v,"
        " envelope, computed_at) VALUES (?, ?, ?, ?)",
        (fingerprint, CORPUS_V, json.dumps(env, ensure_ascii=False),
         _corpus_now()))


def _corpus_refresh_stage_section_in_txn(db, conn, fingerprint, stage,
                                         output_payloads, model,
                                         stage_version, retracted=None):
    """Refresh a stage's envelope section INSIDE the caller's
    transaction (§6.4: the refresh rides the write that changes the
    facts). The section records what the stage currently holds —
    output count + outcome tally for record-shaped outputs — and,
    on a retraction, the retracted_at + reason trace that keeps
    'never assessed' and 'assessed, then withdrawn' distinguishable
    after the section's state falls back to unknown."""
    section_name = _STAGE_SECTION.get(stage)
    if section_name is None:
        return
    env = _corpus_envelope_load(conn, fingerprint)
    sections = env.setdefault("sections", {})
    prior = sections.get(section_name) or {}
    if model is None:
        model = prior.get("model")
    if stage_version is None:
        stage_version = prior.get("stage_version")
    outcomes = {}
    for payload in output_payloads.values():
        rec = (payload or {}).get("record") or {}
        outcome = rec.get("outcome")
        if outcome:
            outcomes[outcome] = outcomes.get(outcome, 0) + 1
    section = {
        "state": "present" if output_payloads else "unknown",
        "stage": stage, "model": model,
        "stage_version": stage_version,
        "updated_at": _corpus_now(), "scope": "edition",
        "value": {"outputs": len(output_payloads),
                  "outcomes": outcomes}}
    if retracted is not None:
        section["retracted_at"] = retracted["at"]
        section["reason"] = retracted["reason"]
    sections[section_name] = section
    _corpus_envelope_store(conn, fingerprint, env)


def corpus_stage_settle(db, fingerprint, stage, *, stage_version,
                        model, outputs, run_payload=None):
    """Settle one stage run's outputs under the §4.1 contract.

    outputs: {output_key: {"input_hash", "payload"}} — the FULL set
    the run produces now. Inside one transaction: produced keys
    whose stored input_hash differs are replaced; keys whose hash
    matches are reused untouched (a same-inputs re-run writes no
    output rows at all); every stored key for (fingerprint, stage)
    NOT in the produced set is deleted — ghost outputs are half of
    what replacement means (A4). The stage_runs accounting row is
    written on every settle (it lives outside the output key space)
    and the stage's envelope section refreshes in the same
    transaction when — and only when — outputs changed.

    Returns {"run_id", "written", "reused", "deleted"}."""
    import uuid as _uuid
    run_id = _uuid.uuid4().hex
    now = _corpus_now()
    existing = {r[0]: r[1] for r in db.query(
        "SELECT output_key, input_hash FROM stage_outputs WHERE "
        "fingerprint=? AND stage=?", (fingerprint, stage))}
    written = reused = 0
    for key, out in outputs.items():
        if existing.get(key) == out["input_hash"]:
            reused += 1
        else:
            written += 1
    deleted = sum(1 for k in existing if k not in outputs)
    run_hash = _corpus_stage_input_hash(
        {k: outputs[k]["input_hash"] for k in sorted(outputs)})
    accounting = {**(run_payload or {}), "written": written,
                  "reused": reused, "deleted": deleted}
    with db.write_txn("stages") as conn:
        conn.execute(
            "INSERT INTO stage_runs (run_id, fingerprint, stage, "
            "stage_version, model, input_hash, started, finished, "
            "status, payload) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'ok', ?)",
            (run_id, fingerprint, stage, stage_version, model,
             run_hash, now, now,
             json.dumps(accounting, ensure_ascii=False)))
        for key, out in outputs.items():
            if existing.get(key) == out["input_hash"]:
                continue  # reused: the row is already the truth
            conn.execute(
                "INSERT OR REPLACE INTO stage_outputs (fingerprint, "
                "stage, output_key, input_hash, run_id, payload) "
                "VALUES (?, ?, ?, ?, ?, ?)",
                (fingerprint, stage, key, out["input_hash"], run_id,
                 json.dumps(out["payload"], ensure_ascii=False)))
        for key in existing:
            if key not in outputs:
                conn.execute(
                    "DELETE FROM stage_outputs WHERE fingerprint=? "
                    "AND stage=? AND output_key=?",
                    (fingerprint, stage, key))
        if written or deleted:
            _corpus_refresh_stage_section_in_txn(
                db, conn, fingerprint, stage,
                {k: v["payload"] for k, v in outputs.items()},
                model, stage_version)
    return {"run_id": run_id, "written": written, "reused": reused,
            "deleted": deleted}


def corpus_retract_stage_output(db, fingerprint, stage, output_key,
                                reason):
    """Retraction as a named operation (§6.4) — MECHANISM ONLY:
    what authorizes retracting a human-corrected output is decision
    D1's question, deliberately not pre-decided here (§0's scoping
    rule); this verb is the machinery D1 will rule over.

    One transaction: (1) an explicit retraction record — a
    stage_runs row at status 'retracted' naming the output, the
    reason class, and the withdrawn input hash (the ingest_runs
    tombstone precedent); (2) the output row itself removed; (3)
    the envelope section refreshed with its retracted_at + reason
    trace stamped. No reader ever sees the withdrawal without the
    record, or the record without the withdrawal. Returns True
    when an output was actually withdrawn."""
    import uuid as _uuid
    rows = db.query(
        "SELECT input_hash, run_id FROM stage_outputs WHERE "
        "fingerprint=? AND stage=? AND output_key=?",
        (fingerprint, stage, output_key))
    if not rows:
        return False
    withdrawn_hash, withdrawn_run = rows[0]
    now = _corpus_now()
    record = {"output_key": output_key, "reason": reason,
              "withdrawn_input_hash": withdrawn_hash,
              "withdrawn_run_id": withdrawn_run}
    with db.write_txn("stages") as conn:
        conn.execute(
            "INSERT INTO stage_runs (run_id, fingerprint, stage, "
            "stage_version, model, input_hash, started, finished, "
            "status, payload) VALUES (?, ?, ?, '', 'retraction', ?, "
            "?, ?, 'retracted', ?)",
            (_uuid.uuid4().hex, fingerprint, stage, withdrawn_hash,
             now, now, json.dumps(record, ensure_ascii=False)))
        conn.execute(
            "DELETE FROM stage_outputs WHERE fingerprint=? AND "
            "stage=? AND output_key=?",
            (fingerprint, stage, output_key))
        remaining = {}
        for key, payload in conn.execute(
                "SELECT output_key, payload FROM stage_outputs WHERE "
                "fingerprint=? AND stage=?", (fingerprint, stage)):
            try:
                remaining[key] = json.loads(payload) if payload else {}
            except (TypeError, ValueError):
                remaining[key] = {}
        _corpus_refresh_stage_section_in_txn(
            db, conn, fingerprint, stage, remaining,
            None, None, retracted={"at": now, "reason": reason})
        if stage in ("quote-verify", "quote-select"):
            # The quotes section is table-derived; stamp the
            # retraction trace onto it here (§6.4 leg 3).
            _corpus_refresh_quotes_section_in_txn(
                db, conn, fingerprint, retracted=reason)
    return True


# -- the two-tier window cache (§4.4) --------------------------------

class _CorpusWindowCache(dict):
    """The §4.4 two-tier window-embedding cache: the per-run memory
    dict in front, the corpus's passage_vectors behind it, keyed by
    CONTENT — window text hash + embed stamp (enforced by
    corpus_vector_by_text_hash: a vector is served only when the
    passage's present text, the model, and the format all match; any
    mismatch is a miss and a re-embed, never a serve).

    Windows the run embeds are buffered and written back by flush()
    — only when this cache is writable (never under replay, §4.3)
    and only for windows that ARE stored passages of the work with
    matching text: a foreign span has nowhere honest to land, and a
    vector is never written against text the corpus does not hold.
    Stored values are the run's normalized vectors; every consumer
    of passage_vectors ranks by cosine, which is scale-invariant,
    so a normalized fill is the same vector for ranking purposes.
    A locked corpus at flush time degrades (§5.2): the fills stay
    unrecorded and the run proceeds — poorer, never wrong."""

    def __init__(self, db, fingerprint, chapters, model,
                 fmt=_CORPUS_VECTOR_FORMAT, writable=True):
        super().__init__()
        self._db = db
        self._fp = fingerprint
        self._model = model
        self._fmt = fmt
        self._writable = bool(writable)
        self._pending = {}   # passage_id -> normalized vector
        self._absent = set()  # (label, offset) confirmed corpus-absent
        self._windows = {}   # (label, offset) -> (passage_id, text_hash)
        stored = {r[0]: r[1] for r in db.query(
            "SELECT passage_id, text_hash FROM corpus_passages WHERE "
            "fingerprint=?", (fingerprint,))}
        seen = set()
        for ch in chapters or []:
            label = ch.get("label")
            text = ch.get("text") or ""
            for w in _evidence_windows(text):
                key = (label, w["offset"])
                if key in seen:
                    continue
                seen.add(key)
                end = w["offset"] + len(w["text"])
                pid = _corpus_passage_id(fingerprint, ch.get("index"),
                                         w["offset"], end)
                if stored.get(pid) == _corpus_text_hash(w["text"]):
                    self._windows[key] = (
                        pid, _corpus_text_hash(w["text"]))

    def _corpus_vec(self, key):
        if key in self._absent:
            return None
        info = self._windows.get(key)
        if info is None:
            self._absent.add(key)
            return None
        raw = corpus_vector_by_text_hash(self._db, self._fp, info[1],
                                         self._model, self._fmt)
        if raw is None:
            self._absent.add(key)
            return None
        return _normalize(raw)

    def __contains__(self, key):
        if dict.__contains__(self, key):
            return True
        return self._corpus_vec(key) is not None

    def get(self, key, default=None):
        if dict.__contains__(self, key):
            return dict.get(self, key)
        vec = self._corpus_vec(key)
        if vec is None:
            return default
        dict.__setitem__(self, key, vec)  # memoize; not a write-back
        return vec

    def __setitem__(self, key, value):
        dict.__setitem__(self, key, value)
        self._absent.discard(key)
        if self._writable:
            info = self._windows.get(key)
            if info is not None:
                self._pending[info[0]] = value

    def flush(self):
        """Write the buffered gap-fills back in one transaction and
        refresh the envelope's vectors section in it (§6.4: the
        refresh rides the write). Returns the number of rows
        written; 0 for a read-only cache or a degraded (locked)
        corpus — the run is never failed by its cache (§5.2)."""
        if not self._writable or not self._pending:
            return 0
        pending, self._pending = self._pending, {}
        try:
            with self._db.write_txn("vectors") as conn:
                for pid, vec in pending.items():
                    conn.execute(
                        "INSERT OR REPLACE INTO passage_vectors "
                        "(passage_id, fingerprint, model, format, "
                        "dim, vector) VALUES (?, ?, ?, ?, ?, ?)",
                        (pid, self._fp, self._model, self._fmt,
                         len(vec), _corpus_pack_vector(vec)))
                _corpus_refresh_envelope_in_txn(self._db, conn,
                                                self._fp)
            self._absent.clear()  # fills landed; re-probe honestly
            return len(pending)
        except Exception:
            return 0


# -- retrieve adoption (§4.2, wave 1) ---------------------------------

def corpus_servable_fingerprint(db, fpath):
    """The fingerprint of the corpus work this file's bytes name,
    when the corpus can serve that work to a run — or None.

    This is the membership test corpus-sourced acquisition applies,
    factored into one place so every caller asks the same question
    and gets the same answer: the file's bytes must hash to a
    stored source_hash, the work's composed state must be
    servable (§3.3: text_complete / vectors_partial / complete
    under the current parser generation), and chapter rows must
    exist. The --corpus-only folder filter admits exactly the
    files this returns a fingerprint for, so the filter can never
    admit a book acquisition would refuse, nor skip one it would
    source. Never raises: corpus trouble reads as absence, and
    the caller falls back to the file — or, for the filter, to
    skipping the book for this scan."""
    try:
        source_hash = _corpus_sha256(Path(fpath).read_bytes())
        # One source_hash can name several works: a metadata
        # correction forks the fingerprint while the file bytes —
        # and so the hash — stay the same. The later ingest is
        # the superseding work, so the newest ingested_at wins;
        # without the ordering the pick was whatever order the
        # store happened to return, and could flip between runs.
        # updated_at and the fingerprint itself break any
        # remaining ties so the order is total.
        rows = db.query(
            "SELECT fingerprint FROM corpus_works "
            "WHERE source_hash=? ORDER BY ingested_at DESC, "
            "updated_at DESC, fingerprint", (source_hash,))
        if not rows:
            return None
        fingerprint = rows[0][0]
        if corpus_work_state(db, fingerprint) not in (
                "text_complete", "vectors_partial", "complete"):
            return None
        if not db.query(
                "SELECT 1 FROM corpus_chapters "
                "WHERE fingerprint=? LIMIT 1", (fingerprint,)):
            return None
        return fingerprint
    except Exception:
        return None


def corpus_acquire_for_run(learn_dir, fpath):
    """Corpus-sourced acquisition (§11 slice 5): when the corpus
    holds this exact file's text — the presented file's bytes hash
    to a stored source_hash — and the generation is current,
    return the acquisition block's full output surface (§3.1's
    mirror) read from the corpus: chapters, title, author,
    identifiers, and the word_count and chapter-detection fallback
    flag recorded by the INGEST run's own parse. None otherwise,
    and the caller parses the file exactly as today.
    Corpus-sourcing never re-derives the surface: what ingest
    recorded is what the run gets, which is what makes §13's
    signal 2a (corpus-sourced ≡ file-sourced) a property of the
    store rather than of two parsers agreeing."""
    try:
        db = _corpus_db_for(learn_dir, mode="processor")
        if db is None:
            return None
        fingerprint = corpus_servable_fingerprint(db, fpath)
        if fingerprint is None:
            return None
        chapters = corpus_chapters_for(db, fingerprint)
        if not chapters:
            return None
        rec = corpus_work_record(db, fingerprint) or {}
        payload = rec.get("payload")
        if isinstance(payload, str):
            try:
                payload = json.loads(payload)
            except ValueError:
                payload = {}
        payload = payload or {}
        identifiers = rec.get("identifiers")
        if isinstance(identifiers, str):
            try:
                identifiers = json.loads(identifiers)
            except ValueError:
                identifiers = {}
        return {"chapters": chapters,
                "title": rec.get("title"),
                "author": rec.get("author"),
                "identifiers": identifiers or {},
                "word_count": payload.get("word_count"),
                "chapter_detection_fallback": bool(
                    payload.get("chapter_detection_fallback")),
                "source_name": payload.get("source_name"),
                "fingerprint": fingerprint}
    except Exception:
        return None


def _effective_judge_identity():
    """The (backend, model) of the judge that will actually judge
    this run's calls, resolved exactly the way the call path
    resolves it: the backend dispatch falls back to Ollama for an
    unknown name, and each backend reads its model from its own
    per-backend config key. The retrieve stage's input hash must
    name THIS judge — reading a generic "model"/"llm" config pair
    instead left the model component empty on any configuration
    that names its models per-backend, so swapping the real judge
    never invalidated a stored verdict (§4.2's contract is that
    the hash covers the judge's backend, model and prompt)."""
    backend = CONFIG.get("llm") or ""
    if backend not in ("ollama", "openrouter", "openai"):
        backend = "ollama"
    models = {"ollama": CONFIG.get("ollama_model") or "",
              "openrouter": CONFIG.get("openrouter_model") or "",
              "openai": CONFIG.get("openai_model") or ""}
    return backend, models[backend]


def _corpus_retrieve_ctx_build(db, fingerprint, writable):
    """The context dict over an already-chosen handle, or None
    when the generation cannot serve (no embed model configured,
    suspect generation). Shared by the run path and the pinned
    replay path (§4.3)."""
    model = CONFIG.get("embed_model") or ""
    if not model:
        return None
    if _corpus_generation_suspect(db, model, _CORPUS_VECTOR_FORMAT):
        return None
    judge_backend, judge_model = _effective_judge_identity()
    return {"db": db, "fingerprint": fingerprint,
            "writable": bool(writable), "embed_model": model,
            "embed_format": _CORPUS_VECTOR_FORMAT,
            "judge_model": judge_model,
            "judge_backend": judge_backend}


def corpus_retrieve_context(learn_dir, fingerprint, *, writable=True):
    """The retrieve stage's adoption context for a run, or None when
    the corpus cannot serve this work: no corpus in the learn dir,
    the work not retrieval-ready (§3.3's gate: complete, current
    parser generation), no embed model configured, or the vector
    generation marked suspect by the drift canary (verdicts ranked
    in a suspect space are neither reused nor settled — the run
    proceeds per-run, exactly as before the corpus). writable=False
    under replay (§4.3: reads only, no settling, no gap-fill
    write-back). Corpus trouble degrades to None — slower, never
    wrong (§5.3) — never to a failed run.

    Under replay the context comes from the snapshot-validated,
    READ-ONLY pinned handle run_replay injected (§4.3) — never
    from the learn dir, which inside a replay is the sandbox."""
    try:
        if _REPLAY_CTX is not None:
            pinned = _REPLAY_CTX.get("corpus")
            if pinned and pinned.get("fingerprint") == fingerprint:
                return _corpus_retrieve_ctx_build(
                    pinned["db"], fingerprint, False)
            return None
        db = _corpus_db_for(learn_dir, mode="processor")
        if db is None or not corpus_retrieval_ready(db, fingerprint):
            return None
        return _corpus_retrieve_ctx_build(db, fingerprint, writable)
    except Exception:
        return None


def _retrieve_claim_input_hash(ctx, claim, floor):
    """One claim's retrieve input hash over its ENUMERATED inputs
    (§4.2): the support chapters' text hashes, the embed stamp,
    the judge's identity AND configuration digest (backend, model,
    prompt — A6), the retrieval floor, the query shape (the claim's
    query text, terms, and definition are hashed as built), the
    query-shape version, and the stage_version itself."""
    support = []
    for ch in claim.get("support") or []:
        support.append({"index": ch.get("index"),
                        "label": ch.get("label"),
                        "text_hash": _corpus_text_hash(
                            ch.get("text") or "")})
    support.sort(key=lambda d: (d["index"] is None, d["index"],
                                d["label"] or ""))
    material = {
        "stage": "retrieve", "stage_version": RETRIEVE_STAGE_VERSION,
        "claim_key": claim.get("key"), "name": claim.get("name"),
        "query_text": claim.get("query_text"),
        "terms": sorted(claim.get("terms") or []),
        "definition": claim.get("definition") or "",
        "support": support,
        "embed": {"model": ctx["embed_model"],
                  "format": ctx["embed_format"]},
        "judge": {"backend": ctx["judge_backend"],
                  "model": ctx["judge_model"],
                  "prompt_sha256": _corpus_sha256(
                      PROMPT_EVIDENCE_JUDGE)},
        "floor": floor,
        "query_shape": _EVIDENCE_QUERY_SHAPE_VERSION,
    }
    return _corpus_stage_input_hash(material)


# ---------------------------------------------------------------------------
# Quote verification (§10.1) + the quote-verify stage (§4.2 wave 1)
#
# VERIFY is a pure corpus function: fingerprint-scoped, matching on
# token SEQUENCE — tolerant of whitespace, punctuation and case
# drift, strict on words. A substituted, inserted or omitted word,
# or a "…" elision, fails closed; the legacy evidence matcher's
# fuzzy fallback (_verify_against_norm) is deliberately NOT used
# here — a quote that ships must be the book's own words. The
# shipped text is always the corpus span bytes; the candidate is
# preserved in provenance beside its snapped flag and drift class.
# A chapter assertion is an assertion (A3): an asserted candidate
# is searched in that chapter only; a match elsewhere records
# drift class "chapter" and FAILS. Unasserted candidates search
# the whole book and the found chapter becomes the assertion.
# ---------------------------------------------------------------------------

QUOTE_VERIFY_STAGE_VERSION = "1"
QUOTE_SELECT_STAGE_VERSION = "1"

_QUOTE_TOKEN_RE = re.compile(r"[^\W_]+")
_QUOTE_SPAN_OPEN = "\"'“‘"
_QUOTE_SPAN_CLOSE = ".!?\"'”’"


def _quote_tokens(text):
    """Word tokens of a text under the _norm_quote discipline
    (quote/dash unification + casefold), each with its (start,
    end) offsets in the ORIGINAL text. Punctuation and whitespace
    are separators: they are where drift is tolerated. Words are
    the tokens themselves: they are where it is not."""
    norm_chars, origins = [], []
    for i, ch in enumerate(text or ""):
        for c in ch.translate(_QUOTE_NORM_TABLE).casefold():
            norm_chars.append(c)
            origins.append(i)
    norm = "".join(norm_chars)
    return [(m.group(0), origins[m.start()], origins[m.end() - 1] + 1)
            for m in _QUOTE_TOKEN_RE.finditer(norm)]


def _quote_find_all(chapter_tokens, cand_tokens):
    """Every (start, end) span in one chapter whose token sequence
    equals the candidate's, in order."""
    if not cand_tokens:
        return []
    seq = [t for t, _s, _e in cand_tokens]
    starts = {}
    for i, (tok, _s, _e) in enumerate(chapter_tokens):
        starts.setdefault(tok, []).append(i)
    hits = []
    n = len(seq)
    for i in starts.get(seq[0], []):
        window = chapter_tokens[i:i + n]
        if [t for t, _s, _e in window] == seq:
            hits.append((window[0][1], window[-1][2]))
    return hits


def _quote_drift(candidate, span):
    """The drift class between a candidate and the corpus span it
    matched: None when byte-identical, else the coarsest single
    class that explains the difference — whitespace, case, or
    punctuation (token equality is already proven, so any
    remaining difference is one of those three by construction)."""
    if candidate == span:
        return None

    def ws(s):
        return re.sub(r"\s+", " ", s.translate(_QUOTE_NORM_TABLE)).strip()

    def wsc(s):
        return re.sub(r"\s+", " ",
                      s.translate(_QUOTE_NORM_TABLE).casefold()).strip()

    if ws(candidate) == ws(span):
        return "whitespace"
    if wsc(candidate) == wsc(span):
        return "case"
    return "punctuation"


def _verify_quote_impl(db, fingerprint, candidate_text, kind,
                       asserted_chapter, support_chapters):
    """The search behind verify_quote: returns (record, diag) —
    a verified-span record, or (None, diag) where diag names the
    failure ({"reason": "no_match"} | {"reason": "chapter",
    "found_chapter_index": n} | {"reason": "no_corpus_text"} |
    {"reason": "empty_candidate"})."""
    chapters = corpus_chapters_for(db, fingerprint)
    if not chapters:
        return None, {"reason": "no_corpus_text"}
    cand = _quote_tokens(candidate_text)
    if not cand:
        return None, {"reason": "empty_candidate"}
    by_index = {c["index"]: c for c in chapters}
    scope = ([asserted_chapter] if asserted_chapter is not None
             else sorted(by_index))
    hits_by_ch = {}
    for ci in scope:
        ch = by_index.get(ci)
        if ch is None:
            continue
        hits = _quote_find_all(_quote_tokens(ch["text"]), cand)
        if hits:
            hits_by_ch[ci] = hits
    if not hits_by_ch:
        if asserted_chapter is not None:
            # A3's diagnostic: the words exist, but not where they
            # were asserted to be — drift class "chapter", a FAIL,
            # never a silent relocation.
            for ci in sorted(by_index):
                if ci == asserted_chapter:
                    continue
                if _quote_find_all(_quote_tokens(by_index[ci]["text"]),
                                   cand):
                    return None, {"reason": "chapter",
                                  "found_chapter_index": ci}
        return None, {"reason": "no_match"}
    chapter_index = min(hits_by_ch)
    occurrences = sum(len(v) for v in hits_by_ch.values())
    text = by_index[chapter_index]["text"]
    start, end = hits_by_ch[chapter_index][0]
    # The shipped span is corpus bytes; let it carry its sentence
    # punctuation (a trailing period, a leading quote mark) so a
    # verified quote reads as the book printed it.
    s, e = start, end
    while s > 0 and text[s - 1] in _QUOTE_SPAN_OPEN:
        s -= 1
    while e < len(text) and text[e] in _QUOTE_SPAN_CLOSE:
        e += 1
    span_text = text[s:e]
    drift = _quote_drift(candidate_text, span_text)
    record = {"chapter_index": chapter_index, "start": s, "end": e,
              "text": span_text, "snapped": drift is not None,
              "drift": drift, "occurrences": occurrences,
              "sentence_bounded": (s, e) in set(_sentence_spans(text))}
    if support_chapters is not None \
            and chapter_index not in support_chapters:
        record["outside_support_chapters"] = True
    return record, {}


def verify_quote(db, fingerprint, candidate_text, kind="evidence",
                 asserted_chapter=None, support_chapters=None):
    """§10.1 VERIFY: does this exact wording occur in this book?

    Returns {chapter_index, start, end, text (the corpus span),
    snapped, drift, occurrences, sentence_bounded} or None.
    kind is the candidate's declared kind ("evidence",
    "signature", "opening", …); asserted_chapter (a chapter
    INDEX) scopes the search to that chapter — a match elsewhere
    fails; support_chapters, when given, adds the
    outside_support_chapters diagnostic when the span lands
    outside the set. FTS narrowing is a future accelerator only:
    the token-sequence scan is the authority, and results must
    not depend on whether the index exists (§1.5 degraded opens
    verify identically)."""
    record, _diag = _verify_quote_impl(
        db, fingerprint, candidate_text, kind, asserted_chapter,
        support_chapters)
    return record


def _corpus_refresh_quotes_section_in_txn(db, conn, fingerprint,
                                          retracted=None):
    """The envelope's quotes section is a materialization of the
    quotes table (§6.4): refreshed in the same transaction as any
    quotes-row write, from the rows themselves. Present iff at
    least one quote is recorded; a work whose quotes were all
    retracted reads unknown WITH the retraction trace — never a
    silent "none"."""
    rows = conn.execute(
        "SELECT status, COUNT(*) FROM quotes WHERE fingerprint=? "
        "GROUP BY status", (fingerprint,)).fetchall()
    by_status = {s: n for s, n in rows}
    total = sum(by_status.values())
    env = _corpus_envelope_load(conn, fingerprint)
    sections = env.setdefault("sections", {})
    section = {"state": "present" if total else "unknown",
               "stage": "quotes", "model": None,
               "stage_version": QUOTE_VERIFY_STAGE_VERSION,
               "updated_at": _corpus_now(), "scope": "work"}
    if total:
        section["value"] = {"quotes": total, "by_status": by_status,
                            "selected": by_status.get("selected", 0)}
    if retracted is not None:
        section["retracted_at"] = _corpus_now()
        section["reason"] = retracted
    sections["quotes"] = section
    _corpus_envelope_store(conn, fingerprint, env)


def _quote_candidate_key(kind, asserted, text_hash):
    return _corpus_sha256(
        f"{kind}\x1f{asserted}\x1f{text_hash}")[:32]


def _quote_verify_material(kind, asserted, text_hash, scope, by_index):
    """The quote-verify stage's enumerated inputs (§4.1) for one
    candidate: its text hash, kind and assertion, and the text
    hashes of every chapter in its search scope. Shared by the
    stage itself and the payload boundary's currency recompute
    (§6.4) — one construction, so the two can never drift."""
    return {
        "stage": "quote-verify",
        "stage_version": QUOTE_VERIFY_STAGE_VERSION,
        "candidate_hash": text_hash, "kind": kind,
        "asserted_chapter": asserted,
        "scope": [{"index": ci,
                   "text_hash": _corpus_text_hash(by_index[ci]["text"])}
                  for ci in scope if ci in by_index],
    }


def _quote_row_id(fingerprint, kind, chapter_index, start, end, text):
    return _corpus_sha256("\x1f".join(
        [fingerprint, kind, str(chapter_index), str(start), str(end),
         text]))[:32]


def corpus_verify_quotes(db, fingerprint, candidates):
    """The quote-verify stage (§4.2 wave 1): settle one verdict per
    candidate — a quotes-table record (§10.3) plus a stage output
    carrying the verify provenance — under the §4 contract, so a
    re-run over the same book text and the same candidates
    re-reads verdicts instead of re-scanning.

    Each candidate: {"text", "kind" (default "evidence"),
    "chapter_index" or "chapter_label" (the A3 assertion),
    "source"}. The stage's input hash enumerates the candidate
    text, its kind and assertion, and the text hashes of every
    chapter in its search scope."""
    chapters = corpus_chapters_for(db, fingerprint)
    by_index = {c["index"]: c for c in chapters}
    label_to_index = {}
    for c in chapters:
        label_to_index.setdefault(c.get("label"), c["index"])
        label_to_index.setdefault(
            " ".join(str(c.get("label") or "").casefold().split()),
            c["index"])

    def resolve_asserted(cand):
        if cand.get("chapter_index") is not None:
            idx = cand["chapter_index"]
            return (idx, None) if idx in by_index else (None, "chapter")
        label = cand.get("chapter_label")
        if label is None:
            return None, None
        if label in label_to_index:
            return label_to_index[label], None
        folded = " ".join(str(label).casefold().split())
        if folded in label_to_index:
            return label_to_index[folded], None
        return None, "chapter_unresolved"

    stored = corpus_stage_outputs(db, fingerprint, "quote-verify")
    # Quote-verify ACCUMULATES across presentations: ingest's
    # opening line, a run's quotes, and an on-demand batch are
    # separate presentations of one stage, and no presentation is
    # the stage's whole truth — so stored verdicts carry forward
    # and this call's candidates overlay them (§4.1 replacement
    # applies within the presented set). A carried verdict whose
    # book text later changes goes stale silently here and is
    # refused at every read boundary by hash recompute (§6.4);
    # the explicit removal acts remain retraction and
    # corpus_remove_work.
    produced = {k: {"input_hash": v["input_hash"],
                    "payload": v["payload"]}
                for k, v in stored.items()}
    rows = []
    summary = {"verified": 0, "rejected": 0, "reused": 0}
    for cand in candidates or []:
        text_c = cand.get("text") or ""
        kind = cand.get("kind") or "evidence"
        asserted, resolve_err = resolve_asserted(cand)
        text_hash = _corpus_text_hash(text_c)
        key = _quote_candidate_key(kind, asserted, text_hash)
        scope = ([asserted] if asserted is not None
                 else sorted(by_index))
        ih = _corpus_stage_input_hash(_quote_verify_material(
            kind, asserted, text_hash, scope, by_index))
        prior = stored.get(key)
        if prior is not None and prior["input_hash"] == ih:
            produced[key] = {"input_hash": ih,
                             "payload": prior["payload"]}
            summary["reused"] += 1
            summary[prior["payload"]["status"]] += 1
            continue
        if resolve_err is not None:
            record, diag = None, {"reason": resolve_err,
                                  "asserted_label":
                                      cand.get("chapter_label")}
        else:
            record, diag = _verify_quote_impl(
                db, fingerprint, text_c, kind, asserted,
                cand.get("support_chapters"))
        if record is not None:
            status = "verified"
            verify_block = {
                "candidate_text": text_c,
                "chapter_index": record["chapter_index"],
                "start": record["start"], "end": record["end"],
                "snapped": record["snapped"],
                "drift": record["drift"],
                "occurrences": record["occurrences"],
                "sentence_bounded": record["sentence_bounded"]}
            if record.get("outside_support_chapters"):
                verify_block["outside_support_chapters"] = True
            row_id = _quote_row_id(fingerprint, kind,
                                   record["chapter_index"],
                                   record["start"], record["end"],
                                   record["text"])
            payload = {"candidate_text": text_c, "kind": kind,
                       "source": cand.get("source"),
                       "status": status, "verify": verify_block,
                       "quote_id": row_id,
                       "asserted_chapter": asserted}
            rows.append((
                row_id,
                fingerprint, record["chapter_index"], record["start"],
                record["end"], record["text"], kind, status,
                json.dumps(payload, ensure_ascii=False)))
        else:
            status = "rejected"
            row_id = _quote_row_id(fingerprint, kind, asserted, -1, -1,
                                   text_c)
            payload = {"candidate_text": text_c, "kind": kind,
                       "source": cand.get("source"),
                       "status": status,
                       "verify": {"candidate_text": text_c, **diag},
                       "quote_id": row_id,
                       "asserted_chapter": asserted}
            rows.append((
                row_id,
                fingerprint, asserted, None, None, text_c, kind,
                status, json.dumps(payload, ensure_ascii=False)))
        summary[status] += 1
        produced[key] = {"input_hash": ih, "payload": payload}
    if rows:
        with db.write_txn("stages") as conn:
            for row in rows:
                conn.execute(
                    "INSERT OR REPLACE INTO quotes (quote_id, "
                    "fingerprint, chapter_index, start_offset, "
                    "end_offset, text, kind, status, payload) "
                    "VALUES (?,?,?,?,?,?,?,?,?)", row)
            _corpus_refresh_quotes_section_in_txn(db, conn, fingerprint)
    if produced or stored:
        corpus_stage_settle(
            db, fingerprint, "quote-verify",
            stage_version=QUOTE_VERIFY_STAGE_VERSION, model=None,
            outputs=produced,
            run_payload={"candidates": len(candidates or [])})
    summary["outputs"] = produced
    return summary


def _chapter_body_start(chapter):
    """Offset where a chapter's prose begins: past its own
    heading when the stored text opens with the chapter's
    stored label — as a whole first line, or as an exact
    prefix (Advisor Ruling-2: the heading is metadata the
    corpus already stores as the label, and §10.6 ships it
    separately as chapter_label; it is not part of the first
    sentence). Zero when the text carries no such heading,
    so heading-less chapters are unchanged."""
    text = chapter.get("text") or ""
    label = (chapter.get("label") or "").strip()
    if not label:
        return 0
    nl = text.find("\n")
    first_line = text if nl == -1 else text[:nl]
    if first_line.strip() == label:
        return len(text) if nl == -1 else nl + 1
    if text.startswith(label):
        return len(label)
    return 0


def corpus_generate_opening_line(db, fingerprint):
    """§10.4(a): the deterministic opening line — the first
    sentence of the first non-frontmatter chapter, taken from
    after the chapter's own heading (Ruling-2) — verified and
    recorded at ingest. Deterministic by construction: the
    candidate IS a corpus span, so verification is a formality
    that keeps one code path for every recorded quote. Returns
    the quote row's summary dict, or None when the work has no
    non-frontmatter text."""
    chapters = corpus_chapters_for(db, fingerprint)
    target = None
    for c in chapters:
        if not c.get("is_frontmatter"):
            target = c
            break
    if target is None:
        return None
    body = _chapter_body_start(target)
    spans = _sentence_spans(target["text"][body:])
    if not spans:
        return None
    s, e = spans[0]
    # The shipped text slices exactly from the stored chapter
    # text — the heading exclusion is the span's start offset,
    # never string surgery on the sentence itself.
    sentence = target["text"][body + s:body + e]
    corpus_verify_quotes(db, fingerprint, [{
        "text": sentence, "kind": "opening",
        "chapter_index": target["index"],
        "source": "deterministic"}])
    rows = db.query(
        "SELECT quote_id, text FROM quotes WHERE fingerprint=? "
        "AND kind='opening' AND status IN ('verified','selected')",
        (fingerprint,))
    if not rows:
        return None
    return {"quote_id": rows[0][0], "text": rows[0][1],
            "chapter_index": target["index"]}


def corpus_verify_run_quotes(db, fingerprint, run_quotes):
    """Call site (b) (§10.1): a run's model-proposed quotes,
    verified against the corpus when the work is ingested. Run
    quotes carry their chapter LABEL (the reduce's assertion);
    the corpus resolves it. Speaker and spoiler posture stay
    run-side metadata; the corpus records the verify verdict."""
    candidates = []
    for q in run_quotes or []:
        if isinstance(q, dict) and q.get("text"):
            candidates.append({"text": q["text"], "kind": "evidence",
                               "chapter_label": q.get("chapter"),
                               "source": "run"})
    if not candidates:
        return None
    return corpus_verify_quotes(db, fingerprint, candidates)


# ---------------------------------------------------------------------------
# Quote selection (§10.2/§10.5) + the publication payload (§10.6,
# §6.4) — slice 7.
#
# SELECT is a decision-model poll over VERIFIED candidates only.
# The votes are metadata: they rank, they never become a claim, a
# confidence, or a number in any payload. The ship gate is
# conjunctive (verified ∧ spoiler pass ∧ heat pass ∧ caps) and the
# poll sits at the BOTTOM of the shared decision budget's priority
# order and is its FIRST shed: exhausted pool, no validator, or a
# failed call all record poll "skipped" and ship nothing.
# ---------------------------------------------------------------------------

_QUOTE_POLL_ASPECTS = ("quotability", "representative", "spoiler",
                       "heat")
_QUOTE_SCREEN_MAX = 0.5
_SIGNATURE_MAX_CHARS = 140


def _ask_noul_batch(validator, questions, state, label="quote poll"):
    """One decision-model request carrying many noul questions —
    _ask_noul's protocol and discipline (strict score validation,
    circuit breaker) at batch shape. All-or-nothing: any missing
    or malformed score fails the whole batch, because a partial
    poll is not a poll."""
    with validator._lock:
        if validator._disabled:
            return None
    payload = json.dumps({
        "model": validator.model, "state": state,
        "questions": {k: {"type": "noul", "instructions": v}
                      for k, v in questions.items()},
    }).encode()
    headers = {"Content-Type": "application/json"}
    headers.update(validator.extra_headers)
    if validator.api_key:
        headers["Authorization"] = f"Bearer {validator.api_key}"
    try:
        req = urllib.request.Request(
            validator.endpoint, data=payload, headers=headers)
        with urllib.request.urlopen(req, timeout=validator.timeout) \
                as resp:
            result = json.loads(resp.read())
        out = {}
        for key in questions:
            ans = result["answers"][key]
            p_yes = ans.get("noul")
            if p_yes is None:
                p_yes = ans.get("probabilities", {}).get("yes")
            if p_yes is None:
                raise ValueError("response missing 'noul' score")
            if isinstance(p_yes, bool) \
                    or not isinstance(p_yes, (int, float)):
                raise ValueError(f"non-numeric noul score: {p_yes!r}")
            if math.isnan(p_yes) or math.isinf(p_yes):
                raise ValueError(f"non-finite noul score: {p_yes}")
            if not 0 <= p_yes <= 1:
                raise ValueError(
                    f"noul score out of range [0,1]: {p_yes}")
            out[key] = float(p_yes)
        validator._record_success()
        return out
    except Exception as e:
        _tripped = validator._record_error()
        if _tripped:
            validator._note_disabled()
        print(f"  Decision model error ({label}): {e}; "
              f"quote poll shed")
        return None


def corpus_quote_poll(candidates, ask):
    """The §10.2 poll: ONE batched call over the verified
    candidates, returning {quote_id: {quotability, representative,
    spoiler, heat}} — or None when the call fails or any score is
    malformed. ask(questions, state) is injectable; production
    passes a closure over the run's decision validator."""
    questions, lines = {}, []
    for i, cand in enumerate(candidates):
        text = cand["text"]
        lines.append(f"CANDIDATE {i} {text}")
        questions[f"q{i}_quotability"] = (
            "Would readers save and share this line as a quote "
            f"from the book? Line: \"{text}\"")
        questions[f"q{i}_representative"] = (
            "Does this line represent the book — its voice and "
            f"matter — fairly? Line: \"{text}\"")
        questions[f"q{i}_spoiler"] = (
            "Does this line spoil a plot development a new reader "
            f"should discover in the reading? Line: \"{text}\"")
        questions[f"q{i}_heat"] = (
            "Is this line sexually explicit or graphic beyond a "
            f"passing mention? Line: \"{text}\"")
    raw = ask(questions, "\n".join(lines))
    if raw is None:
        return None
    votes = {}
    for i, cand in enumerate(candidates):
        v = {}
        for aspect in _QUOTE_POLL_ASPECTS:
            p = raw.get(f"q{i}_{aspect}")
            if p is None or isinstance(p, bool) \
                    or not isinstance(p, (int, float)) \
                    or not 0 <= p <= 1:
                return None
            v[aspect] = float(p)
        votes[cand["quote_id"]] = v
    return votes


def _quote_select_material(entry, verify_input_hash, poll_model):
    """The quote-select stage's enumerated inputs (§4.1) for one
    candidate: the verified quote (span text hash, chapter, kind),
    the verify stage output it rests on, and the poll model."""
    return {
        "stage": "quote-select",
        "stage_version": QUOTE_SELECT_STAGE_VERSION,
        "quote_id": entry["quote_id"],
        "text_hash": _corpus_text_hash(entry["text"]),
        "chapter_index": entry["chapter_index"],
        "kind": entry["kind"],
        "verify_input_hash": verify_input_hash,
        "poll_model": poll_model,
    }


def _corpus_quote_rows(db, fingerprint, statuses):
    rows = db.query(
        "SELECT quote_id, chapter_index, start_offset, text, kind, "
        "status, payload FROM quotes WHERE fingerprint=? "
        "AND status IN (%s)" % ",".join("?" * len(statuses)),
        (fingerprint, *statuses))
    out = []
    for qid, ci, start, text, kind, status, payload in rows:
        try:
            parsed = json.loads(payload) if payload else {}
        except (TypeError, ValueError):
            parsed = {}
        out.append({"quote_id": qid, "chapter_index": ci,
                    "start": start, "text": text, "kind": kind,
                    "status": status, "payload": parsed,
                    "sentence_bounded": bool(
                        (parsed.get("verify") or {})
                        .get("sentence_bounded"))})
    return out


def _quote_select_shed(db, fingerprint, reason):
    """The fail-closed shed (§10.5): prior selections revert to
    verified, the stage settles the empty set with the skip on its
    run record, and the envelope's quotes section stands present
    with zero selected — which renders as silence."""
    with db.write_txn("stages") as conn:
        for qid, payload in conn.execute(
                "SELECT quote_id, payload FROM quotes WHERE "
                "fingerprint=? AND status='selected'",
                (fingerprint,)):
            try:
                parsed = json.loads(payload) if payload else {}
            except (TypeError, ValueError):
                parsed = {}
            parsed["status"] = "verified"
            parsed.pop("selected_as", None)
            conn.execute(
                "UPDATE quotes SET status='verified', payload=? "
                "WHERE quote_id=?",
                (json.dumps(parsed, ensure_ascii=False), qid))
        _corpus_refresh_quotes_section_in_txn(db, conn, fingerprint)
    corpus_stage_settle(
        db, fingerprint, "quote-select",
        stage_version=QUOTE_SELECT_STAGE_VERSION, model=None,
        outputs={}, run_payload={"poll": "skipped", "reason": reason})
    return {"poll": "skipped", "reason": reason, "selected": 0}


def corpus_select_quotes(db, fingerprint, *, ask=None):
    """The quote-select stage (§10.2–§10.5): poll the verified
    candidates, apply the screens and caps, and record the
    outcome on the quotes rows + stage outputs. Returns
    {"poll": "ok"|"skipped", ...}."""
    chapters = corpus_chapters_for(db, fingerprint)
    if not chapters:
        return {"poll": "skipped", "reason": "no_text", "selected": 0}
    order = sorted(c["index"] for c in chapters)
    rank = {ci: pos for pos, ci in enumerate(order)}
    count = len(order)

    def in_final_quarter(ci):
        # Chapter granularity, safety-biased: a chapter whose span
        # reaches into the book's final quarter counts as final-
        # quarter (§10.4's categorical rule, read fail-safe).
        return (rank.get(ci, 0) + 1) * 4 > 3 * count

    def signature_eligible(e):
        if in_final_quarter(e["chapter_index"]):
            return False  # final quarter: categorically out (§10.4)
        if not e["sentence_bounded"] or len(e["text"]) \
                > _SIGNATURE_MAX_CHARS:
            return False
        if e["kind"] == "evidence" \
                and rank.get(e["chapter_index"], 0) * 2 >= count:
            return False  # source (b) is first-half only
        return True

    # The pool is every verified candidate; a previously selected
    # row is a verified row wearing last run's choice, and this
    # run's settle replaces that choice wholesale (§10.6).
    pool = _corpus_quote_rows(db, fingerprint, ("verified",
                                               "selected"))
    if not pool:
        return _quote_select_shed(db, fingerprint, "no_candidates")
    opening = next((e for e in pool if e["kind"] == "opening"), None)
    sig_pool = [e for e in pool if signature_eligible(e)]
    poll_set = list({e["quote_id"]: e for e in
                     sig_pool + ([opening] if opening else [])}
                    .values())
    if not poll_set:
        return _quote_select_shed(db, fingerprint, "no_candidates")

    poll_model = "injected-ask"
    if ask is None:
        validator = _DECISION_VALIDATOR
        if validator is None:
            return _quote_select_shed(db, fingerprint, "no_validator")
        poll_model = validator.model

        def ask(qs, st, _v=validator):
            return _ask_noul_batch(_v, qs, st)
    if not _dm_budget_claim(1, consumer="quote_poll"):
        # Lowest priority in the shared pool, first shed (§10.5).
        return _quote_select_shed(db, fingerprint, "budget")
    _tel_t0 = time.monotonic()
    votes = corpus_quote_poll(poll_set, ask)
    _telemetry_decision_elapsed(
        "quote", time.monotonic() - _tel_t0)
    if votes is None:
        return _quote_select_shed(db, fingerprint, "poll_failed")

    def screens(e):
        v = votes[e["quote_id"]]
        if v["spoiler"] >= _QUOTE_SCREEN_MAX:
            return "spoiler_screen"
        if v["heat"] >= _QUOTE_SCREEN_MAX:
            return "heat_screen"
        return None

    passing = [e for e in sig_pool if screens(e) is None]
    passing.sort(key=lambda e: (
        -(votes[e["quote_id"]]["quotability"]
          + votes[e["quote_id"]]["representative"]),
        e["chapter_index"], e["quote_id"]))
    winner = passing[0] if passing else None
    opening_ok = opening is not None and screens(opening) is None \
        and (winner is None or opening["quote_id"]
             != winner["quote_id"])

    verify_hashes = {}
    for key, row in corpus_stage_outputs(db, fingerprint,
                                         "quote-verify").items():
        qid = (row.get("payload") or {}).get("quote_id")
        if qid:
            verify_hashes[qid] = row["input_hash"]

    produced = {}
    with db.write_txn("stages") as conn:
        # Unselection is replacement (§10.6): last run's selected
        # rows revert before this run's outcome lands.
        for qid, payload in conn.execute(
                "SELECT quote_id, payload FROM quotes WHERE "
                "fingerprint=? AND status='selected'",
                (fingerprint,)):
            try:
                parsed = json.loads(payload) if payload else {}
            except (TypeError, ValueError):
                parsed = {}
            parsed["status"] = "verified"
            parsed.pop("selected_as", None)
            conn.execute(
                "UPDATE quotes SET status='verified', payload=? "
                "WHERE quote_id=?",
                (json.dumps(parsed, ensure_ascii=False), qid))
        for e in poll_set:
            qid = e["quote_id"]
            v = votes[qid]
            parsed = dict(e["payload"])
            parsed["poll"] = {"model": poll_model, **v}
            fail = screens(e)
            selected_as = None
            if fail is not None:
                new_status = "rejected"
                parsed["status"] = new_status
                parsed["reason"] = fail
            elif winner is not None and qid == winner["quote_id"]:
                new_status, selected_as = "selected", "signature"
                parsed["status"] = new_status
                parsed["selected_as"] = selected_as
                parsed["spoiler_tier"] = "mild"
            elif opening_ok and opening is not None \
                    and qid == opening["quote_id"]:
                new_status, selected_as = "selected", "opening"
                parsed["status"] = new_status
                parsed["selected_as"] = selected_as
                parsed["spoiler_tier"] = "mild"
            else:
                new_status = "verified"
                parsed["status"] = new_status
            conn.execute(
                "UPDATE quotes SET status=?, payload=? "
                "WHERE quote_id=?",
                (new_status, json.dumps(parsed, ensure_ascii=False),
                 qid))
            produced[qid] = {
                "input_hash": _corpus_stage_input_hash(
                    _quote_select_material(
                        e, verify_hashes.get(qid), poll_model)),
                "payload": {"quote_id": qid, "status": new_status,
                            "selected_as": selected_as, "poll": v}}
        _corpus_refresh_quotes_section_in_txn(db, conn, fingerprint)
    corpus_stage_settle(
        db, fingerprint, "quote-select",
        stage_version=QUOTE_SELECT_STAGE_VERSION, model=poll_model,
        outputs=produced,
        run_payload={"poll": "ok", "candidates": len(poll_set)})
    n_selected = sum(1 for o in produced.values()
                     if o["payload"]["status"] == "selected")
    return {"poll": "ok", "selected": n_selected,
            "signature": winner["quote_id"] if winner else None,
            "opening": opening["quote_id"] if opening_ok else None}


def corpus_build_payload(db, fingerprint):
    """The work-level corpus payload (§10.6, §6.4): what may ship.
    Sections carry state, evidence tier and provenance — never a
    raw confidence, never poll votes. Currency is enforced HERE,
    at the boundary: a section whose stage outputs no longer
    recompute equal against the current store is omitted, and
    omission renders as unknown downstream. Edition-scoped
    sections (quotes) state their source edition at section
    level; nothing merges editions."""
    rec = corpus_work_record(db, fingerprint) or {}
    identifiers = rec.get("identifiers")
    if isinstance(identifiers, str):
        try:
            identifiers = json.loads(identifiers)
        except ValueError:
            identifiers = {}
    payload = {"fingerprint": fingerprint,
               "title": rec.get("title"),
               "author": rec.get("author")}
    quotes_section = _corpus_payload_quotes_section(
        db, fingerprint, identifiers or {})
    if quotes_section is not None:
        payload["quotes"] = quotes_section
    return payload


def _corpus_payload_quotes_section(db, fingerprint, identifiers):
    selected = _corpus_quote_rows(db, fingerprint, ("selected",))
    if not selected:
        return None
    chapters = corpus_chapters_for(db, fingerprint)
    by_index = {c["index"]: c for c in chapters}
    select_outputs = corpus_stage_outputs(db, fingerprint,
                                          "quote-select")
    verify_outputs = corpus_stage_outputs(db, fingerprint,
                                          "quote-verify")
    verify_by_qid = {}
    for key, row in verify_outputs.items():
        qid = (row.get("payload") or {}).get("quote_id")
        if qid:
            verify_by_qid[qid] = row
    entries = []
    for e in selected:
        qid = e["quote_id"]
        poll = e["payload"].get("poll") or {}
        so = select_outputs.get(qid)
        vo = verify_by_qid.get(qid)
        if so is None or vo is None or not poll:
            return None  # not current: the section does not ship
        vhash = vo["input_hash"]
        material = _quote_select_material(e, vhash, poll.get("model"))
        if _corpus_stage_input_hash(material) != so["input_hash"]:
            return None
        vp = vo["payload"]
        scope = ([vp.get("asserted_chapter")]
                 if vp.get("asserted_chapter") is not None
                 else sorted(by_index))
        vmat = _quote_verify_material(
            vp.get("kind"), vp.get("asserted_chapter"),
            _corpus_text_hash(vp.get("candidate_text") or ""),
            scope, by_index)
        if _corpus_stage_input_hash(vmat) != vhash:
            return None
        ch = by_index.get(e["chapter_index"]) or {}
        entries.append({
            "text": e["text"],
            "chapter_label": ch.get("label")
            or f"Chapter {e['chapter_index']}",
            "kind": e["payload"].get("selected_as") or e["kind"],
            "spoiler_tier": e["payload"].get("spoiler_tier", "mild"),
            "screens": {"spoiler": "pass", "heat": "pass"},
            "_sort": (e["chapter_index"], qid)})
    entries.sort(key=lambda x: x["_sort"])
    for entry in entries:
        entry.pop("_sort", None)
    return {"state": "present",
            "evidence_tier": "Checked against the text",
            "provenance": "From the text",
            "edition": {"fingerprint": fingerprint,
                        "isbn13": identifiers.get("isbn")},
            "quotes": entries}



# ---------------------------------------------------------------------------
# Migration: JSON store files -> state.db (spine §3.7 + amendment A1)
#
# The build goes into state.db.migrating and is renamed into place
# ONLY after verification passes (per-store counts equal the file
# counts, staging's staged_ever identity closes per work, roster
# accounting closes). A leftover .migrating at startup is an
# incomplete migration: discard it and retry. On abort the JSON
# files remain authoritative and untouched — delay-only, exactly
# the F8 posture. On success the imported originals are renamed
# <name>.migrated-<date> (never deleted); the printed rollback is:
# delete state.db, strip the .migrated-<date> suffixes, done.
# ---------------------------------------------------------------------------

def _migration_sources(d):
    """The JSON store files a migration would import, as Paths."""
    out = []
    for name in ("nicknames.json", "titles.json",
                 "threshold_stats.json", "rejected_tropes.json",
                 "staging.json"):
        p = d / name
        if p.exists():
            out.append(p)
    series = d / "series"
    if series.is_dir():
        out.extend(sorted(series.rglob("*.json")))
    rosters = d / "rosters"
    if rosters.is_dir():
        out.extend(sorted(rosters.glob("*.json")))
    return out


def migrate_state_to_substrate(learn_dir):
    """One-shot JSON -> state.db migration (see the section header).
    Returns a report dict: {"status": migrated|already|aborted,
    "counts": {...}, "reason": ...}. Never raises."""
    d = Path(learn_dir)
    db_path = d / _STATE_DB_NAME
    mig_path = d / _STATE_DB_MIGRATING_NAME
    if db_path.exists():
        return {"status": "already"}
    for sidecar in ("", "-wal", "-shm"):
        try:
            Path(str(mig_path) + sidecar).unlink(missing_ok=True)
        except OSError:
            pass
    sources = _migration_sources(d)
    try:
        d.mkdir(parents=True, exist_ok=True)
        conn = sqlite3.connect(str(mig_path), check_same_thread=False)
        try:
            conn.execute("PRAGMA journal_mode=WAL")
            conn.execute("PRAGMA synchronous=FULL")
            tmpdb = StateDB(mig_path, conn)
            StateDB._create_schema(conn)
            counts = _migration_import(d, tmpdb)
            _migration_verify(d, tmpdb, counts)
            conn.commit()
        finally:
            conn.close()
    except Exception as e:
        for sidecar in ("", "-wal", "-shm"):
            try:
                Path(str(mig_path) + sidecar).unlink(missing_ok=True)
            except OSError:
                pass
        print(f"  !! State migration ABORTED ({e}); the JSON store "
              "files remain authoritative and untouched. The "
              "migration retries on the next run.")
        return {"status": "aborted", "reason": str(e)}
    # Verified: rename into place (A1), then retire the originals.
    os.replace(mig_path, db_path)
    for sidecar in ("-wal", "-shm"):
        s = Path(str(mig_path) + sidecar)
        if s.exists():
            os.replace(s, Path(str(db_path) + sidecar))
    stamp = _staging_today()
    for p in sources:
        try:
            os.replace(p, p.with_name(f"{p.name}.migrated-{stamp}"))
        except OSError:
            pass
    _state_db_for(d)  # register the live handle
    print(f"  State stores migrated to {db_path} "
          f"({counts.get('learned', 0)} learned entries, "
          f"{counts.get('staging_works', 0)} staging works, "
          f"{counts.get('rosters', 0)} roster stores, "
          f"{counts.get('series', 0)} series files). The originals "
          f"were renamed *.migrated-{stamp}, never deleted. "
          "Rollback: delete state.db and strip the suffixes.")
    return {"status": "migrated", "counts": counts}


def _migration_import(d, tmpdb):
    """Import every JSON store into the .migrating DB. Corruption in
    any store raises (the stores degrade-to-empty on their own; here
    that degradation is detected and treated as fatal)."""
    jd = lambda o: json.dumps(o, ensure_ascii=False)
    counts = {}
    learned = LearnedState(learn_dir=d, enabled=True)
    if learned._corrupt_seen:
        raise ValueError(
            f"learned store file(s) unreadable: "
            f"{sorted(learned._corrupt_seen)}")
    learned._db_save_all(tmpdb)
    counts["learned"] = (len(learned.nicknames) + len(learned.titles)
                         + len(learned.threshold_stats)
                         + len(learned.rejected_tropes))
    series_dir = d / "series"
    n_series = 0
    if series_dir.is_dir():
        with tmpdb.write_txn() as conn:
            for p in sorted(series_dir.rglob("*.json")):
                raw = p.read_text(encoding="utf-8")
                json.loads(raw)  # validate; a bad file aborts
                rel = p.relative_to(series_dir)
                key = str(rel)[:-len(".json")].replace(os.sep, "/")
                conn.execute(
                    "INSERT OR REPLACE INTO series_state VALUES (?,?)",
                    (key, raw))
                n_series += 1
    counts["series"] = n_series
    staging = StagingState(learn_dir=d, enabled=True)
    if staging.corrupt_at_load:
        raise ValueError("staging.json is unreadable")
    rep = staging_report_data(staging)
    if rep["unaccounted"] != 0:
        raise ValueError(
            f"staging identity does not close (unaccounted="
            f"{rep['unaccounted']})")
    staging._db_save(tmpdb)
    counts["staging_works"] = len(staging.data["works"])
    counts["staging_claims"] = sum(
        len(w["claims"]) for w in staging.data["works"].values())
    n_rosters = 0
    rosters_dir = d / "rosters"
    if rosters_dir.is_dir():
        for p in sorted(rosters_dir.glob("*.json")):
            raw = json.loads(p.read_text(encoding="utf-8"))
            wk = raw.get("work_key") if isinstance(raw, dict) else None
            if not wk:
                raise ValueError(f"roster store {p.name} has no "
                                 "work_key")
            store = RosterStore(learn_dir=d, work_key=wk)
            if store.corrupt_at_load:
                raise ValueError(f"roster store {p.name} is "
                                 "unreadable")
            if store.accounting()["unaccounted"] != 0:
                raise ValueError(
                    f"roster store {p.name} accounting does not "
                    "close")
            store._db_save(tmpdb)
            n_rosters += 1
    counts["rosters"] = n_rosters
    with tmpdb.write_txn() as conn:
        conn.execute(
            "INSERT OR REPLACE INTO meta VALUES (?,?)",
            ("migrated_from", jd({
                "date": _staging_today(),
                "sources": [p.name for p in _migration_sources(d)],
                "counts": counts})))
    return counts


def _migration_verify(d, tmpdb, counts):
    """Re-read the built DB and compare against the imported counts
    and the source stores (the rename into place happens only when
    this passes)."""
    q = lambda sql, args=(): tmpdb.query(sql, args)[0][0]
    n_learned = sum(q(f"SELECT COUNT(*) FROM {t}") for t in
                    ("learned_nicknames", "learned_titles",
                     "learned_threshold_stats",
                     "learned_rejected_tropes"))
    if n_learned != counts["learned"]:
        raise ValueError("learned counts differ after import")
    if q("SELECT COUNT(*) FROM staging_works") \
            != counts["staging_works"]:
        raise ValueError("staging work counts differ after import")
    if q("SELECT COUNT(*) FROM staging_claims") \
            != counts["staging_claims"]:
        raise ValueError("staging claim counts differ after import")
    if q("SELECT COUNT(*) FROM roster_works") != counts["rosters"]:
        raise ValueError("roster counts differ after import")
    if q("SELECT COUNT(*) FROM series_state") != counts["series"]:
        raise ValueError("series counts differ after import")
    staging_back = StagingState._db_load(tmpdb)
    staging_src = StagingState(learn_dir=d, enabled=True)
    if staging_back != staging_src.data:
        raise ValueError("staging read-back differs from the JSON "
                         "store")
    learned_back = LearnedState._db_load_all(tmpdb)
    src = LearnedState(learn_dir=d, enabled=True)
    if learned_back != (src.nicknames, src.titles,
                        src.threshold_stats, src.rejected_tropes):
        raise ValueError("learned read-back differs from the JSON "
                         "store")


def ensure_state_migrated(learn_dir):
    """OC-7: migration runs automatically on the first run that
    touches state. No state at all -> an empty substrate is created
    (fresh installs start on the substrate)."""
    if not learn_dir:
        return None
    d = Path(learn_dir)
    if (d / _STATE_DB_NAME).exists():
        return {"status": "already"}
    if not _migration_sources(d):
        StateDB.create(d)
        return {"status": "created-empty"}
    return migrate_state_to_substrate(d)


# ---------------------------------------------------------------------------
# Cross-run learning: the pipeline gets smarter with every book processed.
#
# LearnedState persists four kinds of knowledge under <learn_dir>/:
#   nicknames.json       short name -> canonical name (e.g. "pete" -> "peter")
#   titles.json          observed title prefixes ("dr", "herr oberstleutnant")
#   threshold_stats.json P(yes) samples per trigger, kept vs dropped
#   series/<key>.json    character rosters keyed by author, for alias hints
#
# All mutations are lock-protected (safe for --jobs threads). Saves are
# atomic (temp file + os.replace). A single shared instance is created in
# main(); _learn() returns a disabled no-op stub when learning is off so
# call sites never need None checks.
# ---------------------------------------------------------------------------

_LEARN_TITLE_TRUST_COUNT = 2  # distinct name-remainders before a title is trusted


# Trope rejection learning: human rejections (from Trope Lab / the app) feed
# back into the pipeline. 3+ global rejections -> never propose again;
# 1-2 rejections -> raise the acceptance confidence threshold by 0.10 each.
_REJECT_DENYLIST_COUNT = 3
_REJECT_CONF_STEP = 0.10
_TROPE_REJECT_BASE_CONF = 0.50


def _trej_key(trope_id):
    """Rejection lookup key: _tnorm with hyphens -> spaces, so
    'enemies-to-lovers' matches 'enemies to lovers'."""
    return _tnorm(trope_id).replace("-", " ")


class LearnedState:
    """Persistent cross-run learning state. Thread-safe. Degrades to no-op
    when disabled or when the learn directory isn't writable."""

    def __init__(self, learn_dir=None, enabled=True):
        # RLock: load/save hold the lock while their helpers
        # (_note_corrupt, _preserve_corrupt) record state under it.
        self._lock = threading.RLock()
        self.enabled = enabled
        if learn_dir:
            self.dir = Path(learn_dir)
        else:
            self.dir = Path(os.path.expanduser("~")) / ".ebook-processor" / "learned"
        self._writable = True
        self._warned = False
        # Files whose load failed (corrupt/unreadable): their original
        # bytes are preserved as .corrupt backups before any overwrite,
        # and pop_summary flags that prior state was not carried over.
        self._corrupt_paths = set()
        self._corrupt_seen = set()
        # In-memory state (mirrors the JSON files).
        self.nicknames = {}       # nkey -> {"full": nkey, "count": int, "books": [isbn]}
        self.titles = {}          # title -> {"count": int, "rests": [str]}
        self.threshold_stats = {}  # trigger -> {"kept": [p], "dropped": [p]}
        self.rejected_tropes = {}  # trej_key -> {"count": int, "books": [book_key], "reasons": [str], "human": True}
        self._titles_cache = None  # cached frozenset of trusted titles
        self._new = Counter()     # fresh learnings this book (for the summary)
        if self.enabled:
            self._ensure_dir()
            self._load_all()

    # -- setup ----------------------------------------------------------
    def _ensure_dir(self):
        try:
            self.dir.mkdir(parents=True, exist_ok=True)
            (self.dir / "series").mkdir(parents=True, exist_ok=True)
        except Exception:
            self._writable = False
            self._warn_once(
                f"  Learn dir not writable ({self.dir}); learning disabled "
                "for this run")

    def _warn_once(self, msg):
        with self._lock:
            if self._warned:
                return
            self._warned = True
        print(msg)

    # -- persistence ----------------------------------------------------
    def _path(self, name):
        return self.dir / name

    def _note_corrupt(self, path, err):
        """Record a state file that failed to load and say so LOUDLY.

        The store starts empty for that file — silently resetting
        accumulated learning to a plausible fresh state (and then
        overwriting the evidence on save) is how corruption used to
        erase it without a trace. The original bytes are preserved
        as a .corrupt backup before any overwrite (see
        _preserve_corrupt)."""
        path = Path(path)
        with self._lock:
            self._corrupt_paths.add(path)
            first = path.name not in self._corrupt_seen
            self._corrupt_seen.add(path.name)
        if first:
            print(f"  !! WARNING: learned-state file {path} could not "
                  f"be loaded ({err}); starting that store EMPTY. The "
                  f"original file will be preserved as a .corrupt "
                  f"backup before it is overwritten.")

    def _preserve_corrupt(self, path):
        """Back up a corrupt state file's original bytes before it is
        overwritten. Never clobbers an existing backup. No-op for
        files that loaded fine."""
        path = Path(path)
        with self._lock:
            if path not in self._corrupt_paths:
                return
        try:
            if path.exists():
                dest = path.with_name(path.name + ".corrupt")
                n = 1
                while dest.exists():
                    dest = path.with_name(f"{path.name}.corrupt-{n}")
                    n += 1
                shutil.copyfile(path, dest)
                print(f"  !! Preserved corrupt learned-state file "
                      f"as {dest}")
            with self._lock:
                self._corrupt_paths.discard(path)
        except Exception as e:
            print(f"  !! WARNING: could not preserve corrupt file "
                  f"{path} ({e}); it will still be overwritten")

    def _load_json(self, name, default):
        p = self._path(name)
        if not p.exists():
            return default
        try:
            with open(p, encoding="utf-8") as f:
                return json.load(f)
        except Exception as e:
            self._note_corrupt(p, e)
            return default

    def _save_json(self, name, data):
        """Atomic write: temp file + os.replace. No-op when not writable."""
        if not self._writable:
            return False
        try:
            p = self._path(name)
            self._preserve_corrupt(p)
            tmp = p.with_suffix(p.suffix + ".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=1)
            os.replace(tmp, p)
            return True
        except Exception as e:
            self._writable = False
            self._warn_once(f"  Learn dir write failed ({e}); learning "
                            "disabled for this run")
            return False

    def _load_all(self):
        with self._lock:
            db = self._db()
            if db is not None:
                (self.nicknames, self.titles, self.threshold_stats,
                 self.rejected_tropes) = self._db_load_all(db)
                self._titles_cache = None
                if db.corrupt_at_open:
                    self._corrupt_seen.add("state.db")
                return
            self.nicknames = self._load_json("nicknames.json", {})
            self.titles = self._load_json("titles.json", {})
            self.threshold_stats = self._load_json("threshold_stats.json", {})
            self.rejected_tropes = self._load_json("rejected_tropes.json", {})
            self._titles_cache = None

    def save(self):
        """Persist all state. Called at end of each book."""
        if not self.enabled:
            return
        with self._lock:
            db = self._db()
            if db is not None:
                try:
                    self._db_save_all(db)
                except Exception as e:
                    self._writable = False
                    self._warn_once(
                        f"  State substrate write failed ({e}); "
                        f"learning state not persisted this run")
                return
            self._save_json("nicknames.json", self.nicknames)
            self._save_json("titles.json", self.titles)
            self._save_json("threshold_stats.json", self.threshold_stats)
            self._save_json("rejected_tropes.json", self.rejected_tropes)

    # -- substrate seam (spine §3.2: persistence only; the in-memory
    #    model above is unchanged) ------------------------------------
    def _db(self):
        return _state_db_for(self.dir)

    @staticmethod
    def _db_load_all(db):
        nicknames = {}
        for nkey, payload in db.query(
                "SELECT nkey, payload FROM learned_nicknames "
                "ORDER BY rowid"):
            nicknames[nkey] = json.loads(payload)
        titles = {}
        for title, payload in db.query(
                "SELECT title, payload FROM learned_titles "
                "ORDER BY rowid"):
            titles[title] = json.loads(payload)
        threshold_stats = {}
        for trigger, kept, dropped in db.query(
                "SELECT trigger, kept, dropped FROM "
                "learned_threshold_stats ORDER BY rowid"):
            threshold_stats[trigger] = {"kept": json.loads(kept),
                                        "dropped": json.loads(dropped)}
        rejected = {}
        for key, payload in db.query(
                "SELECT trej_key, payload FROM learned_rejected_tropes "
                "ORDER BY rowid"):
            rejected[key] = json.loads(payload)
        return nicknames, titles, threshold_stats, rejected

    def _db_save_all(self, db):
        jd = lambda o: json.dumps(o, ensure_ascii=False)
        with db.write_txn() as conn:
            conn.execute("DELETE FROM learned_nicknames")
            for k, e in self.nicknames.items():
                conn.execute(
                    "INSERT INTO learned_nicknames VALUES "
                    "(?,?,?,?,?,?,?)",
                    (k, e.get("full"), int(e.get("count", 0)),
                     jd(e.get("books", [])),
                     1 if e.get("human") else 0,
                     1 if e.get("manual") else 0, jd(e)))
            conn.execute("DELETE FROM learned_titles")
            for k, e in self.titles.items():
                conn.execute(
                    "INSERT INTO learned_titles VALUES (?,?,?,?)",
                    (k, int(e.get("count", 0)), jd(e.get("rests", [])),
                     jd(e)))
            conn.execute("DELETE FROM learned_threshold_stats")
            for k, e in self.threshold_stats.items():
                conn.execute(
                    "INSERT INTO learned_threshold_stats VALUES "
                    "(?,?,?)",
                    (k, jd(e.get("kept", [])), jd(e.get("dropped", []))))
            conn.execute("DELETE FROM learned_rejected_tropes")
            for k, e in self.rejected_tropes.items():
                conn.execute(
                    "INSERT INTO learned_rejected_tropes VALUES "
                    "(?,?,?,?,?,?)",
                    (k, int(e.get("count", 0)), jd(e.get("books", [])),
                     jd(e.get("reasons", [])),
                     1 if e.get("human") else 0, jd(e)))

    # -- nicknames ------------------------------------------------------
    def record_alias(self, alias_name, canonical_name):
        """Record a human-validated alias (from --alias flag). Cross-book:
        applies to all future books. Human aliases outrank everything."""
        if not self.enabled or not alias_name or not canonical_name:
            return
        short = norm_name(alias_name)
        full = norm_name(canonical_name)
        if not short or not full or short == full:
            return
        with self._lock:
            ent = self.nicknames.get(short)
            if ent is None:
                ent = {"full": full, "count": 0, "books": [],
                       "human": True, "manual": True}
                self.nicknames[short] = ent
                self._new["nicknames"] += 1
            else:
                # Manual alias always wins (it's a fact about the universe).
                ent["full"] = full
                ent["human"] = True
                ent["manual"] = True
            ent["count"] += 1

    def record_merge(self, short_key, full_key, isbn=None):
        """Record that short_key merged into full_key. Called from
        _roster_update on successful merges."""
        if not self.enabled or not short_key or not full_key:
            return
        if short_key == full_key:
            return
        with self._lock:
            ent = self.nicknames.get(short_key)
            if ent is None:
                ent = {"full": full_key, "count": 0, "books": []}
                self.nicknames[short_key] = ent
                self._new["nicknames"] += 1
            elif ent["full"] != full_key:
                # Conflicting mapping: human labels outrank automatic ones.
                if ent.get("human"):
                    return
                # Keep the more-observed one.
                if ent["count"] > 1:
                    return
                ent["full"] = full_key
            ent["count"] += 1
            if isbn and isbn not in ent["books"]:
                ent["books"].append(isbn)

    def record_token_merge(self, short_tok, full_tok, isbn=None):
        """Record a single-token nickname, e.g. 'pete' -> 'peter'."""
        if not self.enabled or not short_tok or not full_tok:
            return
        if short_tok == full_tok or len(short_tok) < 2:
            return
        self.record_merge("@" + short_tok, "@" + full_tok, isbn)

    def nick_lookup(self, nkey):
        """Full-key lookup: returns the learned canonical key or None."""
        if not self.enabled or not nkey:
            return None
        with self._lock:
            ent = self.nicknames.get(nkey)
            return ent["full"] if ent else None

    def token_lookup(self, tok):
        """Single-token lookup: returns the learned full token or None."""
        if not self.enabled or not tok:
            return None
        with self._lock:
            ent = self.nicknames.get("@" + tok)
            if ent:
                full = ent["full"]
                return full[1:] if full.startswith("@") else full
            return None

    def import_labels(self, path):
        """Import hand-labeled merge pairs (from label-merges.py) as
        human-validated nickname mappings. Returns count imported."""
        if not self.enabled:
            return 0
        try:
            with open(path, encoding="utf-8") as f:
                labels = json.load(f)
        except Exception as e:
            print(f"  Could not import labels from {path}: {e}")
            return 0
        n = 0
        for _key, lbl in labels.items():
            if lbl.get("uncertain") or not lbl.get("same_person"):
                continue
            a = norm_name(lbl.get("a", ""))
            b = norm_name(lbl.get("b", ""))
            if not a or not b or a == b:
                continue
            # Direction: shorter -> longer (variant -> canonical).
            short, full = (a, b) if len(a) <= len(b) else (b, a)
            with self._lock:
                ent = self.nicknames.get(short)
                if ent is None:
                    ent = {"full": full, "count": 0, "books": [],
                           "human": True}
                    self.nicknames[short] = ent
                    self._new["nicknames"] += 1
                ent["full"] = full
                ent["count"] += 1
                ent["human"] = True
            n += 1
        return n

    # -- titles ---------------------------------------------------------
    def observe_title(self, candidate, rest):
        """Observe a potential title prefix. Trusted after
        _LEARN_TITLE_TRUST_COUNT distinct name-remainders."""
        if not self.enabled or not candidate or not rest:
            return
        candidate = candidate.lower().strip()
        if (not candidate or candidate in _TITLES
                or candidate in {"the", "a", "an"} or len(candidate) < 2):
            return
        with self._lock:
            ent = self.titles.get(candidate)
            if ent is None:
                ent = {"count": 0, "rests": []}
                self.titles[candidate] = ent
            rest_n = rest.lower().strip()
            if rest_n and rest_n not in ent["rests"]:
                ent["rests"].append(rest_n)
                ent["count"] += 1
                if len(ent["rests"]) == _LEARN_TITLE_TRUST_COUNT:
                    self._new["titles"] += 1
                self._titles_cache = None  # invalidate

    def trusted_titles(self):
        """Frozenset of learned titles trusted for stripping (cached)."""
        if not self.enabled:
            return frozenset()
        with self._lock:
            if self._titles_cache is None:
                self._titles_cache = frozenset(
                    t for t, e in self.titles.items()
                    if len(e.get("rests", [])) >= _LEARN_TITLE_TRUST_COUNT)
            return self._titles_cache

    # -- threshold stats ------------------------------------------------
    def record_threshold(self, trigger, p_yes, kept):
        """Record a decision-model score for future threshold tuning."""
        if not self.enabled:
            return
        try:
            p = float(p_yes)
        except (TypeError, ValueError):
            return
        with self._lock:
            ent = self.threshold_stats.setdefault(
                trigger, {"kept": [], "dropped": []})
            ent["kept" if kept else "dropped"].append(round(p, 4))
            # Cap memory: keep the most recent 500 samples per bucket.
            for k in ("kept", "dropped"):
                if len(ent[k]) > 500:
                    ent[k] = ent[k][-500:]
            self._new["threshold_samples"] += 1

    # -- trope rejections ------------------------------------------------
    def record_trope_rejection(self, trope_id, book_key, reason):
        """Record a human rejection of a trope claim (from Trope Lab or the
        app). Human rejections outrank everything (same pattern as
        --import-labels). Idempotent on (trope, book): re-importing the same
        file does not double-count. Returns True if newly counted."""
        if not self.enabled or not trope_id:
            return False
        key = _trej_key(trope_id)
        if not key:
            return False
        with self._lock:
            ent = self.rejected_tropes.get(key)
            if ent is None:
                ent = {"count": 0, "books": [], "reasons": [],
                       "human": True}
                self.rejected_tropes[key] = ent
                self._new["rejected_tropes"] += 1
            # Idempotency: the same (trope, book) rejection only counts once.
            # A new reason for an already-counted book is still kept.
            dup = bool(book_key) and book_key in ent["books"]
            if not dup:
                ent["count"] += 1
            if book_key and book_key not in ent["books"]:
                ent["books"].append(book_key)
            if reason:
                r = reason[:200]
                if r not in ent["reasons"]:
                    ent["reasons"].append(r)
            return not dup

    def get_trope_rejection_count(self, trope_id):
        """Global rejection count for a trope (0 when disabled/unknown)."""
        if not self.enabled or not trope_id:
            return 0
        with self._lock:
            ent = self.rejected_tropes.get(_trej_key(trope_id))
            return ent["count"] if ent else 0

    def is_trope_denylisted(self, trope_id):
        """True when a trope has been rejected enough times to never propose."""
        return self.get_trope_rejection_count(trope_id) >= _REJECT_DENYLIST_COUNT

    def trope_rejection_threshold(self, trope_id, base=_TROPE_REJECT_BASE_CONF):
        """Acceptance confidence threshold for a trope, raised by
        _REJECT_CONF_STEP per rejection (capped below the denylist)."""
        n = min(self.get_trope_rejection_count(trope_id),
                _REJECT_DENYLIST_COUNT - 1)
        return round(base + _REJECT_CONF_STEP * n, 2)

    def import_rejections(self, path):
        """Import trope rejections from a JSON file (see --import-rejections).
        Accepts a list of {trope_id, book_key, reason} or
        {"rejections": [...]}. Returns count newly recorded."""
        if not self.enabled:
            return 0
        try:
            with open(path, encoding="utf-8") as f:
                items = json.load(f)
        except Exception as e:
            print(f"  Could not import rejections from {path}: {e}")
            return 0
        if isinstance(items, dict):
            items = items.get("rejections", [])
        if not isinstance(items, list):
            print(f"  Could not import rejections from {path}: "
                  "expected a list")
            return 0
        n = 0
        for it in items:
            if not isinstance(it, dict):
                continue
            if self.record_trope_rejection(it.get("trope_id"),
                                           it.get("book_key"),
                                           it.get("reason")):
                n += 1
        return n

    def import_rejections_from_supabase(self):
        """Import rejected trope claims from Supabase (book_trope_claims
        where status='rejected'). Catalog trope_ids are reverse-mapped to
        names via the tropes table. Returns count imported, or -1 when
        Supabase isn't configured/reachable."""
        if not self.enabled:
            return 0
        if not CONFIG.get("supabase_url") or not CONFIG.get("supabase_key"):
            print("  Supabase not configured; cannot import rejections "
                  "from Supabase")
            return -1
        cat_rows = sb("tropes", params="?select=id,name&limit=500")
        if cat_rows is None:
            print("  Could not load trope catalog from Supabase")
            return -1
        id_to_name = {str(r.get("id")): r.get("name", "") for r in cat_rows}
        rows = sb("book_trope_claims",
                  params="?status=eq.rejected&select=trope_id,work_id&limit=2000")
        if rows is None:
            return -1
        n = 0
        for r in rows:
            tid = str(r.get("trope_id") or "")
            name = id_to_name.get(tid, tid)  # fall back to the raw id
            if self.record_trope_rejection(
                    name, r.get("work_id"),
                    "rejected in Trope Lab/app"):
                n += 1
        return n

    # -- series rosters -------------------------------------------------
    @staticmethod
    def series_key(author):
        """Series bucket key. Currently author-based (no series metadata
        in EPUB parsing); per-author buckets with per-book rosters."""
        a = (author or "").strip().casefold()
        if not a:
            return None
        return "author_" + re.sub(r"\W+", "_", a)[:48].strip("_")

    def _series_path(self, series_key):
        safe = re.sub(r"\W+", "_", series_key)[:64].strip("_") or "unknown"
        return self.dir / "series" / (safe + ".json")

    # -- series persistence seam (spine: series/*.json files become
    #    series_state rows keyed by their path under series/, minus
    #    the .json suffix — "author_x" flat, "daemon/roster" named) --
    def _series_db_key(self, p):
        rel = Path(p).relative_to(self.dir / "series").as_posix()
        return rel[:-5] if rel.endswith(".json") else rel

    def _db_series_get(self, p):
        """Parsed series payload from the substrate: the dict, or
        None when no row exists. A corrupt payload is LOUD and reads
        as {} (the F8 rule: preserved by the substrate's own
        discipline at open; a bad payload never silently merges)."""
        db = self._db()
        if db is None:
            return None
        rows = db.query(
            "SELECT payload FROM series_state WHERE series_key=?",
            (self._series_db_key(p),))
        if not rows:
            return None
        try:
            data = json.loads(rows[0][0])
            return data if isinstance(data, dict) else {}
        except Exception as e:
            print(f"  !! WARNING: series state row for {p} could not "
                  f"be parsed ({e}); treating it as EMPTY")
            return {}

    def _db_series_put(self, p, data):
        db = self._db()
        with db.write_txn() as conn:
            conn.execute(
                "INSERT OR REPLACE INTO series_state VALUES (?,?)",
                (self._series_db_key(p),
                 json.dumps(data, ensure_ascii=False)))

    def _write_series_data(self, p, data):
        """Persist one series payload: a series_state row on the
        substrate, else the atomic file write."""
        if self._db() is not None:
            self._db_series_put(p, data)
            return
        self._preserve_corrupt(p)
        tmp = p.with_suffix(p.suffix + ".tmp")
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        os.replace(tmp, p)

    def _load_series_data(self, p):
        """Load a series-roster file for a save-side merge. A corrupt
        file starts empty LOUDLY and its bytes are preserved as a
        .corrupt backup before the overwrite — the same rule as the
        learned files (a silent reset here used to erase the roster
        the merge was supposed to extend)."""
        if self._db() is not None:
            data = self._db_series_get(p)
            return data if data is not None else {}
        if not p.exists():
            return {}
        try:
            with open(p, encoding="utf-8") as f:
                return json.load(f)
        except Exception as e:
            self._note_corrupt(p, e)
            return {}

    def load_series_hints(self, series_key):
        """Return {nkey: canonical_nkey} alias hints from prior books in
        the series. Empty dict when disabled/unknown."""
        if not self.enabled or not series_key:
            return {}
        p = self._series_path(series_key)
        if self._db() is None and not p.exists():
            return {}
        data = self._load_series_data(p)
        hints = {}
        for ch in data.get("characters", []):
            canon = norm_name(ch.get("name", ""))
            if not canon:
                continue
            for al in ch.get("aliases", []):
                ak = norm_name(al)
                if ak and ak != canon:
                    hints.setdefault(ak, canon)
        return hints

    def save_series_roster(self, series_key, title, author, isbn, characters):
        """Persist this book's character roster into the series bucket."""
        if not self.enabled or not series_key:
            return
        p = self._series_path(series_key)
        data = self._load_series_data(p)
        data.setdefault("characters", [])
        data.setdefault("books", [])
        seen = {norm_name(c.get("name", "")) for c in data["characters"]}
        added = 0
        for c in characters or []:
            nk = norm_name(c.get("name", ""))
            if not nk or nk in seen:
                continue
            seen.add(nk)
            aliases = sorted({a for a in (c.get("aliases") or [])
                              if a and norm_name(a) != nk})
            data["characters"].append({"name": c.get("name", ""),
                                       "aliases": aliases})
            added += 1
        if isbn and not any(b.get("isbn") == isbn for b in data["books"]):
            data["books"].append({"isbn": isbn, "title": title})
        # Atomic write.
        try:
            self._write_series_data(p, data)
        except Exception as e:
            self._warn_once(f"  Could not save series roster ({e})")
            return
        if added:
            with self._lock:
                self._new["series_chars"] += added

    @staticmethod
    def series_name_key(series_name):
        """Bucket key for a named series (e.g. 'Daemon'). Distinct from the
        author-based series_key(); used for cross-book character continuity
        within a detected series."""
        s = (series_name or "").strip().casefold()
        if not s:
            return None
        return re.sub(r"\W+", "_", s)[:48].strip("_") or None

    def _named_series_path(self, series_key):
        """Path: <learn_dir>/series/{normalized}/roster.json"""
        safe = re.sub(r"\W+", "_", series_key)[:64].strip("_") or "unknown"
        return self.dir / "series" / safe / "roster.json"

    def load_series_name_hints(self, series_key):
        """Return {nkey: canonical_nkey} alias hints from prior books in the
        named series. Empty dict when disabled/unknown."""
        if not self.enabled or not series_key:
            return {}
        p = self._named_series_path(series_key)
        if self._db() is None and not p.exists():
            return {}
        data = self._load_series_data(p)
        hints = {}
        for ch in data.get("characters", []):
            canon = norm_name(ch.get("name", ""))
            if not canon:
                continue
            for al in ch.get("aliases", []):
                ak = norm_name(al)
                if ak and ak != canon:
                    hints.setdefault(ak, canon)
        return hints

    def save_series_name_roster(self, series_key, title, author, isbn,
                                series_position, characters):
        """Persist this book's roster into the named-series bucket."""
        if not self.enabled or not series_key:
            return
        p = self._named_series_path(series_key)
        try:
            p.parent.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass  # the write below surfaces the failure via _warn_once
        data = self._load_series_data(p)
        data.setdefault("characters", [])
        data.setdefault("books", [])
        data["series"] = series_key
        seen = {norm_name(c.get("name", "")) for c in data["characters"]}
        added = 0
        for c in characters or []:
            nk = norm_name(c.get("name", ""))
            if not nk or nk in seen:
                continue
            seen.add(nk)
            aliases = sorted({a for a in (c.get("aliases") or [])
                              if a and norm_name(a) != nk})
            data["characters"].append({"name": c.get("name", ""),
                                       "aliases": aliases})
            added += 1
        if isbn and not any(b.get("isbn") == isbn for b in data["books"]):
            data["books"].append({"isbn": isbn, "title": title,
                                  "position": series_position})
        # Atomic write.
        try:
            self._write_series_data(p, data)
        except Exception as e:
            self._warn_once(f"  Could not save named-series roster ({e})")
            return
        if added:
            with self._lock:
                self._new["series_chars"] += added

    # -- summary --------------------------------------------------------
    def pop_summary(self):
        """Return 'Learned: ...' summary of this book's fresh learnings and
        reset the counters. Empty string when nothing was learned."""
        with self._lock:
            parts = []
            n = self._new.get("nicknames", 0)
            if n:
                parts.append(f"{n} nickname{'s' if n != 1 else ''}")
            t = self._new.get("titles", 0)
            if t:
                parts.append(f"{t} title{'s' if t != 1 else ''}")
            s = self._new.get("threshold_samples", 0)
            if s:
                parts.append(f"{s} threshold sample{'s' if s != 1 else ''}")
            sc = self._new.get("series_chars", 0)
            if sc:
                parts.append(f"{sc} series character{'s' if sc != 1 else ''}")
            rj = self._new.get("rejected_tropes", 0)
            if rj:
                parts.append(f"{rj} trope rejection{'s' if rj != 1 else ''}")
            self._new.clear()
            corrupt = sorted(self._corrupt_seen)
        if not parts:
            return ""
        summary = "Learned: " + ", ".join(parts)
        if corrupt:
            # This run's counts are real, but the store they joined
            # started empty for these files — the summary must not
            # read as if the prior state had carried over.
            summary += (f" (warning: {len(corrupt)} learned file(s) "
                        f"failed to load this run — prior state not "
                        f"carried over; originals preserved as .corrupt "
                        f"backups)")
        return summary


# ---------------------------------------------------------------------------
# Option F: staging store (empty-evidence staging gate + persistence gate).
#
# Design: eval/f-staging-design.md. Doctrine, binding on everything
# below: persistence is a stability filter, not truth. A promoted claim
# is a claim that stopped flickering, not a claim that was verified.
# Promotion never raises a claim's confidence, never applies to family
# relationships (the helper REFUSES those classes — there is no code
# path from staging to a relationship row), and never overrides a
# denylist, a rejection, or a human curation state.
#
# StagingState is per-work RUN BOOKKEEPING, not learning: entries
# expire, learning accumulates. It shares LearnedState's directory and
# its F8 persistence discipline (atomic save, loud corruption notice,
# .corrupt preservation) but is a separate class and file
# (staging.json), deliberately unentangled from the learning
# governance questions. Every failure direction is delay-only:
# corruption, splits and lost state can postpone a claim, never ship
# one early — promotion requires state the failure destroyed.
# ---------------------------------------------------------------------------

_STAGEABLE_CLASSES = ("trope", "trigger")
_STAGING_EXPIRE_ABSENCES = 3    # completed runs unsighted -> expired
_STAGING_STALE_DAYS = 180       # report flag; no wall-clock expiry
_STAGING_EXPIRED_CAP = 200      # retained expired records per work
_STAGING_SIZE_WARN = 5 * 1024 * 1024


def staging_claim_key(cls, name=None, catalog_id=None, warning=None):
    """Identity key for a stageable claim (design section 3).

    Tropes anchor on the catalog id when the claim resolves to one
    (paraphrases collapse to one id, surviving display-form flips);
    otherwise the normalized name. Triggers key on the normalized
    warning name. Any other claim class — relationships above all —
    is refused: staging has no identity for them and must never grow
    one in v1 (endpoint identity is the unsolved roster problem)."""
    if cls == "trope":
        if catalog_id:
            return f"trope:id:{catalog_id}"
        return f"trope:name:{_tnorm(name)}"
    if cls == "trigger":
        return f"trigger:{(warning or '').lower().strip()}"
    raise ValueError(
        f"claim class {cls!r} is not stageable: only trope and "
        "trigger claims stage in v1; relationships/family claims are "
        "never staged or promoted (fail-closed has no bypass)")


def staging_work_key(work_id=None, isbn=None, title="", author=""):
    """Store key for a work (design section 3): the catalog work_id
    when resolved, else the ISBN, else normalized title|author. The
    weaker keys are a fallback for previewing un-ingested books, not
    a second identity system: entries under them are adopted into
    the work_id entry when a run resolves the id (OC-8)."""
    if work_id:
        return str(work_id)
    if isbn:
        return f"isbn:{isbn}"
    return f"title:{_tnorm(title)}|{_tnorm(author)}"


def _staging_day(s):
    """ISO date string -> ordinal day number (None when unparsable)."""
    if not s:
        return None
    try:
        from datetime import date
        y, m, d = (int(p) for p in str(s).split("-"))
        return date(y, m, d).toordinal()
    except (ValueError, TypeError):
        return None


def _staging_today():
    from datetime import date
    return date.today().isoformat()


class StagingState:
    """Per-work staging bookkeeping. Thread-safe: observe+save are
    serialized under an RLock (books run concurrently under --jobs;
    an unsynchronized load-modify-save would lose sightings — delay
    only, but promotion timing would go nondeterministic). Degrades
    to no-claims-ship-differently when the directory isn't writable:
    the seam checks .enabled/.writable and skips staging entirely."""

    FILE_NAME = "staging.json"

    def __init__(self, learn_dir=None, enabled=True):
        # RLock: observe holds the lock while its helpers record
        # state under it (same lesson as LearnedState, sweep F8).
        self._lock = threading.RLock()
        self.enabled = enabled
        if learn_dir:
            self.dir = Path(learn_dir)
        else:
            self.dir = Path(os.path.expanduser("~")) / ".ebook-processor" / "learned"
        self._writable = True
        self._warned = False
        self._corrupt_paths = set()
        self._corrupt_seen = set()
        self.data = {"version": 1, "works": {}}
        if self.enabled:
            self._ensure_dir()
            self._load()

    # -- setup / persistence (LearnedState's F8 pattern) --------------
    def _ensure_dir(self):
        try:
            self.dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            self._writable = False
            self._warn_once(
                f"  Staging dir not writable ({self.dir}); staging "
                "disabled for this run")

    def _warn_once(self, msg):
        with self._lock:
            if self._warned:
                return
            self._warned = True
        print(msg)

    @property
    def writable(self):
        return self._writable

    @property
    def corrupt_at_load(self):
        return bool(self._corrupt_seen)

    def _path(self):
        return self.dir / self.FILE_NAME

    def _note_corrupt(self, path, err):
        """Record a staging file that failed to load and say so
        LOUDLY. The store starts empty — the failure direction is
        safe by construction: lost state means sightings reset and
        promotions are DELAYED, because promotion requires state the
        corruption destroyed. The original bytes are preserved as a
        .corrupt backup before any overwrite."""
        path = Path(path)
        with self._lock:
            self._corrupt_paths.add(path)
            first = path.name not in self._corrupt_seen
            self._corrupt_seen.add(path.name)
        if first:
            print(f"  !! WARNING: staging file {path} could not be "
                  f"loaded ({err}); starting the staging store EMPTY "
                  f"(claims will re-stage; nothing can promote "
                  f"early). The original file will be preserved as a "
                  f".corrupt backup before it is overwritten.")

    def _preserve_corrupt(self, path):
        """Back up a corrupt staging file's original bytes before it
        is overwritten. Never clobbers an existing backup."""
        path = Path(path)
        with self._lock:
            if path not in self._corrupt_paths:
                return
        try:
            if path.exists():
                dest = path.with_name(path.name + ".corrupt")
                n = 1
                while dest.exists():
                    dest = path.with_name(f"{path.name}.corrupt-{n}")
                    n += 1
                shutil.copyfile(path, dest)
                print(f"  !! Preserved corrupt staging file as {dest}")
            with self._lock:
                self._corrupt_paths.discard(path)
        except Exception as e:
            print(f"  !! WARNING: could not preserve corrupt file "
                  f"{path} ({e}); it will still be overwritten")

    def _load(self):
        db = _state_db_for(self.dir)
        if db is not None:
            try:
                self.data = self._db_load(db)
            except Exception as e:
                self._note_corrupt(self.dir / _STATE_DB_NAME, e)
                self.data = {"version": 1, "works": {}}
            return
        p = self._path()
        if not p.exists():
            return
        try:
            with open(p, encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict) \
                    or not isinstance(data.get("works"), dict):
                raise ValueError("staging store has no 'works' map")
            self.data = {"version": 1, "works": data["works"]}
        except Exception as e:
            self._note_corrupt(p, e)
            self.data = {"version": 1, "works": {}}

    # -- substrate seam (spine §3.2) ------------------------------------
    @staticmethod
    def _db_load(db):
        works = {}
        for work_key, payload in db.query(
                "SELECT work_key, payload FROM staging_works "
                "ORDER BY rowid"):
            w = json.loads(payload)
            w["claims"] = {}
            w["expired_recent"] = []
            works[work_key] = w
        for work_key, claim_key, payload in db.query(
                "SELECT work_key, claim_key, payload FROM "
                "staging_claims ORDER BY rowid"):
            works[work_key]["claims"][claim_key] = json.loads(payload)
        for work_key, payload in db.query(
                "SELECT work_key, payload FROM staging_expired "
                "ORDER BY rowid"):
            works[work_key]["expired_recent"].append(json.loads(payload))
        return {"version": 1, "works": works}

    def _db_save(self, db):
        jd = lambda o: json.dumps(o, ensure_ascii=False)
        with db.write_txn() as conn:
            conn.execute("DELETE FROM staging_works")
            conn.execute("DELETE FROM staging_claims")
            conn.execute("DELETE FROM staging_expired")
            for wk, w in self.data["works"].items():
                payload = {k: v for k, v in w.items()
                           if k not in ("claims", "expired_recent")}
                conn.execute(
                    "INSERT INTO staging_works VALUES (?,?,?,?,?,?,?)",
                    (wk, w.get("work_id"), w.get("title"),
                     w.get("author"), int(w.get("runs_completed", 0)),
                     int(w.get("staged_ever", 0)), jd(payload)))
                for ck, c in w["claims"].items():
                    conn.execute(
                        "INSERT INTO staging_claims VALUES "
                        "(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (wk, ck, c.get("class"), c.get("display"),
                         c.get("state"), c.get("promoted_run"),
                         c.get("promoted_via"),
                         int(c.get("best_chapters", 0)),
                         1 if c.get("evidence_ever") else 0,
                         c.get("first_seen"), c.get("last_seen"),
                         jd(c.get("sightings", [])),
                         jd(c.get("name_forms", [])), jd(c)))
                for e in w["expired_recent"]:
                    conn.execute(
                        "INSERT INTO staging_expired VALUES (?,?,?,?,?)",
                        (wk, e.get("key"), e.get("expired_run"),
                         jd(e.get("sightings", [])), jd(e)))

    def save(self):
        """Atomic write: temp file + os.replace. No-op when not
        writable. A size guard warns past 5 MB (the realistic growth
        driver is works never reprocessed; the report shows them)."""
        if not self._writable or not self.enabled:
            return False
        with self._lock:
            db = _state_db_for(self.dir)
            if db is not None:
                try:
                    self._db_save(db)
                    return True
                except Exception as e:
                    self._writable = False
                    self._warn_once(
                        f"  Staging store write failed ({e}); "
                        "staging is disabled for the rest of this run.")
                    return False
            try:
                p = self._path()
                self._preserve_corrupt(p)
                tmp = p.with_suffix(p.suffix + ".tmp")
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump(self.data, f, ensure_ascii=False, indent=1)
                os.replace(tmp, p)
                try:
                    if p.stat().st_size > _STAGING_SIZE_WARN:
                        self._warn_once(
                            f"  Staging store is large "
                            f"({p.stat().st_size} bytes); run "
                            "--staging-report to see what is trapped")
                except OSError:
                    pass
                return True
            except Exception as e:
                self._writable = False
                self._warn_once(
                    f"  Staging dir write failed ({e}); staging "
                    "disabled for this run")
                return False

    # -- work entries ---------------------------------------------------
    @staticmethod
    def _new_work(work_id, title, author):
        return {"work_id": work_id, "title": title or "",
                "author": author or "", "runs_completed": 0,
                "staged_ever": 0, "claims": {}, "expired_recent": [],
                "expired_dropped": 0, "adoptions": []}

    @staticmethod
    def _new_claim(cls, display, today):
        return {"class": cls, "display": display or "",
                "name_forms": [display] if display else [],
                "sightings": [], "first_seen": today,
                "last_seen": today, "best_chapters": 0,
                "evidence_ever": False, "state": "staged",
                "promoted_run": None, "promoted_via": None,
                "promoted_form_changed": False}

    def work_entry(self, work_key, work_id=None, title="", author=""):
        """Fetch-or-create a work entry (call under the lock)."""
        w = self.data["works"].get(work_key)
        if w is None:
            w = self._new_work(work_id, title, author)
            self.data["works"][work_key] = w
        else:
            if work_id and not w.get("work_id"):
                w["work_id"] = work_id
            if title and not w.get("title"):
                w["title"] = title
            if author and not w.get("author"):
                w["author"] = author
        return w

    # -- adoption (OC-8) --------------------------------------------------
    def _adopt_fallbacks(self, work, work_id, title, author, isbn):
        """Adopt fallback-key entries into the work_id entry when a
        work first resolves its id. Exact title+author match only
        (normalized); adoptions are recorded on the surviving entry
        so the next trapped report lists them — a wrong adoption
        must be visible to be correctable."""
        if not work_id:
            return
        candidates = []
        if isbn:
            candidates.append(f"isbn:{isbn}")
        candidates.append(
            f"title:{_tnorm(title)}|{_tnorm(author)}")
        for cand in candidates:
            src = self.data["works"].get(cand)
            if src is None or src is work:
                continue
            if _tnorm(src.get("title")) != _tnorm(title) \
                    or _tnorm(src.get("author")) != _tnorm(author):
                continue
            moved = self._merge_work_into(work, src)
            del self.data["works"][cand]
            if moved:
                work["adoptions"].append(
                    {"from_key": cand, "claims_moved": moved})

    def _merge_work_into(self, dst, src):
        """Fold src's claims into dst (adoption). The two entries
        partition the work's runs (each run observes under exactly
        one key), so src's sighting ordinals SHIFT by dst's completed
        run count before unioning — a fallback entry recreated fresh
        each run numbers its run 1 every time, and a plain union
        would silently eat every later sighting (delay-only, but it
        would break promotion for exactly the books adoption serves).
        staged_ever stays exact: a claim key live in BOTH entries was
        one claim counted on both sides, so each such overlap
        subtracts one duplicate; a key expired on one side and live
        on the other is two staging episodes (expired, then
        re-staged) and counts twice, exactly as observe counts a
        re-stage. Promotion is sticky. Returns claims moved/merged."""
        moved = 0
        dup = 0
        shift = dst["runs_completed"]
        for key, entry in list(src["claims"].items()):
            moved += 1
            if shift:
                entry["sightings"] = [s + shift
                                      for s in entry["sightings"]]
                if entry.get("promoted_run"):
                    entry["promoted_run"] += shift
            cur = dst["claims"].get(key)
            if cur is None:
                dst["claims"][key] = entry
            else:
                self._fold_entry_into(cur, entry)
                dup += 1
        for rec in src["expired_recent"]:
            if shift and rec.get("expired_run"):
                rec["expired_run"] += shift
            if all(r["key"] != rec["key"]
                   for r in dst["expired_recent"]):
                dst["expired_recent"].append(rec)
            else:
                dup += 1
        dst["expired_dropped"] = dst.get("expired_dropped", 0) \
            + src.get("expired_dropped", 0)
        dst["staged_ever"] += src["staged_ever"] - dup
        while len(dst["expired_recent"]) > _STAGING_EXPIRED_CAP:
            dst["expired_recent"].pop(0)
            dst["expired_dropped"] += 1
        dst["runs_completed"] = shift + src["runs_completed"]
        return moved

    def _reevaluate_adopted(self, work):
        """Re-evaluate promotion and absence-expiry on the surviving
        entry after an adoption fold (call under the lock).

        Promotion/expiry otherwise evaluate only at observe time, on
        the entry the run observes under. A work whose seam
        resolution misses EVERY run is only ever observed under its
        fallback key, so its canonical entry accumulated sightings no
        check ever saw: claims at 2+ sightings stayed "staged"
        forever and absent claims never expired. The folded state is
        complete (sightings already shifted into the survivor's
        ordinal space by _merge_work_into), so both checks can run
        here on exactly the values observe would have used. The
        persistence rule is the one applied — sightings are the only
        evidence an adoption carries (no current observation, so no
        support/evidence promotion can be judged here). Promotion is
        sticky and accounting-preserving: staged -> promoted, or
        staged -> expired_recent, staged_ever untouched."""
        ordinal = work["runs_completed"]
        for key, entry in list(work["claims"].items()):
            if entry["state"] != "staged":
                continue
            if len(entry["sightings"]) >= 2:
                entry["state"] = "promoted"
                entry["promoted_run"] = max(entry["sightings"])
                entry["promoted_via"] = "persistence"
            elif entry["sightings"] and \
                    ordinal - max(entry["sightings"]) \
                    >= _STAGING_EXPIRE_ABSENCES:
                work["expired_recent"].append(
                    {"key": key, "display": entry["display"],
                     "class": entry["class"], "expired_run": ordinal,
                     "sightings": len(entry["sightings"])})
                del work["claims"][key]
        while len(work["expired_recent"]) > _STAGING_EXPIRED_CAP:
            work["expired_recent"].pop(0)
            work["expired_dropped"] += 1

    def adopt_for(self, work_id, title="", author="", isbn=None):
        """Post-resolution adoption (OC-8), the net for works whose
        observe ran under a fallback key: the staging seam resolves
        read-only BEFORE observing and observes under the canonical
        key whenever the work already exists, so adoption now fires
        only for works that resolve later (genuinely new works, or a
        seam resolution that missed and the creating resolution
        caught). Creates no entry when nothing waits to be adopted.
        After a fold, the surviving entry's staged claims are
        re-evaluated for promotion/expiry (see _reevaluate_adopted):
        a work that misses at the seam every run never observes its
        canonical entry, so adoption is the only place its folded
        sightings can ever be judged. Returns True when an adoption
        happened."""
        if not work_id or not self.enabled:
            return False
        with self._lock:
            dst_key = str(work_id)
            candidates = []
            if isbn:
                candidates.append(f"isbn:{isbn}")
            candidates.append(
                f"title:{_tnorm(title)}|{_tnorm(author)}")
            if not any(c in self.data["works"] for c in candidates
                       if c != dst_key):
                return False
            dst = self.work_entry(dst_key, work_id, title, author)
            before = len(dst["adoptions"])
            self._adopt_fallbacks(dst, work_id, title, author, isbn)
            # A fold happened iff a candidate entry was consumed —
            # NOT iff an adoption record was appended: a fallback
            # entry holding no claims moves nothing and records
            # nothing, yet its runs still merged into the survivor's
            # runs_completed, which is exactly what the expiry
            # re-evaluation must see.
            folded = not any(c in self.data["works"] for c in candidates
                             if c != dst_key)
            if len(dst["adoptions"]) == before and not folded:
                return False
            self._reevaluate_adopted(dst)
            self.save()
            return True

    @staticmethod
    def _fold_entry_into(dst, src):
        """Merge src claim entry into dst (same claim, two keyings).
        Sightings union (ordinals are per-work; a run contributes at
        most one ordinal per claim, so union is exact)."""
        dst["sightings"] = sorted(set(dst["sightings"])
                                   | set(src["sightings"]))
        for form in src["name_forms"]:
            if _tnorm(form) not in {_tnorm(f)
                                    for f in dst["name_forms"]}:
                dst["name_forms"].append(form)
        dst["best_chapters"] = max(dst["best_chapters"],
                                   src["best_chapters"])
        dst["evidence_ever"] = dst["evidence_ever"] \
            or src["evidence_ever"]
        # Option G: a folded entry's recorded support grade goes
        # with it (strong wins) — the survivor's next observe is
        # where promotion rule 4 evaluates it, never the fold.
        _grades = (dst.get("evidence_grade"),
                   src.get("evidence_grade"))
        if "strong" in _grades:
            dst["evidence_grade"] = "strong"
        elif "single" in _grades:
            dst["evidence_grade"] = "single"
        for f in ("first_seen",):
            a, b = _staging_day(dst.get(f)), _staging_day(src.get(f))
            if b is not None and (a is None or b < a):
                dst[f] = src[f]
        a, b = _staging_day(dst.get("last_seen")), \
            _staging_day(src.get("last_seen"))
        if b is not None and (a is None or b > a):
            dst["last_seen"] = src["last_seen"]
        if src["state"] == "promoted" and dst["state"] != "promoted":
            dst["state"] = "promoted"
            dst["promoted_run"] = src["promoted_run"]
            dst["promoted_via"] = src["promoted_via"]
            dst["promoted_form_changed"] = \
                src["promoted_form_changed"]

    # -- observe ----------------------------------------------------------
    def observe_work(self, *, work_key, work_id=None, title="",
                     author="", isbn=None, tropes=(), triggers=(),
                     auto_min=3, independent=True, today=None):
        """Record one completed run's stageable claims for a work and
        decide this run's ship/hold split.

        tropes:   [{"name", "n_ch", "catalog_id"}]
        triggers: [{"warning", "has_evidence"}]

        A sighting counts only on an INDEPENDENT run (fresh
        extraction — no checkpoint payloads reused). A resumed or
        retried run re-derives the same extraction; counting it would
        manufacture persistence out of one observation. Non-independent
        runs still get the split from current store state (the run is
        a continuation of its original) and may move last_seen, but
        they create no entries, record no sightings, promote nothing
        and expire nothing.

        Returns {"trope_actions", "trigger_actions", "staged",
        "promoted", "expired_this_run", "sightings_recorded",
        "trapped_total"}. Actions align with the input lists:
        {"action": "ship"|"hold", "key", "stamp", "form_changed"}.
        Serialized under the lock, save included."""
        today = today or _staging_today()
        with self._lock:
            if not independent \
                    and work_key not in self.data["works"]:
                # A continuation of a run this store never saw: no
                # entries to continue, nothing may be created.
                ship = {"action": "ship", "key": None, "stamp": None,
                        "form_changed": False}
                return {"trope_actions": [dict(ship) for _ in tropes],
                        "trigger_actions": [dict(ship)
                                            for _ in triggers],
                        "staged": [], "promoted": [],
                        "expired_this_run": 0, "sightings_recorded": 0,
                        "trapped_total": 0}
            work = self.work_entry(work_key, work_id, title, author)
            self._adopt_fallbacks(work, work_id, title, author, isbn)
            out = {"trope_actions": [], "trigger_actions": [],
                   "staged": [], "promoted": [], "expired_this_run": 0,
                   "sightings_recorded": 0, "trapped_total": 0}
            ordinal = None
            if independent:
                work["runs_completed"] += 1
                ordinal = work["runs_completed"]
            for obs in tropes:
                act = self._observe_trope(work, obs, auto_min,
                                          independent, ordinal, today,
                                          out)
                out["trope_actions"].append(act)
            for obs in triggers:
                act = self._observe_trigger(work, obs, independent,
                                            ordinal, today, out)
                out["trigger_actions"].append(act)
            if independent:
                out["expired_this_run"] = self._expire_absent(
                    work, ordinal)
            out["trapped_total"] = sum(
                1 for e in work["claims"].values()
                if e["state"] == "staged")
            self.save()
            return out

    def _resolve_trope_entry(self, work, obs):
        """Find (entry, key, form_changed) for a trope observation,
        folding a name-keyed entry into its catalog-id entry when the
        claim now resolves (union of ordinals — exact, never summed).
        Creates nothing; returns (None, key, False) when unsighted."""
        name = obs.get("name") or ""
        cat = obs.get("catalog_id")
        key_name = staging_claim_key("trope", name=name)
        if not cat:
            return work["claims"].get(key_name), key_name, False
        key_id = staging_claim_key("trope", name=name, catalog_id=cat)
        claims = work["claims"]
        entry = claims.get(key_id)
        name_entry = claims.get(key_name)
        if name_entry is not None:
            if entry is None:
                # The entry MOVES to the id key; it was always one
                # claim, so staged_ever does not change.
                entry = name_entry
                claims[key_id] = entry
                del claims[key_name]
            else:
                # Two entries were one claim sighted under two keys.
                self._fold_entry_into(entry, name_entry)
                del claims[key_name]
                work["staged_ever"] -= 1
        key = key_id or key_name
        entry = claims.get(key)
        form_changed = False
        if entry is not None and key_id:
            forms = {_tnorm(f) for f in entry["name_forms"]}
            form_changed = _tnorm(name) not in forms
        return entry, key, form_changed

    def _record_sighting(self, work, entry, ordinal, today, obs,
                         name):
        if ordinal not in entry["sightings"]:
            entry["sightings"].append(ordinal)
            entry["sightings"].sort()
            recorded = True
        else:
            recorded = False
        entry["last_seen"] = today
        if name and _tnorm(name) not in {
                _tnorm(f) for f in entry["name_forms"]}:
            entry["name_forms"].append(name)
        return recorded

    @staticmethod
    def _persistence_stamp(entry, via):
        """The OC-7 stamp a promoted claim's shipped row carries:
        how many independent sightings earned the ship, the
        mechanism, and — since fix-queue batch 3 item 3 — WHICH runs
        sighted it (`sighting_runs`: the entry's sighting ordinals).
        The count alone evaporated at the reviewer's desk: a queue
        row showed only the claim's own evidence, with the
        persistence signal nowhere in it. Per-run CHAPTER support
        cannot ride along — the entry retains no per-run chapter
        lists (only best_chapters, a max across sightings); the
        row's evidence.chapters carries the shipping run's support,
        and sighting_runs names the runs to compare it against."""
        return {"sightings": len(entry["sightings"]), "via": via,
                "sighting_runs": list(entry["sightings"])}

    def _promote(self, work, entry, ordinal, via, form_changed, out,
                 display):
        entry["state"] = "promoted"
        entry["promoted_run"] = ordinal
        entry["promoted_via"] = via
        entry["promoted_form_changed"] = bool(form_changed)
        item = {"key": None, "display": display or entry["display"],
                "via": via, "sightings": len(entry["sightings"])}
        if form_changed:
            item["form_changed"] = True
        out["promoted"].append(item)
        return item

    def _observe_trope(self, work, obs, auto_min, independent, ordinal,
                       today, out):
        name = obs.get("name") or ""
        n_ch = obs.get("n_ch") or 0
        entry, key, form_changed = self._resolve_trope_entry(work, obs)
        if entry is None:
            if not independent or n_ch >= auto_min:
                # Non-independent runs create no entries (the run is
                # a continuation); auto-band claims never stage.
                return {"action": "ship", "key": None, "stamp": None,
                        "form_changed": False}
            entry = self._new_claim("trope", name, today)
            entry["best_chapters"] = n_ch
            work["claims"][key] = entry
            work["staged_ever"] += 1
            if self._record_sighting(work, entry, ordinal, today,
                                     obs, name):
                out["sightings_recorded"] += 1
            out["staged"].append(
                {"key": key, "display": name, "class": "trope",
                 "sightings": len(entry["sightings"])})
            return {"action": "hold", "key": key, "stamp": None,
                    "form_changed": False}
        # Existing entry.
        if independent:
            if self._record_sighting(work, entry, ordinal, today,
                                     obs, name):
                out["sightings_recorded"] += 1
            entry["best_chapters"] = max(entry["best_chapters"], n_ch)
        else:
            entry["last_seen"] = today
        if entry["state"] == "promoted":
            stamp = None
            if n_ch < auto_min:
                # Gate-band ship explained by earned standing alone:
                # the stamp is how a reviewer sees that (OC-7).
                stamp = self._persistence_stamp(
                    entry, entry["promoted_via"])
            return {"action": "ship", "key": key, "stamp": stamp,
                    "form_changed": False}
        # Staged entry: promotion rules (independent sightings only;
        # a non-independent run adds no sighting, so nothing new can
        # promote — the checks below simply don't fire for it because
        # len(sightings) did not change... except support: a resumed
        # run re-derives the same n_ch its original run saw, which
        # already had its chance; gate on independent explicitly).
        if independent and n_ch >= auto_min:
            item = self._promote(work, entry, ordinal, "support",
                                 form_changed, out, name)
            item["key"] = key
            return {"action": "ship", "key": key, "stamp": None,
                    "form_changed": form_changed}
        if independent and entry.get("evidence_grade") == "strong":
            # Promotion rule 4 (Option G, OC-5): evidence recorded
            # by an EARLIER run's retrieval, evaluated here at the
            # one promotion decision point. This run's retrieval
            # cannot fire it — recording happens after this observe
            # in the pipeline (the G2 lag is structural, not a
            # delay loop). Strong support only: >=2 distinct
            # chapters, the same multiplicity persistence demands;
            # single-chapter support records evidence but never
            # promotes. Evidence outranks persistence when both
            # qualify — the trigger path's precedent in
            # _observe_trigger (evidence arrival before the
            # persistence rule) — because the recorded passages are
            # the more specific signal, and the OC-7 stamp must
            # name the mechanism that earned the ship.
            item = self._promote(work, entry, ordinal, "evidence",
                                 form_changed, out, name)
            item["key"] = key
            stamp = self._persistence_stamp(entry, "evidence")
            return {"action": "ship", "key": key, "stamp": stamp,
                    "form_changed": form_changed}
        if independent and len(entry["sightings"]) >= 2:
            item = self._promote(work, entry, ordinal, "persistence",
                                 form_changed, out, name)
            item["key"] = key
            stamp = self._persistence_stamp(entry, "persistence")
            return {"action": "ship", "key": key, "stamp": stamp,
                    "form_changed": form_changed}
        out["staged"].append(
            {"key": key, "display": name, "class": "trope",
             "sightings": len(entry["sightings"])})
        return {"action": "hold", "key": key, "stamp": None,
                "form_changed": False}

    def record_trope_evidence(self, work_key, name, catalog_id,
                              grade):
        """Option G (design §6): record one run's retrieved evidence
        on a STAGED trope entry — evidence_ever plus the support
        grade — so the NEXT run's observe can evaluate promotion
        rule 4. Recording is all this does: promotion decisions
        read recorded state at observe time, never the current
        run's in-flight retrieval (amendment G2). Strong is sticky
        (a later single-grade recording never downgrades it).
        Returns True when an entry was updated; a missing or
        already-promoted entry records nothing."""
        if not self.enabled or grade not in ("strong", "single"):
            return False
        with self._lock:
            work = self.data["works"].get(work_key)
            if work is None:
                return False
            entry, _key, _fc = self._resolve_trope_entry(
                work, {"name": name, "catalog_id": catalog_id})
            if entry is None or entry.get("state") != "staged":
                return False
            entry["evidence_ever"] = True
            if grade == "strong" \
                    or entry.get("evidence_grade") not in (
                        "strong", "single"):
                entry["evidence_grade"] = grade
            self.save()
            return True

    def _observe_trigger(self, work, obs, independent, ordinal, today,
                         out):
        warning = obs.get("warning") or ""
        has_ev = bool(obs.get("has_evidence"))
        key = staging_claim_key("trigger", warning=warning)
        entry = work["claims"].get(key)
        if entry is None:
            if not independent or has_ev:
                # Evidenced triggers never stage; non-independent
                # runs create no entries.
                return {"action": "ship", "key": None, "stamp": None,
                        "form_changed": False}
            entry = self._new_claim("trigger", warning, today)
            entry["evidence_ever"] = False
            work["claims"][key] = entry
            work["staged_ever"] += 1
            if self._record_sighting(work, entry, ordinal, today,
                                     obs, warning):
                out["sightings_recorded"] += 1
            out["staged"].append(
                {"key": key, "display": warning, "class": "trigger",
                 "sightings": len(entry["sightings"])})
            return {"action": "hold", "key": key, "stamp": None,
                    "form_changed": False}
        if independent:
            if self._record_sighting(work, entry, ordinal, today,
                                     obs, warning):
                out["sightings_recorded"] += 1
        else:
            entry["last_seen"] = today
        entry["evidence_ever"] = entry["evidence_ever"] or has_ev
        if entry["state"] == "promoted":
            stamp = None
            if not has_ev:
                stamp = self._persistence_stamp(
                    entry, entry["promoted_via"])
            return {"action": "ship", "key": key, "stamp": stamp,
                    "form_changed": False}
        if independent and has_ev:
            item = self._promote(work, entry, ordinal, "evidence",
                                 False, out, warning)
            item["key"] = key
            return {"action": "ship", "key": key, "stamp": None,
                    "form_changed": False}
        if independent and len(entry["sightings"]) >= 2:
            item = self._promote(work, entry, ordinal, "persistence",
                                 False, out, warning)
            item["key"] = key
            stamp = self._persistence_stamp(entry, "persistence")
            return {"action": "ship", "key": key, "stamp": stamp,
                    "form_changed": False}
        out["staged"].append(
            {"key": key, "display": warning, "class": "trigger",
             "sightings": len(entry["sightings"])})
        return {"action": "hold", "key": key, "stamp": None,
                "form_changed": False}

    def _expire_absent(self, work, ordinal):
        """Expire staged entries unseen for 3 completed runs of this
        work. Absence evidence, not the clock: a never-reprocessed
        book accrues no absences and its claims wait, visibly."""
        n_expired = 0
        for key, entry in list(work["claims"].items()):
            if entry["state"] != "staged":
                continue
            last = max(entry["sightings"]) if entry["sightings"] else 0
            if ordinal - last >= _STAGING_EXPIRE_ABSENCES:
                work["expired_recent"].append(
                    {"key": key, "display": entry["display"],
                     "class": entry["class"], "expired_run": ordinal,
                     "sightings": len(entry["sightings"])})
                del work["claims"][key]
                n_expired += 1
        while len(work["expired_recent"]) > _STAGING_EXPIRED_CAP:
            work["expired_recent"].pop(0)
            work["expired_dropped"] = work.get("expired_dropped", 0) + 1
        return n_expired

    def consume_adoptions(self):
        """Return all pending adoption records and clear them (the
        trapped report lists each adoption once)."""
        with self._lock:
            out = []
            for key, w in self.data["works"].items():
                for rec in w.get("adoptions", []):
                    out.append({"work_key": key, **rec})
                w["adoptions"] = []
            if out:
                self.save()
            return out


def staging_report_data(state, today=None):
    """Pure read model over a StagingState for --staging-report and
    the dashboard: per-work buckets that must satisfy
    staged_ever = promoted + still_staged + expired, with the
    difference surfaced as `unaccounted` (printed; must be 0)."""
    today = today or _staging_today()
    today_ord = _staging_day(today)
    works_out = []
    totals = {"works": 0, "staged_ever": 0, "promoted": 0, "staged": 0,
              "expired": 0, "form_changed_promotions": 0}
    unaccounted = 0
    for key in sorted(state.data.get("works", {})):
        w = state.data["works"][key]
        claims_out = []
        n_promoted = n_staged = 0
        fc_promotions = 0
        for ckey in sorted(w["claims"]):
            e = w["claims"][ckey]
            if e["state"] == "promoted":
                n_promoted += 1
                if e.get("promoted_form_changed"):
                    fc_promotions += 1
            else:
                n_staged += 1
            first = _staging_day(e.get("first_seen"))
            last = _staging_day(e.get("last_seen"))
            forms = {_tnorm(f) for f in e.get("name_forms", [])}
            claims_out.append({
                "key": ckey, "display": e["display"],
                "class": e["class"], "state": e["state"],
                "sightings": list(e["sightings"]),
                "sightings_count": len(e["sightings"]),
                "best_chapters": e["best_chapters"],
                "first_seen": e.get("first_seen"),
                "last_seen": e.get("last_seen"),
                "age_days": (today_ord - first)
                            if (today_ord and first) else 0,
                "stale": bool(
                    e["state"] == "staged" and today_ord and last
                    and today_ord - last >= _STAGING_STALE_DAYS),
                "forms_differ": len(forms) > 1,
                "promoted_via": e.get("promoted_via"),
                "promoted_form_changed": bool(
                    e.get("promoted_form_changed")),
            })
        n_expired = len(w["expired_recent"]) \
            + w.get("expired_dropped", 0)
        w_unacc = w["staged_ever"] - (n_promoted + n_staged
                                      + n_expired)
        unaccounted += w_unacc
        works_out.append({
            "key": key, "work_id": w.get("work_id"),
            "title": w.get("title", ""), "author": w.get("author", ""),
            "runs_completed": w["runs_completed"],
            "staged_ever": w["staged_ever"], "promoted": n_promoted,
            "staged": n_staged, "expired": n_expired,
            "expired_retained": len(w["expired_recent"]),
            "unaccounted": w_unacc,
            "form_changed_promotions": fc_promotions,
            "claims": claims_out,
            "expired_recent": list(w["expired_recent"]),
            "adoptions": list(w.get("adoptions", [])),
        })
        totals["works"] += 1
        totals["staged_ever"] += w["staged_ever"]
        totals["promoted"] += n_promoted
        totals["staged"] += n_staged
        totals["expired"] += n_expired
        totals["form_changed_promotions"] += fc_promotions
    return {"works": works_out, "totals": totals,
            "unaccounted": unaccounted,
            "corrupt_at_load": state.corrupt_at_load}


# ---------------------------------------------------------------------------
# Spine §3.5: per-work verdict read-back + suppression (OC-3)
#
# The generalization of the global rejection read: for THIS work,
# the curated (confirmed/rejected) verdicts on its trope and
# trigger claims (characters excluded, OC-3), read at emission.
# Posture (cmd_verify_preview's): a FAILED read is not an empty
# set — sb() returns None on any error, and None means "unknown":
# fall back to the local cache of any age and SAY SO with the
# cache's age, or suppress nothing and say that. Read-back never
# writes to Supabase.
# ---------------------------------------------------------------------------

def _now_iso():
    from datetime import datetime
    return datetime.now().isoformat(timespec="seconds")


class VerdictSet:
    """One work's curated verdicts, keyed in staging currency:
    tropes by catalog id (`trope:id:<uuid>`), triggers by the
    normalized warning (`trigger:<warning>`)."""

    def __init__(self, work_id):
        self.work_id = work_id
        self.tropes = {}    # trope_id -> status
        self.triggers = {}  # normalized warning -> status
        self.from_cache = False
        self.fetched_at = None

    def rejected_keys(self):
        keys = {staging_claim_key("trope", catalog_id=t)
                for t, s in self.tropes.items() if s == "rejected"}
        keys |= {staging_claim_key("trigger", warning=w)
                 for w, s in self.triggers.items() if s == "rejected"}
        return keys

    def confirmed_keys(self):
        keys = {staging_claim_key("trope", catalog_id=t)
                for t, s in self.tropes.items() if s == "confirmed"}
        keys |= {staging_claim_key("trigger", warning=w)
                 for w, s in self.triggers.items() if s == "confirmed"}
        return keys

    def __len__(self):
        return len(self.tropes) + len(self.triggers)


def fetch_work_verdicts(work_id):
    """GET the work's curated trope + trigger verdicts. Returns a
    VerdictSet, or None on ANY failure (never an empty set)."""
    trope_rows = sb(
        "book_trope_claims",
        params=f"?work_id=eq.{work_id}"
               "&status=in.(confirmed,rejected)"
               "&select=trope_id,status")
    if trope_rows is None:
        return None
    trig_rows = sb(
        "book_trigger_claims",
        params=f"?work_id=eq.{work_id}"
               "&status=in.(confirmed,rejected)"
               "&select=warning,status")
    if trig_rows is None:
        return None
    vs = VerdictSet(work_id)
    for r in trope_rows:
        if r.get("trope_id") and r.get("status"):
            vs.tropes[str(r["trope_id"])] = r["status"]
    for r in trig_rows:
        if r.get("warning") and r.get("status"):
            vs.triggers[str(r["warning"]).lower().strip()] = r["status"]
    vs.fetched_at = _now_iso()
    return vs


def _log_verdict_fetch(db, ok, claims, note):
    if db is None:
        return
    try:
        with db.write_txn() as conn:
            conn.execute(
                "INSERT INTO verdict_fetches VALUES (NULL,?,?,?,?,?)",
                (_now_iso(), 1 if ok else 0, 1, claims, note))
    except Exception:
        pass


def work_verdicts(work_id, learn_dir):
    """The run's verdict source: fresh fetch (cached on success),
    else the cache of any age (with the age stated), else nothing.
    Returns (VerdictSet|None, note|None). Every attempt is logged
    in verdict_fetches when the substrate is active; the cache
    lives in verdicts_cache (substrate only — pre-migration there
    is no cache and a failed read simply suppresses nothing)."""
    db = _state_db_for(learn_dir)
    vs = fetch_work_verdicts(work_id)
    if vs is not None:
        if db is not None:
            try:
                with db.write_txn() as conn:
                    conn.execute(
                        "DELETE FROM verdicts_cache WHERE work_id=?",
                        (work_id,))
                    for tid, status in vs.tropes.items():
                        conn.execute(
                            "INSERT INTO verdicts_cache VALUES "
                            "(?,?,?,?,?)",
                            (work_id, "trope",
                             staging_claim_key("trope",
                                               catalog_id=tid),
                             status, vs.fetched_at))
                    for w, status in vs.triggers.items():
                        conn.execute(
                            "INSERT INTO verdicts_cache VALUES "
                            "(?,?,?,?,?)",
                            (work_id, "trigger",
                             staging_claim_key("trigger", warning=w),
                             status, vs.fetched_at))
            except Exception:
                pass
        _log_verdict_fetch(db, True, len(vs), "ok")
        note = (f"{len(vs)} curated verdicts read for this work "
                f"({len(vs.rejected_keys())} rejected)")
        return vs, note
    _log_verdict_fetch(db, False, 0, "fetch failed")
    if db is not None:
        rows = db.query(
            "SELECT class, claim_key, verdict, fetched_at FROM "
            "verdicts_cache WHERE work_id=?", (work_id,))
        if rows:
            vs = VerdictSet(work_id)
            vs.from_cache = True
            vs.fetched_at = max(r[3] for r in rows)
            for cls, key, verdict, _fa in rows:
                if cls == "trope":
                    vs.tropes[key[len("trope:id:"):]] = verdict
                else:
                    vs.triggers[key[len("trigger:"):]] = verdict
            return vs, (f"verdict read-back failed; using cached "
                        f"verdicts from {vs.fetched_at}")
    return None, ("verdict read-back failed and no cached verdicts "
                  "exist; nothing suppressed")


def apply_verdict_suppression(tropes, trope_conf, triggers,
                              rejected_keys, catalog_map):
    """Net A (design §3.5.2): the emission filter. Drops every
    claim whose staging-currency key a human rejected, from the
    ship lists AND their confidence map. Returns (tropes, conf,
    triggers, suppressed_keys, suppressed_names)."""
    supp_keys = set()
    supp_names = []

    def trope_key(name):
        return staging_claim_key(
            "trope", name=name,
            catalog_id=(catalog_map or {}).get(_tnorm(name)))

    kept_tropes = []
    for t in tropes:
        if trope_key(t) in rejected_keys:
            supp_keys.add(trope_key(t))
            supp_names.append(t)
        else:
            kept_tropes.append(t)
    in_t = {_tnorm(t) for t in kept_tropes}
    conf = {k: v for k, v in (trope_conf or {}).items() if k in in_t}
    kept_triggers = []
    for t in triggers:
        w = t.get("warning") if isinstance(t, dict) else str(t)
        key = staging_claim_key("trigger", warning=w)
        if key in rejected_keys:
            supp_keys.add(key)
            supp_names.append(str(w))
        else:
            kept_triggers.append(t)
    return kept_tropes, conf, kept_triggers, supp_keys, supp_names


def record_rejection_events(learn_dir, run_ref, work_key, keys):
    """The suppression counter (§3.5.3): one row per suppressed
    claim per run, counted on the union of both nets."""
    db = _state_db_for(learn_dir)
    if db is None or not keys:
        return
    with db.write_txn() as conn:
        for key in sorted(keys):
            cls = key.split(":", 1)[0]
            conn.execute(
                "INSERT INTO rejection_events VALUES (NULL,?,?,?,?,?)",
                (run_ref, work_key, cls, key, _now_iso()))


# ---------------------------------------------------------------------------
# Spine: the uncertainty queue (design §3.7 queue classes + OC-4
# binding controls). The queue holds the runs' most informative
# undecided items for labelling; packets are self-contained (the
# pair/claim, both verdicts + scores, chapter co-listing, evidence
# held, provenance) so a labeller never needs the run's context.
# ---------------------------------------------------------------------------

_UNCERTAINTY_CLASSES = ("tier-judge-disagreement", "near-threshold",
                        "family-band", "split-suspect",
                        "form-changed-promotion", "control")


def collect_uncertainty_items(result, *, book_label, work_key,
                              suspects=()):
    """The run's uncertainty items (design classes 1, 2, 4 +
    controls). Pure over the result dict."""
    items = []
    prov = {"book": book_label, "work_key": work_key}
    roster = ((result.get("chapter_data") or {}).get("roster")
              or {})

    def _roster_entry(name):
        for k, e in roster.items():
            if _tnorm(k) == _tnorm(name) \
                    or _tnorm(e.get("name") or "") == _tnorm(name):
                return e
        return {}

    def _desc(entry):
        descs = entry.get("descriptions") or []
        if descs and isinstance(descs[0], (list, tuple)) \
                and len(descs[0]) >= 2:
            return descs[0][1] or ""
        return ""

    # Class 2 (merge half): pairs near the 0.85 merge bar.
    for pm in result.get("possible_merges") or []:
        p = pm.get("p_yes")
        if p is None or abs(p - 0.85) > 0.10:
            continue
        ea, eb = _roster_entry(pm.get("name_a") or ""), \
            _roster_entry(pm.get("name_b") or "")
        both = sorted(set(ea.get("chapters") or [])
                      & set(eb.get("chapters") or []))
        items.append({
            "class": "near-threshold",
            "subject": f"merge: {pm.get('name_a')} ~ "
                       f"{pm.get('name_b')}",
            "packet": {
                "kind": "merge_pair",
                "name_a": pm.get("name_a"),
                "name_b": pm.get("name_b"),
                "p_yes": p, "reason": pm.get("reason"),
                "chapters_both": both,
                "desc_a": _desc(ea), "desc_b": _desc(eb),
                "evidence_a": "", "evidence_b": "",
                "book": book_label, "provenance": prov}})
    # Classes 1 + 2 (family half) + controls, from the family
    # validation outcomes recorded on the relationships.
    for rel in result.get("relationships") or []:
        if (rel.get("type") or "") not in _REL_FAMILY_TYPES:
            continue
        p = rel.get("validation_p")
        if p is None:
            continue
        packet = {
            "kind": "family_claim",
            "from": rel.get("from"), "to": rel.get("to"),
            "type": rel.get("type"), "judge_p": p,
            "note": rel.get("validation_note"),
            "evidence": rel.get("evidence_mined")
                        or rel.get("evidence") or "",
            "evidence_grade": rel.get("evidence_grade"),
            "provenance": prov}
        subject = (f"family: {rel.get('from')} — {rel.get('to')} "
                   f"({rel.get('type')})")
        binding = rel.get("evidence_grade") == "binding"
        bare = not (rel.get("evidence") or "").strip() and not binding
        if (binding and p < 0.30) or (p >= 0.70 and bare):
            # Class 1: the deterministic evidence tier and the
            # judge point opposite ways.
            items.append({"class": "tier-judge-disagreement",
                          "subject": subject, "packet": packet})
        elif abs(p - 0.30) <= 0.10 or abs(p - 0.70) <= 0.10:
            items.append({"class": "family-band",
                          "subject": subject, "packet": packet})
        elif p >= 0.80 or p <= 0.20:
            # A decided pair: a control for the 4:1 batch mix.
            items.append({"class": "control", "subject": subject,
                          "packet": packet})
    # Class 4: form-changed promotions (staging marker).
    for prom in ((result.get("staging") or {}).get("promoted")
                 or []):
        if prom.get("form_changed"):
            items.append({
                "class": "form-changed-promotion",
                "subject": f"claim: {prom.get('display')}",
                "packet": {"kind": "claim", "key": prom.get("key"),
                           "display": prom.get("display"),
                           "via": prom.get("via"),
                           "provenance": prov}})
    items.extend(suspects)
    return items


def roster_split_suspects(learn_dir):
    """Class 3: roster split-suspects still unresolved in a later
    run than the one that recorded them (substrate query over the
    roster payloads)."""
    db = _state_db_for(learn_dir)
    if db is None:
        return []
    items = []
    for wk, runs, payload in db.query(
            "SELECT work_key, runs_completed, payload FROM "
            "roster_works ORDER BY rowid"):
        try:
            data = json.loads(payload)
        except Exception:
            continue
        for s in data.get("suspects") or []:
            first = s.get("run")
            if first is None or (runs or 0) - first < 1:
                continue
            items.append({
                "class": "split-suspect",
                "subject": f"split suspect: {s.get('a')} ~ "
                           f"{s.get('b')} ({wk})",
                "packet": {"kind": "split_suspect", "work_key": wk,
                           "a": s.get("a"), "b": s.get("b"),
                           "reason": s.get("reason"),
                           "first_run": first,
                           "runs_completed": runs}})
    return items


def emit_uncertainty(learn_dir, run_ref, items):
    """Write queue rows (substrate only; JSON mode has no queue).
    Controls are stored with status 'control', the rest 'pending'.
    Returns rows written."""
    db = _state_db_for(learn_dir)
    if db is None or not items:
        return 0
    with db.write_txn() as conn:
        for it in items:
            conn.execute(
                "INSERT INTO uncertainty_queue VALUES "
                "(NULL,?,?,?,?,?,?,?,?,?,?)",
                (_now_iso(), run_ref,
                 (it["packet"].get("provenance") or {}).get(
                     "work_key"),
                 it["class"], it["subject"],
                 json.dumps(it["packet"], ensure_ascii=False),
                 "control" if it["class"] == "control" else "pending",
                 None, None, None))
    return len(items)


def build_labelling_batch(learn_dir, cap=20):
    """One labelling round (OC-4): pending uncertainty items mixed
    4:1 with random controls (decided pairs from real runs), cap
    ~20. Deterministic order (queue order); the mix ratio is the
    binding control, randomness of the control draw is not."""
    db = _state_db_for(learn_dir)
    if db is None:
        return []
    rows = db.query(
        "SELECT id, class, subject, packet FROM uncertainty_queue "
        "WHERE status='pending' ORDER BY id")
    controls = db.query(
        "SELECT id, class, subject, packet FROM uncertainty_queue "
        "WHERE status='control' ORDER BY id")
    n_ctl = min(len(controls), cap // 5)
    n_unc = min(len(rows), cap - n_ctl)
    picked = [rows[i] for i in range(n_unc)] \
        + [controls[i] for i in range(n_ctl)]
    return [{"id": r[0], "class": r[1], "subject": r[2],
             "packet": json.loads(r[3])} for r in picked]


def apply_uncertainty_labels(learn_dir, labels_path,
                             merge_pairs_path=None):
    """Intake: apply a labels file ([{queue_id, label, labeller}])
    to the queue; merge-pair labels also append to
    eval/merge_pairs.json in the harness's entry shape. Only
    rows still 'pending' are applied: labels files are retained
    (the portal keeps them, an operator can re-run one from a
    terminal), so a replay must land as a counted skip, never as
    a second application."""
    db = _state_db_for(learn_dir)
    if db is None:
        return {"labelled": 0, "merge_pairs_added": 0,
                "skipped": 0, "missing": [],
                "error": "no substrate"}
    labels = json.loads(
        Path(labels_path).read_text(encoding="utf-8"))
    if merge_pairs_path is None:
        merge_pairs_path = SCRIPT_DIR / "eval" / "merge_pairs.json"
    pairs = []
    if Path(merge_pairs_path).exists():
        pairs = json.loads(
            Path(merge_pairs_path).read_text(encoding="utf-8"))
    labelled = 0
    added = 0
    skipped = 0
    missing = []
    with db.write_txn() as conn:
        for lab in labels:
            qid = lab.get("queue_id", lab.get("id"))
            rows = db.query(
                "SELECT class, packet, status FROM "
                "uncertainty_queue WHERE id=?", (qid,))
            if not rows:
                missing.append(qid)
                continue
            # The pending precondition is what makes a replay
            # harmless: without it, re-applying a retained file
            # appended a duplicate merge pair and overwrote the
            # first ruling's label and stamp. A row already
            # labelled (or a control, or any non-pending state)
            # is skipped, not re-decided.
            if rows[0][2] != "pending":
                skipped += 1
                continue
            conn.execute(
                "UPDATE uncertainty_queue SET status='labelled', "
                "label=?, labelled_by=?, labelled_at=? WHERE id=?",
                (lab.get("label"), lab.get("labeller"),
                 _now_iso(), qid))
            labelled += 1
            packet = json.loads(rows[0][1])
            if packet.get("kind") == "merge_pair" \
                    and lab.get("label") in ("same", "different"):
                pairs.append({
                    "name_a": packet.get("name_a"),
                    "name_b": packet.get("name_b"),
                    "label": lab["label"],
                    "book": packet.get("book")
                            or (packet.get("provenance") or {})
                            .get("book"),
                    "desc_a": packet.get("desc_a") or "",
                    "desc_b": packet.get("desc_b") or "",
                    "evidence_a": packet.get("evidence_a") or "",
                    "evidence_b": packet.get("evidence_b") or "",
                    "source": "uncertainty queue (spine)"})
                added += 1
    if added:
        with open(merge_pairs_path, "w", encoding="utf-8") as f:
            json.dump(pairs, f, indent=1, ensure_ascii=False)
    return {"labelled": labelled, "merge_pairs_added": added,
            "skipped": skipped, "missing": missing}


def cmd_apply_uncertainty_labels(learn_dir, labels_path):
    rep = apply_uncertainty_labels(learn_dir, labels_path)
    if rep.get("error"):
        print(f"  --apply-uncertainty-labels: {rep['error']}")
        return
    detail = (f"{rep['merge_pairs_added']} merge pair(s) appended "
              f"to eval/merge_pairs.json")
    if rep["missing"]:
        detail += f"; unknown queue ids: {rep['missing']}"
    if rep.get("skipped"):
        # A replay is an operator accident, not a failure: the
        # run still succeeds, it just says what it declined to
        # re-apply.
        detail += f"; {rep['skipped']} skipped (already applied)"
    print(f"  Uncertainty labels applied: {rep['labelled']} "
          f"({detail})")


def staging_observe_result(parts, state, *, independent):
    """Option F seam helper (design section 5): observe one completed
    run's stageable claims and compute the ship set. Called ONCE per
    run from process_file_v2; result["tropes"]/["triggers"] become
    the returned ship set and every downstream consumer inherits the
    split.

    The pre-staging hard filters run here for the gated candidates,
    exactly as they do for any claim: rejection learning is applied
    with the pipeline's own formula confidence (the gate block applied
    it to the ship candidates), so a claim the filter drops is never
    observed and never staged. Denylisted candidates never reach this
    helper at all (the gate block's split already excluded them).

    parts keys: work_key, work_id, title, author, isbn, auto_min,
    trope_auto, trope_gated, trope_counts, trope_ship, trope_conf,
    catalog_map, triggers.
    Returns {ship_tropes, trope_conf, ship_triggers, marker,
    trope_persistence, trigger_persistence}."""
    counts = parts.get("trope_counts") or {}
    cat_map = parts.get("catalog_map") or {}
    gated = list(parts.get("trope_gated") or [])
    if gated:
        _gconf = {_tnorm(c): round(
            min(0.9, 0.55 + 0.1 * counts.get(_tnorm(c), 1)), 2)
            for c in gated}
        gated, _gconf, _nf = _apply_trope_rejections(
            gated, _gconf, _learn())
    obs_tropes = [{"name": c,
                   "n_ch": counts.get(_tnorm(c), 1),
                   "catalog_id": cat_map.get(_tnorm(c))}
                  for c in list(parts.get("trope_auto") or []) + gated]
    triggers_in = list(parts.get("triggers") or [])
    obs_triggers = []
    for t in triggers_in:
        if isinstance(t, dict):
            obs_triggers.append({
                "warning": t.get("warning") or "",
                "has_evidence": bool(t.get("evidence"))})
        else:
            obs_triggers.append({"warning": str(t),
                                 "has_evidence": False})
    out = state.observe_work(
        work_key=parts["work_key"], work_id=parts.get("work_id"),
        title=parts.get("title", ""), author=parts.get("author", ""),
        isbn=parts.get("isbn"), tropes=obs_tropes,
        triggers=obs_triggers, auto_min=parts.get("auto_min", 3),
        independent=independent)
    acts = {}
    for obs, act in zip(obs_tropes, out["trope_actions"]):
        acts[_tnorm(obs["name"])] = act
    ship_src = list(parts.get("trope_ship") or [])
    ship_tropes = [t for t in ship_src
                   if (acts.get(_tnorm(t)) or {}).get("action")
                   == "ship"]
    in_ship = {_tnorm(t) for t in ship_tropes}
    for c in list(parts.get("trope_auto") or []) + gated:
        if _tnorm(c) not in in_ship \
                and (acts.get(_tnorm(c)) or {}).get("action") == "ship":
            ship_tropes.append(c)
            in_ship.add(_tnorm(c))
    conf = {k: v for k, v in (parts.get("trope_conf") or {}).items()
            if k in in_ship}
    for t in ship_tropes:
        k = _tnorm(t)
        if k not in conf:
            # A claim shipping via promotion carries the pipeline's
            # own formula confidence for its support — never boosted,
            # and identical to what a gate "yes" would have given it.
            conf[k] = round(min(0.9, 0.55 + 0.1
                                * counts.get(k, 1)), 2)
    trope_persistence = {}
    for obs, act in zip(obs_tropes, out["trope_actions"]):
        if act.get("stamp"):
            trope_persistence[_tnorm(obs["name"])] = act["stamp"]
    ship_triggers = []
    trigger_persistence = {}
    for t, act in zip(triggers_in, out["trigger_actions"]):
        if act.get("action") == "ship":
            ship_triggers.append(t)
            if act.get("stamp"):
                w = t.get("warning") if isinstance(t, dict) else str(t)
                trigger_persistence[str(w).lower()] = act["stamp"]
    # Spine §3.5.2, net B (amendment A3): a claim staged in run N
    # and human-rejected before run N+1 must not ship in N+1 via
    # promotion. The observe above already decided this run's ship
    # set, promotion included; the verdict set drops rejected
    # claims from it HERE, inside the seam, so no caller can
    # re-ship them. The sighting itself stays recorded — the store
    # is an observation log; suppression governs emission only.
    suppressed_keys = set()
    suppressed_names = []
    _vrej = parts.get("verdict_rejected") or set()
    if _vrej:
        _key_of = {}
        for obs, act in zip(obs_tropes, out["trope_actions"]):
            if act.get("key"):
                _key_of[_tnorm(obs["name"])] = act["key"]
        _kept = []
        for t in ship_tropes:
            _k = _key_of.get(_tnorm(t))
            if _k in _vrej:
                suppressed_keys.add(_k)
                suppressed_names.append(t)
            else:
                _kept.append(t)
        ship_tropes = _kept
        _in = {_tnorm(t) for t in ship_tropes}
        conf = {k: v for k, v in conf.items() if k in _in}
        trope_persistence = {k: v for k, v in
                             trope_persistence.items() if k in _in}
        _tkey_of = {}
        for t_in, act in zip(triggers_in, out["trigger_actions"]):
            if act.get("key"):
                _w = t_in.get("warning") if isinstance(t_in, dict) \
                    else str(t_in)
                _tkey_of[str(_w)] = act["key"]
        _kept_tr = []
        for t in ship_triggers:
            _w = t.get("warning") if isinstance(t, dict) else str(t)
            _k = _tkey_of.get(str(_w))
            if _k in _vrej:
                suppressed_keys.add(_k)
                suppressed_names.append(str(_w))
            else:
                _kept_tr.append(t)
        ship_triggers = _kept_tr
        trigger_persistence = {
            k: v for k, v in trigger_persistence.items()
            if staging_claim_key("trigger", warning=k) not in _vrej}
    marker = {"staged": out["staged"], "promoted": out["promoted"],
              "trapped_total": out["trapped_total"],
              "expired_this_run": out["expired_this_run"],
              "sightings_recorded": out["sightings_recorded"],
              "trapped_store_total":
                  staging_report_data(state)["totals"]["staged"]}
    return {"ship_tropes": ship_tropes, "trope_conf": conf,
            "ship_triggers": ship_triggers, "marker": marker,
            "trope_persistence": trope_persistence,
            "trigger_persistence": trigger_persistence,
            "suppressed_keys": suppressed_keys,
            "suppressed_names": suppressed_names}


def _staging_report_text(state, today=None, data=None):
    """The trapped report (design section 6 of the spec's reporting
    surface): every staged claim named with its sightings and best
    support, promotions with their via, form-changed promotions on
    their own line (OC-6), expiries and adoptions listed, and the
    accounting identity closed in the open. Pure over the read
    model."""
    if data is None:
        data = staging_report_data(state, today=today)
    lines = ["Staging report (local staging store):"]
    if data["corrupt_at_load"]:
        lines.append(
            "  WARNING: staging.json failed to load and the store "
            "started EMPTY (original preserved as a .corrupt backup). "
            "Sightings were reset — store loss delays promotion, it "
            "never causes one.")
    t = data["totals"]
    if not data["works"]:
        lines.append("  Nothing trapped: the staging store is empty.")
    lines.append(
        f"  Totals: {t['works']} work(s), {t['staged_ever']} claim(s) "
        f"ever staged, {t['promoted']} promoted, {t['staged']} still "
        f"staged, {t['expired']} expired")
    for w in data["works"]:
        lines.append(
            f"  {w['title'] or w['key']} by {w['author'] or '?'} "
            f"[{w['key']}] — {w['runs_completed']} completed run(s)")
        for c in w["claims"]:
            if c["state"] == "staged":
                stale = " STALE" if c["stale"] else ""
                lines.append(
                    f"    STAGED {c['class']}: {c['display']} — "
                    f"sightings {c['sightings_count']}, best support "
                    f"{c['best_chapters']} ch, last seen "
                    f"{c['last_seen']}{stale}")
        for c in w["claims"]:
            if c["state"] == "promoted":
                fc = (" [name form changed between sightings]"
                      if c["promoted_form_changed"] else "")
                lines.append(
                    f"    PROMOTED {c['class']}: {c['display']} "
                    f"(via {c['promoted_via']}){fc}")
        if w["form_changed_promotions"]:
            lines.append(
                f"    Form-changed promotions: "
                f"{w['form_changed_promotions']}")
        for rec in w["expired_recent"]:
            lines.append(
                f"    EXPIRED {rec['class']}: {rec['display']} "
                f"(sightings {rec['sightings']})")
        for ad in w["adoptions"]:
            lines.append(
                f"    ADOPTED: {ad['claims_moved']} claim(s) from "
                f"{ad['from_key']}")
    lines.append(
        f"  UNACCOUNTED: {data['unaccounted']} (must be 0: "
        f"staged_ever = promoted + still staged + expired)")
    return "\n".join(lines)


def cmd_staging_report(as_json=False, learn_dir=None, state=None):
    """Print the trapped report (for --staging-report). Adoptions are
    listed once: they are consumed after being reported, so the next
    report does not repeat them."""
    if state is None:
        state = StagingState(learn_dir=learn_dir, enabled=True)
    data = staging_report_data(state)
    text = None if as_json else _staging_report_text(state, data=data)
    adoptions = state.consume_adoptions()
    if as_json:
        data["adoptions"] = adoptions
        print(json.dumps(data, ensure_ascii=False, indent=1))
    else:
        print(text)


# ---------------------------------------------------------------------------
# Option G — targeted evidence retrieval for trope/trigger claims
# (design: eval/g-evidence-design.md; user-approved open choices
# OC-1..OC-7 as amended, Advisor amendments G1-G5, Trope Review seat
# amendments A/B). Doctrine, binding on everything in this section:
# retrieval finds passages; it does not manufacture support. Every
# attached passage is a literal span of the book's own text, produced
# by the retriever and re-verified before attach; a passage attaches
# only when the local-model judge rules it "supports" (depiction,
# not topic). G never raises a claim's confidence, never drops a
# claim, and never draws on the decision-model budget — the judge
# is the pipeline's local model, batched like the trope gate.
# ---------------------------------------------------------------------------

_EVIDENCE_METHOD = "targeted-v1"
_EVIDENCE_WINDOW_CHARS = 600     # attached-passage cap (OC-3)
_EVIDENCE_MAX_PASSAGES = 3       # attached passages per claim (OC-3)
_EVIDENCE_JUDGE_BATCH = 10       # claims per judge call (design §4)
_EVIDENCE_MAX_CLAIMS = 250       # per-book claim cap (design §7)
_EVIDENCE_MAX_WINDOWS = 5000     # per-book embedded-window cap (§7)
_EVIDENCE_STOPWORDS = frozenset({
    "the", "a", "an", "and", "or", "of", "to", "in", "on", "at", "by",
    "for", "with", "from", "as", "is", "are", "was", "were", "be",
    "been", "it", "its", "this", "that", "these", "those", "who",
    "whom", "when", "where", "while", "into", "over", "under",
    "about", "after", "before", "their", "they", "them", "then",
    "than", "but", "not", "no", "yes", "one", "two", "all", "any",
})


def _evidence_tokens(text):
    """Content tokens for the lexical prefilter: lowercase alpha
    tokens of length >= 3, minus a small stopword set. One tokenizer
    for query terms and window text alike, so the prefilter compares
    like with like."""
    return {t for t in re.findall(r"[a-z][a-z0-9']*",
                                  (text or "").lower())
            if len(t) >= 3 and t not in _EVIDENCE_STOPWORDS}


def _evidence_stem(tok):
    """Light suffix stem for prefilter matching, applied to both
    sides alike: 'betrayal', 'betrays' and 'betrayed' must all meet
    at 'betray', or the recall-oriented prefilter silently drops
    depicting windows whose only query-term hit is a morphological
    variant. Precision is not this stage's job (rank + judge are);
    a missed window is unrecoverable downstream."""
    for suf in ("ingly", "edly", "ing", "ed", "es", "al", "s"):
        if tok.endswith(suf) and len(tok) - len(suf) >= 4:
            return tok[:-len(suf)]
    return tok


def evidence_query_terms(name, description=None):
    """Lexical-prefilter terms for a claim (design §3 stage 1):
    content tokens from the claim name, plus — for catalog-mapped
    claims — content tokens from the catalog description."""
    terms = _evidence_tokens(name)
    if description:
        terms |= _evidence_tokens(description)
    return terms


def evidence_query_text(name, description=None, summaries=None):
    """The embedding query for a claim, in a deliberately chosen
    text shape (design §3 stage 2). Mapped claims embed in the
    catalog's own shape — "name: description" (EMBED_TEXT_FORMAT) —
    never as a bare name: cosine against prose windows must measure
    trope presence, not name-mention. Unmapped claims (OC-7) use
    the name plus the gate's own summaries of the claim's support
    chapters, the richest honest description available."""
    if description:
        return f"{name}: {description}"
    if summaries:
        joined = " ".join(s.strip() for s in summaries if s and s.strip())
        if joined:
            return f"{name}: {joined}"
    return name or ""


def _sentence_spans(text):
    """(start, end) offsets of the sentences _split_sentences would
    return. Sentences are verbatim substrings; offsets are located
    by a forward scan, so a repeated sentence resolves to successive
    occurrences. The offsets are provenance (Trope amendment A);
    the spans themselves are always literal slices."""
    spans = []
    pos = 0
    for piece in re.split(r"(?<=[.!?])\s+", text or ""):
        s = piece.strip()
        if not s:
            continue
        start = text.find(s, pos)
        if start == -1:
            continue
        spans.append((start, start + len(s)))
        pos = start + len(s)
    return spans


def _evidence_windows(text):
    """Sentence-anchored candidate windows over one chapter's text:
    greedy runs of whole sentences up to _EVIDENCE_WINDOW_CHARS,
    overlapping by one sentence when a window holds three or more
    (a passage straddling a boundary is still whole somewhere). A
    single sentence longer than the cap is hard-cut at the cap —
    still a literal span. Every window is text[offset:offset+len],
    an exact substring of the chapter."""
    spans = _sentence_spans(text)
    windows = []
    prev = None
    i = 0
    while i < len(spans):
        start = spans[i][0]
        j = i
        while j + 1 < len(spans) \
                and spans[j + 1][1] - start <= _EVIDENCE_WINDOW_CHARS:
            j += 1
        end = spans[j][1]
        if end - start > _EVIDENCE_WINDOW_CHARS:
            end = start + _EVIDENCE_WINDOW_CHARS
        # A window fully contained in its predecessor (the overlap
        # tail at a chapter's end) adds no new span — its text is
        # already covered, and as a standalone candidate its brevity
        # would game the cosine rank.
        if prev is None or start < prev[0] or end > prev[1]:
            windows.append({"offset": start, "text": text[start:end]})
            prev = (start, end)
        n_sent = j - i + 1
        i += (n_sent - 1) if n_sent >= 3 else n_sent
    return windows


def _resolve_support_chapters(refs, chapters):
    """Resolve a claim's support-chapter references to chapter
    dicts. References arrive as chapter LABELS from the reduce's
    trope_chapters map, or as chapter INDICES from the seam's
    fallback construction; both resolve, unknown refs are skipped,
    order follows the refs, duplicates collapse."""
    by_label = {c.get("label"): c for c in chapters}
    by_index = {c.get("index"): c for c in chapters}
    out, seen = [], set()
    for ref in refs or []:
        ch = None
        if isinstance(ref, str) and ref in by_label:
            ch = by_label[ref]
        elif ref in by_index:
            ch = by_index[ref]
        elif isinstance(ref, str) and ref.isdigit() \
                and int(ref) in by_index:
            ch = by_index[int(ref)]
        if ch is not None and id(ch) not in seen:
            seen.add(id(ch))
            out.append(ch)
    return out


def _select_judge_candidates(candidates, limit=_EVIDENCE_MAX_PASSAGES):
    """The windows the judge sees for a claim (design §3/§4): the
    top `limit` by score, chosen with a distinct-chapter preference
    — the best window per chapter first, then fillers by score — so
    three windows from one paragraph cannot impersonate book-wide
    support at the judging stage either."""
    picked, picked_keys, seen_ch = [], set(), set()
    for p in candidates:
        if len(picked) >= limit:
            break
        if p["chapter"] not in seen_ch:
            picked.append(p)
            picked_keys.add((p["chapter"], p["offset"]))
            seen_ch.add(p["chapter"])
    for p in candidates:
        if len(picked) >= limit:
            break
        if (p["chapter"], p["offset"]) not in picked_keys:
            picked.append(p)
            picked_keys.add((p["chapter"], p["offset"]))
    return picked


def retrieve_claim_candidates(claim, embedder, cache, floor=None,
                              window_filter=None):
    """Two-stage targeted retrieval over a claim's OWN support
    chapters (design §3): lexical prefilter, then embedding rank
    against the claim's query. No whole-book scan: if the passages
    are not in the support chapters, that absence is the finding
    (the judge stage turns it into a recorded abstention).

    claim: {"key", "name", "query_text", "terms", "support":
    [chapter dicts {"label", "index", "text"}]}. embedder(texts)
    -> [vectors] (the embed_vectors shape). cache is the per-run
    window-embedding cache (amendment G5: in-memory only, keyed by
    chapter label + window offset, shared across claims, discarded
    when the run ends — never persisted, never the catalog cache).

    Returns {"candidates": [passage, ...], "verify_failures": n}
    with passages score-ranked and shaped {"quote", "chapter",
    "chapter_index", "offset", "score"} — chapter + location
    provenance on every passage (Trope amendment A). Every returned
    span is re-verified as a literal span of its chapter before it
    may attach; a verification failure is a build bug, dropped and
    counted, never shipped."""
    if floor is None:
        floor = CONFIG.get("evidence_retrieval_floor", 0.25)
    terms = {_evidence_stem(t) for t in (claim.get("terms") or set())}
    cand = []
    for ch in claim.get("support") or []:
        for w in _evidence_windows(ch.get("text", "")):
            if window_filter is not None \
                    and not window_filter(w["text"]):
                continue
            if {_evidence_stem(t)
                    for t in _evidence_tokens(w["text"])} & terms:
                cand.append((ch, w))
    if not cand:
        return {"candidates": [], "verify_failures": 0}
    qvec = _normalize(embedder([claim["query_text"]])[0])
    missing = [(ch, w) for ch, w in cand
               if (ch.get("label"), w["offset"]) not in cache]
    if missing:
        vecs = embedder([w["text"] for _, w in missing])
        for (ch, w), v in zip(missing, vecs):
            cache[(ch.get("label"), w["offset"])] = _normalize(v)
    scored, vfails = [], 0
    for ch, w in cand:
        vec = cache.get((ch.get("label"), w["offset"]))
        if vec is None:
            continue
        score = _dot(qvec, vec)
        if score < floor:
            continue
        if not verify_evidence(w["text"], ch.get("text", "")):
            vfails += 1
            continue
        scored.append({"quote": w["text"],
                       "chapter": ch.get("label"),
                       "chapter_index": ch.get("index"),
                       "offset": w["offset"],
                       "score": round(score, 4)})
    scored.sort(key=lambda p: (-p["score"], p["chapter_index"]
                               if p["chapter_index"] is not None
                               else 0, p["offset"]))
    return {"candidates": scored, "verify_failures": vfails}


PROMPT_EVIDENCE_JUDGE = """You are checking whether passages from a book actually SHOW a claimed trope or content warning happening, for a book-catalog pipeline. Judge each passage on its own text only. Return ONLY valid JSON. No commentary, no markdown.

VERDICTS:
- "supports": the passage itself DEPICTS the claim's defining dynamic or event — a reader shown only this passage would say it is happening here.
- "adjacent": the passage is merely ABOUT the claim's neighbourhood: the topic is mentioned, discussed, remembered as backstory, hypothesised, or negated ("she would never..."), or only a single ingredient is present. A discussion of betrayal is not a betrayal scene.
- "contradicts": the passage is unrelated, or shows the claim is not happening.

Claims and passages:
{claims}

{
  "verdicts": [{"claim": 0, "passage": 0, "verdict": "supports|adjacent|contradicts"}]
}

RULES:
1. One verdict per listed passage, using the claim and passage numbers shown.
2. Judge ONLY from the passage text — never from the chapter title, the claim name alone, or the claim's plausibility elsewhere in the book.
3. When torn between "supports" and "adjacent", choose "adjacent": evidence must depict, not suggest."""


def _sanitize_evidence_judge(r):
    """Coerce the judge's raw JSON to {"verdicts": [{claim, passage,
    verdict}]} with integer indices and verdicts from the three
    classes; anything else is dropped."""
    if not isinstance(r, dict):
        return None
    verdicts = []
    for v in _list(r.get("verdicts")):
        if not isinstance(v, dict):
            continue
        try:
            ci = int(v.get("claim"))
            pi = int(v.get("passage"))
        except (TypeError, ValueError):
            continue
        verdict = _s(v.get("verdict"), 12).lower()
        if verdict in ("supports", "adjacent", "contradicts"):
            verdicts.append({"claim": ci, "passage": pi,
                             "verdict": verdict})
    return {"verdicts": verdicts}


def judge_evidence_batch(call, jobs):
    """Batched local-model support verdicts (design §4, OC-2).

    jobs: [{"key", "name", "definition", "passages": [passage]}] —
    the judge is the pipeline's own local model on the same channel
    as v2_trope_gate, batched _EVIDENCE_JUDGE_BATCH claims per call.
    It NEVER claims decision-model budget: _dm_budget_claim is not
    called anywhere on the G path (pinned by test, design §9.3).

    Returns (verdicts, failed): verdicts {key: {passage_index:
    verdict}}; failed is the set of claim keys that were not judged
    (their batch errored, or the judge returned no verdict for the
    claim at all). A claim whose batch succeeded but which is
    missing a verdict for SOME passage was judged — the missing
    passage simply does not support (fail-closed for attachment).
    Failure is fail-open: failed claims proceed with no evidence,
    counted as failed, never stamped as abstentions."""
    verdicts, failed = {}, set()
    for bi in range(0, len(jobs), _EVIDENCE_JUDGE_BATCH):
        batch = jobs[bi:bi + _EVIDENCE_JUDGE_BATCH]
        blocks = []
        for ci, job in enumerate(batch):
            head = f"CLAIM {ci}: {job['name']}"
            if job.get("definition"):
                head += f" — {job['definition']}"
            blocks.append(head)
            for pi, p in enumerate(job["passages"]):
                blocks.append(f"PASSAGE {ci}.{pi} "
                              f"(from {p['chapter']}): {p['quote']}")
        prompt = PROMPT_EVIDENCE_JUDGE.replace(
            "{claims}", "\n".join(blocks))
        out = _run_task(
            call, prompt, "", 1, 1,
            f"evidence-judge-b{bi // _EVIDENCE_JUDGE_BATCH + 1}",
            sanitize_fn=_sanitize_evidence_judge)
        if not out or not out.get("verdicts"):
            failed.update(j["key"] for j in batch)
            continue
        for v in out["verdicts"]:
            if 0 <= v["claim"] < len(batch):
                job = batch[v["claim"]]
                if 0 <= v["passage"] < len(job["passages"]):
                    verdicts.setdefault(job["key"], {})[
                        v["passage"]] = v["verdict"]
        for job in batch:
            if job["key"] not in verdicts:
                failed.add(job["key"])
    return verdicts, failed


def classify_evidence(passages, verdicts):
    """Deterministic support grade + outcome for one judged claim
    (design §4). Only "supports" passages attach; "adjacent" is a
    named, counted outcome that never attaches — adjacency is the
    laundering vector, so it must be visible to be governed.

    Returns {"outcome": "supported-strong"|"supported-single"|
    "adjacent-only"|"abstained", "support": "strong"|"single"|
    "none", "attached": [passage] (cap _EVIDENCE_MAX_PASSAGES,
    distinct-chapter preference), "chapters_with_support": n,
    "adjacent": n, "supports": n, "contradicts": n}. The judge's
    verdict rides as counts — metadata only; it never becomes a
    confidence (design §6)."""
    supports = [p for i, p in enumerate(passages)
                if verdicts.get(i) == "supports"]
    n_adjacent = sum(1 for v in verdicts.values() if v == "adjacent")
    n_contra = sum(1 for v in verdicts.values()
                   if v == "contradicts")
    chapters = {p["chapter"] for p in supports}
    if len(chapters) >= 2:
        grade = "strong"
    elif chapters:
        grade = "single"
    else:
        grade = "none"
    attached = _select_judge_candidates(
        supports, limit=_EVIDENCE_MAX_PASSAGES) if supports else []
    if supports:
        outcome = f"supported-{grade}"
    elif n_adjacent:
        outcome = "adjacent-only"
    else:
        outcome = "abstained"
    return {"outcome": outcome, "support": grade,
            "attached": attached,
            "chapters_with_support": len(chapters),
            "adjacent": n_adjacent, "supports": len(supports),
            "contradicts": n_contra}


def _trope_catalog_entries():
    """{catalog_id: {"name", "description"}} for G's query shapes,
    read with the same select trope_catalog_vectors uses. {} when
    the catalog cannot be read (no Supabase configured, fetch
    error): mapped claims then fall back to the unmapped query
    shape — weaker retrieval, never wronger claims."""
    try:
        if not CONFIG.get("supabase_url"):
            return {}
        rows = sb("tropes",
                  params="?select=id,name,description&order=id")
        return {r["id"]: {"name": r.get("name") or "",
                           "description": r.get("description") or ""}
                for r in rows or []}
    except Exception:
        return {}


def _evidence_claim_record(spec, chapters, catalog,
                           summaries_by_label):
    """Assemble one retrieval claim from a seam spec {"name",
    "support_refs", "catalog_id", "staged"}: support chapters
    resolved, query shape chosen by mapping status (design §3)."""
    name = spec.get("name") or ""
    support = _resolve_support_chapters(spec.get("support_refs"),
                                        chapters)
    entry = (catalog or {}).get(spec.get("catalog_id")) \
        if spec.get("catalog_id") else None
    if entry:
        desc = entry.get("description") or ""
        query_text = evidence_query_text(entry.get("name") or name,
                                         desc)
        terms = evidence_query_terms(name, desc)
        definition = desc
    else:
        sums = [summaries_by_label.get(ch.get("label"))
                for ch in support]
        sums = [s for s in sums if s]
        query_text = evidence_query_text(name, summaries=sums)
        terms = evidence_query_terms(name)
        definition = " ".join(sums)[:500]
    return {"key": _tnorm(name), "name": name,
            "query_text": query_text, "terms": terms,
            "support": support, "definition": definition,
            "staged": bool(spec.get("staged"))}


def _evidence_run(claims, *, call, embedder, window_filter=None,
                  stage_ctx=None):
    """The shared G engine: retrieval + judging over assembled
    claim records (see _evidence_claim_record). Returns (evidence,
    records, marker) — evidence {claim_key: [passage]}, records
    {claim_key: record}, marker the run accounting. Failure is
    fail-open and loud (design §7): an embedding failure marks the
    claim failed and trips a breaker so a dead endpoint is not
    retried per claim; a judge failure fails the batch's claims;
    nothing about any claim set changes either way. Per-claim
    records carry the outcome, the support grade (None when the
    claim was not judged), the chapters searched (Trope amendment
    B: a negative retrieval is an explicit recorded result), and
    the judge's verdict counts as metadata.

    With a stage context (corpus-design §4.2 — the retrieve
    stage's adoption), the engine partitions the claims before any
    work: a claim whose stored stage output is CURRENT (its input
    hash recomputes equal over the enumerated inputs) is reused —
    yesterday's verdict re-read, no retrieval, no judging — and
    the rest derive exactly as today, through the two-tier cache
    (§4.4), settling their outputs afterwards. Failed claims are
    never settled: a failure is not a verdict, and the next run
    must retry it, not reuse it. Without a context the engine is
    byte-for-byte the per-run computation it has always been."""
    floor = CONFIG.get("evidence_retrieval_floor", 0.25)
    cache = {}
    evidence, records = {}, {}
    totals = {"attempted": 0, "supported_strong": 0,
              "supported_single": 0, "adjacent_only": 0,
              "abstained": 0, "failed": 0, "skipped": 0}
    verify_failures = 0
    fresh_vf = {}
    jobs = []
    embed_dead = False
    specs = list(claims or [])
    reused = {}
    input_hashes = {}
    if stage_ctx is not None:
        stored = corpus_stage_outputs(stage_ctx["db"],
                                      stage_ctx["fingerprint"],
                                      "retrieve")
        for claim in specs:
            ih = _retrieve_claim_input_hash(stage_ctx, claim, floor)
            input_hashes[claim["key"]] = ih
            row = stored.get(claim["key"])
            if row is not None and row["input_hash"] == ih \
                    and isinstance(row.get("payload"), dict) \
                    and "record" in row["payload"]:
                reused[claim["key"]] = row["payload"]
        cache = _CorpusWindowCache(
            stage_ctx["db"], stage_ctx["fingerprint"],
            [ch for c in specs for ch in (c.get("support") or [])],
            stage_ctx["embed_model"], stage_ctx["embed_format"],
            writable=stage_ctx.get("writable", True))
        for key, payload in reused.items():
            rec = payload["record"]
            records[key] = rec
            if payload.get("evidence"):
                evidence[key] = payload["evidence"]
            verify_failures += payload.get("verify_failures", 0)
            totals[rec["outcome"].replace("-", "_")] += 1
    pending = [c for c in specs if c["key"] not in reused]
    for idx, claim in enumerate(pending):
        if idx >= _EVIDENCE_MAX_CLAIMS \
                or len(cache) >= _EVIDENCE_MAX_WINDOWS:
            totals["skipped"] += len(pending) - idx
            break
        key = claim["key"]
        totals["attempted"] += 1
        base = {"name": claim["name"], "staged": claim["staged"],
                "chapters_searched": [ch.get("label")
                                      for ch in claim["support"]]}
        failed_rec = {**base, "outcome": "failed", "support": None,
                      "passages": 0, "chapters_with_support": 0,
                      "adjacent": 0}
        if embed_dead:
            records[key] = failed_rec
            totals["failed"] += 1
            continue
        try:
            out = retrieve_claim_candidates(
                claim, embedder, cache, floor=floor,
                window_filter=window_filter)
        except Exception:
            embed_dead = True
            records[key] = failed_rec
            totals["failed"] += 1
            continue
        verify_failures += out["verify_failures"]
        fresh_vf[key] = out["verify_failures"]
        cands = _select_judge_candidates(out["candidates"])
        if not cands:
            records[key] = {
                **base, "outcome": "abstained", "support": "none",
                "passages": 0, "chapters_with_support": 0,
                "adjacent": 0,
                "judge": {"supports": 0, "adjacent": 0,
                          "contradicts": 0}}
            totals["abstained"] += 1
            continue
        jobs.append({"key": key, "name": claim["name"],
                     "definition": claim["definition"],
                     "passages": cands, "_base": base})
    if jobs:
        try:
            verdicts, failed = judge_evidence_batch(call, jobs)
        except Exception:
            verdicts, failed = {}, {j["key"] for j in jobs}
        for job in jobs:
            key, base = job["key"], job["_base"]
            if key in failed:
                records[key] = {
                    **base, "outcome": "failed", "support": None,
                    "passages": 0, "chapters_with_support": 0,
                    "adjacent": 0}
                totals["failed"] += 1
                continue
            cls = classify_evidence(job["passages"],
                                    verdicts.get(key, {}))
            records[key] = {
                **base, "outcome": cls["outcome"],
                "support": cls["support"],
                "passages": len(cls["attached"]),
                "chapters_with_support":
                    cls["chapters_with_support"],
                "adjacent": cls["adjacent"],
                "judge": {"supports": cls["supports"],
                          "adjacent": cls["adjacent"],
                          "contradicts": cls["contradicts"]}}
            totals[cls["outcome"].replace("-", "_")] += 1
            if cls["attached"]:
                evidence[key] = cls["attached"]
    marker = {"method": _EVIDENCE_METHOD, "floor": floor,
              "totals": totals,
              "claims": {k: r["outcome"] for k, r in records.items()},
              "verify_failures": verify_failures,
              "failed": bool(totals["attempted"])
                        and totals["failed"] == totals["attempted"]}
    if stage_ctx is not None:
        if isinstance(cache, _CorpusWindowCache):
            cache.flush()
        if stage_ctx.get("writable", True) and specs:
            # Settle the stage's full produced set: reused outputs
            # (unchanged hashes — the settle leaves their rows
            # untouched) plus this run's fresh non-failed verdicts.
            # A claim that failed, or was capped out, produces
            # nothing this run, so a stale row under its key is a
            # ghost and the settle deletes it (A4). A corpus write
            # must never fail the run (§5.2): degradation is
            # proceeding unrecorded.
            try:
                produced = {}
                for key, payload in reused.items():
                    produced[key] = {
                        "input_hash": input_hashes[key],
                        "payload": payload}
                for claim in pending:
                    key = claim["key"]
                    rec = records.get(key)
                    if rec is None or rec.get("outcome") == "failed":
                        continue
                    produced[key] = {
                        "input_hash": input_hashes[key],
                        "payload": {
                            "record": rec,
                            "evidence": evidence.get(key, []),
                            "verify_failures": fresh_vf.get(key, 0)}}
                corpus_stage_settle(
                    stage_ctx["db"], stage_ctx["fingerprint"],
                    "retrieve", stage_version=RETRIEVE_STAGE_VERSION,
                    model=stage_ctx["judge_model"], outputs=produced,
                    run_payload={"claims": len(specs)})
            except Exception:
                pass
    return evidence, records, marker


def evidence_retrieve_result(parts, chapters, *, call, embedder,
                             stage_ctx=None):
    """The trope half of the G seam (design §8): targeted retrieval
    + local-model judging for one run's confirmed trope claims —
    the ship set and the staged set alike.

    parts: {"claims": [{"name", "support_refs", "catalog_id",
    "staged"}], "catalog": {id: {"name", "description"}},
    "summaries": {chapter_label: summary}}.

    A stage context (corpus-design §4.2) makes the results stage
    outputs: current verdicts are re-read instead of re-judged, and
    fresh ones settle under the stage contract. Returns
    {"trope_evidence": {_tnorm(name): [passage]},
    "trope_retrieval": {_tnorm(name): record}, "marker": {...}} —
    plain JSON types throughout."""
    catalog = parts.get("catalog") or {}
    summaries_by_label = parts.get("summaries") or {}
    claims = [_evidence_claim_record(spec, chapters, catalog,
                                     summaries_by_label)
              for spec in list(parts.get("claims") or [])]
    evidence, records, marker = _evidence_run(
        claims, call=call, embedder=embedder, stage_ctx=stage_ctx)
    return {"trope_evidence": evidence,
            "trope_retrieval": records, "marker": marker}


def _trigger_claim_record(td, chapters):
    """Assemble one retrieval claim for an evidence-less trigger:
    the query is the warning name plus the category definition's
    depiction text where one exists (the _DECISION_TRIGGER_DEFS
    shape), over the trigger's own chapters."""
    warn = td.get("warning") or ""
    d = _DECISION_TRIGGER_DEFS.get(warn) \
        or _DECISION_TRIGGER_DEFS.get(str(warn).lower()) or ()
    depicts = d[1] if len(d) > 1 else ""
    return {"key": f"trigger:{str(warn).lower()}", "name": warn,
            "query_text": evidence_query_text(warn, depicts)
                          if depicts else warn,
            "terms": evidence_query_terms(warn, depicts),
            "support": _resolve_support_chapters(
                td.get("chapters"), chapters),
            "definition": depicts, "staged": False}


def evidence_retrieve_triggers(triggers, chapters, *, call,
                               embedder):
    """The trigger half of the G seam (design §2/§6, OC-1): runs
    BEFORE the staging seam for triggers whose extraction evidence
    list is empty — the exact set F stages. Retrieved passages pass
    the category's existing negative-regex discipline first
    (_TRIGGER_NEGATIVE_RE hits disqualify a window outright, as in
    the reduce gate), then the same retrieval + judge as tropes;
    supported passages fill the trigger's evidence list in place,
    stamped decision_gate "retrieval" so their provenance is never
    confused with extraction evidence. Severity and confidence are
    never touched, and no sighting is recorded — G is evidence,
    not occurrence; the filled list is what the staging seam's
    has_evidence then reads, so F's existing evidence-arrival
    promotion fires with no staging change.

    Returns {"trigger_retrieval": {warn_lower: record},
    "marker": partial marker (claims keyed "trigger:<warn>")}."""
    targets = [td for td in triggers or []
               if isinstance(td, dict) and not td.get("evidence")]
    claims = [_trigger_claim_record(td, chapters) for td in targets]

    # The negative-regex discipline is per category; the shared
    # engine takes one filter, so each claim's filter is applied
    # via its own single-claim run only when its category has a
    # regex — in practice _TRIGGER_NEGATIVE_RE is tiny, so claims
    # are grouped: regex categories run individually, the rest in
    # one shared run.
    records, marker = {}, None
    evidence_all = {}

    def _merge(m):
        nonlocal marker
        marker = _merge_evidence_markers(marker, m)

    plain = [c for c in claims
             if not _TRIGGER_NEGATIVE_RE.get(c["name"])]
    if plain:
        ev, recs, m = _evidence_run(plain, call=call,
                                    embedder=embedder)
        evidence_all.update(ev)
        records.update(recs)
        _merge(m)
    for c in claims:
        neg = _TRIGGER_NEGATIVE_RE.get(c["name"])
        if not neg:
            continue
        ev, recs, m = _evidence_run(
            [c], call=call, embedder=embedder,
            window_filter=lambda t, _n=neg: not _n.search(t))
        evidence_all.update(ev)
        records.update(recs)
        _merge(m)
    by_key = {c["key"]: td for c, td in zip(claims, targets)}
    out_records = {}
    for key, passages in evidence_all.items():
        td = by_key[key]
        td["evidence"] = [
            {"quote": p["quote"], "chapter": p["chapter"],
             "decision_gate": "retrieval"}
            for p in passages[:_EVIDENCE_MAX_PASSAGES]]
    for key, rec in records.items():
        out_records[key.split(":", 1)[1]] = rec
    return {"trigger_retrieval": out_records,
            "marker": marker or _empty_evidence_marker()}


def _empty_evidence_marker():
    return {"method": _EVIDENCE_METHOD,
            "floor": CONFIG.get("evidence_retrieval_floor", 0.25),
            "totals": {"attempted": 0, "supported_strong": 0,
                       "supported_single": 0, "adjacent_only": 0,
                       "abstained": 0, "failed": 0, "skipped": 0},
            "claims": {}, "verify_failures": 0, "failed": False}


def _merge_evidence_markers(a, b):
    """Combine the trigger-half and trope-half markers into the
    run's single evidence_retrieval marker (design §8): totals
    summed, per-claim outcomes merged, the run-level failed flag
    recomputed from the merged totals."""
    if a is None:
        return b
    if b is None:
        return a
    totals = {k: (a.get("totals") or {}).get(k, 0)
                 + (b.get("totals") or {}).get(k, 0)
              for k in set(a.get("totals") or {})
              | set(b.get("totals") or {})}
    return {"method": a.get("method", _EVIDENCE_METHOD),
            "floor": a.get("floor"),
            "totals": totals,
            "claims": {**(a.get("claims") or {}),
                       **(b.get("claims") or {})},
            "verify_failures": a.get("verify_failures", 0)
                               + b.get("verify_failures", 0),
            "failed": bool(totals.get("attempted"))
                      and totals.get("failed")
                          == totals.get("attempted")}


# ---------------------------------------------------------------------------
# Option B — persisted per-work roster (design: eval/b-roster-design.md).
#
# Identity is a hypothesis with provenance, never a fact the store
# asserts. A persisted link says "run N's entry X was judged the same
# person as entity E, by tier T, on this evidence" — recorded,
# reversible, and re-vetted against every later run's evidence. Names
# are observations; identity is the thing observed. Unlike F's staging
# store, this store holds authority (it can change WHO a row is
# about), so it does not claim F's delay-only failure property: a
# missing/corrupt store degrades to the stateless path (safe), and a
# loadable-but-wrong store is countered by provenance, suspension,
# anchors and the roster report — every exercise of the store's
# authority is attributed and reversible.
# ---------------------------------------------------------------------------

_ROSTER_SIZE_WARN = 5 * 1024 * 1024


class RosterVetoError(ValueError):
    """A recorded union would contradict a human NO. Raised by
    RosterStore itself (the invariant lives in the store, not in
    callers, so no future code path can re-form a vetoed identity
    by forgetting to check)."""


def roster_desc_hash(text):
    """Short hash of a run's best description for an entry/entity, so
    description continuity is checkable across runs without storing
    prose (design section 3)."""
    import hashlib as _hl
    if not text:
        return ""
    return _hl.sha1(text.encode("utf-8")).hexdigest()[:12]


def _roster_store_filename(work_key):
    """Filesystem name for a work's roster store file. The work_key
    itself is stored inside the file and is authoritative; the name
    is a deterministic sanitization (plus a hash suffix whenever
    sanitization changed anything, so distinct keys can't collide)."""
    import hashlib as _hl
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(work_key)).strip("_")
    if not safe:
        safe = "work"
    if safe != str(work_key):
        safe = f"{safe}-{_hl.sha1(str(work_key).encode()).hexdigest()[:8]}"
    return safe + ".json"


class RosterStore:
    """One work's persisted roster identity: minted entity IDs,
    name observations with provenance, first-class link records,
    curation anchors, merge tombstones and a suspension ledger.

    One JSON file per work under <learn_dir>/rosters/, persistence
    discipline copied from StagingState (F8: atomic save, loud
    corruption with .corrupt preservation, RLock). NOT a
    LearnedState file and NOT the staging file: cross-run roster
    links live and die inside this per-work store and never become
    cross-book learning (design section 7, D1 containment).
    """

    def __init__(self, learn_dir=None, work_key=None, enabled=True):
        self._lock = threading.RLock()
        self.enabled = enabled
        if learn_dir:
            base = Path(learn_dir)
        else:
            base = Path(os.path.expanduser("~")) / ".ebook-processor" \
                / "learned"
        self.dir = base / "rosters"
        self.work_key = work_key
        self._writable = True
        self._warned = False
        self._corrupt_paths = set()
        self._corrupt_seen = set()
        self.data = self._empty_data(work_key)
        if self.enabled:
            self._ensure_dir()
            if work_key is not None:
                self._load()

    @staticmethod
    def _empty_data(work_key):
        return {"version": 1, "work_key": work_key, "work_id": None,
                "title": "", "author": "", "runs_completed": 0,
                "last_run_fingerprint": None, "next_entity_seq": 1,
                "minted_total": 0, "entities": {}, "retired": {},
                "no_pairs": [], "adoptions": [],
                "suspects": [], "canonical_changes": [],
                "collisions": [], "anchor_retirements": []}

    # -- setup / persistence (StagingState's F8 pattern) --------------
    def _ensure_dir(self):
        try:
            self.dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            self._writable = False
            self._warn_once(
                f"  Roster dir not writable ({self.dir}); roster "
                "persistence disabled for this run")

    def _warn_once(self, msg):
        with self._lock:
            if self._warned:
                return
            self._warned = True
        print(msg)

    @property
    def writable(self):
        return self._writable

    @property
    def corrupt_at_load(self):
        return bool(self._corrupt_seen)

    @property
    def path(self):
        return self.dir / _roster_store_filename(self.work_key or "")

    @property
    def runs_completed(self):
        return self.data["runs_completed"]

    def _note_corrupt(self, path, err):
        """Record a roster file that failed to load and say so LOUDLY.
        The store starts EMPTY: the run degrades to the stateless path
        (today's behaviour) and says so on its face. Identity history
        is lost; correctness is not. Original bytes are preserved as a
        .corrupt backup before any overwrite."""
        path = Path(path)
        with self._lock:
            self._corrupt_paths.add(path)
            first = path.name not in self._corrupt_seen
            self._corrupt_seen.add(path.name)
        if first:
            print(f"  !! WARNING: roster store {path} could not be "
                  f"loaded ({err}); starting this work's roster store "
                  f"EMPTY (the run is stateless for this work). The "
                  f"original file will be preserved as a .corrupt "
                  f"backup before it is overwritten.")

    def _preserve_corrupt(self, path):
        path = Path(path)
        with self._lock:
            if path not in self._corrupt_paths:
                return
        try:
            if path.exists():
                dest = path.with_name(path.name + ".corrupt")
                n = 1
                while dest.exists():
                    dest = path.with_name(f"{path.name}.corrupt-{n}")
                    n += 1
                shutil.copyfile(path, dest)
                print(f"  !! Preserved corrupt roster store as {dest}")
            with self._lock:
                self._corrupt_paths.discard(path)
        except Exception as e:
            print(f"  !! WARNING: could not preserve corrupt file "
                  f"{path} ({e}); it will still be overwritten")

    def _load(self):
        db = _state_db_for(self.dir.parent)
        if db is not None:
            try:
                data = self._db_load(db)
            except Exception as e:
                self._note_corrupt(self.dir.parent / _STATE_DB_NAME, e)
                self.data = self._empty_data(self.work_key)
                return
            if data is not None:
                empty = self._empty_data(self.work_key)
                empty.update(data)
                empty["work_key"] = self.work_key
                self.data = empty
            return
        p = self.path
        if not p.exists():
            return
        try:
            with open(p, encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict) \
                    or not isinstance(data.get("entities"), dict) \
                    or not isinstance(data.get("retired"), dict):
                raise ValueError("roster store has no entity maps")
            empty = self._empty_data(self.work_key)
            empty.update(data)
            empty["work_key"] = self.work_key
            self.data = empty
        except Exception as e:
            self._note_corrupt(p, e)
            self.data = self._empty_data(self.work_key)

    # -- substrate seam (spine §3.3): one row-set per work ------------
    def _db_load(self, db):
        wk = self.work_key
        rows = db.query("SELECT payload FROM roster_works "
                        "WHERE work_key=?", (wk,))
        if not rows:
            return None
        data = json.loads(rows[0][0])
        jd = json.loads
        data["entities"] = {
            eid: jd(p) for eid, p in db.query(
                "SELECT entity_id, payload FROM roster_entities "
                "WHERE work_key=? ORDER BY rowid", (wk,))}
        data["retired"] = {
            rid: jd(p) for rid, p in db.query(
                "SELECT entity_id, payload FROM roster_retired "
                "WHERE work_key=? ORDER BY rowid", (wk,))}
        data["no_pairs"] = [jd(p) for (p,) in db.query(
            "SELECT payload FROM roster_no_pairs WHERE work_key=? "
            "ORDER BY rowid", (wk,))]
        data["adoptions"] = [jd(p) for (p,) in db.query(
            "SELECT payload FROM roster_adoptions WHERE work_key=? "
            "ORDER BY seq", (wk,))]
        data["anchor_retirements"] = [jd(p) for (p,) in db.query(
            "SELECT payload FROM roster_anchor_retirements "
            "WHERE work_key=? ORDER BY rowid", (wk,))]
        return data

    def _db_save(self, db):
        wk = self.work_key
        d = self.data
        jd = lambda o: json.dumps(o, ensure_ascii=False)
        residual = {k: v for k, v in d.items()
                    if k not in ("entities", "retired", "no_pairs",
                                 "adoptions", "anchor_retirements")}
        with db.write_txn() as conn:
            for table in ("roster_works", "roster_entities",
                          "roster_retired", "roster_no_pairs",
                          "roster_adoptions",
                          "roster_anchor_retirements"):
                conn.execute(
                    f"DELETE FROM {table} WHERE work_key=?", (wk,))
            conn.execute(
                "INSERT INTO roster_works VALUES (?,?,?,?,?,?,?,?,?)",
                (wk, d.get("work_id"), d.get("title"), d.get("author"),
                 int(d.get("runs_completed", 0)),
                 d.get("last_run_fingerprint"),
                 int(d.get("next_entity_seq", 1)),
                 int(d.get("minted_total", 0)), jd(residual)))
            for eid, e in d["entities"].items():
                conn.execute(
                    "INSERT INTO roster_entities VALUES (?,?,?,?,?)",
                    (wk, eid, e.get("status"), e.get("canonical"),
                     jd(e)))
            for rid, r in d["retired"].items():
                conn.execute(
                    "INSERT INTO roster_retired VALUES (?,?,?)",
                    (wk, rid, jd(r)))
            for pair in d["no_pairs"]:
                conn.execute(
                    "INSERT INTO roster_no_pairs VALUES (?,?,?,?,?)",
                    (wk, pair.get("a"), pair.get("b"),
                     pair.get("source"), jd(pair)))
            for i, ad in enumerate(d["adoptions"]):
                conn.execute(
                    "INSERT INTO roster_adoptions VALUES (?,?,?)",
                    (wk, i, jd(ad)))
            for r in d["anchor_retirements"]:
                conn.execute(
                    "INSERT INTO roster_anchor_retirements VALUES "
                    "(?,?,?,?)",
                    (wk, r.get("entity_id") or r.get("entity"),
                     r.get("run"), jd(r)))

    def save(self):
        """Atomic write: temp file + os.replace. No-op when not
        writable/enabled."""
        if not self._writable or not self.enabled \
                or self.work_key is None:
            return False
        with self._lock:
            db = _state_db_for(self.dir.parent)
            if db is not None:
                try:
                    self._db_save(db)
                    return True
                except Exception as e:
                    self._writable = False
                    self._warn_once(
                        f"  Roster store write failed ({e}); roster "
                        "persistence is disabled for the rest of this "
                        "run.")
                    return False
            try:
                p = self.path
                self._preserve_corrupt(p)
                tmp = p.with_suffix(p.suffix + ".tmp")
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump(self.data, f, ensure_ascii=False, indent=1)
                os.replace(tmp, p)
                try:
                    if p.stat().st_size > _ROSTER_SIZE_WARN:
                        self._warn_once(
                            f"  Roster store is large "
                            f"({p.stat().st_size} bytes); run "
                            "--roster-report to inspect it")
                except OSError:
                    pass
                return True
            except Exception as e:
                self._writable = False
                self._warn_once(
                    f"  Roster store write failed ({e}); roster "
                    "persistence disabled for this run")
                return False

    # -- entities -------------------------------------------------------
    def mint_entity(self):
        """Mint a fresh opaque entity ID. IDs are never derived from
        a name, never reused, and never deleted (a merged-away ID
        tombstones in retired with a redirect)."""
        with self._lock:
            eid = f"ent_{self.data['next_entity_seq']:04d}"
            self.data["next_entity_seq"] += 1
            self.data["minted_total"] += 1
            self.data["entities"][eid] = {
                "canonical": None, "canonical_source": None,
                "status": "active", "split_from": None, "split_into": [],
                "anchor": None, "observations": [], "links": []}
            return eid

    def get_entity(self, eid):
        return self.data["entities"].get(eid)

    def resolve_id(self, eid):
        """Follow merged_into redirects to the surviving entity ID
        (None when the ID is unknown). Split entities do not
        redirect: their successors carry the observations, so
        matching finds them directly."""
        seen = set()
        cur = eid
        while cur in self.data["retired"]:
            if cur in seen:
                return None
            seen.add(cur)
            cur = self.data["retired"][cur].get("merged_into")
        return cur if cur in self.data["entities"] else None

    def set_canonical(self, eid, name, source):
        with self._lock:
            ent = self.data["entities"][eid]
            ent["canonical"] = name
            ent["canonical_source"] = source

    # -- observations ---------------------------------------------------
    def append_observation(self, eid, obs):
        """Append one run's observation of an entity (at most one per
        entity per run; the caller mints the run ordinal via
        claim_run). Stored verbatim apart from the suspect/detached
        flags, which default to False."""
        with self._lock:
            o = dict(obs)
            o.setdefault("suspect", False)
            o.setdefault("detached", False)
            o["chapters"] = sorted(o.get("chapters") or [])
            o["aliases"] = sorted(o.get("aliases") or [])
            o["alias_keys"] = sorted(o.get("alias_keys") or [])
            self.data["entities"][eid]["observations"].append(o)
            return o

    def claim_run(self, fingerprint):
        """Claim the run ordinal for a completing run. Returns
        (ordinal, repeat): when the roster fingerprint equals the
        last completed run's, this is the SAME extraction completing
        again (resume-after-crash at the seam boundary) — the ordinal
        is reused and runs_completed does not advance. The seam's
        repeat path refreshes the run's observations in place (see
        replace_observation) instead of re-matching: the identity
        assignment from the first completion stands, so one
        extraction can never double-count or re-mint (design
        section 7)."""
        with self._lock:
            if fingerprint is not None \
                    and fingerprint == self.data["last_run_fingerprint"] \
                    and self.data["runs_completed"] > 0:
                return self.data["runs_completed"], True
            self.data["runs_completed"] += 1
            self.data["last_run_fingerprint"] = fingerprint
            return self.data["runs_completed"], False

    def replace_observation(self, eid, obs):
        """Refresh in place: replace the entity's existing
        observation for (run, form_key) with this one, or append
        when none exists. Used by the repeat-completion path."""
        with self._lock:
            ent = self.data["entities"][eid]
            ent["observations"] = [
                o for o in ent["observations"]
                if not (o.get("run") == obs.get("run")
                        and o.get("form_key") == obs.get("form_key"))]
            return self.append_observation(eid, obs)

    def run_assignments(self, ordinal):
        """{form_key: entity_id} from the observations recorded
        under a run ordinal (non-detached). The repeat path's
        identity map: which entity each form was assigned to when
        this extraction first completed."""
        out = {}
        with self._lock:
            for eid, ent in self.data["entities"].items():
                for o in ent["observations"]:
                    if o.get("run") == ordinal \
                            and not o.get("detached"):
                        out[o["form_key"]] = eid
            return out

    # -- human NO (store-level invariant) --------------------------------
    def record_no(self, form_a, form_b, source=""):
        """Record a human NO: these two name forms are NOT the same
        person. The store refuses any later union that would re-form
        this pair's identity (links, folds, merge tombstones,
        adoptions) — see union_veto."""
        a, b = norm_name(form_a), norm_name(form_b)
        if not a or not b or a == b:
            return False
        with self._lock:
            if self.has_no(a, b):
                return False
            self.data["no_pairs"].append(
                {"a": a, "b": b, "source": source or ""})
            return True

    def has_no(self, form_a, form_b):
        a, b = norm_name(form_a), norm_name(form_b)
        return any({p["a"], p["b"]} == {a, b}
                   for p in self.data["no_pairs"])

    def union_veto(self, forms_a, forms_b):
        """The recorded NO a union of these two form sets would
        contradict, or None. A union is contradicted when one side
        of a NO pair sits in each set."""
        sa = {norm_name(f) for f in forms_a if f}
        sb = {norm_name(f) for f in forms_b if f}
        for p in self.data["no_pairs"]:
            if (p["a"] in sa and p["b"] in sb) \
                    or (p["a"] in sb and p["b"] in sa):
                return p
        return None

    def _entity_form_keys(self, eid, include_detached=False):
        """Every form key an entity claims: observed primary forms,
        observed alias keys, and its canonical key. Detached
        observations (a human removed that form from this entity)
        no longer speak for it."""
        ent = self.data["entities"].get(eid)
        if ent is None:
            return set()
        keys = set()
        for o in ent["observations"]:
            if o.get("detached") and not include_detached:
                continue
            keys.add(o["form_key"])
            keys.update(o.get("alias_keys") or [])
        if ent.get("canonical"):
            keys.add(norm_name(ent["canonical"]))
        anchor = ent.get("anchor")
        if anchor:
            keys.add(norm_name(anchor["name"]))
            keys.update(norm_name(a) for a in anchor.get("aliases") or [])
        return keys

    def _check_union(self, forms_a, forms_b, what):
        veto = self.union_veto(forms_a, forms_b)
        if veto is not None:
            raise RosterVetoError(
                f"{what} refused: it would re-form an identity a human "
                f"vetoed ({veto['a']!r} is not {veto['b']!r}"
                f"{'; ' + veto['source'] if veto.get('source') else ''})")

    # -- links ------------------------------------------------------------
    def record_link(self, eid, link, entry_forms):
        """Record a cross-run link between a run entry (entry_forms:
        its form key + claimed alias keys) and an entity. Refused by
        the store itself when the union contradicts a recorded NO.
        The link record carries run, tier, state and a human-readable
        evidence string — a link with no recorded basis does not
        exist."""
        with self._lock:
            self._check_union(set(entry_forms),
                              self._entity_form_keys(eid), "link")
            rec = {"run": link.get("run"), "tier": link.get("tier"),
                   "state": link.get("state", "active"),
                   "evidence": link.get("evidence", ""),
                   "form_key": link.get("form_key")}
            self.data["entities"][eid]["links"].append(rec)
            return rec

    def suspend_link(self, eid, run, form_key, evidence):
        """Suspend the active link(s) this run's entry (form_key)
        made into the entity, and flag the observations that link
        carried as suspect (A1: a suspended link's observations stop
        voting — excluded from canonical weighting and tier-2 alias
        evidence until a human resolves them). Returns how many
        links were suspended."""
        with self._lock:
            ent = self.data["entities"].get(eid)
            if ent is None:
                return 0
            n = 0
            for link in ent["links"]:
                if link.get("run") == run \
                        and link.get("form_key") == form_key \
                        and link.get("state") == "active":
                    link["state"] = "suspended"
                    link["evidence"] = (
                        f"{link.get('evidence', '')} | suspended: "
                        f"{evidence}").strip(" |")
                    n += 1
            if n:
                self.flag_suspect_observations(eid, run, form_key)
            return n

    def suspension_ledger(self):
        """Suspended links plus the entities they touch — reported
        as its own line, OUTSIDE the ID partition (suspension is a
        link state, not an entity status; design A4)."""
        out = []
        for eid, ent in self.data["entities"].items():
            for link in ent["links"]:
                if link.get("state") == "suspended":
                    out.append({"entity": eid, "link": dict(link)})
        return out

    def flag_suspect_observations(self, eid, run, form_key):
        with self._lock:
            ent = self.data["entities"].get(eid)
            if ent is None:
                return
            for o in ent["observations"]:
                if o.get("run") == run \
                        and o.get("form_key") == form_key:
                    o["suspect"] = True

    def resolve_suspect(self, eid, form_key):
        """A human affirmed this form belongs to this entity: its
        observations vote again."""
        with self._lock:
            ent = self.data["entities"].get(eid)
            if ent is None:
                return
            for o in ent["observations"]:
                if o.get("form_key") == form_key:
                    o["suspect"] = False

    def affirm_form(self, eid, form_key):
        """--roster-link: a human asserts this form belongs to this
        entity. Its observations vote again AND speak for the entity
        again (suspect + detached cleared). Returns how many
        observations were affirmed."""
        form_key = norm_name(form_key)
        n = 0
        with self._lock:
            ent = self.data["entities"].get(eid)
            if ent is None:
                return 0
            for o in ent["observations"]:
                if o.get("form_key") == form_key:
                    o["suspect"] = False
                    o["detached"] = False
                    n += 1
            return n

    def retire_no_pairs(self, form_key, other_forms):
        """Remove recorded NOs between form_key and any of
        other_forms. Used ONLY by the human --roster-link command:
        the same authority that recorded the NO (directly or via
        --roster-unlink) explicitly reverses it for this pair set.
        Automatic paths never call this — for them a NO is final.
        Returns how many pairs were retired."""
        form_key = norm_name(form_key)
        others = {norm_name(f) for f in other_forms}
        with self._lock:
            kept, removed = [], 0
            for p in self.data["no_pairs"]:
                pair = {p["a"], p["b"]}
                if form_key in pair and pair & others \
                        and pair != {form_key}:
                    removed += 1
                else:
                    kept.append(p)
            self.data["no_pairs"] = kept
            return removed

    @classmethod
    def load_path(cls, path):
        """Load a store from an enumerated file (report commands):
        the filename is a sanitized work key, so read the content's
        own work_key — the authoritative one — and construct
        normally. Callers pre-check readability; a file whose
        content cannot be parsed is reported by the caller, not
        silently opened as an empty store."""
        path = Path(path)
        with open(path, encoding="utf-8") as f:
            wk = json.load(f).get("work_key")
        return cls(learn_dir=path.parent.parent, work_key=wk)

    # -- detach / split / merge -------------------------------------------
    def detach_form(self, eid, form_key, run=None):
        """A human removed this form from this entity (--roster-
        unlink): the form's observations are flagged detached (they
        stop speaking for the entity in every view, permanently
        until a human re-links), and NOs are recorded between the
        form and every other form the entity claims, so the union
        cannot silently re-form. Returns the NO records added."""
        form_key = norm_name(form_key)
        added = []
        with self._lock:
            ent = self.data["entities"].get(eid)
            if ent is None:
                return added
            others = self._entity_form_keys(eid) - {form_key}
            for o in ent["observations"]:
                if o.get("form_key") == form_key:
                    o["detached"] = True
                    o["suspect"] = False
            for other in sorted(others):
                if self.record_no(form_key, other,
                                   source="--roster-unlink"):
                    added.append({"a": form_key, "b": other})
            return added

    def record_merge(self, survivor_id, folded_id, run, reason):
        """Tombstone folded_id into survivor_id: the folded entity
        leaves `entities` and is recorded ONCE in `retired` with a
        merged_into redirect; its observations and links are
        preserved under the survivor. Refused by the store itself
        when the union contradicts a recorded human NO."""
        with self._lock:
            if survivor_id == folded_id:
                return False
            surv = self.data["entities"].get(survivor_id)
            fold = self.data["entities"].get(folded_id)
            if surv is None or fold is None:
                return False
            self._check_union(self._entity_form_keys(survivor_id),
                              self._entity_form_keys(folded_id),
                              "merge")
            surv["observations"].extend(fold["observations"])
            surv["links"].extend(fold["links"])
            fold_anchor = fold.get("anchor")
            both_anchored = bool(surv.get("anchor") and fold_anchor)
            if surv.get("anchor") is None and fold_anchor:
                surv["anchor"] = fold_anchor
                surv["canonical"] = fold["canonical"]
                surv["canonical_source"] = fold["canonical_source"]
            tombstone = {"merged_into": survivor_id, "run": run,
                         "reason": reason}
            if both_anchored:
                # Both sides curated: the survivor keeps its OWN
                # anchor, and the folded side's is preserved on
                # the tombstone — never silently dropped — so a
                # later split, unlink or report can see the
                # conflict and a human can rule on it.
                tombstone["anchor"] = fold_anchor
            self.data["retired"][folded_id] = tombstone
            del self.data["entities"][folded_id]
            return True

    def record_split(self, eid, form_keys, run=None):
        """Partition an entity's observations by form: each listed
        form's observations move to a fresh successor entity
        (split_from = eid). When no observations remain, the
        original tombstones as status `split` with split_into
        naming the successors; otherwise it stays active with the
        remainder. Returns {form_key: successor_id}."""
        wanted = [norm_name(f) for f in form_keys]
        out = {}
        with self._lock:
            ent = self.data["entities"].get(eid)
            if ent is None:
                return out
            for fk in wanted:
                mine = [o for o in ent["observations"]
                        if o.get("form_key") == fk]
                if not mine:
                    continue
                ent["observations"] = [
                    o for o in ent["observations"]
                    if o.get("form_key") != fk]
                succ = self.mint_entity()
                sent = self.data["entities"][succ]
                sent["split_from"] = eid
                sent["observations"] = mine
                sent["canonical"] = mine[-1].get("form")
                sent["canonical_source"] = "rule"
                ent["split_into"].append(succ)
                out[fk] = succ
            if out and ent.get("anchor"):
                # The anchor follows its sightings: when the
                # anchor's own name form moved, the anchor moves
                # to that successor — left behind, it would sit
                # on an entity tier 0 cannot see (views are
                # active-only) while anchored_entities kept
                # listing it. When the split empties the original
                # and the anchor's form was never among the
                # observations (a fetch-minted anchor), the anchor
                # follows the largest share of the sightings
                # rather than stranding on the tombstone.
                anchor = ent["anchor"]
                target = out.get(norm_name(anchor.get("name") or ""))
                if target is None and not ent["observations"]:
                    target = max(
                        out.values(),
                        key=lambda s: sum(
                            o.get("appearances") or 0
                            for o in self.data["entities"][s]
                            ["observations"]))
                if target is not None:
                    sent = self.data["entities"][target]
                    sent["anchor"] = anchor
                    if ent.get("canonical_source") == "anchor":
                        sent["canonical"] = anchor["name"]
                        sent["canonical_source"] = "anchor"
                        if ent["observations"]:
                            ent["canonical"] = \
                                ent["observations"][-1].get("form")
                            ent["canonical_source"] = "rule"
                    ent["anchor"] = None
            if out and not ent["observations"]:
                ent["status"] = "split"
            return out

    # -- anchors ------------------------------------------------------------
    def seed_anchor(self, name, kind, source, run, aliases=(),
                    lock_canonical=True):
        """Fetch-or-create the anchored entity for a human decision
        (a preserved DB row, or a manual --alias). The anchor's key
        set is closed and exact (A3): the anchor name's form_key
        plus the form keys of the aliases recorded for it — no token
        decomposition. Re-seeding an existing anchor reconciles
        kind/source/aliases from the fresh row (the curation may
        have changed since the first fetch). Returns the
        entity ID. lock_canonical=False for anchors whose name is a
        normalized key rather than a display form (manual --alias):
        the anchor still pins identity at tier 0, but the display
        name is left to the canonical rule."""
        form_key = norm_name(name)
        keyset = {form_key} | {norm_name(a) for a in aliases if a}
        with self._lock:
            for eid, ent in self.data["entities"].items():
                if ent.get("status") != "active":
                    # A split tombstone's anchor is stranded
                    # legacy state: matching it here would shadow
                    # re-attachment to the active successor that
                    # carries the sightings (it retires via
                    # retire_unclaimed_anchors instead).
                    continue
                anchor = ent.get("anchor")
                if anchor:
                    aset = {norm_name(anchor["name"])} | {
                        norm_name(a) for a in anchor.get("aliases") or []}
                    if aset & keyset:
                        # Reconcile with the freshly fetched row:
                        # kind, source and aliases are the row's
                        # CURRENT curation, not the first fetch's —
                        # a row that flipped confirmed -> rejected
                        # must start suppressing, and one whose
                        # aliases grew must claim the new forms.
                        # (The name is the identity key the match
                        # was made on and stays.)
                        anchor["kind"] = kind
                        anchor["source"] = source
                        anchor["aliases"] = sorted(aliases)
                        anchor["seen_run"] = run
                        return eid
            for eid, ent in self.data["entities"].items():
                if ent.get("status") != "active":
                    continue
                primaries = {o["form_key"] for o in ent["observations"]
                             if not o.get("detached")}
                if primaries & keyset:
                    ent["anchor"] = {
                        "kind": kind, "name": name, "source": source,
                        "aliases": sorted(aliases), "seen_run": run}
                    if lock_canonical:
                        ent["canonical"] = name
                        ent["canonical_source"] = "anchor"
                    return eid
            eid = self.mint_entity()
            ent = self.data["entities"][eid]
            ent["anchor"] = {"kind": kind, "name": name,
                             "source": source,
                             "aliases": sorted(aliases),
                             "seen_run": run}
            if lock_canonical:
                ent["canonical"] = name
                ent["canonical_source"] = "anchor"
            return eid

    def anchored_entities(self):
        """{entity_id: anchor} over ACTIVE entities only. A
        non-active (split) entity's anchor is stranded legacy
        state — tier 0 cannot claim it (views are active-only),
        so it must not hold the A8 disengagement set hostage."""
        return {eid: ent["anchor"]
                for eid, ent in self.data["entities"].items()
                if ent.get("anchor")
                and ent.get("status") == "active"}

    def retire_unclaimed_anchors(self, claimed_ids, run):
        """Retire every anchor this run's anchor re-read did NOT
        claim (claimed_ids: the entity IDs seed_anchor returned
        for the fetched rows). The re-read is the authority: a
        preserved DB row that was deleted, or a manual alias that
        was removed, means the curation is gone — the anchor
        clears (a deleted rejected row must STOP suppressing) and
        the retirement is tombstoned in `anchor_retirements` for
        the report. Returns [(entity_id, anchor)] retired. Only
        ever called after a SUCCESSFUL re-read: a failed fetch
        disengages the seam under A8 before this can run, so a
        transient DB error can never retire anything."""
        out = []
        with self._lock:
            for eid, ent in self.data["entities"].items():
                anchor = ent.get("anchor")
                if anchor and eid not in claimed_ids:
                    self.data["anchor_retirements"].append(
                        {"entity": eid, "run": run, "anchor": anchor})
                    ent["anchor"] = None
                    out.append((eid, anchor))
            return out

    # -- views (matcher input) ----------------------------------------------
    def entity_views(self):
        """Per-entity matching views over ACTIVE entities. Primary
        forms (`primary_forms`) count only forms attested by at
        least one NON-suspect observation (B-F1): a form carried
        solely by a suspended link's observations must not claim
        tier 1 / tier 3 for the entity — the same A1 exclusion the
        canonical vote and tier-2 alias evidence already apply.
        `primary_forms_all` keeps every non-detached form for the
        reporting / split-suspect surface, mirroring
        `alias_keys_all`. desc_hash is the latest trusted
        (non-suspect) observation's."""
        views = []
        with self._lock:
            for eid, ent in self.data["entities"].items():
                if ent.get("status") != "active":
                    continue
                primary, primary_all = set(), set()
                alias_trusted, alias_all = set(), set()
                chapters = set()
                appearances = 0
                desc_hash = ""
                for o in ent["observations"]:
                    if o.get("detached"):
                        continue
                    primary_all.add(o["form_key"])
                    alias_all.update(o.get("alias_keys") or [])
                    chapters.update(o.get("chapters") or [])
                    appearances += o.get("appearances") or 0
                    if not o.get("suspect"):
                        primary.add(o["form_key"])
                        alias_trusted.update(o.get("alias_keys") or [])
                        if o.get("desc_hash"):
                            desc_hash = o["desc_hash"]
                views.append({
                    "id": eid,
                    "canonical": ent.get("canonical"),
                    "canonical_key": norm_name(ent["canonical"] or ""),
                    "anchor": ent.get("anchor"),
                    "primary_forms": primary,
                    "primary_forms_all": primary_all,
                    "alias_keys": alias_trusted,
                    "alias_keys_all": alias_all,
                    "chapters": chapters,
                    "appearances": appearances,
                    "desc_hash": desc_hash,
                    "provisional": self._is_provisional(ent),
                })
            return views

    @staticmethod
    def _is_provisional(ent):
        return sum(1 for o in ent["observations"]
                   if not o.get("detached")) < 2

    def is_provisional(self, eid):
        ent = self.data["entities"].get(eid)
        return bool(ent) and self._is_provisional(ent)

    # -- adoption -------------------------------------------------------------
    def adopt_store(self, src):
        """Adopt another store's contents into this one (work-key
        adoption on work_id resolution, design section 8): entities
        are reminted under this store's sequence, redirects and
        split_from are rewritten, NO records union in, and the
        adoption is recorded on this store. Refused wholesale when
        any entity on either side embodies a union the combined NO
        set vetoes — adoption must not smuggle a vetoed identity
        past the store-level invariant. Returns entities moved."""
        with self._lock:
            nos = list(self.data["no_pairs"]) + list(src.data["no_pairs"])
            for store in (self, src):
                for ent in store.data["entities"].values():
                    forms = set()
                    for o in ent["observations"]:
                        forms.add(o["form_key"])
                        forms.update(o.get("alias_keys") or [])
                    for p in nos:
                        if p["a"] in forms and p["b"] in forms:
                            raise RosterVetoError(
                                "adoption refused: an entity embodies "
                                f"a vetoed union ({p['a']!r} is not "
                                f"{p['b']!r})")
            id_map = {}
            for old_id in src.data["entities"]:
                id_map[old_id] = self.mint_entity()
                # mint_entity counted a fresh mint; adoption MOVES an
                # identity, it does not mint one — the combined
                # store's minted_total is the two stores' sum, set
                # explicitly below.
                self.data["minted_total"] -= 1
            for old_id, ent in src.data["entities"].items():
                new_ent = self.data["entities"][id_map[old_id]]
                moved = json.loads(json.dumps(ent))
                moved["split_from"] = id_map.get(ent.get("split_from"),
                                                 ent.get("split_from"))
                moved["split_into"] = [
                    id_map.get(s, s) for s in ent.get("split_into") or []]
                new_ent.update(moved)
            n_retired = 0
            for old_id, rec in src.data["retired"].items():
                new_id = f"ent_{self.data['next_entity_seq']:04d}"
                self.data["next_entity_seq"] += 1
                n_retired += 1
                self.data["retired"][new_id] = {
                    "merged_into": id_map.get(rec.get("merged_into"),
                                              rec.get("merged_into")),
                    "run": rec.get("run"), "reason": rec.get("reason")}
            for p in src.data["no_pairs"]:
                self.record_no(p["a"], p["b"], source=p.get("source", ""))
            self.data["minted_total"] += src.data["minted_total"]
            _self_runs = self.data["runs_completed"]
            self.data["runs_completed"] = max(
                _self_runs, src.data["runs_completed"])
            # Carry the repeat-guard fingerprint (the rename path
            # in adopt_roster_store moves the whole record,
            # fingerprint included; dropping it here left the
            # combined store unable to recognise a re-completion
            # of the source extraction, which then double-counted
            # its sightings). Which fingerprint: the one belonging
            # to whichever store completed MORE runs — its ordinal
            # is the runs_completed recorded above, so the
            # fingerprint, the ordinal and the observations
            # recorded under that ordinal stay one extraction's.
            # Ties go to the source: adoption happens because a
            # run resolved the work mid-flight, and the source
            # store's last extraction is the one that may complete
            # again against this store. claim_run compares
            # fingerprints by equality — there is no ordinal
            # comparison to relax; the invariant is fingerprint
            # <-> runs_completed <-> assignments under that ordinal.
            _src_fp = src.data.get("last_run_fingerprint")
            if _src_fp is not None and (
                    self.data.get("last_run_fingerprint") is None
                    or src.data["runs_completed"] >= _self_runs):
                self.data["last_run_fingerprint"] = _src_fp
            if src.work_key:
                self.data["adoptions"].append(
                    {"from_key": src.work_key,
                     "entities_moved": len(id_map) + n_retired})
            return len(id_map) + n_retired

    # -- accounting -----------------------------------------------------------
    def accounting(self):
        """The ID partition, closed in the open (F's accounting
        discipline applied to IDs): minted = active + merged + split
        with UNACCOUNTED: 0. Suspension is a link state and is NOT
        part of this partition; it has its own ledger."""
        with self._lock:
            active = sum(1 for e in self.data["entities"].values()
                         if e.get("status") == "active")
            split = sum(1 for e in self.data["entities"].values()
                        if e.get("status") == "split")
            merged = len(self.data["retired"])
            minted = self.data["minted_total"]
            return {"minted": minted, "active": active,
                    "merged": merged, "split": split,
                    "unaccounted": minted - (active + merged + split)}


def roster_store_paths(learn_dir=None):
    """All roster store files under the learned dir's rosters/
    (for --roster-report and the correction commands, which find a
    work's store by scanning: the file's stored work_key is
    authoritative, not its name)."""
    if learn_dir:
        base = Path(learn_dir)
    else:
        base = Path(os.path.expanduser("~")) / ".ebook-processor" \
            / "learned"
    rdir = base / "rosters"
    if not rdir.is_dir():
        return []
    return sorted(rdir.glob("*.json"))


def _roster_store_locs(learn_dir):
    """Every persisted roster store as (label, work_key_or_None,
    path_or_None): on the substrate the label is a state.db key and
    the store is constructed by key; in JSON mode the label is the
    store filename and the store loads via load_path."""
    base = Path(learn_dir) if learn_dir else _learned_dir()
    db = _state_db_for(base)
    if db is not None:
        return [(f"state.db:{wk}", wk, None) for (wk,) in db.query(
            "SELECT work_key FROM roster_works ORDER BY rowid")]
    return [(p.name, None, p) for p in roster_store_paths(base)]


def _roster_store_exists(store):
    """True when the store has a persisted home: a roster_works row
    on the substrate, else its file."""
    db = _state_db_for(store.dir.parent)
    if db is not None:
        return bool(db.query(
            "SELECT 1 FROM roster_works WHERE work_key=?",
            (store.work_key,)))
    return store.path.exists()


def _roster_delete_persisted(learn_dir, work_key):
    """Remove a store's persisted home (substrate rows, else its
    file)."""
    base = Path(learn_dir) if learn_dir else _learned_dir()
    db = _state_db_for(base)
    if db is not None:
        with db.write_txn() as conn:
            for table in ("roster_works", "roster_entities",
                          "roster_retired", "roster_no_pairs",
                          "roster_adoptions",
                          "roster_anchor_retirements"):
                conn.execute(
                    f"DELETE FROM {table} WHERE work_key=?",
                    (work_key,))
        return
    p = base / "rosters" / _roster_store_filename(work_key)
    if p.exists():
        p.unlink()


def find_roster_store(learn_dir, work):
    """Find the store for a <work> argument (exact work_key, else
    work_id, else title — first unambiguous match). Returns
    (RosterStore, None) or (None, error_message)."""
    matches = []
    db = _state_db_for(Path(learn_dir) if learn_dir
                       else _learned_dir())
    if db is not None:
        for wk, wid, title in db.query(
                "SELECT work_key, work_id, title FROM roster_works "
                "ORDER BY rowid"):
            if work in (wk, wid):
                return RosterStore(learn_dir=learn_dir,
                                   work_key=wk), None
            if work and _tnorm(work) == _tnorm(title or ""):
                matches.append(RosterStore(learn_dir=learn_dir,
                                           work_key=wk))
        if len(matches) == 1:
            return matches[0], None
        if len(matches) > 1:
            return None, (f"work {work!r} matches {len(matches)} "
                          "roster stores by title; use the work_id "
                          "or work key")
        return None, f"no roster store found for work {work!r}"
    for path in roster_store_paths(learn_dir):
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        wk = data.get("work_key")
        store = RosterStore(learn_dir=learn_dir, work_key=wk)
        if work in (wk, data.get("work_id")):
            return store, None
        if work and _tnorm(work) == _tnorm(data.get("title") or ""):
            matches.append(store)
    if len(matches) == 1:
        return matches[0], None
    if len(matches) > 1:
        return None, (f"work {work!r} matches {len(matches)} roster "
                      "stores by title; use the work_id or work key")
    return None, f"no roster store found for work {work!r}"


def adopt_roster_store(learn_dir, work_id, title="", author="",
                       isbn=None):
    """Work-key adoption on work_id resolution (the F adopt_for
    pattern, per-work files): a store recorded under a fallback key
    (isbn / title|author) is adopted into the work_id store once a
    run resolves the id — merged in when both files exist, renamed
    when only the fallback does. Exact title+author match only.
    Adoptions are recorded on the surviving store so the next
    roster report lists them. Returns True when an adoption
    happened."""
    if not work_id:
        return False
    candidates = []
    if isbn:
        candidates.append(f"isbn:{isbn}")
    candidates.append(f"title:{_tnorm(title)}|{_tnorm(author)}")
    dst_key = str(work_id)
    adopted = False
    for cand in candidates:
        if cand == dst_key:
            continue
        src = RosterStore(learn_dir=learn_dir, work_key=cand)
        if not _roster_store_exists(src) or src.corrupt_at_load:
            continue
        if _tnorm(src.data.get("title")) != _tnorm(title) \
                or _tnorm(src.data.get("author")) != _tnorm(author):
            continue
        dst = RosterStore(learn_dir=learn_dir, work_key=dst_key)
        if not _roster_store_exists(dst):
            # Rename: same store, new key — no reminting needed.
            src.data["work_key"] = dst_key
            src.data["work_id"] = str(work_id)
            src.data["adoptions"].append(
                {"from_key": cand, "entities_moved":
                 len(src.data["entities"]) + len(src.data["retired"])})
            old_path = src.path
            old_key = cand
            src.work_key = dst_key  # .path now resolves to the new key
            src.save()              # writes the store under the new key
            if _state_db_for(Path(learn_dir)) is not None:
                _roster_delete_persisted(learn_dir, old_key)
            else:
                try:
                    if old_path != src.path and old_path.exists():
                        old_path.unlink()
                except OSError:
                    pass
            adopted = True
            continue
        try:
            dst.adopt_store(src)
        except RosterVetoError as e:
            print(f"  Roster adoption refused for {cand}: {e}")
            continue
        if not dst.data.get("work_id"):
            dst.data["work_id"] = str(work_id)
        dst.save()
        try:
            _roster_delete_persisted(learn_dir, cand)
        except OSError:
            pass
        adopted = True
    return adopted


# ---------------------------------------------------------------------------
# Option B report + correction commands (design sections 10-12):
# read models and human assertions over the roster stores. The
# corrections are the store's reason to exist in human terms — they
# are attributed, recorded and reversible, and they are the ONLY
# writers besides the seam itself.
# ---------------------------------------------------------------------------

def _roster_report_store(path):
    """Load one store file for the report; a file that cannot be
    parsed is reported as corrupt by the caller, never silently
    opened as an empty store."""
    try:
        return RosterStore.load_path(path)
    except Exception:
        return None


def _roster_cmd_learn_dir(learn_dir):
    return Path(learn_dir) if learn_dir else _learn().dir


def cmd_roster_report(learn_dir=None):
    """--roster-report: every roster store, its accounting closed,
    suspects loudest, then entities, links, suspensions,
    suppressions, collisions, splits and canonical changes."""
    base = _roster_cmd_learn_dir(learn_dir)
    locs = _roster_store_locs(base)
    if not locs:
        print("No roster stores found. Roster stores are written by "
              "runs with --persist-roster.")
        return
    print(f"Roster stores: {len(locs)} work(s)")
    for label, wk, path in locs:
        store = (RosterStore(learn_dir=base, work_key=wk)
                 if wk is not None else _roster_report_store(path))
        if store is None or store.corrupt_at_load:
            print(f"\n!! CORRUPT roster store: "
                  f"{label if wk is not None else path}")
            print("   Unreadable — preserved on disk. Runs against "
                  "this work degrade to stateless behaviour until "
                  "the file is repaired or removed.")
            continue
        d = store.data
        acc = store.accounting()
        print(f"\n=== {d.get('title') or '(untitled)'} — "
              f"{d.get('author') or ''}")
        print(f"    work_id: {d.get('work_id') or '(unresolved)'}   "
              f"runs completed: {d.get('runs_completed', 0)}   "
              f"store: {label}")
        if d.get("work_id"):
            try:
                wid2, how2 = resolve_work(d.get("title") or "",
                                          d.get("author") or "",
                                          {}, False, create=False)
                if how2 == "new" or (wid2 and str(wid2)
                                     != str(d["work_id"])):
                    print("    !! ORPHANED: the recorded work_id no "
                          "longer resolves to this work "
                          f"(resolution now: {how2})")
            except Exception:
                pass
        # A1: suspect observations FIRST and loudest — a canonical
        # or an alias resting on a suspended link is exactly the
        # failure this report exists to catch.
        suspects = [(eid, o) for eid, ent in d["entities"].items()
                    for o in ent["observations"] if o.get("suspect")]
        if suspects:
            print("    !! SUSPECT OBSERVATIONS (under suspended "
                  "links; excluded from canonical weighting, "
                  "alias evidence and primary-form authority "
                  "until resolved):")
            for eid, o in suspects:
                print(f"       {eid} form '{o['form']}' (run "
                      f"{o.get('run')}) — resolve with --roster-link"
                      f" / --roster-split")
        print(f"    Accounting: minted {acc['minted']} = "
              f"active {acc['active']} + merged {acc['merged']} + "
              f"split {acc['split']}   "
              f"UNACCOUNTED: {acc['unaccounted']}")
        ledger = store.suspension_ledger()
        if ledger:
            print(f"    Suspended links: {len(ledger)}")
            for item in ledger:
                lnk = item["link"]
                print(f"       {item['entity']} form "
                      f"'{lnk.get('form_key')}' run {lnk.get('run')}"
                      f" — {lnk.get('evidence', '')}")
        if d.get("no_pairs"):
            print(f"    Recorded NOs (never the same person): "
                  f"{len(d['no_pairs'])}")
            for p in d["no_pairs"]:
                print(f"       '{p['a']}' =/= '{p['b']}' "
                      f"({p.get('source', '')})")
        by_canonical = {}
        for eid, ent in d["entities"].items():
            if ent.get("status") == "active" and ent.get("canonical"):
                by_canonical.setdefault(
                    norm_name(ent["canonical"]), []).append(eid)
        collisions = {k: v for k, v in by_canonical.items()
                      if len(v) > 1}
        if collisions:
            print("    !! CANONICAL COLLISIONS (two live entities, "
                  "one display name — the write still ships one "
                  "row per entity; the report surfaces it):")
            for key, eids in sorted(collisions.items()):
                print(f"       '{key}': {', '.join(sorted(eids))}")
        for eid in sorted(d["entities"]):
            ent = d["entities"][eid]
            anchor = ent.get("anchor") or {}
            print(f"    {eid} [{ent.get('status')}] "
                  f"canonical: {ent.get('canonical')!r} "
                  f"({ent.get('canonical_source') or '?'})")
            if anchor:
                print(f"       anchor: {anchor.get('kind')} "
                      f"'{anchor.get('name')}' "
                      f"({anchor.get('source')})")
            if ent.get("split_from"):
                print(f"       split from: {ent['split_from']}")
            forms = {}
            for o in ent["observations"]:
                forms.setdefault(o["form"], []).append(o.get("run"))
            for form, runs in forms.items():
                print(f"       observed '{form}' in run(s) "
                      f"{sorted(runs)}")
            tiers = {}
            for lnk in ent["links"]:
                tiers.setdefault(lnk.get("tier"), []).append(
                    lnk.get("run"))
            for tier, runs in tiers.items():
                print(f"       links: {tier} in run(s) "
                      f"{sorted(runs)}")
            if anchor.get("kind") == "rejected" and any(
                    lnk.get("tier") in ("anchor", "exact-form")
                    and lnk.get("state") == "active"
                    for lnk in ent["links"]):
                print("       SUPPRESSED at row build (rejected "
                      "anchor, tier 0/1 link)")
        for rid, rec in sorted(d["retired"].items()):
            print(f"    {rid} [merged -> {rec.get('merged_into')}] "
                  f"run {rec.get('run')}: {rec.get('reason')}")
            if rec.get("anchor"):
                _ra = rec["anchor"]
                print(f"       folded anchor preserved on the "
                      f"tombstone: {_ra.get('kind')} "
                      f"'{_ra.get('name')}' ({_ra.get('source')}) "
                      f"— the survivor kept its own anchor")
        if d.get("suspects"):
            print("    Split suspects (proposals only — never "
                  "auto-linked):")
            for s in d["suspects"]:
                print(f"       run {s.get('run')}: '{s.get('a')}' "
                      f"vs '{s.get('b')}' — {s.get('why')}")
        if d.get("collisions"):
            print("    Recorded collisions:")
            for c in d["collisions"]:
                print(f"       run {c.get('run')}: {c.get('kind')} "
                      f"— {c.get('why')}")
        if d.get("canonical_changes"):
            print("    Canonical changes:")
            for c in d["canonical_changes"]:
                print(f"       run {c.get('run')}: {c.get('entity')} "
                      f"'{c.get('from')}' -> '{c.get('to')}' "
                      f"({c.get('reason')})")
        if d.get("adoptions"):
            print("    Adoptions:")
            for a in d["adoptions"]:
                print(f"       from {a.get('from_key')}: "
                      f"{a.get('entities_moved')} entit(ies) moved")
        if d.get("anchor_retirements"):
            print("    Anchor retirements (the curated row was "
                  "gone at re-read; the anchor stopped applying):")
            for t in d["anchor_retirements"]:
                _ta = t.get("anchor") or {}
                print(f"       run {t.get('run')}: {t.get('entity')} "
                      f"anchor {_ta.get('kind')} "
                      f"'{_ta.get('name')}' ({_ta.get('source')})")


def _roster_cmd_store(work, learn_dir=None):
    store, err = find_roster_store(_roster_cmd_learn_dir(learn_dir),
                                   work)
    if store is None:
        print(f"{err} (stores are matched by work key, work_id, or "
              f"exact title — see --roster-report).")
    return store


def cmd_roster_link(work, entity_id, form, learn_dir=None):
    """--roster-link: a human asserts FORM belongs to ENTITY. The
    form must already be observed in the entity (links assert
    identity between recorded observations; they do not invent
    forms). Clears the form's suspect/detached flags. When a
    recorded NO stands between the form and the entity's other
    forms, the explicit human assertion supersedes it for that
    pair set — the retirement is printed and the link's evidence
    records it. Automatic paths never supersede a NO."""
    store = _roster_cmd_store(work, learn_dir)
    if store is None:
        return
    eid = store.resolve_id(entity_id)
    if eid is None:
        print(f"Entity {entity_id} not found in this work's store "
              f"(see --roster-report).")
        return
    if eid != entity_id:
        print(f"Note: {entity_id} was merged into {eid}; the link "
              f"is recorded against the survivor.")
    ent = store.get_entity(eid)
    form_key = norm_name(form)
    observed = {o["form_key"] for o in ent["observations"]}
    if form_key not in observed:
        print(f"Refused: form '{form}' is not observed in entity "
              f"{eid} (observed: "
              f"{', '.join(sorted(observed)) or 'none'}). "
              f"--roster-link asserts identity between recorded "
              f"observations; it does not invent forms.")
        return
    # include_detached: the NO being superseded may pair the form
    # with a form claimed only through the very observations the
    # unlink detached — they still count for pair retirement.
    others = store._entity_form_keys(eid, include_detached=True) \
        - {form_key}
    retired = store.retire_no_pairs(form_key, others)
    evidence = "human assertion (--roster-link)"
    if retired:
        evidence += (f"; supersedes {retired} recorded NO pair(s) "
                     f"for this form")
    store.record_link(eid, {"run": store.runs_completed,
                            "tier": "human", "state": "active",
                            "evidence": evidence,
                            "form_key": form_key},
                      entry_forms={form_key})
    n = store.affirm_form(eid, form_key)
    store.save()
    print(f"Linked: form '{form}' affirmed in entity {eid} "
          f"({n} observation(s) vote again).")
    if retired:
        print(f"Retired {retired} recorded NO pair(s) between this "
              f"form and the entity's other forms — your explicit "
              f"assertion supersedes them.")


def cmd_roster_unlink(work, entity_id, form, learn_dir=None):
    """--roster-unlink: a human removes FORM from ENTITY. The
    form's observations are flagged detached and NOs are recorded
    between the form and the entity's other forms, so the union
    cannot silently re-form on the next run — the matcher, the
    folds and the dedupe tombstone path all refuse it (A2)."""
    store = _roster_cmd_store(work, learn_dir)
    if store is None:
        return
    resolved = store.resolve_id(entity_id)
    if resolved is None:
        print(f"Entity {entity_id} not found in this work's store "
              f"(see --roster-report).")
        return
    if resolved != entity_id:
        print(f"Refused: {entity_id} was merged into {resolved}; "
              f"unlink against the surviving entity instead.")
        return
    ent = store.get_entity(entity_id)
    form_key = norm_name(form)
    if form_key not in {o["form_key"] for o in ent["observations"]}:
        print(f"Refused: form '{form}' is not observed in entity "
              f"{entity_id}.")
        return
    added = store.detach_form(entity_id, form_key)
    store.save()
    print(f"Unlinked: form '{form}' detached from entity "
          f"{entity_id}; {len(added)} NO pair(s) recorded — the "
          f"form will not re-link to this entity automatically.")


def cmd_roster_split(work, entity_id, forms, learn_dir=None):
    """--roster-split: a human partitions ENTITY by form — each
    listed form's observations move to a fresh successor entity
    (split_from recorded). When nothing remains, the original
    accounts as `split` in the report's accounting."""
    store = _roster_cmd_store(work, learn_dir)
    if store is None:
        return
    resolved = store.resolve_id(entity_id)
    if resolved is None:
        print(f"Entity {entity_id} not found in this work's store "
              f"(see --roster-report).")
        return
    if resolved != entity_id:
        print(f"Refused: {entity_id} was merged into {resolved}; "
              f"split the surviving entity instead.")
        return
    out = store.record_split(entity_id, list(forms),
                             run=store.runs_completed)
    if not out:
        print(f"Refused: none of the listed forms are observed in "
              f"entity {entity_id}: {', '.join(forms)}.")
        return
    store.save()
    for fk, succ in sorted(out.items()):
        print(f"Split: form '{fk}' moved from {entity_id} to new "
              f"entity {succ}.")
    missing = [f for f in forms if norm_name(f) not in out]
    if missing:
        print(f"Not observed in {entity_id} (skipped): "
              f"{', '.join(missing)}.")


def _matcher_no_veto(no_pairs, entry_forms, view_forms):
    """The recorded NO a link between these form sets would
    contradict, or None (same cross-check as RosterStore.union_veto,
    over plain sets so the matcher stays a pure function)."""
    for a, b in no_pairs:
        if (a in entry_forms and b in view_forms) \
                or (a in view_forms and b in entry_forms):
            return (a, b)
    return None


def _view_primary_forms_all(view):
    """Every primary form the view's entity was observed under,
    including forms attested only by suspect observations. This is
    the claims / proposal surface (veto checks, contested ground,
    split suspects): a suspended link's form still marks the
    ground, it just cannot LINK (tiers 1/3 read `primary_forms`,
    which entity_views now restricts to trusted attestations —
    B-F1). Hand-built views without the key fall back to
    `primary_forms`."""
    return set(view.get("primary_forms_all")
               or view.get("primary_forms") or ())


def _view_form_keys(view):
    """Every form key an entity view claims: observed primaries, all
    observed alias keys, its canonical key, and its anchor's closed
    key set."""
    forms = _view_primary_forms_all(view)
    forms |= set(view.get("alias_keys_all") or ())
    if view.get("canonical_key"):
        forms.add(view["canonical_key"])
    anchor = view.get("anchor")
    if anchor:
        forms.add(norm_name(anchor.get("name") or ""))
        forms |= {norm_name(a) for a in anchor.get("aliases") or []}
    return forms


def roster_match_entries(entries, views, no_pairs=()):
    """Cross-run identity matcher (design section 4): a pure
    function over (run entries, store entity views, human NOs).

    entries: [{key, name, form_key, alias_keys, chapters,
               appearances, desc_hash}]
    views:   RosterStore.entity_views() dicts.
    no_pairs: iterable of (form_key, form_key) human NOs.

    Tiers are tried in order; the first tier producing a UNIQUE,
    unvetoed match wins. Every tier is deterministic in v1 (OC-1) —
    JEV/embeddings never link here. Returns {links, folds,
    suspensions, collisions, suspects, vetoed}: links maps entry
    key -> {entity, tier}; pairs no tier links but which carry a
    similarity signal are split SUSPECTS (proposed, never applied).
    """
    no_pairs = [(norm_name(a), norm_name(b)) for a, b in no_pairs
                if a and b]
    views = sorted(views, key=lambda v: v["id"])
    entries = sorted(entries,
                     key=lambda e: (-(e.get("appearances") or 0),
                                    e["key"]))
    by_id = {v["id"]: v for v in views}
    view_forms = {v["id"]: _view_form_keys(v) for v in views}
    links = {}          # entry key -> {"entity", "tier"}
    collisions, vetoed, suspects = [], [], []
    cannot_link = set()  # (entry key, entity id) — surname trap
    entry_forms = {e["key"]: {e["form_key"]} | set(e["alias_keys"])
                   for e in entries}

    def _veto(e, view):
        return _matcher_no_veto(no_pairs, entry_forms[e["key"]],
                                view_forms[view["id"]])

    def _link(e, view, tier):
        links[e["key"]] = {"entity": view["id"], "tier": tier}

    # -- Tier 0: curation anchors -------------------------------------
    # The anchor's key set is closed and exact (A3): its own form
    # key plus the aliases recorded for it. No token decomposition —
    # a bare surname never claims an anchor.
    anchor_claims = {}   # entity id -> [entry keys]
    for v in views:
        anchor = v.get("anchor")
        if not anchor:
            continue
        keyset = {norm_name(anchor.get("name") or "")} | {
            norm_name(a) for a in anchor.get("aliases") or []}
        keyset.discard("")
        claimed = [e["key"] for e in entries
                   if e["form_key"] in keyset
                   or (set(e["alias_keys"]) & keyset)]
        if claimed:
            anchor_claims[v["id"]] = claimed
    contested_entries = set()
    for eid, keys in anchor_claims.items():
        if len(keys) > 1:
            collisions.append({
                "kind": "anchor", "entity": eid, "entries": keys,
                "why": "two entries claim one anchor; the anchor "
                       "claims neither (both fall through)"})
            contested_entries.update(keys)
    tentative = {}
    for eid, keys in anchor_claims.items():
        if len(keys) == 1 and keys[0] not in contested_entries:
            tentative.setdefault(keys[0], []).append(eid)
    for e in entries:
        cands = tentative.get(e["key"]) or []
        if len(cands) == 1:
            v = by_id[cands[0]]
            if _veto(e, v):
                vetoed.append({"entry": e["key"], "entity": v["id"],
                               "tier": "anchor",
                               "why": "human NO veto"})
            else:
                _link(e, v, "anchor")
        elif len(cands) > 1:
            collisions.append({
                "kind": "anchor", "entity": None,
                "entries": [e["key"]],
                "why": "one entry claims two anchors; neither claims "
                       "it at tier 0"})

    # -- Tiers 1-3 ------------------------------------------------------
    all_forms = set()
    for v in views:
        all_forms |= view_forms[v["id"]]
    for e in entries:
        all_forms |= entry_forms[e["key"]]

    def _third_party_claims(e, candidate):
        """Entities other than the candidate claiming the entry's
        form (primary or alias): the form is contested ground."""
        out = []
        for v in views:
            if v["id"] == candidate["id"]:
                continue
            if e["form_key"] in (_view_primary_forms_all(v)
                                 | set(v.get("alias_keys_all") or ())):
                out.append(v)
        return out

    for e in entries:
        if e["key"] in links:
            continue
        # Tier 1 — exact form match (unique candidate required; a
        # same-form collision abstains rather than picking the
        # bigger entity).
        cands = [v for v in views
                 if e["form_key"] in (v.get("primary_forms") or ())]
        live = []
        for v in cands:
            if _veto(e, v):
                vetoed.append({"entry": e["key"], "entity": v["id"],
                               "tier": "exact-form",
                               "why": "human NO veto"})
            else:
                live.append(v)
        if len(live) == 1:
            _link(e, live[0], "exact-form")
            continue
        if len(cands) > 1:
            collisions.append({
                "kind": "exact-form",
                "entities": [v["id"] for v in cands],
                "entries": [e["key"]],
                "why": "two entities observed under the same form; "
                       "tier 1 abstains rather than guessing"})
        # Tier 2 — alias cross-match (mutual claim + uniqueness).
        cands = [v for v in views
                 if e["form_key"] in (v.get("alias_keys") or ())
                 and v.get("canonical_key")
                 and v["canonical_key"] in e["alias_keys"]]
        live = []
        for v in cands:
            if _veto(e, v):
                vetoed.append({"entry": e["key"], "entity": v["id"],
                               "tier": "alias-cross",
                               "why": "human NO veto"})
            else:
                live.append(v)
        if len(live) == 1 \
                and not _third_party_claims(e, live[0]):
            _link(e, live[0], "alias-cross")
            continue
        # Tier 3 — subsequence / title signals, cross-run: the
        # _merge_tier Tier-2 signals (titles, spelling, nicknames,
        # unambiguous subsequence) plus unambiguous word-prefix
        # growth, against the entity's OWN observed forms in this
        # work's store (closed comparison set, design A7). A
        # surname-trap 'no' is a cannot-link, recorded as such.
        cands = []
        for v in views:
            signal = False
            for f in (set(v.get("primary_forms") or ())
                      | set(v.get("alias_keys") or ())):
                if f == e["form_key"]:
                    continue
                t = _merge_tier(e["form_key"], f,
                                roster_keys=all_forms)
                if t == "no":
                    cannot_link.add((e["key"], v["id"]))
                    signal = False
                    break
                if t == "yes" or _names_overlap(e["form_key"], f):
                    signal = True
            if signal:
                cands.append(v)
        live = []
        for v in cands:
            if (e["key"], v["id"]) in cannot_link:
                continue
            if _veto(e, v):
                vetoed.append({"entry": e["key"], "entity": v["id"],
                               "tier": "subsequence",
                               "why": "human NO veto"})
            else:
                live.append(v)
        if len(live) == 1 \
                and not _third_party_claims(e, live[0]):
            _link(e, live[0], "subsequence")
            continue

    # -- Folds / suspensions ---------------------------------------------
    # Two entries of the SAME run linked to one entity fold into it
    # ONLY when their chapter sets are disjoint (the Tier 1
    # cannot-link, enforced cross-run). Co-occurring dual links are
    # refused: the weaker entry's link suspends and is reported —
    # B never lets last run's identity overrule this run's own
    # co-occurrence evidence.
    folds, suspensions = [], []
    by_entity = {}
    for e in entries:
        link = links.get(e["key"])
        if link:
            by_entity.setdefault(link["entity"], []).append(e)
    entry_by_key = {e["key"]: e for e in entries}
    for eid, es in by_entity.items():
        if len(es) < 2:
            continue
        ordered = sorted(es, key=lambda x: (-(x.get("appearances")
                                              or 0), x["key"]))
        keep = ordered[0]
        refused = []
        for other in ordered[1:]:
            shared = set(keep.get("chapters") or ()) \
                & set(other.get("chapters") or ())
            if shared:
                refused.append((other, shared))
        if not refused:
            folds.append({"entity": eid,
                          "entries": [x["key"] for x in ordered]})
            continue
        for other, shared in refused:
            del links[other["key"]]
            suspensions.append({
                "entity": eid, "entry": other["key"],
                "form_key": other["form_key"],
                "evidence": f"fold refused: co-occurs with "
                            f"{keep['name']!r} in chapter(s) "
                            f"{sorted(shared)} (the Tier 1 "
                            f"cannot-link, enforced cross-run)"})

    # -- Split suspects ----------------------------------------------------
    # Pairs no tier linked but which carry a similarity signal:
    # proposed for a human, never applied.
    for e in entries:
        if e["key"] in links:
            continue
        first = e["form_key"].split()[0] if e["form_key"] else ""
        for v in views:
            if (e["key"], v["id"]) in cannot_link:
                continue
            if any(s["entry"] == e["key"] and s["entity"] == v["id"]
                   for s in suspensions):
                continue
            if _veto(e, v):
                continue
            why = None
            if first and any(f.split()[0] == first
                             for f in _view_primary_forms_all(v)):
                if set(e.get("chapters") or ()) \
                        & set(v.get("chapters") or ()):
                    why = ("shared first token + overlapping "
                           "chapters; no deterministic bridge")
            if why is None and e.get("desc_hash") \
                    and e["desc_hash"] == v.get("desc_hash"):
                why = "description-hash proximity; no name bridge"
            if why:
                suspects.append({"a": e["key"], "b": v["id"],
                                 "why": why})
    return {"links": links, "folds": folds,
            "suspensions": suspensions, "collisions": collisions,
            "suspects": suspects, "vetoed": vetoed}


def roster_fingerprint(roster):
    """Identity of one extraction, for run idempotency (design
    section 7): a hash of the final roster's sorted form keys +
    summed appearances + chapter count (A9 — form keys and chapter
    count alone can coincide across two genuinely different
    extractions). Two completions with the same fingerprint are the
    same extraction completing again, never two sightings."""
    import hashlib as _hl
    form_keys = sorted(norm_name(e.get("name") or "") for e in
                       roster.values())
    appearances = sum(e.get("appearances") or 0
                      for e in roster.values())
    chapters = set()
    for e in roster.values():
        chapters |= set(e.get("chapters") or ())
    payload = json.dumps([form_keys, appearances, len(chapters)])
    return _hl.sha1(payload.encode("utf-8")).hexdigest()[:16]


def _roster_entry_observation(entry, run):
    """One run's observation of a roster entry (design section 3):
    the form this run used, its chapter set and appearance count,
    the aliases the run claimed, and a hash of the run's best
    description (continuity checkable without storing prose)."""
    roles = entry.get("roles") or Counter()
    return {"run": run, "form": entry.get("name") or "",
            "form_key": norm_name(entry.get("name") or ""),
            "chapters": sorted(entry.get("chapters") or ()),
            "appearances": entry.get("appearances") or 0,
            "role_hint": roles.most_common(1)[0][0] if roles else None,
            "aliases": sorted(entry.get("aliases") or ()),
            "alias_keys": sorted(entry.get("alias_keys") or ()),
            "desc_hash": roster_desc_hash(_roster_best_desc(entry))}


_LINK_EVIDENCE = {
    "anchor": "anchor key set claims the run form",
    "exact-form": "run form matches a form this entity was "
                  "observed under in a prior run",
    "alias-cross": "mutual alias claim: the run form is in the "
                   "entity's alias forms and the entity's canonical "
                   "is in the run entry's claimed aliases",
    "subsequence": "deterministic form signal (titles / spelling / "
                   "nickname / unambiguous subsequence or prefix) "
                   "against the entity's own observed forms",
}


def _note_roster_suppression(store, marker, eid, tier, form_display):
    """OC-3 (as amended): a rejected-anchor entity linked at tier 0
    (anchor) or tier 1 (exact-form) is suppressed at row build —
    the human rejected the person, not one spelling of them. Tier
    2/3 links never suppress. Every suppression is an event in the
    marker (and the report), never a silent drop."""
    ent = store.get_entity(eid)
    anchor = (ent or {}).get("anchor") or {}
    if anchor.get("kind") == "rejected" \
            and tier in ("anchor", "exact-form"):
        marker["suppressed"].append({
            "entity": eid, "form": form_display, "tier": tier,
            "anchor_name": anchor.get("name", "")})
        if eid not in marker["suppressed_entities"]:
            marker["suppressed_entities"].append(eid)


def roster_assign_entities(roster, store, *, anchors=None,
                           extra_no_pairs=(), alias_targets=None):
    """The Option B seam (design section 7): assign each final
    roster entry a stable entity ID, exactly once per run, after
    post_pass_merge and before v2_reduce. Annotates entries in
    place with "entity_id", folds disjoint dual-linked entries,
    records observations + links in the store, saves it, and
    returns the marker dict for the result (None when B disengages
    under A8). Provisional entities (single observation) accept
    links normally (OC-7).

    anchors: freshly fetched anchor rows [{name, kind, source,
    aliases}] — [] when the work has none. None means the anchor
    FETCH FAILED (A8): a store already holding anchored entities
    disengages B for the run (flag-off behaviour, loudly) rather
    than matching against anchors it could not verify; a store
    holding none proceeds with a warning.
    """
    if anchors is None:
        if store.anchored_entities():
            print("  !! Roster persistence DISENGAGED for this run: "
                  "the anchor re-read failed and this work's store "
                  "holds anchored entities — matching unanchored "
                  "would void curation (A8). The run proceeds "
                  "exactly as --persist-roster off.")
            return None
        print("  Roster persistence: anchor re-read failed; the "
              "store holds no anchors yet, proceeding with a "
              "warning (no curated substrate to protect)")
        anchors = []
    fingerprint = roster_fingerprint(roster)
    ordinal, repeat = store.claim_run(fingerprint)
    claimed = set()
    for a in anchors:
        claimed.add(store.seed_anchor(
            a["name"], a["kind"], a.get("source", "db"),
            ordinal, a.get("aliases") or (),
            lock_canonical=a.get("lock_canonical", True)))
    # The re-read succeeded (a failure returned under A8 above):
    # any stored anchor it did not claim backs a curated row that
    # is gone — retire it, tombstoned, so revocations take effect.
    for eid, anchor in store.retire_unclaimed_anchors(claimed,
                                                      ordinal):
        print(f"  Roster: anchor '{anchor.get('name')}' "
              f"({anchor.get('kind')}, {anchor.get('source')}) on "
              f"{eid} was not in this run's anchor re-read — the "
              f"curated row is gone; anchor retired (see "
              f"--roster-report).")
    marker = {"linked": 0, "folded": 0, "minted": 0, "suspects": [],
              "suspended": [], "suppressed": [],
              "canonical_changes": [], "canonical_names": {},
              "suppressed_entities": [], "observations_recorded": 0,
              "run_ordinal": ordinal, "repeat": repeat}
    if repeat:
        # The same extraction completing again: the first
        # completion's identity assignment stands. Re-annotate from
        # the recorded assignments and refresh observations in
        # place — no re-matching, no new links, no re-minting.
        assignments = store.run_assignments(ordinal)
        by_entity = {}
        for key in sorted(roster):
            entry = roster[key]
            eid = assignments.get(norm_name(entry.get("name") or ""))
            if eid is None:
                eid = store.mint_entity()
                store.set_canonical(eid, entry.get("name") or "",
                                     "rule")
                marker["minted"] += 1
            entry["entity_id"] = eid
            store.replace_observation(
                eid, _roster_entry_observation(entry, ordinal))
            marker["observations_recorded"] += 1
            by_entity.setdefault(eid, []).append(key)
        for eid, keys in by_entity.items():
            if len(keys) < 2:
                continue
            keep = max(keys, key=lambda k: roster[k].get(
                "appearances") or 0)
            for k in keys:
                if k != keep:
                    _merge_roster_entries(roster, keep, k)
                    marker["folded"] += 1
        marker["linked"] = sum(1 for e in roster.values()
                               if e.get("entity_id"))
        for entry in roster.values():
            eid = entry.get("entity_id")
            if not eid:
                continue
            ent = store.get_entity(eid)
            for lnk in (ent or {}).get("links") or ():
                if lnk.get("run") == ordinal and lnk.get(
                        "form_key") == norm_name(
                        entry.get("name") or ""):
                    _note_roster_suppression(
                        store, marker, eid, lnk.get("tier"),
                        entry.get("name") or "")
                    break
        _roster_canonicalize(roster, store, marker, ordinal,
                             alias_targets)
        store.save()
        return marker

    views = store.entity_views()
    entries = []
    for key in sorted(roster):
        e = roster[key]
        entries.append({
            "key": key, "name": e.get("name") or "",
            "form_key": norm_name(e.get("name") or ""),
            "alias_keys": set(e.get("alias_keys") or ()),
            "chapters": set(e.get("chapters") or ()),
            "appearances": e.get("appearances") or 0,
            "desc_hash": roster_desc_hash(_roster_best_desc(e))})
    no_pairs = [(p["a"], p["b"]) for p in store.data["no_pairs"]]
    no_pairs += [(norm_name(a), norm_name(b))
                 for a, b in extra_no_pairs]
    match = roster_match_entries(entries, views, no_pairs)
    view_by_id = {v["id"]: v for v in views}
    suspended_by_entry = {s["entry"]: s for s in match["suspensions"]}

    for key, link in match["links"].items():
        entry = roster[key]
        eid = link["entity"]
        try:
            store.record_link(eid, {
                "run": ordinal, "tier": link["tier"],
                "state": "active",
                "evidence": _LINK_EVIDENCE.get(link["tier"], ""),
                "form_key": norm_name(entry.get("name") or "")},
                entry_forms={norm_name(entry.get("name") or "")}
                | set(entry.get("alias_keys") or ()))
        except RosterVetoError:
            continue  # matcher pre-checked; a veto here is final
        entry["entity_id"] = eid
        marker["linked"] += 1
        _note_roster_suppression(store, marker, eid, link["tier"],
                                 entry.get("name") or "")
    for key in sorted(roster):
        if key in suspended_by_entry or "entity_id" in roster[key]:
            continue
        eid = store.mint_entity()
        roster[key]["entity_id"] = eid
        store.set_canonical(eid, roster[key].get("name") or "", "rule")
        marker["minted"] += 1
    # Observations: one per entry — under its entity, or (for a
    # suspended weaker entry) under the contested entity, flagged
    # suspect so it stops voting (A1).
    for key in sorted(roster):
        entry = roster[key]
        obs = _roster_entry_observation(entry, ordinal)
        if key in suspended_by_entry:
            susp = suspended_by_entry[key]
            obs["suspect"] = True
            store.append_observation(susp["entity"], obs)
            try:
                store.record_link(susp["entity"], {
                    "run": ordinal, "tier": "fold",
                    "state": "suspended",
                    "evidence": susp["evidence"],
                    "form_key": obs["form_key"]},
                    entry_forms={obs["form_key"]}
                    | set(entry.get("alias_keys") or ()))
            except RosterVetoError:
                pass
            marker["suspended"].append({
                "entity": susp["entity"], "form": obs["form"],
                "evidence": susp["evidence"]})
        else:
            store.append_observation(entry["entity_id"], obs)
        marker["observations_recorded"] += 1
    # Folds: merge the folded roster entries into their keeper.
    for fold in match["folds"]:
        keys = [k for k in fold["entries"] if k in roster]
        if len(keys) < 2:
            continue
        keep = keys[0]
        for drop in keys[1:]:
            _merge_roster_entries(roster, keep, drop)
            marker["folded"] += 1
    for s in match["suspects"]:
        ent = view_by_id.get(s["b"]) or {}
        _susp = {
            "a": roster[s["a"]].get("name") if s["a"] in roster
                 else s["a"],
            "b": ent.get("canonical") or s["b"], "why": s["why"]}
        marker["suspects"].append(_susp)
        # Persisted (design section 10): split suspects are
        # proposals for a human, and the report reads the store —
        # a suspect that only existed in one run's preview JSON
        # would never be seen again.
        store.data["suspects"].append({"run": ordinal, **_susp})
    store.data["suspects"] = store.data["suspects"][-100:]
    for c in match["collisions"]:
        store.data["collisions"].append({"run": ordinal, **c})
    store.data["collisions"] = store.data["collisions"][-50:]
    _roster_canonicalize(roster, store, marker, ordinal, alias_targets)
    store.save()
    return marker


def compute_canonical_name(entity, alias_targets=None):
    """The section 5 canonical rule: identity and display are
    separate decisions. Returns (name, source) or (None, None) when
    nothing may vote.

    1. Anchor wins: an entity anchored to a DB row (canonical
       locked at seed time) keeps the anchor's name, rule-proof.
    2. Human override: a manual alias target observed among the
       entity's forms beats the vote — the display used is the
       target's own observed form (a target never observed has no
       display form to ship and does not fire).
    3. Deterministic vote over observed primary forms: greatest
       total appearances; ties and near-ties (within 80% of the
       leader) break toward the FULLEST form (most tokens, then
       longest); remaining ties toward the most recently observed.
    Suspect and detached observations do not vote (A1): a canonical
    name never rests on evidence a suspended link carried in.
    """
    if entity.get("anchor") \
            and entity.get("canonical_source") == "anchor":
        return entity["anchor"]["name"], "anchor"
    by_form = {}
    for o in entity.get("observations") or ():
        if o.get("suspect") or o.get("detached"):
            continue
        slot = by_form.setdefault(
            o["form_key"], {"apps": 0, "display": o["form"],
                            "last_run": o.get("run") or 0})
        slot["apps"] += o.get("appearances") or 0
        if (o.get("run") or 0) >= slot["last_run"]:
            slot["last_run"] = o.get("run") or 0
            slot["display"] = o["form"]
    if not by_form:
        return None, None
    for src_key, tgt_key in (alias_targets or {}).items():
        if src_key in by_form and tgt_key in by_form \
                and src_key != tgt_key:
            return by_form[tgt_key]["display"], "human"
    leader = max(s["apps"] for s in by_form.values())
    contenders = {k: s for k, s in by_form.items()
                  if s["apps"] >= 0.8 * leader}
    best = sorted(
        contenders.values(),
        key=lambda s: (-len(s["display"].split()),
                       -len(s["display"]), -s["last_run"],
                       s["display"]))[0]
    return best["display"], "rule"


_CANONICAL_REASONS = {
    "anchor": "curation anchor name (rule-proof)",
    "human": "manual alias override",
    "rule": "appearance-weighted rule, fullest form on near-ties",
}


def _roster_canonicalize(roster, store, marker, ordinal,
                         alias_targets=None):
    """Recompute canonical names for the entities this run touched
    (design section 5) and fill the marker's canonical_names map —
    the map the write builders resolve IDs through. A canonical
    that CHANGES from a previously shipped name is an event:
    recorded in the marker with its reason, never silent, because
    on the app surface it looks like a rename."""
    names = {}
    for e in roster.values():
        eid = e.get("entity_id")
        if not eid:
            continue
        ent = store.get_entity(eid)
        if ent is None:
            continue
        new, source = compute_canonical_name(ent, alias_targets)
        if new is None:
            new = ent.get("canonical") or e.get("name") or ""
            source = source or ent.get("canonical_source") or "rule"
        old = ent.get("canonical")
        if new != old:
            store.set_canonical(eid, new, source)
            if old is not None:
                _change = {
                    "entity": eid, "from": old, "to": new,
                    "reason": _CANONICAL_REASONS.get(source, source)}
                marker["canonical_changes"].append(_change)
                store.data["canonical_changes"].append(
                    {"run": ordinal, **_change})
                store.data["canonical_changes"] = \
                    store.data["canonical_changes"][-100:]
        names[eid] = new
    marker["canonical_names"] = names


def _roster_alias_targets():
    """Manual --alias pairs from learned state, as {form_key:
    target_form_key} for the canonical rule's human override.
    LearnedState stores both sides normalized; only human-recorded
    (manual) pairs count — learned merges are not overrides."""
    ln = _learn()
    if not ln.enabled:
        return {}
    return {short: ent.get("full")
            for short, ent in (ln.nicknames or {}).items()
            if ent.get("manual") and ent.get("full")}


def _roster_record_dedupe_folds(store, pre_characters, report,
                                run_ordinal):
    """Record dedupe_characters merges in the store (design
    section 4): when two result characters carrying different
    entity IDs merge, the folded ID tombstones into the survivor
    with reason 'within-run merge' and its observations are
    preserved under the survivor. The run's shipped rows are
    unaffected — the veto governs the PERSISTED identity. Returns
    the number of tombstones recorded."""
    def _eid_of(name):
        for c in pre_characters:
            if c.get("entity_id") and (
                    norm_name(c.get("name") or "") == norm_name(name)
                    or (c.get("name") or "").lower()
                    == (name or "").lower()):
                return c["entity_id"]
        return None

    n = 0
    for cluster in report or ():
        survivor = _eid_of(cluster.get("canonical"))
        if not survivor:
            continue
        for name in cluster.get("merged") or ():
            folded = _eid_of(name)
            if not folded or folded == survivor:
                continue
            try:
                if store.record_merge(survivor, folded,
                                      run=run_ordinal,
                                      reason="within-run merge"):
                    n += 1
            except RosterVetoError as e:
                print(f"  Roster store refused a dedupe tombstone: "
                      f"{e} (the run's rows are unaffected; the "
                      f"identities stay separate in the store)")
    if n:
        store.save()
    return n


def _roster_store_for(title, author, identifiers):
    """Open the RosterStore for a book at the seam. The work_id is
    resolved READ-ONLY here (the pipeline resolves for real after
    result assembly): when it resolves, the store lives under the
    work_id key from the start; when it doesn't (a brand-new work),
    the fallback key applies and adoption on resolution moves the
    store (design section 8). Returns (store, work_id-or-None);
    (None, None) when the store can't be opened."""
    wid = None
    try:
        wid, _how = resolve_work(title, author, identifiers, False,
                                 create=False)
    except Exception:
        wid = None
    key = staging_work_key(wid, (identifiers or {}).get("isbn"),
                           title, author)
    try:
        store = RosterStore(learn_dir=_learn().dir, work_key=key)
    except Exception:
        return None, None
    store.data["title"] = title or ""
    store.data["author"] = author or ""
    if wid:
        store.data["work_id"] = str(wid)
    return store, wid


def _roster_fetch_anchors(work_id):
    """Fetch a work's curation anchors (design section 8): every
    preserved book_characters row (confirmed / rejected /
    contributor, per _partition_claims) becomes an anchor, plus
    manual --alias pairs from learned state. Returns a list of
    {name, kind, source, aliases, lock_canonical}, or None on DB
    error — the seam applies A8's failure discipline to None."""
    rows = _sb_fetch_all(
        "book_characters",
        f"?work_id=eq.{quote(str(work_id), safe='')}"
        f"&select=id,name,status,source_type,aliases")
    if rows is None:
        return None
    preserved, _rejected, _ndel = _partition_claims(
        "book_characters", rows)
    anchors = []
    for r in rows:
        if _claim_key("book_characters", r) not in preserved:
            continue
        status = r.get("status") or ""
        if status == "rejected":
            kind = "rejected"
        elif status == "confirmed":
            kind = "confirmed"
        else:
            kind = "contributor"
        aliases = r.get("aliases") or []
        if isinstance(aliases, str):
            try:
                aliases = json.loads(aliases)
            except Exception:
                aliases = []
        anchors.append({
            "name": r.get("name") or "", "kind": kind, "source": "db",
            "aliases": [a for a in aliases if isinstance(a, str)],
            "lock_canonical": True})
    _ln = _learn()
    if _ln.enabled:
        for short, ent in (_ln.nicknames or {}).items():
            if ent.get("manual"):
                anchors.append({
                    "name": ent.get("full") or "", "kind": "manual-alias",
                    "source": "--alias", "aliases": [short],
                    "lock_canonical": False})
    return anchors


# Module-level staging state, mirroring _learn(): _staging() always
# returns a usable object (disabled stub when --staging-gate is off),
# rooted at the learned-state directory so staging.json sits beside
# the learning files. Tests may assign _STAGING_STATE directly.
_STAGING_STATE = None


def _staging():
    global _STAGING_STATE
    if _STAGING_STATE is None:
        if CONFIG.get("staging_gate", False):
            _STAGING_STATE = StagingState(_learn().dir)
        else:
            _STAGING_STATE = StagingState(enabled=False)
    return _STAGING_STATE


# Module-level learning state, created in main() when --learn is on.
# _learn() always returns a usable object (disabled stub when off), so
# call sites never need None checks.
_LEARNED = None

# Spine replay/capture contexts (design §3.4). _REPLAY_CTX is set
# only inside run_replay: while it lives, _checkpoint_dir serves the
# snapshot's payload directory, checkpoint WRITES are suppressed
# (the snapshot stays pristine), and every store write lands in the
# sandbox substrate. _CAPTURE_CTX arms snapshot capture for the
# current (fresh, preview) run.
_REPLAY_CTX = None
_CAPTURE_CTX = None

# Corpus snapshot block staging (corpus-design §4.3): a capture
# run stashes ITS OWN parse's chapter hashes here, keyed by the
# run's fingerprint, immediately before capture_snapshot runs;
# capture consumes (pops) the entry into the manifest's corpus
# block. The hashes are never read back from corpus rows — the
# block attests what the capture run itself parsed, and replay
# validates the live corpus against it.
_PENDING_CAPTURE_HASHES = {}


def _learn():
    global _LEARNED
    if _LEARNED is None:
        _LEARNED = LearnedState(enabled=False)
    return _LEARNED


def _count_series_rosters(state):
    """(n_series, n_characters) from the <learn_dir>/series/ tree.

    Counts each series bucket once: author-based flat files
    (series/*.json) and named-series rosters (series/*/roster.json).
    Pure (no I/O beyond reading); returns (0, 0) when the dir is absent.
    On the substrate the same buckets are series_state rows, keyed
    "author_x" (flat) and "<name>/roster" (named)."""
    db = _state_db_for(state.dir)
    if db is not None:
        n_series = 0
        n_chars = 0
        seen = set()
        for (key, payload) in db.query(
                "SELECT series_key, payload FROM series_state "
                "ORDER BY rowid"):
            bucket = key[:-len("/roster")] if key.endswith("/roster") \
                else key
            if not bucket or bucket in seen:
                continue
            seen.add(bucket)
            try:
                data = json.loads(payload)
            except Exception:
                continue
            if not isinstance(data, dict):
                continue
            n_series += 1
            chars = data.get("characters", [])
            if isinstance(chars, list):
                n_chars += len(chars)
        return n_series, n_chars
    series_dir = state.dir / "series"
    if not series_dir.is_dir():
        return 0, 0
    n_series = 0
    n_chars = 0
    seen = set()
    for p in sorted(series_dir.rglob("*.json")):
        if p.name.endswith(".tmp"):
            continue
        # Bucket key: flat file -> stem; roster.json -> parent dir name.
        # Prevents double-counting if both layouts ever overlap.
        if p.name == "roster.json":
            key = p.parent.name
        else:
            key = p.stem
        if not key or key in seen:
            continue
        seen.add(key)
        try:
            with open(p, encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        n_series += 1
        chars = data.get("characters", [])
        if isinstance(chars, list):
            n_chars += len(chars)
    return n_series, n_chars


def _learn_status_text(state):
    """Human-readable summary of a LearnedState. Pure (no I/O)."""
    lines = [f"Learning system status ({state.dir}/):"]
    # Nicknames (human-validated subset) and manual aliases.
    nicks = state.nicknames or {}
    n_total = len(nicks)
    n_human = sum(1 for e in nicks.values()
                  if isinstance(e, dict) and e.get("human"))
    lines.append(f"  Nicknames: {n_total} ({n_human} human-validated)")
    n_manual = sum(1 for e in nicks.values()
                   if isinstance(e, dict) and e.get("manual"))
    lines.append(f"  Manual aliases: {n_manual}")
    # Trusted titles.
    try:
        n_titles = len(state.trusted_titles())
    except Exception:
        n_titles = 0
    lines.append(f"  Trusted titles: {n_titles}")
    # Rejected tropes (denylisted subset, with names).
    rej = state.rejected_tropes or {}
    n_rej = len(rej)
    deny_names = sorted(
        k for k, e in rej.items()
        if isinstance(e, dict)
        and e.get("count", 0) >= _REJECT_DENYLIST_COUNT)
    lines.append(f"  Rejected tropes: {n_rej} ({len(deny_names)} denylisted)")
    if deny_names:
        lines.append(f"    Denylisted: {', '.join(deny_names)}")
    # Threshold samples.
    n_samples = 0
    for e in (state.threshold_stats or {}).values():
        if isinstance(e, dict):
            n_samples += len(e.get("kept", []) or [])
            n_samples += len(e.get("dropped", []) or [])
    lines.append(f"  Threshold samples: {n_samples}")
    # Series rosters.
    n_series, n_chars = _count_series_rosters(state)
    lines.append(f"  Series rosters: {n_series} series, {n_chars} characters")
    return "\n".join(lines)


def cmd_learn_status(learn_dir=None):
    """Print learning system status and exit (for --learn-status)."""
    state = LearnedState(learn_dir=learn_dir, enabled=True)
    print(_learn_status_text(state))
    db = _state_db_for(state.dir)
    if db is not None:
        nbytes = db.size_info()["bytes"]
        print(f"  State substrate: state.db (SQLite), {nbytes} bytes "
              "on disk incl. WAL. state.db IS the state, not a "
              "cache; state.db.bak beside it is the rolling backup "
              "(refreshed on the first write of each process).")
        if nbytes > 50 * 1024 * 1024:
            print("  Note: state.db is large (>50 MB); the staging "
                  "and roster reports show what is accumulating.")




# ---------------------------------------------------------------------------
# Corpus reports: --calibration-report (§6.3/§7.3 — the analytics down
# payment: existing threshold samples, no corpus required) and
# --corpus-status (§7.4). Both are read-model commands: they open the
# stores, print, and change nothing.
# ---------------------------------------------------------------------------

_CALIBRATION_LIMIT_NOTICE = (
    "DISTRIBUTIONAL ONLY: the threshold samples carry no work, run, "
    "or outcome keys, so this report describes the score "
    "distributions the judge produces — it cannot say what a score "
    "was worth downstream, because nothing joins a sample to its "
    "fate.")
_CALIBRATION_DECISION_RULE = (
    "Decision rule: distributional shape may inform a threshold "
    "conversation; it may not move one. A threshold move requires "
    "the wave-2 outcome-joined calibration (samples recorded with "
    "work/run/outcome refs by the stage-contract adoption).")
_CALIBRATION_LEVELS = (0.5, 0.75, 0.9, 0.95)


def _percentile(sorted_vals, p):
    """Linear-interpolation percentile (p in [0, 100])."""
    if not sorted_vals:
        return None
    if len(sorted_vals) == 1:
        return sorted_vals[0]
    rank = (p / 100.0) * (len(sorted_vals) - 1)
    lo = int(rank)
    hi = min(lo + 1, len(sorted_vals) - 1)
    frac = rank - lo
    return sorted_vals[lo] * (1 - frac) + sorted_vals[hi] * frac


def _deciles(vals):
    s = sorted(vals)
    return [round(_percentile(s, p), 4) for p in range(10, 100, 10)]


def _auc(kept, dropped):
    """P(a random kept sample out-scores a random dropped one),
    ties counting half (Mann-Whitney). None when a bucket is empty."""
    if not kept or not dropped:
        return None
    wins = 0.0
    for k in kept:
        for d in dropped:
            if k > d:
                wins += 1.0
            elif k == d:
                wins += 0.5
    return wins / (len(kept) * len(dropped))


def _kept_rate_crossings(kept, dropped):
    """For each named level, the P(yes) value at which the observed
    kept-rate — P(kept | score >= t) over the pooled samples —
    first reaches the level, scanning t upward over observed
    scores. None when the rate never reaches the level."""
    pooled = sorted(set(kept) | set(dropped))
    out = {}
    for level in _CALIBRATION_LEVELS:
        cross = None
        for t in pooled:
            kg = sum(1 for v in kept if v >= t)
            dg = sum(1 for v in dropped if v >= t)
            if kg + dg and kg / (kg + dg) >= level:
                cross = t
                break
        out[f"{level:.2f}"] = cross
    return out


def _calibration_report(stats):
    """Pure: threshold_stats dict -> report data (§6.3)."""
    triggers = []
    for trigger in sorted(stats or {}):
        ent = stats.get(trigger) or {}
        kept = [float(v) for v in (ent.get("kept") or [])]
        dropped = [float(v) for v in (ent.get("dropped") or [])]
        ks, ds = sorted(kept), sorted(dropped)
        triggers.append({
            "trigger": trigger,
            "kept": {"n": len(kept),
                     "deciles": _deciles(kept) if kept else [],
                     "median": (round(_percentile(ks, 50), 4)
                                if kept else None)},
            "dropped": {"n": len(dropped),
                        "deciles": _deciles(dropped) if dropped else [],
                        "median": (round(_percentile(ds, 50), 4)
                                   if dropped else None)},
            "separation": {
                "median_diff": (
                    round(_percentile(ks, 50) - _percentile(ds, 50), 4)
                    if kept and dropped else None),
                "auc": (round(_auc(kept, dropped), 4)
                        if kept and dropped else None)},
            "crossings": _kept_rate_crossings(kept, dropped),
        })
    return {"triggers": triggers,
            "limit": _CALIBRATION_LIMIT_NOTICE,
            "decision_rule": _CALIBRATION_DECISION_RULE}


def _calibration_report_text(stats):
    data = _calibration_report(stats)
    lines = ["Threshold calibration report",
             f"  {data['limit']}",
             f"  {data['decision_rule']}"]
    if not data["triggers"]:
        lines.append("  No threshold samples recorded yet.")
    for t in data["triggers"]:
        lines.append(f"  {t['trigger']}:")
        for bucket in ("kept", "dropped"):
            b = t[bucket]
            dec = ", ".join(f"{v:.2f}" for v in b["deciles"])
            lines.append(
                f"    {bucket} (n={b['n']}): deciles [{dec}]"
                + (f" median {b['median']:.2f}"
                   if b["median"] is not None else ""))
        sep = t["separation"]
        if sep["auc"] is not None:
            lines.append(
                f"    separation: AUC {sep['auc']:.3f}, median diff "
                f"{sep['median_diff']:+.3f}")
        cross = ", ".join(
            f"{lvl} -> {v if v is not None else 'never'}"
            for lvl, v in t["crossings"].items())
        lines.append(f"    kept-rate crossings: {cross}")
    return "\n".join(lines)


def cmd_calibration_report(learn_dir=None, as_json=False):
    """Print the §6.3 calibration report and exit."""
    state = LearnedState(learn_dir=learn_dir, enabled=True)
    if as_json:
        print(json.dumps(_calibration_report(state.threshold_stats),
                         ensure_ascii=False, indent=1))
    else:
        print(_calibration_report_text(state.threshold_stats))


def _corpus_generations(db):
    """Vector generations recorded in meta (§2.4): a list of
    {model, format, dim, canary} dicts, oldest first."""
    gens = []
    for k, v in db.query(
            "SELECT k, v FROM meta WHERE k LIKE 'generation:%' "
            "ORDER BY k"):
        try:
            gens.append(json.loads(v))
        except (TypeError, ValueError):
            continue
    return gens


def _corpus_size_breakdown(db):
    """corpus.db bytes by component (§7.4): per-table page counts
    via dbstat when this SQLite has it; content-byte estimates as
    the fallback. Keys: text, fts, vectors, other, total."""
    total = db.size_info()["bytes"]
    try:
        rows = db.query(
            "SELECT name, SUM(pgsize) FROM dbstat GROUP BY name")
        pages = {name: size for name, size in rows}
        text = pages.get("corpus_chapters", 0)
        fts = pages.get("corpus_fts", 0) + sum(
            v for k, v in pages.items() if k.startswith("corpus_fts_"))
        vectors = pages.get("passage_vectors", 0)
        other = max(total - text - fts - vectors, 0)
        return {"text": text, "fts": fts, "vectors": vectors,
                "other": other, "total": total, "via": "dbstat"}
    except Exception:
        text = db.query(
            "SELECT COALESCE(SUM(LENGTH(text)), 0) "
            "FROM corpus_chapters")[0][0]
        vectors = db.query(
            "SELECT COALESCE(SUM(LENGTH(vector)), 0) "
            "FROM passage_vectors")[0][0]
        return {"text": text, "fts": 0, "vectors": vectors,
                "other": max(total - text - vectors, 0),
                "total": total, "via": "content-estimate"}


def _corpus_status_data(learn_dir):
    """Pure read model for --corpus-status (§7.4)."""
    d = (Path(learn_dir) if learn_dir
         else Path(os.path.expanduser("~")) / ".ebook-processor"
         / "learned")
    data = {"present": False, "dir": str(d), "works": [],
            "totals": {"works": 0, "by_status": {}, "quotes": 0,
                       "quotes_by_status": {}},
            "generations": [], "bytes": None,
            "current_parser_version": CORPUS_PARSER_VERSION}
    db = _corpus_db_for(d, mode="report")
    if db is None:
        return data
    data["present"] = True
    data["fts_available"] = db.fts_available
    gen = None
    cur = db.meta_get("generation_current")
    if cur:
        try:
            gen = json.loads(cur)
        except (TypeError, ValueError):
            gen = None
    works = []
    for row in db.query(
            "SELECT fingerprint, title, author, status, "
            "parser_version, chapter_count FROM corpus_works "
            "ORDER BY title, fingerprint"):
        fp, title, author, status, pv, nch = row
        n_pass = db.query(
            "SELECT COUNT(*) FROM corpus_passages WHERE fingerprint=?",
            (fp,))[0][0]
        coverage = None
        if gen and n_pass:
            n_vec = db.query(
                "SELECT COUNT(*) FROM passage_vectors pv JOIN "
                "corpus_passages p ON p.passage_id = pv.passage_id "
                "WHERE p.fingerprint=? AND pv.model=? AND pv.format=?",
                (fp, gen.get("model"), gen.get("format")))[0][0]
            coverage = round(n_vec / n_pass, 4)
        env = db.query(
            "SELECT computed_at FROM work_envelope WHERE fingerprint=?",
            (fp,))
        works.append({
            "fingerprint": fp, "title": title, "author": author,
            "status": status, "parser_version": pv,
            "chapters": nch, "passages": n_pass,
            "vector_coverage": coverage,
            "envelope_computed_at": env[0][0] if env else None})
        by = data["totals"]["by_status"]
        by[status] = by.get(status, 0) + 1
    data["works"] = works
    data["totals"]["works"] = len(works)
    for status, n in db.query(
            "SELECT status, COUNT(*) FROM quotes GROUP BY status"):
        data["totals"]["quotes_by_status"][status] = n
        data["totals"]["quotes"] += n
    data["generations"] = _corpus_generations(db)
    data["bytes"] = _corpus_size_breakdown(db)
    return data


_CORPUS_STANDING_SENTENCE = (
    "corpus.db IS retained book text, not a cache — deleting it "
    "costs re-ingest, never correctness (§5.3).")


def _corpus_status_text(learn_dir):
    data = _corpus_status_data(learn_dir)
    lines = [f"Corpus status ({data['dir']}/):"]
    if not data["present"]:
        lines.append("  corpus.db: absent — no books ingested yet "
                     "(--ingest is the named act that creates it).")
        lines.append(f"  {_CORPUS_STANDING_SENTENCE}")
        return "\n".join(lines)
    if not data["fts_available"]:
        lines.append("  FTS: unavailable on this Python's SQLite "
                     "(degraded open, §1.5) — text search skipped; "
                     "text, passages, and vectors unaffected.")
    for w in data["works"]:
        cov = ("n/a" if w["vector_coverage"] is None
               else f"{w['vector_coverage'] * 100:.0f}%")
        stale = ("" if w["parser_version"] == CORPUS_PARSER_VERSION
                 else " [stale parser]")
        lines.append(
            f"  {w['title'] or '(untitled)'} [{w['fingerprint'][:8]}] "
            f"{w['status']} · parser {w['parser_version']} "
            f"(current {CORPUS_PARSER_VERSION}){stale} · "
            f"{w['chapters']} chapters · {w['passages']} passages · "
            f"vectors {cov}")
    t = data["totals"]
    by = ", ".join(f"{k} {v}" for k, v in sorted(t["by_status"].items()))
    lines.append(f"  Works: {t['works']}" + (f" ({by})" if by else ""))
    if t["quotes"]:
        qb = ", ".join(f"{k} {v}" for k, v in
                       sorted(t["quotes_by_status"].items()))
        lines.append(f"  Quotes: {t['quotes']} ({qb})")
    for g in data["generations"]:
        warn = ("  !! GENERATION SUSPECT — drift canary failed; its "
                "vectors read as misses until re-embedded (§2.4)"
                if g.get("canary") == "suspect" else "")
        lines.append(
            f"  Vector generation {g.get('model')} / "
            f"{g.get('format')} (dim {g.get('dim')}): canary "
            f"{g.get('canary', 'unknown')}{warn}")
    b = data["bytes"]
    if b:
        lines.append(
            f"  corpus.db: {b['total']} bytes (text {b['text']}, "
            f"FTS {b['fts']}, vectors {b['vectors']}, other "
            f"{b['other']}; via {b['via']})")
    lines.append(f"  {_CORPUS_STANDING_SENTENCE}")
    return "\n".join(lines)


def cmd_corpus_status(learn_dir=None, as_json=False):
    """Print the §7.4 corpus status report and exit."""
    # §2.4: --corpus-status is a canary check point. When an
    # embedder is configured and a current generation exists,
    # re-embed the sentinels first so a SUSPECT line is earned by
    # THIS check, not stale history. Best-effort: the check detects
    # drift; it never gates a report.
    emb = _corpus_config_embedder()
    if emb is not None:
        d = (Path(learn_dir) if learn_dir
             else Path(os.path.expanduser("~")) / ".ebook-processor"
             / "learned")
        db = _corpus_db_for(d, mode="report")
        if db is not None:
            cur_raw = db.meta_get("generation_current")
            if cur_raw:
                try:
                    cur = json.loads(cur_raw)
                    _corpus_canary_check(db, emb[0], cur["model"],
                                         cur.get("format")
                                         or _CORPUS_VECTOR_FORMAT)
                except Exception:
                    pass
    if as_json:
        print(json.dumps(_corpus_status_data(learn_dir),
                         ensure_ascii=False, indent=1))
    else:
        print(_corpus_status_text(learn_dir))


# ---------------------------------------------------------------------------
# --corpus-snapshot (docs/corpus-snapshot-spec.md): a metadata-only,
# point-in-time observation of the local corpus, uploaded to the
# processor schema (one header row + one row per corpus work). Not
# a run and not a sync: nothing flows back, the local corpus is
# never modified, and no other command takes one implicitly.
# ---------------------------------------------------------------------------

_SNAPSHOT_SCHEMA = "processor"
_SNAPSHOT_BOOK_CHUNK = 200
_SNAPSHOT_UUID_RE = re.compile(
    r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-"
    r"[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")
_SNAPSHOT_GENERATION_KEYS = ("model", "format", "dim", "canary",
                             "born", "checked")


def _snapshot_generation_projection(gen):
    """The ONLY shape a generation record may ship in: the six
    state fields, named explicitly. The stored record also carries
    the canary's sentinel vectors and pairwise cosines — embedding
    material that must never leave the machine — so the projection
    is a whitelist, never a copy with keys removed afterwards."""
    if not isinstance(gen, dict):
        return None
    return {k: gen.get(k) for k in _SNAPSHOT_GENERATION_KEYS}


def _snapshot_isbn(raw_identifiers):
    """The one identifier a snapshot ships: an ISBN, re-cleaned
    through _clean_isbn at build time. The stored identifier record
    also carries the ASIN and the raw identifier list; neither is
    shipped, and the raw list is consulted only as a source of
    further ISBN candidates. Re-cleaning (rather than trusting the
    value ingest stored) keeps the 'cleaned ISBN-13 only' guarantee
    provable against legacy or hand-edited rows. Malformed records
    read as no ISBN, never as a crash and never shipped raw."""
    try:
        ids = json.loads(raw_identifiers) if isinstance(
            raw_identifiers, str) else raw_identifiers
    except (TypeError, ValueError):
        ids = None
    candidates = []
    if isinstance(ids, dict):
        if ids.get("isbn"):
            candidates.append(ids["isbn"])
        raw = ids.get("raw")
        if isinstance(raw, list):
            candidates.extend(raw)
    elif isinstance(ids, list):
        candidates.extend(ids)
    elif isinstance(ids, str):
        candidates.append(ids)
    for c in candidates:
        if isinstance(c, (str, int)):
            cleaned = _clean_isbn(str(c))
            if cleaned:
                return cleaned
    return None


def _snapshot_work_id(raw):
    """corpus_works.work_id is a soft reference with no local
    constraint on its shape, and no current local writer populates
    it. A malformed local value shipped raw would make Postgres
    reject the whole book chunk, so only a UUID-shaped value
    ships — anything else reads as unknown (NULL)."""
    if isinstance(raw, str) and _SNAPSHOT_UUID_RE.match(raw.strip()):
        return raw.strip()
    return None


def _corpus_snapshot_fingerprint(cur_gen, books):
    """The content identity of the whole corpus (spec §6): sha256
    of the canonical JSON of the current generation's {model,
    format} and the per-work identity tuples, sorted by
    fingerprint. Machine label and capture time are NOT inputs —
    the same corpus on another machine, observed at another time,
    fingerprints identically. Quote counts are deliberately
    excluded: curation churn (verify / select / retract) must not
    re-identify the corpus; quote changes stay visible by diffing
    the book rows themselves."""
    import hashlib as _hl
    gen_part = None
    if cur_gen:
        gen_part = {"model": cur_gen.get("model"),
                    "format": cur_gen.get("format")}
    tuples = sorted(
        ([b["fingerprint"], b["status"], b["parser_version"],
          b["text_root_hash"], b["source_hash"], b["vectors"]]
         for b in books),
        key=lambda t: t[0])
    canon = json.dumps({"generation": gen_part, "works": tuples},
                       sort_keys=True, separators=(",", ":"),
                       ensure_ascii=False)
    return _hl.sha256(canon.encode("utf-8")).hexdigest()


def _corpus_snapshot_data(learn_dir):
    """Build one corpus snapshot's payloads (header + book rows)
    from the local corpus. Returns {"present": False, "reason":
    "absent" | "unavailable"} when there is nothing to snapshot,
    else {"present": True, "header": ..., "books": [...]}.

    Field discipline is whitelist-only (spec §5): every shipped
    value is projected field by field from a named column or a
    named payload key — the raw payload, the raw envelope JSON and
    the raw identifier list are never copied. Per-work fields come
    from a direct corpus_works query; the aggregate counts come
    from grouped queries, and the vector count / coverage are
    computed exactly as _corpus_status_data computes them (a
    current-generation JOIN count, coverage rounded to 4 places),
    so a snapshot reconciles against --corpus-status output."""
    import uuid as _uuid
    d = _explain_learn_dir(learn_dir)
    if not (d / _CORPUS_DB_NAME).exists():
        return {"present": False, "reason": "absent"}
    # The read opens the corpus DIRECTLY in report mode on a
    # read-only handle — never via _corpus_db_for, whose ordinary
    # open path stamps probe results into meta and can rebuild the
    # FTS index: the snapshot must not mutate the corpus it
    # observes. No embedder is consulted and no canary runs, so a
    # generation's canary value is its state as last recorded by
    # corpus operations, exactly as the spec states.
    try:
        db = CorpusDB.open(d, mode="report", readonly=True)
    except Exception:
        db = None
    if db is None:
        # corpus.db exists but would not open: the open discipline
        # has already warned and preserved the file as .corrupt.
        # That is an UNAVAILABLE corpus, not an absent one — the
        # two must never be reported as each other.
        return {"present": False, "reason": "unavailable"}
    try:
        captured_at = _corpus_now()
        cur_ptr = None
        raw_ptr = db.meta_get("generation_current")
        if raw_ptr:
            try:
                cur_ptr = json.loads(raw_ptr)
            except (TypeError, ValueError):
                cur_ptr = None
        cur_gen = None
        if isinstance(cur_ptr, dict) and cur_ptr.get("model"):
            cur_gen = _corpus_generation(
                db, cur_ptr["model"],
                cur_ptr.get("format") or _CORPUS_VECTOR_FORMAT)
        generations = []
        for g in _corpus_generations(db):
            proj = _snapshot_generation_projection(g)
            if proj is not None:
                generations.append(proj)
        # Aggregate counts via grouped queries — the same measured
        # values _corpus_status_data reaches per work, without a
        # query per work.
        passage_counts = dict(db.query(
            "SELECT fingerprint, COUNT(*) FROM corpus_passages "
            "GROUP BY fingerprint"))
        vector_counts = {}
        if cur_gen:
            vector_counts = dict(db.query(
                "SELECT p.fingerprint, COUNT(*) FROM passage_vectors "
                "pv JOIN corpus_passages p "
                "ON p.passage_id = pv.passage_id "
                "WHERE pv.model=? AND pv.format=? "
                "GROUP BY p.fingerprint",
                (cur_gen.get("model"), cur_gen.get("format"))))
        quote_counts = {}
        for fp, qstatus, n in db.query(
                "SELECT fingerprint, status, COUNT(*) FROM quotes "
                "GROUP BY fingerprint, status"):
            qc = quote_counts.setdefault(
                fp, {"total": 0, "by_status": {}, "selected": 0})
            qc["by_status"][qstatus] = n
            qc["total"] += n
        for qc in quote_counts.values():
            qc["selected"] = qc["by_status"].get("selected", 0)
        # The envelope contributes its corpus_v and computed_at
        # COLUMNS only — the envelope JSON itself (stage sections,
        # retraction reasons, quote text hashes) is never parsed
        # here, let alone shipped.
        envelopes = {fp: (cv, ca) for fp, cv, ca in db.query(
            "SELECT fingerprint, corpus_v, computed_at "
            "FROM work_envelope")}
        books = []
        by_status = {}
        for row in db.query(
                "SELECT fingerprint, book_key, work_id, title, "
                "author, identifiers, series, series_index, "
                "parser_version, chapter_count, text_root_hash, "
                "source_hash, status, ingested_at, updated_at, "
                "payload FROM corpus_works ORDER BY fingerprint"):
            (fp, book_key, work_id, title, author, identifiers,
             series, series_index, parser_version, chapter_count,
             text_root_hash, source_hash, status, ingested_at,
             updated_at, payload_raw) = row
            try:
                payload = json.loads(payload_raw) if isinstance(
                    payload_raw, str) else {}
            except (TypeError, ValueError):
                payload = {}
            if not isinstance(payload, dict):
                payload = {}
            # The ingest payload is projected to exactly two keys:
            # word_count and chapter_detection_fallback. Its
            # source_name (a filename) and series_source never ship.
            words = payload.get("word_count")
            if not isinstance(words, int) or isinstance(words, bool):
                words = None
            fallback = payload.get("chapter_detection_fallback")
            n_pass = passage_counts.get(fp, 0)
            if cur_gen:
                n_vec = vector_counts.get(fp, 0)
                coverage = (round(n_vec / n_pass, 4) if n_pass
                            else None)
            else:
                # No current generation: every work's vector state
                # is unknown, and unknown ships as NULL — a
                # measured-looking 0 would claim embedding coverage
                # that was never assessed.
                n_vec = None
                coverage = None
            env = envelopes.get(fp)
            books.append({
                "fingerprint": fp,
                "book_key": book_key,
                "work_id": _snapshot_work_id(work_id),
                "title": title,
                "author": author,
                "isbn": _snapshot_isbn(identifiers),
                "series": series,
                "series_index": series_index,
                "status": status,
                "parser_version": parser_version,
                "chapters": chapter_count,
                "words": words,
                "passages": n_pass,
                "vectors": n_vec,
                "vector_coverage": coverage,
                "chapter_detection_fallback": (
                    bool(fallback) if fallback is not None else None),
                "text_root_hash": text_root_hash,
                "source_hash": source_hash,
                "quotes": quote_counts.get(
                    fp, {"total": 0, "by_status": {},
                         "selected": 0}),
                "envelope_corpus_v": env[0] if env else None,
                "envelope_computed_at": env[1] if env else None,
                "ingested_at": ingested_at,
                "updated_at": updated_at,
            })
            if status is not None:
                by_status[status] = by_status.get(status, 0) + 1
        try:
            breakdown = _corpus_size_breakdown(db)
        except Exception:
            breakdown = None
        quotes_by_status = {}
        for qc in quote_counts.values():
            for s, n in qc["by_status"].items():
                quotes_by_status[s] = (
                    quotes_by_status.get(s, 0) + n)
        header = {
            "snapshot_key": f"snapshot-{_uuid.uuid4().hex}",
            "captured_at": captured_at,
            "machine_label": CONFIG.get("machine_label") or None,
            "processor_version": PORTABLE_VERSION,
            "corpus_parser_version": CORPUS_PARSER_VERSION,
            "corpus_v": CORPUS_V,
            "corpus_fingerprint": _corpus_snapshot_fingerprint(
                cur_gen, books),
            "works_count": len(books),
            "corpus_bytes": (breakdown or {}).get("total"),
            "size_breakdown": breakdown or {},
            "fts_available": bool(db.fts_available),
            "current_generation": _snapshot_generation_projection(
                cur_gen),
            "generations": generations,
            "totals": {
                "works": len(books),
                "by_status": by_status,
                "quotes": sum(q["total"]
                              for q in quote_counts.values()),
                "quotes_by_status": quotes_by_status,
            },
            "complete": False,
        }
        return {"present": True, "header": header, "books": books}
    finally:
        db.close()


def _snapshot_delete_header(snapshot_id):
    """Delete a snapshot header (its book rows follow via the
    internal CASCADE). Confirmed ONLY by a non-None, non-empty
    response: the REST helper returns the deleted rows under
    return=representation, so an empty or None response leaves the
    delete unproven and the caller names the snapshot key for
    manual cleanup instead of claiming it."""
    rows = sb("processor_corpus_snapshots", method="DELETE",
              params=f"?id=eq.{snapshot_id}",
              schema=_SNAPSHOT_SCHEMA)
    return bool(rows)


def _snapshot_fail_cleanup(header, snapshot_id, reason):
    """The common upload-failure tail (spec §7): try to leave no
    partial snapshot behind, and say plainly whether the cleanup
    is proven. The snapshot key is named either way — it is the
    handle a manual cleanup needs."""
    key = header["snapshot_key"]
    if _snapshot_delete_header(snapshot_id):
        print(f"  Corpus snapshot: upload failed ({reason}); "
              f"snapshot {key} was deleted — no partial snapshot "
              f"remains.")
    else:
        print(f"  Corpus snapshot: upload failed ({reason}); "
              f"cleanup of snapshot {key} could not be confirmed "
              f"— delete that snapshot_key from "
              f"processor_corpus_snapshots manually.")
    return 1


def cmd_corpus_snapshot(learn_dir=None, as_json=False):
    """--corpus-snapshot: upload one metadata-only snapshot of
    the local corpus (docs/corpus-snapshot-spec.md) and return
    the exit code: 0 shipped, 1 the upload failed (partial state
    deleted, or named for manual cleanup), 2 nothing to snapshot
    / corpus unavailable / Supabase not configured. Invoking the
    command is itself the named act: it does not consult the
    run-history setting, never arms the run-history recorder, and
    never takes a snapshot implicitly on any other path."""
    data = _corpus_snapshot_data(learn_dir)
    if not data["present"]:
        if data["reason"] == "absent":
            print("  Corpus snapshot: no corpus.db in the learn "
                  "dir — nothing to snapshot.")
        else:
            print("  Corpus snapshot: the corpus is unavailable "
                  "(see the warning above) — nothing uploaded.")
        return 2
    # The config guard stands before ANY sb() call: an unconfigured
    # install must make zero requests, not one failed one.
    if not (CONFIG.get("supabase_url") and CONFIG.get("supabase_key")):
        print("  Corpus snapshot: supabase_url/supabase_key are "
              "not set in config.json — nothing uploaded.")
        return 2
    header = data["header"]
    books = data["books"]
    key = header["snapshot_key"]
    # Upload order (spec §7): the header first, stamped
    # complete=false, so a snapshot interrupted mid-upload exists
    # only as a visibly partial row — and the failure paths below
    # delete it rather than leaving even that behind.
    rows = sb("processor_corpus_snapshots", method="POST",
              data=[header], schema=_SNAPSHOT_SCHEMA)
    if not rows or not rows[0].get("id"):
        # No usable response: the insert may still have landed (a
        # response can be lost after the commit), so probe by the
        # client-generated UNIQUE snapshot_key before declaring
        # anything, and delete a landed header.
        probe = sb("processor_corpus_snapshots", method="GET",
                   params=(f"?snapshot_key=eq.{key}&select=id"),
                   schema=_SNAPSHOT_SCHEMA)
        landed_id = probe[0].get("id") if probe else None
        if landed_id and _snapshot_delete_header(landed_id):
            print(f"  Corpus snapshot: upload failed "
                  f"(no-response); the landed header for snapshot "
                  f"{key} was deleted — no partial snapshot "
                  f"remains.")
        elif probe is not None and not probe:
            print(f"  Corpus snapshot: upload failed "
                  f"(no-response); no landed header was found "
                  f"under snapshot {key}.")
        else:
            print(f"  Corpus snapshot: upload failed "
                  f"(no-response); cleanup of snapshot {key} "
                  f"could not be confirmed — delete that "
                  f"snapshot_key from processor_corpus_snapshots "
                  f"manually.")
        return 1
    snapshot_id = rows[0]["id"]
    for start in range(0, len(books), _SNAPSHOT_BOOK_CHUNK):
        chunk = books[start:start + _SNAPSHOT_BOOK_CHUNK]
        for b in chunk:
            b["snapshot_id"] = snapshot_id
        sent = sb("processor_corpus_snapshot_books", method="POST",
                  data=chunk, schema=_SNAPSHOT_SCHEMA)
        # A chunk counts as landed only when the response carries
        # exactly the rows sent: a short response means rows the
        # finalize step would otherwise have blessed are missing.
        if sent is None or len(sent) != len(chunk):
            return _snapshot_fail_cleanup(
                header, snapshot_id,
                "book-chunk" if sent is None else "book-count")
    fin = sb("processor_corpus_snapshots", method="PATCH",
             data={"complete": True},
             params=f"?id=eq.{snapshot_id}", schema=_SNAPSHOT_SCHEMA)
    if not fin:
        return _snapshot_fail_cleanup(header, snapshot_id,
                                      "finalize")
    if as_json:
        # The receipt names the snapshot and nothing more — never
        # the full payload.
        print(json.dumps(
            {"snapshot_key": key,
             "captured_at": header["captured_at"],
             "works": header["works_count"],
             "corpus_fingerprint": header["corpus_fingerprint"]},
            separators=(",", ":")))
    else:
        size = header["corpus_bytes"]
        size_txt = (f"{size:,} bytes" if size is not None
                    else "size unmeasured")
        print(f"  Corpus snapshot {key}: "
              f"{header['works_count']} works · corpus "
              f"fingerprint {header['corpus_fingerprint'][:12]} "
              f"· {size_txt}")
    return 0


# ---------------------------------------------------------------------------
# --explain (§7.1): the forensics join over both stores. Read-only:
# the corpus side is a report-mode handle, the state side a mode=ro
# SQLite connection; the command writes nothing, and says plainly
# which half is absent when a store is missing.
# ---------------------------------------------------------------------------

def _explain_learn_dir(learn_dir):
    return (Path(learn_dir) if learn_dir
            else Path(os.path.expanduser("~")) / ".ebook-processor"
            / "learned")


def _match_work_row(rows, work, key_idx, title_idx):
    """Resolve a work query against store rows: exact fingerprint
    / work_key first, then prefix, then title (exact, then
    contains). rows are tuples with the key at key_idx and the
    title at title_idx."""
    if not rows:
        return None
    for row in rows:
        if row[key_idx] == work:
            return row
    for row in rows:
        if row[key_idx] and str(row[key_idx]).startswith(work):
            return row
    folded = str(work).casefold()
    for row in rows:
        if str(row[title_idx] or "").casefold() == folded:
            return row
    for row in rows:
        if folded in str(row[title_idx] or "").casefold():
            return row
    return None


def _explain_state_conn(d):
    """A read-only connection to state.db, or None when absent."""
    path = d / _STATE_DB_NAME
    if not path.exists():
        return None
    return sqlite3.connect(f"file:{path}?mode=ro", uri=True)


def explain_data(learn_dir, work, claim=None, character=None):
    """The §7.1 read model: one work, both stores, joined. Pure
    reads; absent halves are named in "absent", never papered
    over."""
    d = _explain_learn_dir(learn_dir)
    data = {"work": work, "absent": [], "corpus": None,
            "state": None, "claim": None, "character": None}
    # -- corpus half ------------------------------------------------
    cdb = _corpus_db_for(d, mode="report")
    corpus_rec = None
    if cdb is None:
        data["absent"].append("corpus")
    else:
        rows = cdb.query(
            "SELECT fingerprint, title, author, status, "
            "chapter_count, series FROM corpus_works "
            "ORDER BY title, fingerprint")
        row = _match_work_row(rows, work, 0, 1)
        if row is not None:
            fp = row[0]
            corpus_rec = {"fingerprint": fp, "title": row[1],
                          "author": row[2],
                          "status": corpus_work_state(cdb, fp),
                          "chapter_count": row[4], "series": row[5],
                          "quotes": [], "stages": {}}
            for q in _corpus_quote_rows(cdb, fp, (
                    "candidate", "verified", "selected",
                    "rejected")):
                entry = {"text": q["text"], "kind": q["kind"],
                         "status": q["status"],
                         "chapter_index": q["chapter_index"],
                         "spoiler_tier": q["payload"].get(
                             "spoiler_tier")}
                poll = q["payload"].get("poll") or {}
                if poll:
                    entry["screens"] = {
                        "spoiler": "pass" if poll.get(
                            "spoiler", 1) < _QUOTE_SCREEN_MAX
                        else "fail",
                        "heat": "pass" if poll.get(
                            "heat", 1) < _QUOTE_SCREEN_MAX
                        else "fail"}
                corpus_rec["quotes"].append(entry)
            for stage, n in cdb.query(
                    "SELECT stage, COUNT(*) FROM stage_outputs "
                    "WHERE fingerprint=? GROUP BY stage", (fp,)):
                corpus_rec["stages"][stage] = n
            data["corpus"] = corpus_rec
    # -- state half ---------------------------------------------------
    conn = _explain_state_conn(d)
    state_rec = None
    work_key = work_id = None
    claim_row = None
    if conn is None:
        data["absent"].append("state.db")
    else:
        try:
            rows = conn.execute(
                "SELECT work_key, work_id, title, author, "
                "runs_completed, staged_ever FROM staging_works "
                "ORDER BY title, work_key").fetchall()
            row = _match_work_row(rows, work, 0, 2)
            if row is None:
                rows = conn.execute(
                    "SELECT work_key, work_id, title, author, "
                    "runs_completed, NULL FROM roster_works "
                    "ORDER BY title, work_key").fetchall()
                row = _match_work_row(rows, work, 0, 2)
            if row is not None:
                (work_key, work_id, title, author, runs,
                 staged) = row
                state_rec = {"work_key": work_key,
                             "work_id": work_id, "title": title,
                             "author": author,
                             "runs_completed": runs,
                             "staged_ever": staged}
                data["state"] = state_rec
            # -- claim block --------------------------------------
            if claim is not None and work_key is not None:
                crow = conn.execute(
                    "SELECT claim_key, class, display, state, "
                    "promoted_run, promoted_via, best_chapters, "
                    "evidence_ever, first_seen, last_seen, "
                    "sightings, name_forms FROM staging_claims "
                    "WHERE work_key=? AND (claim_key=? OR "
                    "claim_key=?)",
                    (work_key, claim, _tnorm(claim))).fetchone()
                if crow is not None:
                    claim_row = crow
                    block = {
                        "claim_key": crow[0], "class": crow[1],
                        "display": crow[2], "state": crow[3],
                        "promotion": (
                            {"run": crow[4], "via": crow[5]}
                            if crow[4] is not None else None),
                        "best_chapters": crow[6],
                        "evidence_ever": bool(crow[7]),
                        "first_seen": crow[8], "last_seen": crow[9],
                        "sightings": _json_or(crow[10], []),
                        "name_forms": _json_or(crow[11], []),
                        "suppression": [
                            {"id": r[0], "run_ref": r[1],
                             "created": r[2]}
                            for r in conn.execute(
                                "SELECT id, run_ref, created FROM "
                                "rejection_events WHERE work_key=? "
                                "AND claim_key=? ORDER BY id",
                                (work_key, crow[0]))],
                        "verdict": None, "retrieve": None}
                    vrow = conn.execute(
                        "SELECT verdict, fetched_at FROM "
                        "verdicts_cache WHERE work_id=? AND "
                        "class=? AND claim_key=?",
                        (work_id, crow[1], crow[0])).fetchone()
                    if vrow is not None:
                        block["verdict"] = {
                            "verdict": vrow[0],
                            "fetched_at": vrow[1]}
                    data["claim"] = block
            # -- character block ----------------------------------
            if character is not None and work_key is not None:
                data["character"] = _explain_character(
                    conn, cdb, corpus_rec, work_key, character)
        finally:
            conn.close()
    # The retrieve half of a claim lives in the corpus; join it
    # once both halves are known.
    if data["claim"] is not None and corpus_rec is not None \
            and cdb is not None:
        outputs = corpus_stage_outputs(cdb, corpus_rec["fingerprint"],
                                       "retrieve")
        row = outputs.get(data["claim"]["claim_key"])
        if row is not None:
            rec = (row.get("payload") or {}).get("record") or {}
            data["claim"]["retrieve"] = {
                "outcome": rec.get("outcome"),
                "support": rec.get("support"),
                "chapters_searched": rec.get("chapters_searched"),
                "chapters_with_support":
                    rec.get("chapters_with_support"),
                "passages": (row.get("payload") or {}).get(
                    "evidence") or []}
    return data


def _json_or(raw, default):
    try:
        parsed = json.loads(raw) if raw else default
        return parsed if parsed is not None else default
    except (TypeError, ValueError):
        return default


def _explain_character(conn, cdb, corpus_rec, work_key, character):
    """Roster lineage + occurrences for one character (§7.1).
    Occurrence counts come from the chapter texts themselves —
    the same authority verify_quote answers to — with the first
    and last citations as chapter + offset; the work's series, if
    any, extends the scan across the series' ingested works."""
    entity_rows = list(conn.execute(
        "SELECT entity_id, status, canonical, payload FROM "
        "roster_entities WHERE work_key=?", (work_key,)))
    if not entity_rows and conn.execute(
            "SELECT 1 FROM roster_works WHERE work_key=?",
            (work_key,)).fetchone() is None:
        # No roster record of either kind: the work has never had
        # a roster persisted (previews and replays write none), so
        # "not found" would blame the character for a missing
        # precondition. The flag lets the report say which case
        # it is — the fixes are entirely different.
        return {"name": character, "found": False,
                "no_roster": True}
    erow = None
    for row in entity_rows:
        payload = _json_or(row[3], {})
        forms = payload.get("name_forms") or [row[2]]
        if any(str(f).casefold() == character.casefold()
               for f in forms) \
                or str(row[2]).casefold() == character.casefold():
            erow = (row, payload, forms)
            break
    if erow is None:
        return {"name": character, "found": False}
    row, payload, forms = erow
    entity_id, status, canonical = row[0], row[1], row[2]
    block = {"name": character, "found": True,
             "entity_id": entity_id, "status": status,
             "canonical": canonical, "name_forms": forms,
             "lineage": payload,
             "no_pairs": [
                 {"a": r[0], "b": r[1], "source": r[2]}
                 for r in conn.execute(
                     "SELECT a_key, b_key, source FROM "
                     "roster_no_pairs WHERE work_key=? AND "
                     "(a_key IN (%s) OR b_key IN (%s))"
                     % (",".join("?" * len(forms)),
                        ",".join("?" * len(forms))),
                     (work_key, *[_tnorm(f) for f in forms],
                      *[_tnorm(f) for f in forms]))],
             "adoptions": [
                 _json_or(r[0], {}) for r in conn.execute(
                     "SELECT payload FROM roster_adoptions WHERE "
                     "work_key=? ORDER BY seq", (work_key,))
                 if any(f.casefold() in str(r[0]).casefold()
                        for f in forms)],
             "anchor_retirements": [
                 {"entity_id": r[0], "run": r[1],
                  "payload": _json_or(r[2], {})}
                 for r in conn.execute(
                     "SELECT entity_id, run, payload FROM "
                     "roster_anchor_retirements WHERE work_key=? "
                     "AND entity_id=?", (work_key, entity_id))],
             "occurrences": None}
    if cdb is not None and corpus_rec is not None:
        fps = [corpus_rec["fingerprint"]]
        if corpus_rec.get("series"):
            fps = [r[0] for r in cdb.query(
                "SELECT fingerprint FROM corpus_works WHERE "
                "series=? ORDER BY fingerprint",
                (corpus_rec["series"],))]
        block["occurrences"] = _character_occurrences(
            cdb, fps, forms)
    return block


def _character_occurrences(cdb, fingerprints, forms):
    by_form = {f: 0 for f in forms}
    chapters_hit, first, last = [], None, None
    for fp in fingerprints:
        for ch in corpus_chapters_for(cdb, fp):
            text = ch["text"]
            folded = text.casefold()
            hit = False
            for form in forms:
                n = folded.count(form.casefold())
                if n:
                    by_form[form] += n
                    hit = True
            if hit:
                chapters_hit.append(ch["index"])
                for form in forms:
                    off = folded.find(form.casefold())
                    if off >= 0:
                        cite = {"fingerprint": fp,
                                "chapter_index": ch["index"],
                                "offset": off}
                        if first is None:
                            first = cite
                        last = cite
                        break
    return {"by_form": by_form, "chapters": chapters_hit,
            "first": first, "last": last}


def explain_text(learn_dir, work, claim=None, character=None):
    data = explain_data(learn_dir, work, claim=claim,
                        character=character)
    lines = [f"Explain: {work}"]
    if data["corpus"] is None:
        lines.append("  corpus: absent" if "corpus" in data["absent"]
                     else "  corpus: no matching work")
    else:
        c = data["corpus"]
        lines.append(
            f"  corpus: {c['title']} [{c['fingerprint'][:12]}…] "
            f"state {c['status']}, {c['chapter_count']} chapters")
        for q in c["quotes"]:
            lines.append(
                f"    quote ({q['kind']}/{q['status']}, "
                f"ch {q['chapter_index']}): {q['text']!r}")
    if data["state"] is None:
        lines.append("  state.db: absent"
                     if "state.db" in data["absent"]
                     else "  state.db: no matching work")
    else:
        s = data["state"]
        lines.append(
            f"  state.db: {s['title']} (work_key {s['work_key']}, "
            f"{s['runs_completed']} runs)")
    if claim is not None:
        cl = data["claim"]
        if cl is None:
            lines.append(f"  claim {claim}: not found in staging")
        else:
            lines.append(
                f"  claim {cl['display']}: state {cl['state']}, "
                f"{len(cl['sightings'])} sightings, "
                f"promotion {cl['promotion']}, "
                f"verdict {cl['verdict']}, "
                f"suppressions {len(cl['suppression'])}")
            if cl["retrieve"]:
                lines.append(
                    f"    retrieve: {cl['retrieve']['outcome']} "
                    f"(support {cl['retrieve']['support']}), "
                    f"searched {cl['retrieve']['chapters_searched']}")
    if character is not None:
        ch = data["character"]
        if ch is None or ch.get("no_roster"):
            # No persisted roster exists for this work (the state
            # half never matched it, or matched it without any
            # roster record), so the character check itself is
            # unavailable — a different fact from an absent
            # character, and one that sends the reader to a
            # different fix (a roster-persisting run, not a roster
            # correction).
            lines.append(
                f"  character {character}: check unavailable — "
                f"this work has no persisted roster in state.db")
        elif not ch.get("found"):
            lines.append(f"  character {character}: not on the "
                         f"work's roster")
        else:
            lines.append(
                f"  character {ch['canonical']} ({ch['entity_id']}): "
                f"forms {ch['name_forms']}, "
                f"no-pairs {len(ch['no_pairs'])}")
            if ch["occurrences"]:
                lines.append(
                    f"    occurrences: {ch['occurrences']['by_form']}"
                    f" in chapters "
                    f"{ch['occurrences']['chapters']}")
    return "\n".join(lines)


def cmd_explain(work, claim=None, character=None, learn_dir=None):
    """--explain (§7.1): print the forensics report and return the
    read model. Human-invoked, read-only."""
    print(explain_text(learn_dir, work, claim=claim,
                       character=character))
    return explain_data(learn_dir, work, claim=claim,
                        character=character)


def cmd_corpus_verify_quote(fingerprint, quote, learn_dir=None):
    """--corpus-verify-quote: check ONE candidate quote against
    one work's corpus text, on demand (§10.1), and print the
    verdict. The quote-verify STAGE settles its verdicts as stage
    outputs; this command exists for the questions a human asks
    outside any run — a planted candidate, a spot check — so it
    deliberately records NOTHING: no quote row, no stage output,
    no envelope change. Returns the exit code: 0 verified,
    1 rejected, 2 when the question itself cannot be asked (no
    corpus, an unknown or ambiguous fingerprint, no servable
    text, or no --quote given)."""
    d = _explain_learn_dir(learn_dir)
    if quote is None:
        print("  --corpus-verify-quote needs --quote \"<text>\": "
              "the candidate wording to check.")
        return 2
    db = _corpus_db_for(d, mode="report")
    if db is None:
        print(f"  No corpus in {d} — nothing to verify against.")
        return 2
    rec = corpus_work_record(db, fingerprint)
    if rec is None:
        # Exact match failed; accept the prefix form the status
        # and explain outputs print, but only when it names
        # exactly one work — a guess here would verify against
        # the wrong book.
        matches = [r[0] for r in db.query(
            "SELECT fingerprint FROM corpus_works")
            if r[0].startswith(fingerprint)]
        if len(matches) == 1:
            rec = corpus_work_record(db, matches[0])
        elif len(matches) > 1:
            print(f"  Fingerprint {fingerprint} is ambiguous — "
                  f"{len(matches)} corpus works start with it.")
            return 2
    if rec is None:
        print(f"  No corpus work with fingerprint {fingerprint}.")
        return 2
    fp = rec["fingerprint"]
    chapters = corpus_chapters_for(db, fp)
    if chapters is None:
        print(f"  Corpus work {fp[:12]}… has no servable text "
              f"(state {corpus_work_state(db, fp)}) — nothing to "
              f"verify against.")
        return 2
    record = verify_quote(db, fp, quote)
    if record is None:
        print("rejected — no matching chapter")
        return 1
    label = next((c["label"] for c in chapters
                  if c["index"] == record["chapter_index"]), None)
    where = f"chapter {record['chapter_index']}"
    if label:
        where += f" ({label})"
    print(f"verified — {where}")
    return 0


# ---------------------------------------------------------------------------
# --backup-state / --restore-state (§7.2): the PAIR as one act.
# A backup is both stores, copied via the backup API, plus a
# manifest carrying each file's logical dump hash, both schema
# versions, the portable version and the timestamp; a directory
# missing any element is not a backup. Restore verifies every
# hash BEFORE touching a live file, refuses a major schema
# mismatch up front, and keeps the replaced live pair as
# <name>.pre-restore-<date>. Human-invoked only; no run path ever
# calls these.
# ---------------------------------------------------------------------------

def cmd_backup_state(dest_dir, learn_dir=None):
    d = _explain_learn_dir(learn_dir)
    dest = Path(dest_dir)
    stores = {}
    plan = []
    if (d / _STATE_DB_NAME).exists():
        plan.append(("state", _state_db_for(d), StateDB))
    if (d / _CORPUS_DB_NAME).exists():
        plan.append(("corpus", _corpus_db_for(d, mode="report"),
                     CorpusDB))
    plan = [(k, h, cls) for k, h, cls in plan if h is not None]
    if not plan:
        print(f"  --backup-state: no stores present under {d} — "
              f"nothing to back up")
        return {"ok": False, "reason": "no stores present"}
    dest.mkdir(parents=True, exist_ok=True)
    for key, handle, cls in plan:
        handle.backup_to(dest / cls._DB_NAME)
        entry = {"present": True, "file": cls._DB_NAME,
                 "dump_hash": handle.dump_hash(),
                 "user_version": handle.query(
                     "PRAGMA user_version")[0][0]}
        if key == "corpus":
            entry["corpus_v"] = handle.meta_get("corpus_v")
        stores[key] = entry
    manifest = {"portable_version": PORTABLE_VERSION,
                "created": _corpus_now(), "stores": stores}
    (dest / "manifest.json").write_text(
        json.dumps(manifest, ensure_ascii=False, indent=1),
        encoding="utf-8")
    print(f"  Backup written to {dest}: "
          + ", ".join(sorted(stores)))
    return {"ok": True, "manifest": manifest, "dir": str(dest)}


def cmd_restore_state(src_dir, learn_dir=None):
    d = _explain_learn_dir(learn_dir)
    src = Path(src_dir)
    man_path = src / "manifest.json"
    if not man_path.exists():
        print(f"  --restore-state: {src} has no manifest.json — "
              f"not a backup; nothing touched")
        return {"ok": False, "reason": "no manifest"}
    try:
        manifest = json.loads(man_path.read_text(encoding="utf-8"))
    except (TypeError, ValueError) as e:
        print(f"  --restore-state: manifest unreadable ({e}); "
              f"nothing touched")
        return {"ok": False, "reason": "manifest unreadable"}
    stores = manifest.get("stores") or {}
    if not stores:
        print("  --restore-state: manifest lists no stores; "
              "nothing touched")
        return {"ok": False, "reason": "manifest lists no stores"}
    # Phase 1: verify EVERYTHING — hashes and versions — before a
    # single live file moves.
    plan = []
    for key, cls in (("state", StateDB), ("corpus", CorpusDB)):
        entry = stores.get(key)
        if entry is None or not entry.get("present"):
            plan.append((key, cls, None))
            continue
        backup_file = src / entry["file"]
        if not backup_file.exists():
            print(f"  --restore-state: backup file "
                  f"{entry['file']} missing; nothing touched")
            return {"ok": False,
                    "reason": f"backup file missing: {entry['file']}"}
        if entry.get("user_version") != cls._SCHEMA_VERSION:
            print(f"  --restore-state: {key} schema version "
                  f"mismatch (backup user_version "
                  f"{entry.get('user_version')} vs current "
                  f"{cls._SCHEMA_VERSION}) — major mismatch "
                  f"refused; nothing touched")
            return {"ok": False,
                    "reason": f"schema version mismatch for {key}"}
        try:
            conn = sqlite3.connect(
                f"file:{backup_file}?mode=ro", uri=True)
            try:
                digest = _dump_hash_conn(conn, cls._TABLES)
            finally:
                conn.close()
        except Exception as e:
            print(f"  --restore-state: backup file "
                  f"{entry['file']} unreadable ({e}); nothing "
                  f"touched")
            return {"ok": False,
                    "reason": f"backup file unreadable: "
                              f"{entry['file']}"}
        if digest != entry.get("dump_hash"):
            print(f"  --restore-state: dump hash mismatch for "
                  f"{key} — the backup file does not match its "
                  f"manifest; nothing touched")
            return {"ok": False,
                    "reason": f"dump hash mismatch for {key}"}
        plan.append((key, cls, backup_file))
    # Phase 2: close live handles, set the live pair aside
    # (rename-in-place, the F8/A11 posture), copy the verified
    # backups in through the backup API.
    _close_state_dbs()
    _close_corpus_dbs()
    stamp = _staging_today()
    for key, cls, backup_file in plan:
        live = d / cls._DB_NAME
        if live.exists():
            aside = live.with_name(
                live.name + f".pre-restore-{stamp}")
            for suffix in ("", "-wal", "-shm"):
                side = Path(str(live) + suffix)
                if side.exists():
                    os.replace(side, Path(str(aside) + suffix))
            print(f"  {cls._DB_NAME}: live file kept as "
                  f"{aside.name}")
        if backup_file is not None:
            src_conn = sqlite3.connect(
                f"file:{backup_file}?mode=ro", uri=True)
            try:
                dst_conn = sqlite3.connect(str(live))
                try:
                    src_conn.backup(dst_conn)
                finally:
                    dst_conn.close()
            finally:
                src_conn.close()
            print(f"  {cls._DB_NAME}: restored from backup")
    return {"ok": True}


def _effective_titles():
    """Hardcoded titles plus learned trusted titles."""
    return _TITLES | _learn().trusted_titles()


# Module-level validator, set from --decision-model-url in main().
# None = use regex gates (default).
_DECISION_VALIDATOR = None


