def _watch_cycle(args):
    """One watch-mode cycle after the auto-update check: the optional
    import-folder ingest, then the scan.

    Split out of main()'s loop so the cycle's ordering is testable
    without running the loop itself. Ingest runs before the scan of
    the same cycle so a book dropped into the import folder is
    corpus-sourced by that scan instead of one cycle late. The ingest
    is guarded because watch mode's job is to keep scanning: a
    corpus-side failure costs one printed warning and the scan still
    runs, and the next cycle retries the ingest on its own.
    """
    # The history hint: run_once reads it to mode this cycle's run
    # row "watch_cycle" (each cycle is its own run). The cycle's own
    # ingest is part of the cycle, not a separate ingest run.
    global _HISTORY_WATCH
    _HISTORY_WATCH = {"watch_ingest": bool(
        getattr(args, "watch_ingest", False))}
    try:
        if getattr(args, "watch_ingest", False):
            try:
                cmd_ingest([IMPORT_DIR],
                           learn_dir=args.learn_dir or None,
                           reason="watch cycle")
            except Exception as e:
                print(f"  watch: ingest failed this cycle ({e}); "
                      "scanning anyway")
        run_once(args.dry_run, args.preview, args.max_books, args.file)
    finally:
        _HISTORY_WATCH = None


# One-shot commands dispatch and exit: exactly one operation runs and
# every other operation or mode flag on the command line is silently
# dropped. The dispatch chain below main's parse is a long sequence
# of `if args.<flag>: ... return`, so `--validate X --push-preview X`
# validated only, `--watch --verify X` verified and never watched,
# and `--push-preview X --file book.epub` pushed and never processed
# the book — with no notice anywhere. Combinations now refuse at
# startup instead: a requested operation that will not happen must
# be named, not silently ignored.
#
# The two lists are deliberately narrow. Companion arguments that aim
# a one-shot (--learn-dir, --json, --quote, --work, --explain-claim,
# --ingest-reason/--ingest-force, ...) are NOT conflicts: the winning
# command honours them. Run-shaping settings (--llm, --batch, --jobs,
# --run-history, ...) are NOT conflicts either: they are configuration
# the run path threads into CONFIG, and no second operation hides
# among them. What conflicts is a second OPERATION (another one-shot)
# or a MODE/TARGET that only a book-processing run or watch/replay
# cycle could honour — those are what a one-shot dispatch drops.
_ONE_SHOT_FLAGS = {
    "list_profiles": "--list-profiles",
    "save_profile": "--save-profile",
    "trope_map": "--trope-map",
    "preview_diff": "--preview-diff",
    "recalibrate_spice": "--recalibrate-spice",
    "validate": "--validate",
    "push_preview": "--push-preview",
    "retry_failed": "--retry-failed",
    "verify": "--verify",
    "learn_status": "--learn-status",
    "apply_uncertainty_labels": "--apply-uncertainty-labels",
    "staging_report": "--staging-report",
    "roster_report": "--roster-report",
    "roster_link": "--roster-link",
    "roster_unlink": "--roster-unlink",
    "roster_split": "--roster-split",
    "corpus_status": "--corpus-status",
    "corpus_snapshot": "--corpus-snapshot",
    "run_history_backfill": "--run-history-backfill",
    "explain": "--explain",
    "corpus_verify_quote": "--corpus-verify-quote",
    "backup_state": "--backup-state",
    "restore_state": "--restore-state",
    "ingest": "--ingest",
    "corpus_remove": "--corpus-remove",
    "corpus_reembed": "--corpus-reembed",
    "calibration_report": "--calibration-report",
    # --replay dispatches in the run path rather than the chain
    # above, but it is the same shape: it runs alone and exits, so a
    # second operation beside it would be dropped exactly the same.
    "replay": "--replay",
}

# Modes, targets and per-run selectors that only a book-processing
# run (or watch cycle) honours — silently dropped when a one-shot
# dispatch pre-empts the run.
_RUN_MODE_FLAGS = {
    "watch": "--watch",
    "watch_ingest": "--watch-ingest",
    "file": "--file",
    "preview": "--preview",
    "dry_run": "--dry-run",
    "guided": "--guided",
    "profile": "--profile",
    "auto_update": "--auto-update",
    "capture_snapshot": "--capture-snapshot",
    "resume": "--resume",
    "alias": "--alias",
    "chunks": "--chunks",
    "import_labels": "--import-labels",
    "import_rejections": "--import-rejections",
    "from_supabase": "--from-supabase",
    "isbn": "--isbn",
    "max_books": "--max-books",
    "series": "--series",
    "series_position": "--series-position",
}


def _flag_conflicts(args, defaults):
    """Name an operation/mode combination the dispatch would
    silently half-serve, or None when the invocation is coherent.

    A flag counts as present when its parsed value differs from its
    default (the _apply_profile test for "explicitly set"), so a
    defaulted dest never trips the check. --file beside --replay is
    the one designed pairing in these lists: replay replays against
    its own book file and refuses without one, so it is exempted —
    every other run-mode flag beside a one-shot is a drop."""
    def _present(mapping):
        return [flag for dest, flag in mapping.items()
                if getattr(args, dest, None) != getattr(defaults, dest, None)]

    shots = _present(_ONE_SHOT_FLAGS)
    if not shots:
        return None
    modes = _present(_RUN_MODE_FLAGS)
    if shots == ["--replay"]:
        modes = [m for m in modes if m != "--file"]
    if shots == ["--save-profile"]:
        # --save-profile's whole job is capturing run-shaping
        # settings, and preview/dry_run are persistable settings it
        # honours (both are in _PROFILE_PERSISTABLE and _save_profile
        # writes them): the pairing was never a dropped mode, only a
        # captured setting, so it is exempt. Every other run-mode
        # flag beside --save-profile still refuses as before.
        modes = [m for m in modes
                 if m not in ("--preview", "--dry-run")]
    if shots == ["--run-history-backfill"]:
        # --dry-run is the backfill's own preview posture: the
        # command honours it (build and scan the payloads, write
        # nothing), so the pairing is a served combination, not a
        # dropped mode. Every other run-mode flag beside it still
        # refuses as before.
        modes = [m for m in modes if m != "--dry-run"]
    if len(shots) == 1 and not modes:
        return None
    parts = []
    if len(shots) > 1:
        parts.append(f"{', '.join(shots)} are separate one-shot "
                     "commands — only the first would run and the "
                     "rest would be silently ignored")
    if modes:
        parts.append(f"{shots[0]} is a one-shot command and cannot "
                     f"combine with {', '.join(modes)} — the run/mode "
                     "flags would be silently ignored")
    return "conflicting flags: " + "; ".join(parts) + \
        "; run them separately"


def main():
    ap = _build_parser()
    args = ap.parse_args()
    defaults = ap.parse_args([])

    # Refuse operation/mode combinations the dispatch chain would
    # silently half-serve (#51) BEFORE anything runs — before profile
    # loading, guided prompts, or any state migration — so a refused
    # invocation has no side effects. ap.error exits 2 with the
    # conflict named.
    _conflict = _flag_conflicts(args, defaults)
    if _conflict:
        ap.error(_conflict)

    if args.list_profiles:
        for name, src in sorted(_available_profiles().items()):
            print(f"  {name} ({src})")
        return

    if args.save_profile:
        path = _save_profile(args.save_profile, args, defaults)
        print(f"  Profile saved to {path}")
        return

    if args.guided:
        if not _guided_setup(args):
            return

    if args.profile:
        profile = _load_profile(args.profile)
        if profile is None:
            sys.exit(f"ERROR: profile '{args.profile}' not found "
                     "(--list-profiles to see available)")
        _apply_profile(args, defaults, profile)

    # Spine OC-7: the state stores migrate to the SQLite substrate
    # automatically on the first run that touches state. Placed
    # before every state-reading dispatch below (and before the
    # _LEARNED construction further down).
    ensure_state_migrated(
        Path(args.learn_dir) if getattr(args, "learn_dir", None)
        else Path(os.path.expanduser("~")) / ".ebook-processor"
        / "learned")

    if args.trope_map:
        load_config()
        cmd_trope_map(args.trope_map)
        return

    if args.preview_diff:
        print(_cmd_preview_diff(args.preview_diff[0], args.preview_diff[1]))
        return

    if args.recalibrate_spice:
        print(_cmd_recalibrate_spice(args.recalibrate_spice))
        return

    if args.validate:
        load_config()
        cmd_validate(args.validate)
        return

    if args.push_preview:
        load_config()
        # cmd_push_preview returns the exit code (the corpus_snapshot
        # convention): a push whose writes failed must exit nonzero,
        # or a caller chaining on the exit code reads a partial
        # write as success.
        sys.exit(cmd_push_preview(args.push_preview))

    if args.retry_failed:
        load_config()
        cmd_retry_failed(args.retry_failed)
        return

    if args.verify:
        load_config()
        cmd_verify(args.verify)
        return

    if args.learn_status:
        load_config()
        cmd_learn_status(args.learn_dir or None)
        return
    if getattr(args, "apply_uncertainty_labels", None):
        load_config()
        cmd_apply_uncertainty_labels(
            Path(args.learn_dir) if args.learn_dir
            else Path(os.path.expanduser("~")) / ".ebook-processor"
            / "learned",
            args.apply_uncertainty_labels)
        return
    if args.staging_report:
        load_config()
        cmd_staging_report(as_json=args.json,
                           learn_dir=args.learn_dir or None)
        return
    if args.roster_report:
        load_config()
        cmd_roster_report(learn_dir=args.learn_dir or None)
        return
    if args.roster_link:
        load_config()
        cmd_roster_link(*args.roster_link,
                        learn_dir=args.learn_dir or None)
        return
    if args.roster_unlink:
        load_config()
        cmd_roster_unlink(*args.roster_unlink,
                          learn_dir=args.learn_dir or None)
        return
    if args.roster_split:
        load_config()
        if len(args.roster_split) < 3:
            ap.error("--roster-split needs WORK ENTITY FORM "
                     "[FORM ...]")
        cmd_roster_split(args.roster_split[0], args.roster_split[1],
                         args.roster_split[2:],
                         learn_dir=args.learn_dir or None)
        return

    if args.corpus_status:
        load_config()
        cmd_corpus_status(args.learn_dir or None, as_json=args.json)
        return
    if args.corpus_snapshot:
        load_config()
        sys.exit(cmd_corpus_snapshot(args.learn_dir or None,
                                     as_json=args.json))
    if args.run_history_backfill:
        load_config()
        # cmd_run_history_backfill returns the exit code (the
        # corpus_snapshot convention): a backfill that skipped a
        # corrupt artifact must exit nonzero, or a caller chaining
        # on the exit code reads a partial backfill as complete.
        sys.exit(cmd_run_history_backfill(
            args.run_history_backfill, dry_run=args.dry_run,
            learn_dir=args.learn_dir or None))
    if args.explain:
        load_config()
        cmd_explain(args.explain,
                    claim=args.explain_claim or None,
                    character=args.explain_character or None,
                    learn_dir=args.learn_dir or None)
        return
    if args.corpus_verify_quote:
        load_config()
        sys.exit(cmd_corpus_verify_quote(
            args.corpus_verify_quote, args.quote,
            learn_dir=args.learn_dir or None))
    if args.backup_state:
        load_config()
        # The cmd reports refusal as {"ok": False} (nothing was
        # backed up); the exit code must say the same, or the portal
        # marks a Backup that did nothing as "done".
        _bk = cmd_backup_state(args.backup_state,
                               learn_dir=args.learn_dir or None)
        if isinstance(_bk, dict) and not _bk.get("ok"):
            sys.exit(1)
        return
    if args.restore_state:
        load_config()
        # Same contract as backup: an {"ok": False} refusal (no
        # manifest, hash mismatch, ...) exits nonzero.
        _rs = cmd_restore_state(args.restore_state,
                                learn_dir=args.learn_dir or None)
        if isinstance(_rs, dict) and not _rs.get("ok"):
            sys.exit(1)
        return
    if args.ingest:
        load_config()
        # A standalone ingest is its own run in the history mirror.
        # The capture flag scopes the recorder's ingest hook to this
        # dispatch: watch cycles ingest too, but their books belong
        # to the cycle's scan run, not an ingest row of their own.
        global _HISTORY_INGEST_CAPTURE
        _history_begin("ingest",
                       learn_dir=args.learn_dir or None)
        _HISTORY_INGEST_CAPTURE = True
        try:
            cmd_ingest([args.ingest], learn_dir=args.learn_dir or None,
                       reason=args.ingest_reason or "",
                       force=args.ingest_force)
        finally:
            _HISTORY_INGEST_CAPTURE = False
            _history_finish()
        return
    if args.corpus_remove:
        load_config()
        cmd_corpus_remove(args.corpus_remove,
                          learn_dir=args.learn_dir or None)
        return
    if args.corpus_reembed:
        load_config()
        cmd_corpus_reembed(learn_dir=args.learn_dir or None,
                           work=args.work or None)
        return
    if args.calibration_report:
        load_config()
        cmd_calibration_report(args.learn_dir or None,
                               as_json=args.json)
        return

    # Auto-update: check origin/master before doing any real work. On a
    # successful pull the process re-execs with fresh code (never returns).
    if args.auto_update and not args.watch:
        _do_auto_update()

    if args.prompt_cache:
        CONFIG["v2_prompt_cache"] = True
    if args.shared_system:
        CONFIG["v2_shared_system"] = True
    if args.task_last:
        CONFIG["v2_task_last"] = True
    if args.no_viz:
        UI.set_viz_enabled(False)
    _dm_enabled = bool(args.decision_model or args.decision_model_url
                       or args.decision_model_provider == "openrouter")
    if _dm_enabled and args.decision_model_provider == "openrouter" \
            and args.decision_model_url:
        print("  Warning: --decision-model-url is ignored with provider "
              "'openrouter' (endpoint is fixed)")
    if _dm_enabled:
        try:
            _dm_endpoint, _dm_model, _dm_key, _dm_headers = \
                resolve_decision_model(
                    args.decision_model_provider,
                    args.decision_model_url, CONFIG)
        except ValueError as e:
            print(f"  Error: {e}")
            # A decision model was requested but cannot be configured
            # (missing key / base URL): nothing will be processed, so
            # the exit code must not claim success — the portal reads
            # rc==0 as "done". A run that never asked for a decision
            # model never reaches this resolution and is unaffected.
            sys.exit(1)
        global _DECISION_VALIDATOR
        _DECISION_VALIDATOR = DecisionValidator(
            _dm_endpoint, model=_dm_model, api_key=_dm_key,
            extra_headers=_dm_headers)
        # Never print the API key.
        print(f"  Decision model trigger validation: "
              f"provider={args.decision_model_provider} "
              f"endpoint={_dm_endpoint} model={_dm_model}")
        # The run-history stamps read the decision model's identity
        # from CONFIG: the model NAME only. The endpoint is a URL
        # and never enters a payload (spec §5).
        CONFIG["decision_model"] = True
        CONFIG["decision_model_provider"] = \
            args.decision_model_provider
        CONFIG["decision_model_model"] = _dm_model

    # Cross-run learning state (shared across --jobs threads).
    global _LEARNED
    _LEARNED = LearnedState(
        learn_dir=args.learn_dir or None, enabled=args.learn)
    if args.learn:
        print(f"  Learning state: {_LEARNED.dir} "
              f"({len(_LEARNED.nicknames)} nicknames, "
              f"{len(_LEARNED.trusted_titles())} trusted titles, "
              f"{len(_LEARNED.rejected_tropes)} rejected tropes)")
    if getattr(args, "capture_snapshot", None):
        if getattr(args, "replay", None):
            print("  --capture-snapshot and --replay cannot combine")
            return
        _arm_capture(args.capture_snapshot,
                     getattr(args, "snapshot_reason", "") or "")
    if args.import_labels:
        n_imp = _LEARNED.import_labels(args.import_labels)
        print(f"  Imported {n_imp} labeled merge pairs from "
              f"{args.import_labels}")
        _LEARNED.save()
    if args.import_rejections is not None:
        if args.from_supabase:
            n_imp = _LEARNED.import_rejections_from_supabase()
            if n_imp >= 0:
                print(f"  Imported {n_imp} trope rejections from Supabase")
        elif args.import_rejections:
            n_imp = _LEARNED.import_rejections(args.import_rejections)
            print(f"  Imported {n_imp} trope rejections from "
                  f"{args.import_rejections}")
        else:
            print("  --import-rejections needs a PATH or --from-supabase")
        _LEARNED.save()
    if args.alias:
        n_alias = 0
        for spec in args.alias:
            if "=" not in spec:
                print(f"  WARNING: --alias '{spec}' ignored (use A=B format)")
                continue
            a, b = spec.split("=", 1)
            a, b = a.strip(), b.strip()
            if not a or not b:
                print(f"  WARNING: --alias '{spec}' ignored (empty name)")
                continue
            _LEARNED.record_alias(a, b)
            n_alias += 1
            print(f"  Alias: {a} = {b}")
        if n_alias:
            _LEARNED.save()

    if args.isbn:
        _cleaned = _clean_isbn(args.isbn)
        if not _cleaned:
            sys.exit(f"ERROR: --isbn '{args.isbn}' is not a valid ISBN-10/13")
        CONFIG["isbn_override"] = _cleaned
        print(f"ISBN override: {_cleaned}")
    if args.allow_no_isbn:
        CONFIG["allow_no_isbn"] = True
    if args.rename_no_isbn:
        CONFIG["rename_no_isbn"] = True
    if args.series:
        CONFIG["series_override"] = args.series.strip()
        print(f"Series override: {CONFIG['series_override']}")
    if args.series_position is not None:
        CONFIG["series_position_override"] = args.series_position
        print(f"Series position override: {args.series_position:g}")
    if not args.principals_only:
        CONFIG["principals_only"] = False
    if args.min_frequency != 0.20:
        CONFIG["min_frequency"] = args.min_frequency
    if args.show_matrices:
        CONFIG["show_matrices"] = True
        UI._show_matrices = True
    if args.roster_reconcile:
        CONFIG["roster_reconcile"] = True
    if args.staging_gate:
        CONFIG["staging_gate"] = True

    if args.evidence_retrieval:
        CONFIG["evidence_retrieval"] = True

    if getattr(args, "use_corpus", False):
        CONFIG["use_corpus"] = True

    if getattr(args, "corpus_only", False):
        # --corpus-only admits only corpus books to a folder scan,
        # and admitted books are corpus-sourced — so it switches
        # on the same acquisition path --use-corpus does, plus its
        # own switch for run_once's folder filter.
        CONFIG["corpus_only"] = True
        CONFIG["use_corpus"] = True

    if getattr(args, "corpus_quotes", False):
        CONFIG["corpus_quotes"] = True

    if getattr(args, "emit_uncertainty", False):
        CONFIG["emit_uncertainty"] = True

    if getattr(args, "emit_run_events", False):
        CONFIG["emit_run_events"] = True

    if getattr(args, "run_history", False):
        CONFIG["run_history"] = True

    if args.persist_roster:
        CONFIG["persist_roster"] = True
    if getattr(args, "discovery_shadow", False):
        CONFIG["discovery_shadow"] = True
    if getattr(args, "discovery_embedding_rank", False):
        CONFIG["discovery_embedding_rank"] = True
    if args.preview_summary:
        CONFIG["preview_summary"] = True
    if args.resume:
        CONFIG["resume"] = True
    # --explain-blocks defaults ON with --debug, OFF otherwise; explicit
    # --explain-blocks/--no-explain-blocks wins.
    if args.explain_blocks is not None:
        CONFIG["explain_blocks"] = bool(args.explain_blocks)
    elif args.debug:
        CONFIG["explain_blocks"] = True
    if args.llm:
        CONFIG["llm"] = args.llm
    if args.full:
        CONFIG["sample_rate"] = 1
    elif args.sample:
        CONFIG["sample_rate"] = args.sample
    if args.batch:
        CONFIG["batch_size"] = args.batch
    if args.jobs:
        CONFIG["jobs"] = max(1, args.jobs)
    if args.chunks:
        CONFIG["only_chunks"] = args.chunks
    if args.pipeline:
        CONFIG["pipeline"] = args.pipeline
    if args.debug:
        CONFIG["debug"] = True
    if args.dedupe:
        CONFIG["dedupe"] = True
    if CONFIG.get("dedupe") and not CONFIG.get("embed_url"):
        sys.exit("ERROR: --dedupe needs embed_url (and embed_model) set in config.json")
    if CONFIG["llm"] not in ("ollama", "openrouter", "openai"):
        sys.exit(f"ERROR: unknown llm '{CONFIG['llm']}' (use ollama, openrouter, or openai)")
    if CONFIG["llm"] == "openrouter" and not CONFIG["openrouter_key"]:
        sys.exit("ERROR: openrouter_key is not set")
    if not (args.dry_run or args.preview) and not (CONFIG["supabase_url"] and CONFIG["supabase_key"]):
        sys.exit("ERROR: Set supabase_url and supabase_key in config.json")

    print(f"Portable v{PORTABLE_VERSION}")
    # Run start: attempt the relationship registry load before any
    # book work, so every prompt and judgment in the run derives from
    # the same vocabulary. Failure is non-fatal by design (the
    # built-in mirror stays in force) — see _load_rel_registry.
    _load_rel_registry()
    print(f"LLM: {CONFIG['llm']}")
    if args.preview:
        print("Preview mode: results saved to preview/, nothing written to Supabase, files not moved")
    elif args.dry_run:
        print("Dry run: nothing written, files not moved")

    if getattr(args, "replay", None):
        if not args.file:
            print("  --replay needs --file <book>: the snapshot "
                  "replays against its own book file")
            sys.exit(2)
        # A replay is its own run in the history mirror (mode
        # "replay", preview by construction). A refusal happens
        # before any book work, so the run row is a failed run with
        # no book row rather than a book that failed.
        _history_begin("replay", preview=True)
        _history_book_start(Path(args.file))
        _code, _rep = run_replay(args.replay, args.file, _LEARNED.dir)
        if isinstance(_rep, dict) and _rep.get("refusal"):
            _history_book_drop(Path(args.file))
            _history_finish(status="failed",
                            error=str(_rep.get("refusal")))
        else:
            _history_book_outcome(Path(args.file), _code == 0)
            _history_finish(failures=0 if _code == 0 else 1)
        sys.exit(_code)

    if args.watch:
        print(f"Watching {IMPORT_DIR}... (Ctrl+C to stop)")
        try:
            while True:
                # In watch mode, --auto-update checks at the start of each
                # cycle. A successful pull re-execs with fresh code; the flag
                # is preserved across the exec so later cycles keep checking.
                if args.auto_update:
                    _do_auto_update(preserve_flag=True)
                _watch_cycle(args)
                time.sleep(60)
        except KeyboardInterrupt:
            print("\nStopped.")
    else:
        sys.exit(1 if run_once(args.dry_run, args.preview, args.max_books, args.file) else 0)


if __name__ == "__main__":
    main()
